    /// GATE (double-verify-trust-cache T5): the exec trust-cache must be a pure
    /// performance optimization. With a real mempool-populated cache, the resolved
    /// senders from the cached verify MUST equal the uncached (full-recover) verify
    /// action-for-action — including an invalid signature (-> None, the slashing
    /// input that fires app.rs:303-320) and a gossip-TRUSTED action
    /// (verified_locally=false -> not cached -> re-verified, never short-circuited).
    #[test]
    fn trust_cache_resolved_senders_identical_cached_vs_uncached() {
        use torus_types::ActionSignature;
        let (_config, state_db) = make_test_config_and_db();
        let mempool = Mempool::new(state_db.clone(), torus_mempool::MempoolConfig::default());
        let base = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_millis() as u64;

        let k1 = k256::ecdsa::SigningKey::from_slice(&[11u8; 32]).unwrap();
        let k2 = k256::ecdsa::SigningKey::from_slice(&[12u8; 32]).unwrap();

        // (0) EIP-712 admitted via the verified ingress path -> seeds the cache.
        let a_cached =
            torus_types::eip712::sign_native_action(NativeAction::ClaimRewards, base + 1, &k1);
        let s_cached = a_cached.recover_sender().unwrap();
        mempool
            .add_native_action_presigned(s_cached, a_cached.clone())
            .unwrap();

        // (1) EIP-712 valid but never admitted -> cache MISS -> full recover.
        let a_uncached =
            torus_types::eip712::sign_native_action(NativeAction::ClaimRewards, base + 2, &k2);
        let s_uncached = a_uncached.recover_sender().unwrap();

        // (2) EIP-712 with a corrupted signature -> invalid -> None (slash input).
        let mut a_invalid =
            torus_types::eip712::sign_native_action(NativeAction::ClaimRewards, base + 3, &k1);
        if let ActionSignature::Eip712(ref mut sig) = a_invalid.signature {
            sig.r = [0xff; 32];
            sig.s = [0xff; 32];
        }

        // (3) gossip-TRUSTED (sender claimed by a peer, verified_locally=false) ->
        //     NOT cached -> exec must re-verify it (no short-circuit).
        let a_trusted =
            torus_types::eip712::sign_native_action(NativeAction::ClaimRewards, base + 4, &k2);
        let s_trusted = a_trusted.recover_sender().unwrap();
        mempool
            .add_native_action_from_gossip_trusted(s_trusted, a_trusted.clone())
            .unwrap();

        let actions = vec![a_cached, a_uncached, a_invalid, a_trusted.clone()];

        let uncached = torus_types::eip712::batch_verify_native_actions(&actions, base, |_| None);
        let cached = torus_types::eip712::batch_verify_native_actions_cached(
            &actions,
            base,
            |_| None,
            |key| mempool.verified_sender(key),
        );

        assert_eq!(
            cached, uncached,
            "DETERMINISM GATE: cache-on resolved senders must equal cache-off"
        );
        // Structural sanity across the four provenance classes.
        assert_eq!(cached[0], Some(s_cached), "cached HIT == fresh recover");
        assert_eq!(cached[1], Some(s_uncached), "MISS -> full recover");
        assert_eq!(cached[2], None, "invalid sig -> None (slash path input)");
        assert_eq!(
            cached[3],
            Some(s_trusted),
            "trusted re-verified, not short-circuited"
        );

        // Provenance: the trusted action was never seeded into the cache.
        let trusted_key = torus_types::verified_cache_key(&a_trusted).unwrap();
        assert_eq!(
            mempool.verified_sender(&trusted_key),
            None,
            "gossip-trusted (verified_locally=false) must not be cached"
        );
    }

    // ---- FIX 2 (S443): exec-time signature/session failure = DROP, not slash ----

    /// Register `proposer` as a funded validator so a slash/tombstone would actually
    /// take effect (an unregistered proposer's slash is a logged no-op, which would
    /// mask the bug).
    fn register_proposer(state_db: &StateDb, proposer: Address) {
        let staking = StakingManager::new(state_db.clone());
        let stake = torus_economics::MIN_SELF_DELEGATION;
        // Fund the account so register_validator's debit succeeds.
        let mut rec = vec![0u8; 72];
        rec[..32].copy_from_slice(&(stake * U256::from(2u8)).to_be_bytes::<32>());
        state_db
            .put_cf_raw(torus_state::cf::CF_ACCOUNTS, proposer.as_slice(), &rec)
            .unwrap();
        staking
            .register_validator(proposer, [7u8; 32], 500, stake)
            .unwrap();
    }

    fn block_with_proposer(
        height: u64,
        proposer: Address,
        actions: Vec<SignedNativeAction>,
    ) -> TorusBlock {
        let mut b = make_block(height, actions);
        b.header.proposer = proposer;
        b
    }

    /// t15 root cause (fix 2b): a session-signed action whose session is MISSING at
    /// exec time (revoked mid-outage by the bench's revoke/recreate cycle) is a
    /// STATE-DEPENDENT condition, deterministic at the executed height. It must DROP
    /// the action and leave the HONEST proposer untouched — NOT slash 100% + tombstone.
    /// RED at aff21fe: the missing session yields `None`, the invalid-count slash
    /// fires, and the proposer is tombstoned.
    #[test]
    fn missing_session_at_exec_drops_action_no_slash() {
        let (config, state_db) = make_test_config_and_db();
        let proposer = Address::new([0xAB; 20]);
        register_proposer(&state_db, proposer);

        // Session-signed action (valid ed25519) with NO session registered in state
        // → resolve_sender returns SessionNotFound → None at exec.
        let session_key = ed25519_dalek::SigningKey::from_bytes(&[9u8; 32]);
        let action = torus_types::eip712::sign_native_action_with_session(
            NativeAction::CancelOrder { order_id: 1 },
            424_242,
            &session_key,
        );

        let ctx = make_exec_ctx(&config, &state_db);
        ctx.execute_committed_block(&block_with_proposer(1, proposer, vec![action]), vec![]);

        let val = StakingManager::new(state_db.clone())
            .get_validator(&proposer)
            .unwrap()
            .expect("proposer still registered");
        assert_ne!(
            val.status,
            torus_economics::ValidatorStatus::Tombstoned,
            "honest proposer must NOT be tombstoned for a state-dependent missing session"
        );
        assert_eq!(
            val.self_stake,
            torus_economics::MIN_SELF_DELEGATION,
            "honest proposer must NOT be slashed for a state-dependent missing session"
        );
    }

    /// Fix 2b: a STRUCTURALLY-invalid signature at exec time also DROPS the action
    /// without slashing the proposer. The signature-substitution vector is now closed
    /// (`compute_action_hash` commits to the signature since F-2, so a heal-pull peer
    /// can no longer swap a body's signature under the referenced hash), but a bare
    /// exec-time sig failure still is not proposer-attributable: block-level
    /// attestation/QC — not per-action exec re-verification — is the accountability
    /// mechanism, and a deterministic DROP keeps every node's post-state identical.
    /// RED at aff21fe: it slashes+tombstones.
    #[test]
    fn structurally_invalid_sig_at_exec_drops_action_no_slash() {
        use torus_types::ActionSignature;
        let (config, state_db) = make_test_config_and_db();
        let proposer = Address::new([0xCD; 20]);
        register_proposer(&state_db, proposer);

        let key = k256::ecdsa::SigningKey::from_slice(&[21u8; 32]).unwrap();
        let mut action =
            torus_types::eip712::sign_native_action(NativeAction::ClaimRewards, 424_242, &key);
        if let ActionSignature::Eip712(ref mut sig) = action.signature {
            sig.r = [0xff; 32];
            sig.s = [0xff; 32];
        }

        let ctx = make_exec_ctx(&config, &state_db);
        ctx.execute_committed_block(&block_with_proposer(1, proposer, vec![action]), vec![]);

        let val = StakingManager::new(state_db.clone())
            .get_validator(&proposer)
            .unwrap()
            .expect("proposer still registered");
        assert_ne!(
            val.status,
            torus_economics::ValidatorStatus::Tombstoned,
            "exec-time structural sig failure is unattributable (F-2) — must NOT tombstone"
        );
        assert_eq!(
            val.self_stake,
            torus_economics::MIN_SELF_DELEGATION,
            "exec-time structural sig failure must NOT slash the proposer"
        );
    }

    /// A8: exec checks session expiry in MILLISECONDS against the header
    /// timestamp (SECONDS): a session that expired 1 ms before the block time is
    /// skipped, one expiring exactly at the block time executes — on the serial
    /// and on the pipelined flush. RED before A8: the raw header seconds (~1e3)
    /// never exceeded a ms expiry (~1e6), so the expired action executed.
    #[test]
    fn session_expired_at_block_time_is_skipped_serial_and_pipelined() {
        let session_key = ed25519_dalek::SigningKey::from_bytes(&[36u8; 32]);
        let owner = Address::new([0x36; 20]);
        let block_ms =
            torus_types::eip712::block_timestamp_ms(make_block(1, vec![]).header.timestamp);
        let block = make_block(
            1,
            vec![torus_types::eip712::sign_native_action_with_session(
                NativeAction::CancelOrder { order_id: 1 },
                block_ms,
                &session_key,
            )],
        );
        for pipelined in [false, true] {
            for (expiry, skipped) in [(block_ms, false), (block_ms - 1, true)] {
                let (_c, state_db) = make_test_config_and_db();
                state_db
                    .put_session(
                        &session_key.verifying_key().to_bytes(),
                        &torus_types::SessionData {
                            owner,
                            expiry,
                            scope: torus_types::SessionScope::Trading,
                            created_at: 0,
                        },
                    )
                    .unwrap();
                let ctx = pipeline_ctx(&state_db, pipelined, None);
                dispatch_and_execute(&ctx, &state_db, &block);
                assert!(ctx.pipeline_barrier(), "flush worker drained");
                assert!(!ctx.exec_failed.load(Ordering::SeqCst), "no fail-stop");
                assert_eq!(
                    action_status(&state_db, 1).expect("block 1 record").native_skipped,
                    vec![skipped],
                    "pipelined {pipelined}: expiry {expiry} vs block time {block_ms} ms"
                );
                drop(ctx);
            }
        }
    }

    /// Commit 2: exec enforces the ±NONCE_WINDOW_MS nonce window against the
    /// BLOCK time (header seconds -> ms), inclusive. An out-of-window action is
    /// skipped and recorded like any other invalid action (no block rejection,
    /// no slash) and its nonce is not consumed; in-window actions execute. Serial
    /// and pipelined flush agree byte for byte. RED before: exec never checked
    /// the window, so a leader could include stale or far-future actions.
    #[test]
    fn nonce_outside_window_of_block_time_is_skipped_serial_and_pipelined() {
        use torus_types::eip712::{block_timestamp_ms, sign_native_action, NONCE_WINDOW_MS as W};
        let key = k256::ecdsa::SigningKey::from_slice(&[37u8; 32]).unwrap();
        let block_ms = block_timestamp_ms(make_block(1, vec![]).header.timestamp);
        // Oldest allowed, 1 ms too old, newest allowed, 1 ms too new.
        let nonces = [block_ms - W, block_ms - W - 1, block_ms + W, block_ms + W + 1];
        let block = make_block(
            1,
            nonces
                .iter()
                .map(|&n| sign_native_action(NativeAction::ClaimRewards, n, &key))
                .collect(),
        );
        let sender = block.native_actions[0].recover_sender().unwrap();
        let mut dumps = Vec::new();
        for pipelined in [false, true] {
            let (_c, state_db) = make_test_config_and_db();
            let ctx = pipeline_ctx(&state_db, pipelined, None);
            dispatch_and_execute(&ctx, &state_db, &block);
            assert!(ctx.pipeline_barrier(), "flush worker drained");
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "no fail-stop");
            assert_eq!(
                action_status(&state_db, 1).expect("block 1 record").native_skipped,
                vec![false, true, false, true],
                "pipelined {pipelined}: window around block time {block_ms} ms"
            );
            for (n, consumed) in nonces.iter().zip([true, false, true, false]) {
                assert_eq!(nonce_consumed(&state_db, sender, *n), consumed, "nonce {n}");
            }
            drop(ctx);
            dumps.push(dump_all_cfs(&state_db));
        }
        assert_dumps_equal(&dumps[0], &dumps[1], "serial vs pipelined");
    }

    // ---- s84 decision 1: skip invalid actions, record executed/skipped ----

    /// The block's executed/skipped record, if execution wrote one.
    fn action_status(
        state_db: &StateDb,
        height: u64,
    ) -> Option<torus_state::action_status::BlockActionStatus> {
        state_db
            .get_cf_raw(
                torus_state::cf::CF_BLOCK_ACTION_STATUS,
                &height.to_be_bytes(),
            )
            .unwrap()
            .map(|bytes| {
                torus_state::action_status::BlockActionStatus::decode(&bytes)
                    .expect("record decodes")
            })
    }

    fn nonce_consumed(state_db: &StateDb, sender: Address, nonce: u64) -> bool {
        state_db
            .get_cf_raw(
                torus_state::cf::CF_NATIVE_NONCES,
                &torus_state::cf::native_nonce_key(&sender, nonce),
            )
            .unwrap()
            .is_some()
    }

    /// s84 decision 1 (a): a block carrying a forged-signature action, a
    /// replayed nonce, an expired session and an undecodable EVM tx is
    /// certified (every replica's data check holds and `validate_block` is
    /// Valid) and committed on 3 replicas with identical state. Execution
    /// skips exactly those actions and records them as skipped; the valid
    /// native action and the valid EVM tx in the same block execute.
    ///
    /// RED before decision 1: `validate_block` rejects block 2 (non-attested
    /// path: the forged signature and the expired session fail
    /// `batch_verify_native_actions`; `decode_all_txs` fails on the garbage
    /// EVM tx), and execution writes no record.
    #[test]
    fn invalid_actions_are_skipped_and_recorded_identically_on_three_replicas() {
        use torus_types::ActionSignature;
        let key_a = k256::ecdsa::SigningKey::from_slice(&[31u8; 32]).unwrap();
        let key_c = k256::ecdsa::SigningKey::from_slice(&[33u8; 32]).unwrap();
        let evm_key = k256::ecdsa::SigningKey::from_slice(&[34u8; 32]).unwrap();
        let session_key = ed25519_dalek::SigningKey::from_bytes(&[35u8; 32]);

        let first =
            torus_types::eip712::sign_native_action(NativeAction::ClaimRewards, NONCE_BASE + 1, &key_a);
        let block1 = make_block(1, vec![first.clone()]);

        let mut forged = torus_types::eip712::sign_native_action(
            NativeAction::ClaimRewards,
            NONCE_BASE + 7,
            &k256::ecdsa::SigningKey::from_slice(&[32u8; 32]).unwrap(),
        );
        if let ActionSignature::Eip712(ref mut sig) = forged.signature {
            sig.r = [0xff; 32];
            sig.s = [0xff; 32];
        }
        let expired = torus_types::eip712::sign_native_action_with_session(
            NativeAction::CancelOrder { order_id: 1 },
            NONCE_BASE + 8,
            &session_key,
        );
        let valid =
            torus_types::eip712::sign_native_action(NativeAction::ClaimRewards, NONCE_BASE + 9, &key_c);
        // Positions: 0 replay of block 1's action, 1 forged, 2 expired, 3 valid.
        let mut block2 = make_block(2, vec![first, forged, expired, valid]);
        block2.header.parent_hash =
            alloy_primitives::keccak256(block1.header.canonical_header_bytes());
        // EVM positions: 0 undecodable, 1 a valid contract creation.
        block2.evm_transactions = vec![vec![0xde, 0xad], signed_sstore_create(&evm_key, 0)];
        block2.header.evm_tx_count = 2;

        let mut dumps = Vec::new();
        for replica in 0..3 {
            let (config, state_db) = make_test_config_and_db();
            fund_evm_balance(
                &state_db,
                k256_address(&evm_key),
                U256::from(10u128.pow(18)),
            );
            state_db
                .put_session(
                    &session_key.verifying_key().to_bytes(),
                    &torus_types::SessionData {
                        owner: k256_address(&key_c),
                        expiry: 1, // before block 2's timestamp
                        scope: torus_types::SessionScope::Trading,
                        created_at: 0,
                    },
                )
                .unwrap();
            let mut app = TorusApp::new(state_db.clone(), &config, None, None, None);
            let ctx = make_exec_ctx(&config, &state_db);
            let hs1 = hs_block(&block1, PhaseCertificate::genesis_pc());
            let hs2 = hs_block(&block2, justify_for(&hs1));
            for (block, hs) in [(&block1, &hs1), (&block2, &hs2)] {
                let datum = hs.data.vec()[0].bytes().clone();
                let data_hash = hs.data_hash;
                assert_eq!(
                    app.check_proposal_data(hs, |hash| {
                        assert_eq!(*hash, hs1.hash);
                        ParentHeader::Header(Box::new(block1.header.clone()))
                    }),
                    BlockDataCheck::Held,
                    "replica {replica} votes for height {}",
                    block.header.height
                );
                assert!(
                    matches!(
                        app.validate_datum(&datum, &data_hash),
                        ValidateBlockResponse::Valid { .. }
                    ),
                    "replica {replica} must accept height {} (nothing inside a body makes it invalid)",
                    block.header.height
                );
                ctx.execute_committed_block(block, vec![]);
            }
            assert!(
                !ctx.exec_failed.load(Ordering::SeqCst),
                "replica {replica} fail-stopped"
            );

            // v2: both ClaimRewards execute (nonce consumed) and fail —
            // nothing to claim — so they also carry a failure record.
            let no_rewards = |index: u32, sender: Address| {
                torus_state::action_status::NativeActionFailure::new(
                    index,
                    0,
                    1,
                    torus_state::action_status::FailureReason::Other,
                    format!("no rewards to claim for {sender}"),
                )
            };
            assert_eq!(
                action_status(&state_db, 1),
                Some(torus_state::action_status::BlockActionStatus {
                    evm_skipped: vec![],
                    native_skipped: vec![false],
                    native_failed: vec![no_rewards(0, k256_address(&key_a))],
                })
            );
            assert_eq!(
                action_status(&state_db, 2),
                Some(torus_state::action_status::BlockActionStatus {
                    evm_skipped: vec![true, false],
                    native_skipped: vec![true, true, true, false],
                    native_failed: vec![no_rewards(3, k256_address(&key_c))],
                }),
                "replica {replica}: replay, forged and expired skipped; valid executed (and failed)"
            );
            assert!(nonce_consumed(&state_db, k256_address(&key_a), NONCE_BASE + 1));
            assert!(
                nonce_consumed(&state_db, k256_address(&key_c), NONCE_BASE + 9),
                "valid action executed"
            );
            assert!(
                !nonce_consumed(&state_db, k256_address(&key_c), NONCE_BASE + 8),
                "expired-session action consumed nothing"
            );
            let evm_account = state_db
                .get_cf_raw(
                    torus_state::cf::CF_ACCOUNTS,
                    k256_address(&evm_key).as_slice(),
                )
                .unwrap()
                .expect("EVM sender account");
            assert_eq!(
                u64::from_be_bytes(evm_account[32..40].try_into().unwrap()),
                1,
                "the valid EVM tx executed (sender nonce 0 -> 1)"
            );
            drop(app);
            dumps.push(dump_all_cfs(&state_db));
        }
        assert_dumps_equal(&dumps[0], &dumps[1], "replica 0 vs 1");
        assert_dumps_equal(&dumps[0], &dumps[2], "replica 0 vs 2");
    }

    // ---- v2 action status: per-action execution failures ----

    /// Blocks for the failure-record tests (market 1, tick = lot = 1):
    ///   1  fund A, B
    ///   2  0 A sell 100x1 GTC                       executes (rests)
    ///      1 B buy 100x1000 GTC                     rejected: margin
    ///      2 A sell 100.5x1 GTC                     rejected: off-tick
    ///      3 B batch [90x1, 90.5x1, 91x1, 91.5x1]   rejected: order 1 off-tick, 2 failed
    ///      4 replay of block 1's A action           skipped
    ///      5 A cancel unknown order id              fails (pre-EVM list)
    ///      6 B IOC buy 100.5x1                      rejected: off-tick (pre-EVM list)
    ///      7 A sell 100x1 GTC (same as 0, new nonce) executes
    ///   3  A sell 120x1 GTC                         executes (v1 record)
    fn failure_fixture_blocks() -> Vec<TorusBlock> {
        let k_a = k256::ecdsa::SigningKey::from_slice(&[71u8; 32]).unwrap();
        let k_b = k256::ecdsa::SigningKey::from_slice(&[72u8; 32]).unwrap();
        let deposit = U256::from(1_000 * FixedPoint::ONE.raw() as u128);
        let px = |tenths: i128| FixedPoint::from_raw(tenths * FixedPoint::SCALE / 10);
        let order = |is_buy: bool, tenths: i128, qty: i128| torus_types::PlaceOrderParams {
            market_id: 1,
            is_buy,
            price: px(tenths),
            quantity: FixedPoint::from_raw(qty * FixedPoint::SCALE),
            order_type: torus_types::OrderType::Limit,
            time_in_force: torus_types::TimeInForce::GTC,
            reduce_only: false,
            client_order_id: None,
        };
        let sign = |a: NativeAction, n: u64, k: &k256::ecdsa::SigningKey| {
            torus_types::eip712::sign_native_action(a, NONCE_BASE + n, k)
        };
        let place = |o: torus_types::PlaceOrderParams| NativeAction::PlaceOrder(o);
        let fund_a = sign(NativeAction::TransferToPerp { amount: deposit }, 1, &k_a);
        let mut blocks = vec![
            make_block(
                1,
                vec![
                    fund_a.clone(),
                    sign(NativeAction::TransferToPerp { amount: deposit }, 1, &k_b),
                ],
            ),
            make_block(
                2,
                vec![
                    sign(place(order(false, 1000, 1)), 2, &k_a),
                    sign(place(order(true, 1000, 1000)), 2, &k_b),
                    sign(place(order(false, 1005, 1)), 3, &k_a),
                    sign(
                        NativeAction::PlaceOrderBatch(vec![
                            order(true, 900, 1),
                            order(true, 905, 1),
                            order(true, 910, 1),
                            order(true, 915, 1),
                        ]),
                        3,
                        &k_b,
                    ),
                    fund_a,
                    sign(NativeAction::CancelOrder { order_id: 999_999 }, 4, &k_a),
                    sign(
                        place(torus_types::PlaceOrderParams {
                            time_in_force: torus_types::TimeInForce::IOC,
                            ..order(true, 1005, 1)
                        }),
                        4,
                        &k_b,
                    ),
                    sign(place(order(false, 1000, 1)), 5, &k_a),
                ],
            ),
            make_block(3, vec![sign(place(order(false, 1200, 1)), 6, &k_a)]),
        ];
        link_blocks(&mut blocks);
        blocks
    }

    /// Runs the failure fixture on a fresh DB: `engine_threads` pins the
    /// engine (`None` = production `execute_batch`), `pipelined` hands the
    /// flush to the worker. Returns the DB after every block is durable.
    fn run_failure_fixture(engine_threads: Option<usize>, pipelined: bool) -> StateDb {
        run_fixture_blocks(failure_fixture_blocks(), engine_threads, pipelined)
    }

    /// [`run_failure_fixture`] over `blocks` (block 1 = the funding block:
    /// each of its senders gets an EVM balance first).
    fn run_fixture_blocks(
        blocks: Vec<TorusBlock>,
        engine_threads: Option<usize>,
        pipelined: bool,
    ) -> StateDb {
        let (_c, state_db) = make_test_config_and_db();
        let deposit = U256::from(1_000 * FixedPoint::ONE.raw() as u128);
        for signed in &blocks[0].native_actions {
            fund_evm_balance(&state_db, signed.recover_sender().unwrap(), deposit);
        }
        let mut ctx = pipeline_ctx(&state_db, pipelined, None);
        ctx.test_engine_threads = engine_threads;
        for block in &blocks {
            dispatch_and_execute(&ctx, &state_db, block);
        }
        assert!(ctx.pipeline_barrier(), "flush worker drained");
        assert!(!ctx.exec_failed.load(Ordering::SeqCst), "no fail-stop");
        if pipelined {
            assert_eq!(
                ctx.flush_worker.as_ref().map(|w| w.durable_height()),
                Some(blocks.len() as u64),
                "every block went through the flush worker"
            );
        }
        drop(ctx);
        state_db
    }

    /// v2: margin-rejected, off-tick (single, IOC and inside a batch) and
    /// unknown-cancel actions show failed with a reason, at their body
    /// position, in every exec mode (production auto, engine threads 0/2/4)
    /// and on both the serial and the pipelined flush; successes stay
    /// executed, the replay stays skipped, and every run writes identical
    /// bytes to every CF.
    ///
    /// RED before v2: the record only knew executed/skipped (no failures).
    #[test]
    fn execution_failures_are_recorded_identically_in_every_exec_mode() {
        use torus_state::action_status::FailureReason;
        let mut dumps = Vec::new();
        for pipelined in [false, true] {
            for threads in [None, Some(0), Some(2), Some(4)] {
                let label = format!("threads {threads:?} pipelined {pipelined}");
                let db = run_failure_fixture(threads, pipelined);
                let status = action_status(&db, 2).expect("block 2 record");
                assert_eq!(
                    status.native_skipped,
                    vec![false, false, false, false, true, false, false, false],
                    "{label}"
                );
                let got: Vec<(u32, u32, u32, FailureReason)> = status
                    .native_failed
                    .iter()
                    .map(|f| (f.index, f.order, f.failed_orders, f.reason))
                    .collect();
                assert_eq!(
                    got,
                    vec![
                        (1, 0, 1, FailureReason::Margin),
                        (2, 0, 1, FailureReason::Tick),
                        (3, 1, 2, FailureReason::Tick),
                        (5, 0, 1, FailureReason::Other),
                        (6, 0, 1, FailureReason::Tick),
                    ],
                    "{label}: {:?}",
                    status.native_failed
                );
                assert!(
                    status.native_failed[0]
                        .message
                        .starts_with("insufficient margin"),
                    "{label}"
                );
                // Row 50: the margin-refused placement is rejected
                // (perpMarginRejected); review S3: so are the off-tick
                // placements (tickRejected: single, batch, IOC); the unknown
                // cancel stays failed.
                let labels: Vec<&str> = (0..8).map(|i| status.native_label(i)).collect();
                assert_eq!(
                    labels,
                    vec![
                        "executed", "rejected", "rejected", "rejected", "skipped", "failed",
                        "rejected", "executed"
                    ],
                    "{label}"
                );
                // Block 1 and 3: nothing failed -> the compact v1 record.
                for h in [1u64, 3] {
                    let raw = db
                        .get_cf_raw(torus_state::cf::CF_BLOCK_ACTION_STATUS, &h.to_be_bytes())
                        .unwrap()
                        .expect("record");
                    assert_eq!(raw[0], 0x01, "{label}: height {h} keeps v1");
                    assert!(action_status(&db, h).unwrap().native_failed.is_empty());
                }
                dumps.push((label, dump_all_cfs(&db)));
            }
        }
        for (label, dump) in &dumps[1..] {
            assert_dumps_equal(&dumps[0].1, dump, &format!("{} vs {label}", dumps[0].0));
        }
    }

    /// Typed reasons, one action per reason code (market 1, tick = lot = 1):
    ///   1  fund A, B, C
    ///   2  0 A sell 100.5x1 GTC                       tick
    ///      1 A stop-limit buy, limit 100.5             tick (row 40)
    ///      2 A buy 100x0.5                             lot
    ///      3 A buy 0x1 GTC                             price (row 41)
    ///      4 A market buy, cap 0                       price
    ///      5 B buy 100x1000 GTC                        margin
    ///      6 C batch of 1001 buys 1x1                  open_limit at order 1000, 1 failed
    ///      7 A empty PlaceOrderBatch                   batch_cap (0 failed orders)
    ///      8 A cancel unknown order id                 other
    ///      9 A sell 100x1 GTC                          executes
    fn reason_fixture_blocks() -> Vec<TorusBlock> {
        use torus_types::{OrderType, PlaceOrderParams, TimeInForce};
        let k_a = k256::ecdsa::SigningKey::from_slice(&[81u8; 32]).unwrap();
        let k_b = k256::ecdsa::SigningKey::from_slice(&[82u8; 32]).unwrap();
        let k_c = k256::ecdsa::SigningKey::from_slice(&[83u8; 32]).unwrap();
        let deposit = U256::from(1_000 * FixedPoint::ONE.raw() as u128);
        let px = |tenths: i128| FixedPoint::from_raw(tenths * FixedPoint::SCALE / 10);
        let order = |is_buy: bool, tenths: i128, qty_tenths: i128| PlaceOrderParams {
            market_id: 1,
            is_buy,
            price: px(tenths),
            quantity: px(qty_tenths),
            order_type: OrderType::Limit,
            time_in_force: TimeInForce::GTC,
            reduce_only: false,
            client_order_id: None,
        };
        let sign = |a: NativeAction, n: u64, k: &k256::ecdsa::SigningKey| {
            torus_types::eip712::sign_native_action(a, NONCE_BASE + n, k)
        };
        let place = |o: PlaceOrderParams| NativeAction::PlaceOrder(o);
        let fund = |k| sign(NativeAction::TransferToPerp { amount: deposit }, 1, k);
        let mut blocks = vec![
            make_block(1, vec![fund(&k_a), fund(&k_b), fund(&k_c)]),
            make_block(
                2,
                vec![
                    sign(place(order(false, 1005, 10)), 2, &k_a),
                    sign(
                        place(PlaceOrderParams {
                            order_type: OrderType::StopLimit {
                                trigger: px(1200),
                                limit: px(1005),
                            },
                            ..order(true, 0, 10)
                        }),
                        3,
                        &k_a,
                    ),
                    sign(place(order(true, 1000, 5)), 4, &k_a),
                    sign(place(order(true, 0, 10)), 5, &k_a),
                    sign(
                        place(PlaceOrderParams {
                            order_type: OrderType::Market,
                            time_in_force: TimeInForce::IOC,
                            ..order(true, 0, 10)
                        }),
                        6,
                        &k_a,
                    ),
                    sign(place(order(true, 1000, 10_000)), 2, &k_b),
                    sign(
                        NativeAction::PlaceOrderBatch(vec![order(true, 10, 10); 1001]),
                        2,
                        &k_c,
                    ),
                    sign(NativeAction::PlaceOrderBatch(vec![]), 7, &k_a),
                    sign(NativeAction::CancelOrder { order_id: 999_999 }, 8, &k_a),
                    sign(place(order(false, 1000, 10)), 9, &k_a),
                ],
            ),
        ];
        link_blocks(&mut blocks);
        blocks
    }

    /// Row 50 blocks (market 1, tick = lot = 1):
    ///   1  fund A, B, C, D
    ///   2  B sell 105x1, bid 100x2, ask 110x2      rest
    ///   3  C buy 105x1                              trades: last trade 105
    ///   4  0 A IOC buy 105x1                        iocCancelRejected
    ///      1 A PostOnly buy 110x1                   badAloPxRejected
    ///      2 A market buy, cap 106                  marketOrderNoLiquidityRejected
    ///      3 A reduce-only sell 100x1 (flat)        reduceOnlyRejected
    ///      4 A FOK buy 110x5                        fokCancelRejected
    ///      5 A stop buy, trigger 104                badTriggerPxRejected
    ///      6 C batch [GTC 90x1, IOC 105x1, GTC 91x1, PostOnly 110x1]
    ///                                               order 1 iocCancelRejected, 2 not executed
    ///      7 A buy 100x100000 GTC                   perpMarginRejected (placement check)
    ///   5  D IOC sell 100x3                         fills 2 of 3: executed (v1 record)
    fn rejection_fixture_blocks() -> Vec<TorusBlock> {
        use torus_types::{OrderType, PlaceOrderParams, TimeInForce};
        let keys: Vec<_> = (91u8..=94)
            .map(|b| k256::ecdsa::SigningKey::from_slice(&[b; 32]).unwrap())
            .collect();
        let (k_a, k_b, k_c, k_d) = (&keys[0], &keys[1], &keys[2], &keys[3]);
        let deposit = U256::from(1_000 * FixedPoint::ONE.raw() as u128);
        let fp = |units: i128| FixedPoint::from_raw(units * FixedPoint::SCALE);
        let order = |is_buy: bool, price: i128, qty: i128| PlaceOrderParams {
            market_id: 1,
            is_buy,
            price: fp(price),
            quantity: fp(qty),
            order_type: OrderType::Limit,
            time_in_force: TimeInForce::GTC,
            reduce_only: false,
            client_order_id: None,
        };
        let tif = |t, o: PlaceOrderParams| PlaceOrderParams { time_in_force: t, ..o };
        let sign = |a: NativeAction, n: u64, k: &k256::ecdsa::SigningKey| {
            torus_types::eip712::sign_native_action(a, NONCE_BASE + n, k)
        };
        let place = |o: PlaceOrderParams| NativeAction::PlaceOrder(o);
        let fund = |k| sign(NativeAction::TransferToPerp { amount: deposit }, 1, k);
        let mut blocks = vec![
            make_block(1, vec![fund(k_a), fund(k_b), fund(k_c), fund(k_d)]),
            make_block(
                2,
                vec![
                    sign(place(order(false, 105, 1)), 2, k_b),
                    sign(place(order(true, 100, 2)), 3, k_b),
                    sign(place(order(false, 110, 2)), 4, k_b),
                ],
            ),
            make_block(3, vec![sign(place(order(true, 105, 1)), 2, k_c)]),
            make_block(
                4,
                vec![
                    sign(place(tif(TimeInForce::IOC, order(true, 105, 1))), 2, k_a),
                    sign(place(tif(TimeInForce::PostOnly, order(true, 110, 1))), 3, k_a),
                    sign(
                        place(PlaceOrderParams {
                            order_type: OrderType::Market,
                            ..tif(TimeInForce::IOC, order(true, 106, 1))
                        }),
                        4,
                        k_a,
                    ),
                    sign(place(PlaceOrderParams { reduce_only: true, ..order(false, 100, 1) }), 5, k_a),
                    sign(place(tif(TimeInForce::FOK, order(true, 110, 5))), 6, k_a),
                    sign(
                        place(PlaceOrderParams {
                            order_type: OrderType::StopMarket { trigger: fp(104) },
                            ..order(true, 200, 1)
                        }),
                        7,
                        k_a,
                    ),
                    sign(
                        NativeAction::PlaceOrderBatch(vec![
                            order(true, 90, 1),
                            tif(TimeInForce::IOC, order(true, 105, 1)),
                            order(true, 91, 1),
                            tif(TimeInForce::PostOnly, order(true, 110, 1)),
                        ]),
                        3,
                        k_c,
                    ),
                    sign(place(order(true, 100, 100_000)), 8, k_a),
                ],
            ),
            make_block(5, vec![sign(place(tif(TimeInForce::IOC, order(false, 100, 3))), 2, k_d)]),
        ];
        link_blocks(&mut blocks);
        blocks
    }

    /// Row 50: orders the book refuses or cancels without a fill (and a
    /// placement refused for margin) are stored `rejected` with their HL
    /// reason at their body position, a batch as its first rejected order +
    /// the count, in every exec mode — sequential settle (production auto,
    /// engine 0) and the parallel settle's pass B (engine 2, 4) — on both
    /// flushes, with identical bytes in every CF. An IOC that partly fills
    /// stays executed.
    ///
    /// RED before row 50: block 4 recorded only the margin failure (as
    /// `failed`); every book outcome read `executed`.
    #[test]
    fn book_rejections_are_recorded_rejected_in_every_exec_mode() {
        use torus_state::action_status::{FailureReason as R, Outcome};
        let mut dumps = Vec::new();
        for pipelined in [false, true] {
            for threads in [None, Some(0), Some(2), Some(4)] {
                let label = format!("threads {threads:?} pipelined {pipelined}");
                let db = run_fixture_blocks(rejection_fixture_blocks(), threads, pipelined);
                let status = action_status(&db, 4).expect("block 4 record");
                assert_eq!(status.native_skipped, vec![false; 8], "{label}");
                let got: Vec<(u32, u32, u32, Outcome, R)> = status
                    .native_failed
                    .iter()
                    .map(|f| (f.index, f.order, f.failed_orders, f.outcome, f.reason))
                    .collect();
                let rejected = Outcome::Rejected;
                assert_eq!(
                    got,
                    vec![
                        (0, 0, 1, rejected, R::IocCancel),
                        (1, 0, 1, rejected, R::BadAloPx),
                        (2, 0, 1, rejected, R::MarketNoLiquidity),
                        (3, 0, 1, rejected, R::ReduceOnly),
                        (4, 0, 1, rejected, R::FokCancel),
                        (5, 0, 1, rejected, R::BadTriggerPx),
                        (6, 1, 2, rejected, R::IocCancel),
                        (7, 0, 1, rejected, R::Margin),
                    ],
                    "{label}: {:?}",
                    status.native_failed
                );
                assert!(
                    (0..8).all(|i| status.native_label(i) == "rejected"),
                    "{label}"
                );
                assert!(status.native_failed[0].message.starts_with("order rejected: IOC"), "{label}");
                assert!(status.native_failed[7].message.starts_with("insufficient margin"), "{label}");
                let raw = db
                    .get_cf_raw(torus_state::cf::CF_BLOCK_ACTION_STATUS, &4u64.to_be_bytes())
                    .unwrap()
                    .expect("record");
                assert_eq!(raw[0], 0x03, "{label}: v3");
                // Block 5: the partly filled IOC executed (compact v1).
                let raw = db
                    .get_cf_raw(torus_state::cf::CF_BLOCK_ACTION_STATUS, &5u64.to_be_bytes())
                    .unwrap()
                    .expect("record");
                assert_eq!(raw[0], 0x01, "{label}: block 5 keeps v1");
                assert_eq!(action_status(&db, 5).unwrap().native_label(0), "executed", "{label}");
                dumps.push((label, dump_all_cfs(&db)));
            }
        }
        for (label, dump) in &dumps[1..] {
            assert_dumps_equal(&dumps[0].1, dump, &format!("{} vs {label}", dumps[0].0));
        }
    }

    /// Typed reasons: every reason code the executor can produce from a
    /// block is stored as the executor's own reason (M1's tick / lot texts
    /// included), at its body position, in every exec mode and on both
    /// flushes, with identical bytes in every CF. `fill` needs a state
    /// fault at settlement (bridge code path only).
    #[test]
    fn typed_reasons_are_stored_for_every_reason_code() {
        use torus_state::action_status::FailureReason as R;
        let mut dumps = Vec::new();
        for pipelined in [false, true] {
            for threads in [None, Some(0), Some(2), Some(4)] {
                let label = format!("threads {threads:?} pipelined {pipelined}");
                let db = run_fixture_blocks(reason_fixture_blocks(), threads, pipelined);
                let status = action_status(&db, 2).expect("block 2 record");
                assert_eq!(status.native_skipped, vec![false; 10], "{label}");
                let got: Vec<(u32, u32, u32, R)> = status
                    .native_failed
                    .iter()
                    .map(|f| (f.index, f.order, f.failed_orders, f.reason))
                    .collect();
                assert_eq!(
                    got,
                    vec![
                        (0, 0, 1, R::Tick),
                        (1, 0, 1, R::Tick),
                        (2, 0, 1, R::Lot),
                        (3, 0, 1, R::Price),
                        (4, 0, 1, R::Price),
                        (5, 0, 1, R::Margin),
                        (6, 1000, 1, R::OpenLimit),
                        (7, 0, 0, R::BatchCap),
                        (8, 0, 1, R::Other),
                    ],
                    "{label}: {:?}",
                    status.native_failed
                );
                let msgs: Vec<&str> =
                    status.native_failed.iter().map(|f| f.message.as_str()).collect();
                for (i, want) in [
                    "order rejected: price 100.50000000 is not a multiple of the tick 1.00000000",
                    "order rejected: price 100.50000000 is not a multiple of the tick 1.00000000",
                    "order rejected: quantity 0.50000000 below the lot size 1.00000000",
                    "limit order requires a positive price",
                    "market order requires a positive price cap",
                    "insufficient margin",
                    "open order limit reached: 1000 open orders, limit 1000",
                    "PlaceOrderBatch skipped: 0 orders",
                    "order 999999 not found",
                ]
                .into_iter()
                .enumerate()
                {
                    assert!(msgs[i].starts_with(want), "{label} #{i}: {:?}", msgs[i]);
                }
                // Row 50 (+ review S3): placements refused for tick and
                // margin are rejected; lot, price, open limit, batch cap and
                // an unknown cancel stay failed.
                let labels: Vec<&str> = (0..10).map(|i| status.native_label(i)).collect();
                assert_eq!(
                    labels,
                    vec![
                        "rejected", "rejected", "failed", "failed", "failed", "rejected", "failed",
                        "failed", "failed", "executed"
                    ],
                    "{label}"
                );
                dumps.push((label, dump_all_cfs(&db)));
            }
        }
        for (label, dump) in &dumps[1..] {
            assert_dumps_equal(&dumps[0].1, dump, &format!("{} vs {label}", dumps[0].0));
        }
    }

    /// Item 6 cut 1: random blocks 2..=5 (three funded senders; repeated
    /// identical orders of one sender under new nonces, off-tick / lot /
    /// margin failures, PlaceOrderBatch with bad orders, empty batches, IOC
    /// and cancels, replays skipped), in every exec mode and on both flushes.
    /// Each block's stored record is checked against the pre-cut content
    /// match byte for byte inside the exec path (`#[cfg(test)]` oracle);
    /// here every run writes identical bytes to every CF and the blocks do
    /// fail actions that share a sender and content.
    #[test]
    fn random_blocks_store_the_content_match_record_in_every_exec_mode() {
        use torus_types::{OrderType, PlaceOrderParams, TimeInForce};
        let keys: Vec<k256::ecdsa::SigningKey> = (91u8..94)
            .map(|b| k256::ecdsa::SigningKey::from_slice(&[b; 32]).unwrap())
            .collect();
        let deposit = U256::from(1_000 * FixedPoint::ONE.raw() as u128);
        let px = |tenths: i128| FixedPoint::from_raw(tenths * FixedPoint::SCALE / 10);
        let order = |is_buy: bool, tenths: i128, qty_tenths: i128, tif| PlaceOrderParams {
            market_id: 1,
            is_buy,
            price: px(tenths),
            quantity: px(qty_tenths),
            order_type: OrderType::Limit,
            time_in_force: tif,
            reduce_only: false,
            client_order_id: None,
        };
        let mut seed = 0x51_7cc1_b727_220au64;
        let mut next = move |n: u64| {
            seed ^= seed << 13;
            seed ^= seed >> 7;
            seed ^= seed << 17;
            seed % n
        };
        let sign = |a: NativeAction, n: u64, k: &k256::ecdsa::SigningKey| {
            torus_types::eip712::sign_native_action(a, NONCE_BASE + n, k)
        };
        let mut nonces = vec![1u64; keys.len()];
        let mut blocks = vec![make_block(
            1,
            keys.iter()
                .map(|k| sign(NativeAction::TransferToPerp { amount: deposit }, 1, k))
                .collect(),
        )];
        let mut signed_so_far = blocks[0].native_actions.clone();
        for height in 2..=5u64 {
            let mut actions = Vec::new();
            for _ in 0..24 {
                let who = next(keys.len() as u64) as usize;
                // A replay of an earlier action (skipped by the guard).
                if next(10) == 0 {
                    let i = next(signed_so_far.len() as u64) as usize;
                    actions.push(signed_so_far[i].clone());
                    continue;
                }
                // Few distinct contents, so one sender repeats them.
                let buy = next(2) == 0;
                let price = [995, 1000, 1005][next(3) as usize];
                let qty = [10, 5, 100_000][next(3) as usize];
                let tif = if next(4) == 0 {
                    TimeInForce::IOC
                } else {
                    TimeInForce::GTC
                };
                let action = match next(7) {
                    0 => NativeAction::CancelOrder {
                        order_id: 999_999 + next(2) as u128,
                    },
                    1 => NativeAction::PlaceOrderBatch(
                        (0..next(4))
                            .map(|k| {
                                order(buy, [1000, 1005][(k % 2) as usize], 10, TimeInForce::GTC)
                            })
                            .collect(),
                    ),
                    _ => NativeAction::PlaceOrder(order(buy, price, qty, tif)),
                };
                nonces[who] += 1;
                actions.push(sign(action, nonces[who], &keys[who]));
            }
            signed_so_far.extend(actions.iter().cloned());
            blocks.push(make_block(height, actions));
        }
        link_blocks(&mut blocks);
        // Per block, per body position: does the sender have another action
        // with the same content in the block? (Recovered once: slow in debug.)
        let has_twin: Vec<Vec<bool>> = blocks
            .iter()
            .map(|block| {
                let keyed: Vec<(Address, Vec<u8>)> = block
                    .native_actions
                    .iter()
                    .map(|a| (a.recover_sender().unwrap(), a.action.canonical_bytes()))
                    .collect();
                keyed
                    .iter()
                    .map(|k| keyed.iter().filter(|o| *o == k).count() > 1)
                    .collect()
            })
            .collect();
        let mut dumps = Vec::new();
        for pipelined in [false, true] {
            for threads in [None, Some(0), Some(2), Some(4)] {
                let label = format!("threads {threads:?} pipelined {pipelined}");
                let db = run_fixture_blocks(blocks.clone(), threads, pipelined);
                let mut shared_content_failures = 0;
                for (h, twin) in has_twin.iter().enumerate().skip(1) {
                    let status = action_status(&db, h as u64 + 1).expect("record");
                    assert!(status.native_skipped.iter().any(|&s| s), "{label}: replays");
                    shared_content_failures += status
                        .native_failed
                        .iter()
                        .filter(|f| twin[f.index as usize])
                        .count();
                }
                assert!(
                    shared_content_failures > 3,
                    "{label}: failures among one sender's identical actions \
                     ({shared_content_failures})"
                );
                dumps.push((label, dump_all_cfs(&db)));
            }
        }
        for (label, dump) in &dumps[1..] {
            assert_dumps_equal(&dumps[0].1, dump, &format!("{} vs {label}", dumps[0].0));
        }
    }

    // ---- s84 decision 2: the parent link is checked before the vote ----

    /// A hotstuff block carrying `block`'s full datum under `justify`.
    fn hs_block(block: &TorusBlock, justify: PhaseCertificate) -> Block {
        let datum = encode_proposal_datum(block, false);
        Block::new(
            hotstuff_rs::types::data_types::BlockHeight::new(block.header.height),
            justify,
            CryptoHash::new(TorusApp::hash_datum(&datum)),
            Data::new(vec![Datum::new(datum)]),
        )
    }

    /// A (non-genesis) justify certifying `parent`.
    fn justify_for(parent: &Block) -> PhaseCertificate {
        PhaseCertificate {
            block: parent.hash,
            view: hotstuff_rs::types::data_types::ViewNumber::new(parent.height.int() + 1),
            ..PhaseCertificate::genesis_pc()
        }
    }

    /// s84 decision 2: a replica votes only for a block whose header links to
    /// its parent block's header (`height` + 1, `parent_hash` = keccak of the
    /// parent header). A wrong link is `Invalid` (never certified); a parent
    /// not in the tree yet is `Missing` (the vote waits); the verdict does
    /// not depend on how far local execution got (`last_header`).
    ///
    /// RED before decision 2: the data check ignored the parent, so it voted
    /// `Held` for the wrong `parent_hash`, the wrong height and the
    /// undecodable / missing parent.
    #[test]
    fn vote_requires_the_header_to_link_to_its_parent() {
        let (config, state_db) = make_test_config_and_db();
        let mut app = TorusApp::new(state_db, &config, None, None, None);
        let no_lookup =
            |_: &CryptoHash| -> ParentHeader { panic!("genesis justify needs no lookup") };

        // Height 1 on the genesis justify links to the synthetic genesis parent.
        let parent = make_block(1, vec![sign_claim_rewards(1)]);
        let hs_parent = hs_block(&parent, PhaseCertificate::genesis_pc());
        assert_eq!(
            app.check_proposal_data(&hs_parent, no_lookup),
            BlockDataCheck::Held
        );
        let mut bad_genesis = parent.clone();
        bad_genesis.header.parent_hash = B256::ZERO;
        assert_eq!(
            app.check_proposal_data(
                &hs_block(&bad_genesis, PhaseCertificate::genesis_pc()),
                no_lookup
            ),
            BlockDataCheck::Invalid
        );

        let mut child = make_block(2, vec![]);
        child.header.parent_hash =
            alloy_primitives::keccak256(parent.header.canonical_header_bytes());
        let justify = justify_for(&hs_parent);
        let held_parent = |hash: &CryptoHash| {
            assert_eq!(*hash, hs_parent.hash, "the parent is the justify block");
            ParentHeader::Header(Box::new(parent.header.clone()))
        };
        let check = |app: &mut TorusApp,
                     block: &TorusBlock,
                     parent: &dyn Fn(&CryptoHash) -> ParentHeader| {
            app.check_proposal_data(&hs_block(block, justify.clone()), parent)
        };
        let mut wrong_hash = child.clone();
        wrong_hash.header.parent_hash = B256::repeat_byte(0xEE);
        let mut wrong_height = child.clone();
        wrong_height.header.height = 3;

        for last_header_height in [0, 1, 7] {
            // Execution progress must not matter.
            app.last_header = make_block(last_header_height, vec![]).header;
            assert_eq!(
                check(&mut app, &child, &held_parent),
                BlockDataCheck::Held,
                "correct parent votes"
            );
            assert_eq!(
                check(&mut app, &wrong_hash, &held_parent),
                BlockDataCheck::Invalid,
                "wrong parent_hash"
            );
            assert_eq!(
                check(&mut app, &wrong_height, &held_parent),
                BlockDataCheck::Invalid,
                "wrong height"
            );
            assert_eq!(
                check(&mut app, &child, &|_| ParentHeader::NotInTree),
                BlockDataCheck::Missing,
                "parent not in the tree yet: wait"
            );
            assert_eq!(
                check(&mut app, &child, &|_| ParentHeader::Undecodable),
                BlockDataCheck::Invalid,
                "a parent without a torus header cannot be linked to"
            );
        }
    }

    /// s84 decision 2: the pre-vote rule and execution's parent link agree.
    /// An honest leader's proposals (built on the parent header) pass the
    /// pre-vote check and then execute without tripping
    /// `detect_parent_link_violation`; the only blocks that would trip it are
    /// refused before the vote, so a certified block cannot fail-stop
    /// execution on a parent mismatch.
    #[test]
    fn pre_vote_parent_rule_implies_execution_parent_link() {
        use std::sync::atomic::AtomicBool;
        let (config, state_db) = make_test_config_and_db();
        let mut app = TorusApp::new(state_db.clone(), &config, None, None, None);
        let ctx = make_exec_ctx(&config, &state_db);
        let decode = |resp: &ProduceBlockResponse| -> TorusBlock {
            let bytes = resp.data.vec()[0].bytes();
            bincode::deserialize::<TorusBlock>(bytes).unwrap_or_else(|_| {
                let compact: CompactBlock = bincode::deserialize(bytes).unwrap();
                assert!(compact.native_action_hashes.is_empty());
                TorusBlock {
                    header: compact.header,
                    native_actions: vec![],
                    evm_transactions: compact.evm_transactions,
                    core_writer_actions: compact.core_writer_actions,
                }
            })
        };

        let resp1 = app.build_proposal(torus_bridge::genesis_parent_header());
        let hs1 = Block::new(
            hotstuff_rs::types::data_types::BlockHeight::new(0),
            PhaseCertificate::genesis_pc(),
            resp1.data_hash,
            resp1.data.clone(),
        );
        assert_eq!(
            app.check_proposal_data(&hs1, |_| unreachable!()),
            BlockDataCheck::Held
        );
        let block1 = decode(&resp1);
        ctx.execute_committed_block(&block1, vec![]);

        let resp2 = app.build_proposal(block1.header.clone());
        let hs2 = Block::new(
            hotstuff_rs::types::data_types::BlockHeight::new(1),
            justify_for(&hs1),
            resp2.data_hash,
            resp2.data.clone(),
        );
        let parent1 = |_: &CryptoHash| ParentHeader::Header(Box::new(block1.header.clone()));
        assert_eq!(app.check_proposal_data(&hs2, parent1), BlockDataCheck::Held);
        let block2 = decode(&resp2);
        let latch = AtomicBool::new(false);
        assert!(!detect_parent_link_violation(
            &state_db,
            2,
            &block2.header.parent_hash,
            &latch
        ));
        ctx.execute_committed_block(&block2, vec![]);
        assert!(
            !ctx.exec_failed.load(Ordering::SeqCst),
            "certified chain executes"
        );
        assert_eq!(read_native_applied_height(&state_db), Some(2));

        // The block that WOULD trip execution's link check is refused pre-vote.
        let mut forged = block2.clone();
        forged.header.height = 3;
        forged.header.parent_hash = B256::repeat_byte(0xEE);
        assert!(detect_parent_link_violation(
            &state_db,
            3,
            &forged.header.parent_hash,
            &AtomicBool::new(false)
        ));
        let hs2_block = Block::new(
            hotstuff_rs::types::data_types::BlockHeight::new(1),
            justify_for(&hs1),
            resp2.data_hash,
            resp2.data.clone(),
        );
        let parent2 = |_: &CryptoHash| ParentHeader::Header(Box::new(block2.header.clone()));
        assert_eq!(
            app.check_proposal_data(&hs_block(&forged, justify_for(&hs2_block)), parent2),
            BlockDataCheck::Invalid
        );
    }

    /// s84: an EVM-only block (no native phase: zero fee revenue) records its
    /// EVM statuses through the marker flush, and an empty block records none.
    #[test]
    fn evm_only_block_records_status_and_empty_block_records_none() {
        let (config, state_db) = make_test_config_and_db();
        let ctx = make_exec_ctx(&config, &state_db);
        let mut block1 = make_block(1, vec![]);
        block1.evm_transactions = vec![vec![0x01, 0x02, 0x03]];
        block1.header.evm_tx_count = 1;
        ctx.execute_committed_block(&block1, vec![]);
        let mut block2 = make_block(2, vec![]);
        block2.header.parent_hash =
            alloy_primitives::keccak256(block1.header.canonical_header_bytes());
        ctx.execute_committed_block(&block2, vec![]);

        assert!(!ctx.exec_failed.load(Ordering::SeqCst));
        assert_eq!(read_native_applied_height(&state_db), Some(2));
        assert_eq!(
            action_status(&state_db, 1),
            Some(torus_state::action_status::BlockActionStatus {
                evm_skipped: vec![true],
                native_skipped: vec![],
                native_failed: vec![],
            })
        );
        assert_eq!(action_status(&state_db, 2), None);
    }

    /// GATE (T5, state level): executing the SAME block with the trust-cache warm
    /// (HIT) vs cold (no mempool) must reach identical state. A correct cache reuses
    /// exactly the sender a fresh recover yields, so execution is unchanged.
    #[test]
    fn trust_cache_execution_state_identical_cached_vs_uncached() {
        let amount = U256::from(FixedPoint::ONE.raw() as u128);
        let key = k256::ecdsa::SigningKey::from_slice(&[21u8; 32]).unwrap();
        let signed = torus_types::eip712::sign_native_action(
            NativeAction::TransferToPerp { amount },
            NONCE_BASE + 424,
            &key,
        );
        let sender = signed.recover_sender().unwrap();
        let start = amount * U256::from(10u8);

        // --- Cold cache (no mempool): full recover, today's path. ---
        let (config_off, db_off) = make_test_config_and_db();
        let ctx_off = make_exec_ctx_with_mempool(&config_off, &db_off, None, false);
        fund_evm_balance(&db_off, sender, start);
        ctx_off.execute_committed_block(&make_block(1, vec![signed.clone()]), vec![]);
        let off_balance = read_evm_balance(&db_off, sender);

        // --- Warm cache (HIT): seed the signature-committing key -> sender. ---
        let (config_on, db_on) = make_test_config_and_db();
        let mempool = Arc::new(Mempool::new(
            db_on.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let cache_key = torus_types::verified_cache_key(&signed).unwrap();
        mempool.cache_verified_sender(cache_key, sender);
        assert_eq!(
            mempool.verified_sender(&cache_key),
            Some(sender),
            "precondition: cache is warm so exec takes the HIT path"
        );
        // Flag ON so the warm cache is actually consulted (the HIT path).
        let ctx_on = make_exec_ctx_with_mempool(&config_on, &db_on, Some(mempool), true);
        fund_evm_balance(&db_on, sender, start);
        ctx_on.execute_committed_block(&make_block(1, vec![signed.clone()]), vec![]);
        let on_balance = read_evm_balance(&db_on, sender);

        assert_eq!(
            on_balance, off_balance,
            "execution with a warm trust-cache must reach identical state as cold"
        );
        assert_eq!(
            start - on_balance,
            amount,
            "executed exactly once, correct debit"
        );
    }

    /// T6: with `--exec-trust-cache` OFF (the default), the cache is never consulted
    /// at exec — even a POISONED entry is ignored and the action is fully recovered
    /// (today's behavior). This is what makes the flag a safe default-off rollback
    /// switch.
    #[test]
    fn trust_cache_flag_off_bypasses_cache() {
        let amount = U256::from(FixedPoint::ONE.raw() as u128);
        let key = k256::ecdsa::SigningKey::from_slice(&[31u8; 32]).unwrap();
        let signed = torus_types::eip712::sign_native_action(
            NativeAction::TransferToPerp { amount },
            NONCE_BASE + 424,
            &key,
        );
        let real_sender = signed.recover_sender().unwrap();
        let start = amount * U256::from(10u8);

        let (config, db) = make_test_config_and_db();
        let mempool = Arc::new(Mempool::new(
            db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        // POISON the cache: map this action's key to a bogus sender. If exec ever
        // consulted the cache, the deposit would be attributed to `bogus` and the
        // real sender would NOT be debited.
        let bogus = Address::from([0xCD; 20]);
        assert_ne!(bogus, real_sender);
        let cache_key = torus_types::verified_cache_key(&signed).unwrap();
        mempool.cache_verified_sender(cache_key, bogus);

        // Flag OFF -> cache ignored -> real sender recovered + debited.
        let ctx = make_exec_ctx_with_mempool(&config, &db, Some(mempool), false);
        fund_evm_balance(&db, real_sender, start);
        ctx.execute_committed_block(&make_block(1, vec![signed.clone()]), vec![]);

        assert_eq!(
            start - read_evm_balance(&db, real_sender),
            amount,
            "flag OFF must full-recover the REAL sender, ignoring the poisoned cache"
        );
        assert_eq!(
            read_evm_balance(&db, bogus),
            U256::ZERO,
            "poisoned cache entry must never be used when the flag is off"
        );
    }

    /// Wei per native raw unit: the EVM side is 18-decimal, native `FixedPoint` 8-decimal.
    const WEI_PER_NATIVE_RAW: u64 = 10_000_000_000;

    /// Seed an EVM balance into CF_ACCOUNTS (72-byte record: balance ++ nonce ++ code_hash).
    /// `Lockbox::get_evm_balance` reads the first 32 bytes big-endian.
    ///
    /// `balance` is in NATIVE 8-decimal raw units (the unit of the native lockbox actions
    /// these tests sign); it is stored as 18-decimal wei (×10^10).
    fn fund_evm_balance(state_db: &StateDb, addr: Address, balance: U256) {
        let wei = balance * U256::from(WEI_PER_NATIVE_RAW);
        let mut rec = vec![0u8; 72];
        rec[..32].copy_from_slice(&wei.to_be_bytes::<32>());
        state_db
            .put_cf_raw(torus_state::cf::CF_ACCOUNTS, addr.as_slice(), &rec)
            .unwrap();
    }

    /// EVM balance in NATIVE 8-decimal raw units (wei / 10^10; the tests only move
    /// whole native units, so the division is exact).
    fn read_evm_balance(state_db: &StateDb, addr: Address) -> U256 {
        let wei = match state_db
            .get_cf_raw(torus_state::cf::CF_ACCOUNTS, addr.as_slice())
            .unwrap()
        {
            Some(d) if d.len() >= 32 => U256::from_be_slice(&d[..32]),
            _ => U256::ZERO,
        };
        wei / U256::from(WEI_PER_NATIVE_RAW)
    }

    /// REGRESSION (correctness/fund-safety): an identical native action committed in
    /// several consecutive blocks must be EXECUTED exactly once.
    ///
    /// The non-destructive mempool selection × HotStuff 3-chain pipeline re-includes
    /// the same action in blocks N, N+1, N+2 before N commits (memory b206f59c). The
    /// live commit path had NO per-(sender,nonce) replay guard, so each inclusion
    /// re-executed — proven on devnet: one TransferToPerp credited 3x
    /// (devnet/scripts/native-transfer-probe.py). Here we commit the SAME signed
    /// TransferToPerp in three blocks and assert the sender's EVM balance is debited
    /// for exactly ONE deposit (not three).
    #[test]
    fn duplicate_committed_native_action_executes_once() {
        let (config, state_db) = make_test_config_and_db();
        let exec_ctx = make_exec_ctx(&config, &state_db);

        // Native lockbox action amounts are raw 8-decimal FixedPoint units (u256_to_fp),
        // NOT 18-decimal wei; the lockbox debits amount × 10^10 wei from the EVM side.
        let amount_raw: u128 = FixedPoint::ONE.raw() as u128; // 1.0 == 100_000_000
        let amount = U256::from(amount_raw);
        let key = k256::ecdsa::SigningKey::from_slice(&[7u8; 32]).unwrap();
        let signed = torus_types::eip712::sign_native_action(
            NativeAction::TransferToPerp { amount },
            NONCE_BASE + 424,
            &key,
        );
        let sender = signed.recover_sender().expect("recover sender");

        // Fund enough EVM balance for THREE deposits, so the only thing that can stop
        // a 2nd/3rd execution is correct dedup — never insufficient funds.
        let start_balance = amount * U256::from(10u8);
        fund_evm_balance(&state_db, sender, start_balance);

        // Same action committed in three consecutive blocks (the proven bug scenario).
        // Link each child to its ACTUAL (non-empty) parent so the commit-time
        // ancestry check passes and the per-(sender,nonce) replay guard — not a
        // parent-link fail-stop — is what dedups the 2nd/3rd inclusion.
        let mut parent: Option<TorusBlock> = None;
        for height in 1..=3u64 {
            let mut block = make_block(height, vec![signed.clone()]);
            if let Some(p) = &parent {
                block.header.parent_hash =
                    alloy_primitives::keccak256(p.header.canonical_header_bytes());
            }
            exec_ctx.execute_committed_block(&block, vec![]);
            parent = Some(block);
        }

        let evm_after = read_evm_balance(&state_db, sender);
        let debited = start_balance - evm_after;
        assert_eq!(
            debited, amount,
            "TransferToPerp committed in 3 blocks must debit EVM balance ONCE (got {debited}, \
             expected {amount}); duplicate execution = fund-safety bug",
        );

        // The consumed nonce must be recorded in CF_NATIVE_NONCES.
        let nonce_key = torus_state::cf::native_nonce_key(&sender, signed.nonce);
        assert!(
            state_db
                .get_cf_raw(torus_state::cf::CF_NATIVE_NONCES, &nonce_key)
                .unwrap()
                .is_some(),
            "consumed nonce should be recorded",
        );
    }

    /// O3 + s77: with a background trade writer attached, the block's fills are
    /// encoded into packed trade-history rows and written off the execution
    /// thread. Dropping the ExecutionContext
    /// closes the writer's channel, drains the queue, and joins — the shutdown
    /// flush ordering — so every row must be durable afterwards.
    #[test]
    fn deferred_trades_reach_db_via_background_writer() {
        let (config, state_db) = make_test_config_and_db();
        let mut exec_ctx = make_exec_ctx(&config, &state_db);
        exec_ctx.trade_writer = Some(torus_state::BackgroundCfWriter::spawn(
            state_db.clone(),
            "test-trade-writer",
            8,
        ));

        let k_sell = k256::ecdsa::SigningKey::from_slice(&[31u8; 32]).unwrap();
        let k_buy = k256::ecdsa::SigningKey::from_slice(&[32u8; 32]).unwrap();

        // Block 1: fund native balances through the public path (EVM balance ->
        // TransferToPerp), so block 2's margin reserve succeeds.
        let deposit_raw: u128 = 1_000 * FixedPoint::ONE.raw() as u128; // 1000.0
        let deposit = U256::from(deposit_raw);
        let mut transfers = Vec::new();
        for (i, key) in [&k_sell, &k_buy].into_iter().enumerate() {
            let signed = torus_types::eip712::sign_native_action(
                NativeAction::TransferToPerp { amount: deposit },
                NONCE_BASE + 9_000 + i as u64,
                key,
            );
            fund_evm_balance(&state_db, signed.recover_sender().unwrap(), deposit);
            transfers.push(signed);
        }
        let block1 = make_block(1, transfers);
        exec_ctx.execute_committed_block(&block1, vec![]);

        // Block 2: a resting sell crossed by a buy -> exactly one fill.
        let order = |is_buy: bool| torus_types::PlaceOrderParams {
            market_id: 1,
            is_buy,
            price: FixedPoint::from_raw(100 * FixedPoint::SCALE),
            quantity: FixedPoint::from_raw(FixedPoint::SCALE),
            order_type: torus_types::OrderType::Limit,
            time_in_force: torus_types::TimeInForce::GTC,
            reduce_only: false,
            client_order_id: None,
        };
        let sell = torus_types::eip712::sign_native_action(
            NativeAction::PlaceOrder(order(false)),
            NONCE_BASE + 9_002,
            &k_sell,
        );
        let buy = torus_types::eip712::sign_native_action(
            NativeAction::PlaceOrder(order(true)),
            NONCE_BASE + 9_003,
            &k_buy,
        );
        // Link block 2 to the ACTUAL (non-empty) block 1 so the commit-time
        // ancestry check passes (block 1 persisted its own canonical hash).
        let mut block2 = make_block(2, vec![sell, buy]);
        block2.header.parent_hash =
            alloy_primitives::keccak256(block1.header.canonical_header_bytes());
        exec_ctx.execute_committed_block(&block2, vec![]);

        // Shutdown flush ordering: drop drains + joins the writer before reads.
        drop(exec_ctx);

        let trades =
            StateBackend::iterate_cf(&state_db, torus_state::cf::CF_NATIVE_TRADES, None).unwrap();
        let user_trades =
            StateBackend::iterate_cf(&state_db, torus_state::cf::CF_NATIVE_USER_TRADES, None)
                .unwrap();
        assert_eq!(trades.len(), 1, "one market row via the background writer");
        let (market, block, chunk) = torus_state::trade_rows::parse_trade_key(&trades[0].0).unwrap();
        assert_eq!((market, block, chunk), (1, 2, 0));
        let (ts, fills) = torus_state::trade_rows::decode_trade_row(&trades[0].1).unwrap();
        assert_eq!(ts, block2.header.timestamp);
        assert_eq!(fills.len(), 1, "one fill");
        assert_eq!(fills[0].qty_raw, FixedPoint::SCALE);
        assert_eq!(user_trades.len(), 2, "one row each for maker and taker");
        let roles: Vec<u8> = user_trades
            .iter()
            .flat_map(|(_, v)| torus_state::trade_rows::decode_user_row(v).unwrap().1)
            .map(|e| e.role)
            .collect();
        assert_eq!(roles.iter().copied().collect::<std::collections::BTreeSet<_>>(), [0, 1].into());
    }

    // ---- L3 flush-pipe (b): async post-flush stage (TORUS_ASYNC_POST_FLUSH) ----

    /// Executing an identical native-action block sequence with the post-flush
    /// writer OFF (synchronous, exact-today) and ON (async body persist) must leave
    /// BYTE-IDENTICAL state after the writer drains — every consensus/native CF,
    /// including CF_BLOCK_BODIES, CF_NATIVE_NONCES, and the native mirror/trie. The
    /// async stage only moves the (already-durable-at-dispatch) body rewrite off the
    /// exec chain; it changes no bytes.
    #[test]
    fn async_post_flush_state_identical_over_sequence() {
        let run = |async_on: bool| -> Vec<Vec<(Vec<u8>, Vec<u8>)>> {
            let (config, state_db) = make_test_config_and_db();
            let mut exec_ctx = make_exec_ctx(&config, &state_db);
            if async_on {
                exec_ctx.post_flush_writer = Some(torus_state::BackgroundCfWriter::spawn(
                    state_db.clone(),
                    "test-post-flush",
                    256,
                ));
            }
            // Each block dirties native state + consumes a nonce + writes a body.
            let mut prev: Option<TorusBlock> = None;
            for h in 1..=5u64 {
                let mut block = make_block(h, vec![sign_claim_rewards(h)]);
                if let Some(p) = &prev {
                    block.header.parent_hash =
                        alloy_primitives::keccak256(p.header.canonical_header_bytes());
                }
                exec_ctx.execute_committed_block(&block, vec![]);
                prev = Some(block);
            }
            // Shutdown flush ordering: drop drains + joins the writer before reads.
            drop(exec_ctx);

            [
                torus_state::cf::CF_BLOCK_BODIES,
                torus_state::cf::CF_NATIVE_NONCES,
                torus_state::cf::CF_ACCOUNTS,
                torus_state::cf::CF_NATIVE_HASHED,
                torus_state::cf::CF_NATIVE_TRIE,
            ]
            .iter()
            .map(|cf| StateBackend::iterate_cf(&state_db, cf, None).unwrap())
            .collect::<Vec<Vec<(Vec<u8>, Vec<u8>)>>>()
        };

        let off = run(false);
        let on = run(true);
        assert_eq!(off.len(), on.len());
        for (i, (a, b)) in off.iter().zip(on.iter()).enumerate() {
            assert_eq!(
                a, b,
                "CF index {i} diverged between synchronous and async post-flush"
            );
        }
        assert_eq!(
            on[0].len(),
            5,
            "all 5 block bodies must be durable via the async writer after drain"
        );
    }

    /// Crash window W3 (design-flush-pipeline.md §3): the flush marker is advanced
    /// (native state N durable) but the async exec-time body write is LOST before it
    /// drains to the real DB — simulated by diverting the post-flush writer to a
    /// throwaway DB. Because the AUTHORITATIVE body write already happened at
    /// commit/dispatch (`persist_committed_block_durably`, FIX 1a), the real DB still
    /// has the body and crash-replay reconstructs identical state — no hole, no
    /// fail-stop. This is the async analogue of
    /// `crash_after_commit_before_execute_recovers_via_durable_body`.
    #[test]
    fn async_post_flush_crash_window_body_survives_via_dispatch_write() {
        let (config, state_db) = make_test_config_and_db();

        // Heights 1..=2 applied (empty, bodies present).
        for h in 1..=2u64 {
            persist_block_for_test(&state_db, &make_block(h, vec![]));
        }
        write_native_applied_height(&state_db, 2);

        // Height 3: FIX 1a persists header+body durably at COMMIT/DISPATCH, before exec.
        let b3 = make_block(3, vec![sign_claim_rewards(3)]);
        persist_committed_block_durably(&state_db, &b3);

        // Divert the async exec-time body write to a THROWAWAY db, so the real DB
        // never receives the deferred exec-time rewrite (== a crash losing the
        // queued batch before drain).
        let (_scratch_cfg, scratch_db) = make_test_config_and_db();
        let mut exec_ctx = make_exec_ctx(&config, &state_db);
        exec_ctx.post_flush_writer = Some(torus_state::BackgroundCfWriter::spawn(
            scratch_db.clone(),
            "test-post-flush-lost",
            256,
        ));
        exec_ctx.execute_committed_block(&b3, vec![]);
        drop(exec_ctx); // drains the (diverted) writer; the real DB is unaffected

        // The real DB still has body[3] — from the dispatch-time durable write, not
        // the lost async exec-time write.
        assert!(
            state_db
                .get_cf_raw(CF_BLOCK_BODIES, &3u64.to_be_bytes())
                .unwrap()
                .is_some(),
            "body[3] must survive via the dispatch-time durable write despite the lost async write"
        );
        assert_eq!(
            read_native_applied_height(&state_db),
            Some(3),
            "height 3 must be marked applied (flush marker committed)"
        );

        // Crash-replay from the marker: height 3 is already applied (marker durable),
        // so replay is correctly a no-op (`applied >= committed` ⇒ returns genesis,
        // no hole, no fail-stop). The body must remain present afterwards.
        let exec_ctx2 = make_exec_ctx(&config, &state_db);
        let (_last, parked) = TorusApp::replay_committed(&state_db, &exec_ctx2);
        assert_eq!(parked, None, "no parked hole after async-loss crash window");
        assert!(
            !exec_ctx2
                .exec_failed
                .load(std::sync::atomic::Ordering::SeqCst),
            "async body loss must NOT fail-stop recovery (dispatch-time body covers it)"
        );
        assert_eq!(
            read_native_applied_height(&state_db),
            Some(3),
            "applied height unchanged by the no-op replay"
        );
        assert!(
            state_db
                .get_cf_raw(CF_BLOCK_BODIES, &3u64.to_be_bytes())
                .unwrap()
                .is_some(),
            "body[3] still present after restart+replay (dispatch-time durable write)"
        );
    }

    #[test]
    fn parse_async_post_flush_toggle_default_off() {
        assert!(!parse_async_post_flush_toggle(None));
        assert!(!parse_async_post_flush_toggle(Some("".into())));
        assert!(!parse_async_post_flush_toggle(Some("0".into())));
        assert!(parse_async_post_flush_toggle(Some("1".into())));
        assert!(parse_async_post_flush_toggle(Some("true".into())));
    }

    /// Acceptance (e): exec-critical-chain wall per block, serial vs pipelined.
    /// Measures the wall to execute a native-action block sequence on the single
    /// exec thread (the throughput-binding path) with the post-flush writer OFF vs
    /// ON. With ON, the body write leaves the exec chain (drain overlaps), so the
    /// per-block exec-chain wall should be <= serial. `#[ignore]` (timing; run on a
    /// quiet box): `cargo test -p torus-consensus --release bench_exec_chain -- --ignored --nocapture`.
    #[test]
    #[ignore = "timing microbench; run explicitly on a quiet box with --nocapture"]
    fn bench_exec_chain_body_persist_serial_vs_async() {
        let n = 300u64;
        let bench = |async_on: bool| -> f64 {
            let (config, state_db) = make_test_config_and_db();
            let mut exec_ctx = make_exec_ctx(&config, &state_db);
            if async_on {
                exec_ctx.post_flush_writer = Some(torus_state::BackgroundCfWriter::spawn(
                    state_db.clone(),
                    "bench-post-flush",
                    256,
                ));
            }
            // Pre-build the linked chain so build cost is out of the timed region.
            let mut blocks: Vec<TorusBlock> = Vec::with_capacity(n as usize);
            for h in 1..=n {
                let mut b = make_block(h, vec![sign_claim_rewards(h)]);
                if let Some(p) = blocks.last() {
                    b.header.parent_hash =
                        alloy_primitives::keccak256(p.header.canonical_header_bytes());
                }
                blocks.push(b);
            }
            let t = std::time::Instant::now();
            for b in &blocks {
                exec_ctx.execute_committed_block(b, vec![]);
            }
            let wall = t.elapsed().as_secs_f64();
            drop(exec_ctx); // drain excluded from the exec-chain measurement above
            wall
        };
        let serial = bench(false);
        let pipelined = bench(true);
        println!(
            "BENCH exec-chain over {n} blocks: serial={serial:.4}s ({:.3} ms/blk)  \
             pipelined={pipelined:.4}s ({:.3} ms/blk)  delta={:.1}%",
            serial / n as f64 * 1e3,
            pipelined / n as f64 * 1e3,
            (serial - pipelined) / serial * 100.0,
        );
    }

    #[test]
    fn duplicate_committed_native_batch_consumes_nonce_once() {
        // Phase B / Task B5: a PlaceOrderBatch carries many orders but ONE (sender, nonce),
        // so committing the same batch twice must execute it once (replay guard at the
        // per-action (sender, nonce) granularity — the 2e52851 fix, unchanged by batching).
        let (config, state_db) = make_test_config_and_db();
        let exec_ctx = make_exec_ctx(&config, &state_db);

        let mk = |market_id: u64| torus_types::PlaceOrderParams {
            market_id,
            is_buy: true,
            price: FixedPoint::from_raw(100 * FixedPoint::SCALE),
            quantity: FixedPoint::from_raw(FixedPoint::SCALE),
            order_type: torus_types::OrderType::Limit,
            time_in_force: torus_types::TimeInForce::GTC,
            reduce_only: false,
            client_order_id: None,
        };
        let key = k256::ecdsa::SigningKey::from_slice(&[9u8; 32]).unwrap();
        let signed = torus_types::eip712::sign_native_action(
            NativeAction::PlaceOrderBatch(vec![mk(1), mk(2), mk(3)]),
            NONCE_BASE + 555,
            &key,
        );
        let sender = signed.recover_sender().expect("recover sender");

        // Same batch committed in two consecutive blocks (the proven dup scenario).
        // Link block 2 to the ACTUAL (non-empty) block 1 so the commit-time
        // ancestry check passes and the (sender, nonce) replay guard — not the
        // parent-link fail-stop — is what skips the duplicate.
        let block1 = make_block(1, vec![signed.clone()]);
        exec_ctx.execute_committed_block(&block1, vec![]);
        let mut block2 = make_block(2, vec![signed.clone()]);
        block2.header.parent_hash =
            alloy_primitives::keccak256(block1.header.canonical_header_bytes());
        exec_ctx.execute_committed_block(&block2, vec![]);

        // Recorded exactly once; the stored value is the FIRST commit height (1),
        // proving the second commit was skipped (not re-executed / re-written).
        let nonce_key = torus_state::cf::native_nonce_key(&sender, signed.nonce);
        let recorded = state_db
            .get_cf_raw(torus_state::cf::CF_NATIVE_NONCES, &nonce_key)
            .unwrap()
            .expect("batch must consume its (sender, nonce) once");
        assert_eq!(
            recorded.as_slice(),
            &1u64.to_be_bytes(),
            "replay guard must skip the second commit (nonce height stays 1)",
        );
    }

    /// r2 resident-books-stale-rebuild: a committed block that skips the native
    /// path entirely (no native actions, no fee revenue) leaves the order books
    /// untouched, so the rank8 resident holder must ADVANCE with it (in step
    /// with the standalone applied-height marker) instead of falling behind and
    /// tripping the staleness guard on the next native block (devnet:
    /// "resident_height=376 block_height=379" → multi-second full rebuild).
    #[test]
    fn empty_blocks_advance_resident_holder_with_marker() {
        use torus_bridge::native_executor::{NativeExecContext, ResidentBooks};
        let (config, state_db) = make_test_config_and_db();
        let exec_ctx = make_exec_ctx(&config, &state_db);

        // Height 1: empty block through the pipeline (marker=1, header persisted).
        exec_ctx.execute_committed_block(&make_block(1, vec![]), vec![]);
        assert_eq!(read_native_applied_height(&state_db), Some(1));

        // Seed the holder as if height 1 had been executed resident (post-state
        // of height 1, classic mode = the pipeline's default).
        let mut holder = ResidentBooks::default();
        let mut seed = NativeExecContext::new_with_modes(
            state_db.clone(),
            1,
            1001,
            0,
            config.epoch_length,
            config.max_validators,
            Address::ZERO,
            config.treasury_address,
            config.dev_pool_address,
            false,
            Some(&mut holder),
        );
        seed.save_order_books();
        seed.stash_resident(&mut holder);
        assert_eq!(holder.height(), Some(1));
        *exec_ctx.resident_books.lock().unwrap() = holder;

        // Heights 2 and 3: empty blocks — the holder must track the marker.
        for h in 2..=3u64 {
            exec_ctx.execute_committed_block(&make_block(h, vec![]), vec![]);
            assert_eq!(read_native_applied_height(&state_db), Some(h));
            assert_eq!(
                exec_ctx.resident_books.lock().unwrap().height(),
                Some(h),
                "holder must advance across the untouched block {h}"
            );
        }

        // Height 4 (native, resident): the guard passes — no rebuild.
        let mut holder = std::mem::take(&mut *exec_ctx.resident_books.lock().unwrap());
        let ctx = NativeExecContext::new_with_modes(
            state_db.clone(),
            4,
            1004,
            0,
            config.epoch_length,
            config.max_validators,
            Address::ZERO,
            config.treasury_address,
            config.dev_pool_address,
            false,
            Some(&mut holder),
        );
        assert!(
            ctx.resident_reused(),
            "holder advanced through empty blocks must be reused at the next native block"
        );
    }

    /// Exec-ceiling Option A: executing ONE native block must observe each
    /// phase histogram exactly once and count the executed action, so the
    /// live probe's per-phase sums decompose `exec_block_seconds` cleanly
    /// (per-phase count == native-block count by design).
    #[test]
    fn exec_phase_histograms_observe_per_block() {
        let (config, state_db) = make_test_config_and_db();
        let mut exec_ctx = make_exec_ctx(&config, &state_db);
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        exec_ctx.metrics = Some(metrics.clone());

        exec_ctx.execute_committed_block(&make_block(1, vec![sign_claim_rewards(NONCE_BASE + 7)]), vec![]);

        let text = metrics.encode();
        for name in [
            "torus_exec_verify_seconds",
            "torus_exec_replay_guard_seconds",
            "torus_exec_engine_seconds",
            "torus_exec_save_books_seconds",
            "torus_exec_flush_seconds",
            "torus_exec_block_seconds",
            "torus_exec_evm_seconds",
            "torus_exec_load_books_seconds",
            "torus_exec_margin_configs_seconds",
            "torus_exec_body_persist_seconds",
        ] {
            assert!(
                text.contains(&format!("{name}_count 1")),
                "{name} must observe exactly once per native block:\n{text}",
            );
        }
        assert!(
            text.contains("torus_native_actions_processed_total 1"),
            "executed action must be counted:\n{text}",
        );
        // Direct synchronous call never touches the exec channel; the gauge's
        // inc/dec sites live there and are verified by the live probe (Task 3).
        assert!(
            text.contains("torus_exec_queue_depth 0"),
            "queue gauge must stay 0 on the direct-call path:\n{text}",
        );
    }

    /// r6 engine-untimed-attribution: the six sub-timers that decompose
    /// `exec_engine_seconds` must ALSO observe exactly once per native block
    /// (they are fed from per-block accumulators, not per-`execute_batch`
    /// call), so `_sum / _count` in summarize.py's phase table is directly
    /// ms-per-block and lines up with `exec_engine_seconds_count`.
    #[test]
    fn engine_untimed_sub_timers_observe_per_block() {
        let (config, state_db) = make_test_config_and_db();
        let mut exec_ctx = make_exec_ctx(&config, &state_db);
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        exec_ctx.metrics = Some(metrics.clone());

        exec_ctx.execute_committed_block(&make_block(1, vec![sign_claim_rewards(7)]), vec![]);

        let text = metrics.encode();
        for name in [
            "torus_exec_phase1_actions_seconds",
            "torus_exec_settle_pass_a_seconds",
            "torus_exec_settle_pass_b_seconds",
            "torus_exec_cache_flush_seconds",
            "torus_exec_post_engine_tail_seconds",
            "torus_exec_engine_untimed_seconds",
        ] {
            assert!(
                text.contains(&format!("{name}_count 1")),
                "{name} must observe exactly once per native block:\n{text}",
            );
        }
    }

    /// bl1 exec-chain ruler: read one scalar sample out of an OpenMetrics
    /// exposition (`name value`). Panics with the whole text when absent, so a
    /// missing series is a loud test failure rather than a silent 0.
    fn metric_value(text: &str, name: &str) -> f64 {
        for line in text.lines() {
            if let Some((k, v)) = line.split_once(' ') {
                if k == name {
                    return v
                        .trim()
                        .parse::<f64>()
                        .unwrap_or_else(|e| panic!("{name} is not a number ({v:?}): {e}"));
                }
            }
        }
        panic!("metric {name} absent from exposition:\n{text}");
    }

    /// bl1 exec-chain-sub-100-attribution (RULER): the exec critical chain
    /// per NATIVE block must be observed exactly ONCE per native block, on the
    /// SAME clock as `exec_block_seconds`, together with its hand-off wait and
    /// the save-books drain/write split — so `_sum / _count` is directly
    /// ms-per-native-block and lines up with `exec_engine_seconds_count`.
    #[test]
    fn exec_chain_ruler_observes_once_per_native_block() {
        let (config, state_db) = make_test_config_and_db();
        let mut exec_ctx = make_exec_ctx(&config, &state_db);
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        exec_ctx.metrics = Some(metrics.clone());

        exec_ctx.execute_committed_block(&make_block(1, vec![sign_claim_rewards(7)]), vec![]);

        let text = metrics.encode();
        for name in [
            "torus_exec_chain_seconds",
            "torus_exec_handoff_wait_seconds",
            "torus_exec_save_books_drain_seconds",
            "torus_exec_save_books_write_seconds",
        ] {
            assert!(
                text.contains(&format!("{name}_count 1")),
                "{name} must observe exactly once per native block:\n{text}",
            );
        }
        assert_eq!(
            metric_value(&text, "torus_exec_native_blocks_total"),
            1.0,
            "native-block counter must count this block:\n{text}",
        );
        // The chain count is the denominator summarize.py divides by; it MUST
        // equal the engine count or every new ms-per-block column is skewed.
        assert_eq!(
            metric_value(&text, "torus_exec_chain_seconds_count"),
            metric_value(&text, "torus_exec_engine_seconds_count"),
            "chain must observe on exactly the set of blocks engine does:\n{text}",
        );
    }

    /// bl1 exec-chain ruler, SERIAL-BINARY IDENTITIES. On a binary with no
    /// flush worker:
    ///   * `chain == block` for a native block (same wall clock, no stage is
    ///     off the exec thread), so `chain_sum <= block_sum` with the whole
    ///     difference being the empty blocks;
    ///   * the hand-off wait exists but is identically 0 (E never blocks);
    ///   * `flush_worker_seconds` is NEVER observed and `flush_worker_depth`
    ///     stays 0 — the pair summarize.py and the harness drain key off.
    /// An EMPTY block must move `exec_block_seconds` but NOT the chain, so the
    /// ruler is never diluted by empty blocks.
    #[test]
    fn exec_chain_ruler_serial_identities_and_empty_blocks() {
        let (config, state_db) = make_test_config_and_db();
        let mut exec_ctx = make_exec_ctx(&config, &state_db);
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        exec_ctx.metrics = Some(metrics.clone());

        let block1 = make_block(1, vec![sign_claim_rewards(7)]);
        exec_ctx.execute_committed_block(&block1, vec![]);
        // Empty block 2, linked to the NATIVE block 1 actually persisted above.
        let mut block2 = make_block(2, vec![]);
        block2.header.parent_hash =
            alloy_primitives::keccak256(block1.header.canonical_header_bytes());
        exec_ctx.execute_committed_block(&block2, vec![]);

        let text = metrics.encode();
        assert_eq!(
            metric_value(&text, "torus_exec_block_seconds_count"),
            2.0,
            "both blocks execute:\n{text}",
        );
        assert_eq!(
            metric_value(&text, "torus_exec_chain_seconds_count"),
            1.0,
            "the empty block must NOT be counted into the chain:\n{text}",
        );
        assert_eq!(
            metric_value(&text, "torus_exec_native_blocks_total"),
            1.0,
            "the empty block must NOT be counted as native:\n{text}",
        );

        let chain = metric_value(&text, "torus_exec_chain_seconds_sum");
        let block = metric_value(&text, "torus_exec_block_seconds_sum");
        assert!(
            chain > 0.0 && chain <= block + 1e-9,
            "chain ({chain}) must be the native-block share of block ({block}):\n{text}",
        );

        assert_eq!(
            metric_value(&text, "torus_exec_handoff_wait_seconds_sum"),
            0.0,
            "a serial binary never blocks on a flush hand-off:\n{text}",
        );
        assert_eq!(
            metric_value(&text, "torus_exec_handoff_wait_seconds_count"),
            1.0,
            "the hand-off series must still exist (0 value, not absent):\n{text}",
        );
        assert_eq!(
            metric_value(&text, "torus_flush_worker_seconds_count"),
            0.0,
            "a serial binary has no flush worker to observe:\n{text}",
        );
        assert_eq!(
            metric_value(&text, "torus_flush_worker_depth"),
            0.0,
            "flush-worker depth must stay 0 on a serial binary (the harness \
             drain waits for exactly this before the digest):\n{text}",
        );
    }

    /// Task 3 (RED first): the pull-fallback poll budget must be ≥ 1 s so a body that
    /// arrives a few hundred ms after the request (slow peer / under load) is still
    /// recovered on the sync path. The original 4 × 20 ms = 80 ms gave up far too
    /// early — a body landing later was lost, contributing to the >4 MB wedge. The
    /// widened 20 × 50 ms = 1 s is safe here (sync path only, never consensus voting).
    #[test]
    fn pull_budget_is_at_least_one_second() {
        let budget = PULL_DELAY * PULL_RETRIES as u32;
        assert!(
            budget >= std::time::Duration::from_secs(1),
            "PULL_RETRIES({PULL_RETRIES}) * PULL_DELAY({PULL_DELAY:?}) = {budget:?} must be ≥ 1 s",
        );
    }

    /// Sprint 1 T4: the sync-path pull budget scales with how many bodies are
    /// missing — a flat ~1 s budget recovers a late single body but gives up on
    /// the multi-MB body-sets of batched blocks (s334 bs1000: fetch exhausted,
    /// fell back to sync, which also timed out). Floor stays ~1 s, cap ~8 s.
    #[test]
    fn sync_pull_retries_scales_with_missing_count() {
        assert_eq!(
            sync_pull_retries(0),
            PULL_RETRIES,
            "floor at no/low missing"
        );
        assert_eq!(sync_pull_retries(40), PULL_RETRIES, "40/2 == floor");
        assert_eq!(sync_pull_retries(100), 50, "linear midband: ~2 bodies/tick");
        assert_eq!(
            sync_pull_retries(10_000),
            MAX_SYNC_PULL_RETRIES,
            "cap at ~8 s for huge sets"
        );
    }

    /// Task 3 (behavioral): a body that only arrives AFTER the old 80 ms budget would
    /// have expired (modelled here as delivered on the 8th drain ≈ 400 ms in) is still
    /// recovered within the widened budget. The old 4-retry loop gave up at drain 4 and
    /// lost it; 20 retries reach drain 8 and recover it. This is the consensus-layer
    /// half of the >4 MB un-wedge (the codec/chunk half lives in torus-network).
    #[test]
    fn pull_recovers_body_delivered_after_old_budget() {
        // `LateFetcher` is the shared test double hoisted to module scope.
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(torus_mempool::Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let mut app = TorusApp::new(state_db.clone(), &config, None, Some(mempool.clone()), None);

        let action = sign_claim_rewards(42);
        let hash = torus_types::compute_action_hash(&action);
        let body = bincode::serialize(&action).expect("serialize body");

        // Delivered on the 8th drain — past the old 4-retry budget, within the new 20.
        let fetcher = Arc::new(LateFetcher {
            body,
            deliver_on_drain: 8,
            drains: std::sync::atomic::AtomicUsize::new(0),
        });
        app.set_native_da_fetcher(fetcher);

        assert!(
            mempool.get_native_da(&hash).is_none(),
            "body absent before the pull"
        );
        let recovered = app.pull_missing_bodies(&[hash]);
        assert!(
            recovered,
            "a body arriving after the old 80 ms budget is recovered within ~1 s"
        );
        assert!(
            mempool.get_native_da(&hash).is_some(),
            "the recovered body landed in the durable DA store",
        );
    }

    /// BS-4a (RED first): a true push miss must NOT block the consensus thread on the
    /// in-line pull budget. reconstruct returns Err (MissingData) within the shrunken
    /// local slice, and the RECOVERY WORKER pulls + absorbs the body in the background
    /// so the re-proposed view finds it locally. MUST fail before BS-4a lands (today
    /// the hot path blocks ~260ms and returns Ok via the in-line pull).
    #[test]
    fn hot_path_hands_off_and_recovers_in_background() {
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(torus_mempool::Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let mut app = TorusApp::new(state_db.clone(), &config, None, Some(mempool.clone()), None);

        let action = sign_claim_rewards(13);
        let hash = torus_types::compute_action_hash(&action);
        let body = bincode::serialize(&action).expect("serialize body");
        let fetcher = Arc::new(LateFetcher {
            body,
            deliver_on_drain: 3,
            drains: std::sync::atomic::AtomicUsize::new(0),
        });
        app.set_native_da_fetcher(fetcher);

        let start = std::time::Instant::now();
        let result = app.reconstruct_native_actions_hot(&[hash]);
        let elapsed = start.elapsed();

        assert_eq!(
            result.err(),
            Some(1),
            "a push miss fails THIS view immediately"
        );
        assert!(
            elapsed < std::time::Duration::from_millis(80),
            "consensus thread must not run the pull budget in-line: took {elapsed:?}",
        );
        // The worker recovers the body off-thread well before the next view.
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        while mempool.get_native_da(&hash).is_none() {
            assert!(
                std::time::Instant::now() < deadline,
                "worker never recovered the body"
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
    }

    /// BS-4a: the recovery worker, fed a missing hash, pulls + absorbs the body into
    /// the durable DA store off-thread within its budget.
    #[test]
    fn recovery_worker_recovers_late_body_off_thread() {
        let (_config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(torus_mempool::Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));

        let action = sign_claim_rewards(23);
        let hash = torus_types::compute_action_hash(&action);
        let body = bincode::serialize(&action).expect("serialize body");
        // Delivered on the 3rd drain — inside the worker budget, as in the driver test.
        let fetcher = Arc::new(LateFetcher {
            body,
            deliver_on_drain: 3,
            drains: std::sync::atomic::AtomicUsize::new(0),
        });

        // No TorusApp: the worker is constructed directly from the Arcs it owns.
        let worker = DaRecoveryWorker::spawn(mempool.clone(), fetcher, None, None);
        assert!(
            mempool.get_native_da(&hash).is_none(),
            "body absent before the worker pull"
        );
        worker.submit(vec![hash]);

        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        while mempool.get_native_da(&hash).is_none() {
            assert!(
                std::time::Instant::now() < deadline,
                "worker never recovered the body"
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }

        // Exercise Drop-join on a live worker thread — a hang here IS the defect.
        drop(worker);
    }

    /// T8-integration increment 2 test double: a `ShardFetcher` pre-seeded with a
    /// pool of gathered shards. `fetch_shards` is a no-op (the shards are already
    /// "arrived"); `drain_shards` returns AND CLEARS the pool, matching real drain
    /// semantics (each shard delivered once). An empty pool models "no shards served".
    struct MockShardFetcher {
        pool: std::sync::Mutex<Vec<crate::shard_recovery::GatheredShard<ShardSource>>>,
    }
    impl ShardFetcher for MockShardFetcher {
        fn fetch_shards(&self, _body_hash: [u8; 32], _want: u16) {}
        fn drain_shards(&self) -> Vec<crate::shard_recovery::GatheredShard<ShardSource>> {
            std::mem::take(&mut *self.pool.lock().unwrap())
        }
    }

    /// Encode `action`'s body under `(k,n)` and return `(body_hash, all n StoredShards)`.
    fn shards_for_action(
        action: &SignedNativeAction,
        k: usize,
        n: usize,
    ) -> ([u8; 32], Vec<torus_state::StoredShard>) {
        let body = bincode::serialize(action).expect("serialize body");
        let enc = torus_state::erasure::encode(&body, torus_state::ErasureParams::new(k, n))
            .expect("encode");
        let shards = (0..n)
            .map(|i| torus_state::StoredShard::from_encoded_body(&enc, i))
            .collect();
        (torus_types::compute_action_hash(action).0, shards)
    }

    /// T8-int2 (RED first — `recover_bodies_via_shards` does not exist on base): the
    /// shard pre-step gathers k=2 shards from DISTINCT peers, reconstructs+verifies,
    /// and ABSORBS the body into the durable DA store — returning EMPTY (nothing left
    /// for the whole-body fallback).
    #[test]
    fn recover_bodies_via_shards_absorbs_body() {
        let (_config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(torus_mempool::Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));

        let action = sign_claim_rewards(101);
        let hash = torus_types::compute_action_hash(&action);
        // (k=2, n=3): 3 shards, any 2 distinct-source ones reconstruct.
        let (_h, shards) = shards_for_action(&action, 2, 3);
        // Two DISTINCT peers, distinct indices (0 from peerA, 2 from peerB).
        let mock = MockShardFetcher {
            pool: std::sync::Mutex::new(vec![
                crate::shard_recovery::GatheredShard {
                    source: b"peerA".to_vec(),
                    shard: shards[0].clone(),
                },
                crate::shard_recovery::GatheredShard {
                    source: b"peerB".to_vec(),
                    shard: shards[2].clone(),
                },
            ]),
        };

        assert!(
            mempool.get_native_da(&hash).is_none(),
            "precondition: body absent before shard recovery"
        );

        let still = recover_bodies_via_shards(
            &mempool,
            &mock,
            &[hash],
            8,
            4,
            std::time::Duration::from_millis(5),
            None,
            None,
        );

        assert!(
            still.is_empty(),
            "all bodies recovered from shards → nothing left for whole-body fallback"
        );
        assert!(
            mempool.get_native_da(&hash).is_some(),
            "reconstructed body must be absorbed into the durable DA store"
        );
    }

    /// T8-int2 (RED first): with NO shards served, the pre-step recovers nothing and
    /// returns the hash as STILL missing — a clean fall-through to the UNCHANGED
    /// whole-body pull (the full fallback wiring is exercised end-to-end in T9).
    #[test]
    fn recover_bodies_via_shards_returns_still_missing_when_no_shards() {
        let (_config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(torus_mempool::Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));

        let action = sign_claim_rewards(102);
        let hash = torus_types::compute_action_hash(&action);
        let mock = MockShardFetcher {
            pool: std::sync::Mutex::new(Vec::new()),
        };

        let still = recover_bodies_via_shards(
            &mempool,
            &mock,
            &[hash],
            8,
            4,
            std::time::Duration::from_millis(5),
            None,
            None,
        );

        assert_eq!(
            still,
            vec![hash],
            "no shards → body stays missing for the whole-body fallback"
        );
        assert!(
            mempool.get_native_da(&hash).is_none(),
            "no shards → nothing absorbed"
        );
    }

    /// T9 REGRESSION-LOCK (not RED — `recover_bodies_via_shards` already exists since
    /// inc2): the < k boundary. With SOME shards served but fewer than k (here exactly
    /// ONE, for a (k=2,n=3) body), the shard pre-step must NOT reconstruct — a single
    /// shard reconstructing would be a correctness break. It must return the hash STILL
    /// missing (so the caller falls back to the whole-body pull → never wedges) and must
    /// absorb NOTHING. Genuinely distinct from the "no shards" test (that had zero; this
    /// has some, but under k). This locks the under-k fall-through against future refactor.
    #[test]
    fn recover_bodies_via_shards_under_k_falls_through() {
        let (_config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(torus_mempool::Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));

        let action = sign_claim_rewards(103);
        let hash = torus_types::compute_action_hash(&action);
        // (k=2, n=3): reconstruction needs 2 distinct-source shards. Serve only ONE.
        let (_h, shards) = shards_for_action(&action, 2, 3);
        let mock = MockShardFetcher {
            pool: std::sync::Mutex::new(vec![crate::shard_recovery::GatheredShard {
                source: b"peerA".to_vec(),
                shard: shards[0].clone(),
            }]),
        };

        let still = recover_bodies_via_shards(
            &mempool,
            &mock,
            &[hash],
            8,
            4,
            std::time::Duration::from_millis(5),
            None,
            None,
        );

        assert_eq!(
            still,
            vec![hash],
            "under-k shards → body stays missing for the whole-body fallback (never-wedge)"
        );
        assert!(
            mempool.get_native_da(&hash).is_none(),
            "a single shard (< k) must NOT reconstruct — nothing absorbed"
        );
    }

    /// T9 CORE PROOF (never-wedge, caller side): the DaRecoveryWorker HONORS the
    /// still-missing signal from an insufficient shard path by falling through to the
    /// whole-body pull. The shard fetcher serves only 1 of the 2 shards needed for a
    /// (k=2,n=3) body (never reconstructable); the whole-body fetcher records the pull
    /// hashes AND stages the real body on drain, so the worker actually recovers it.
    /// We assert the body becomes durable (never-wedge) AND that the whole-body fetcher
    /// was asked for the hash — proving the shard path fell through rather than wedging.
    #[test]
    fn worker_falls_back_to_whole_body_when_shards_insufficient() {
        let (_config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(torus_mempool::Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));

        let action = sign_claim_rewards(24);
        let hash = torus_types::compute_action_hash(&action);
        let body = bincode::serialize(&action).expect("serialize body");

        // Shard fetcher serves only ONE shard (< k=2) → never reconstructable, so
        // recover_bodies_via_shards returns the hash still-missing.
        let (_h, shards) = shards_for_action(&action, 2, 3);
        let shard_fetcher = Arc::new(MockShardFetcher {
            pool: std::sync::Mutex::new(vec![crate::shard_recovery::GatheredShard {
                source: b"peerA".to_vec(),
                shard: shards[0].clone(),
            }]),
        });

        // Whole-body fetcher: records the hashes it is asked to pull AND (once a fetch
        // was issued) stages the real body on drain so the worker recovers it — proving
        // the shard path fell THROUGH to whole-body rather than wedging.
        struct RecordingWholeBodyFetcher {
            body: Vec<u8>,
            fetched: std::sync::Mutex<Vec<[u8; 32]>>,
        }
        impl NativeDaFetcher for RecordingWholeBodyFetcher {
            fn fetch(&self, hashes: Vec<[u8; 32]>) {
                self.fetched.lock().unwrap().extend(hashes);
            }
            fn drain(&self) -> Vec<Vec<u8>> {
                if self.fetched.lock().unwrap().is_empty() {
                    Vec::new()
                } else {
                    vec![self.body.clone()]
                }
            }
        }
        let whole = Arc::new(RecordingWholeBodyFetcher {
            body,
            fetched: std::sync::Mutex::new(Vec::new()),
        });

        let worker =
            DaRecoveryWorker::spawn(mempool.clone(), whole.clone(), Some(shard_fetcher), None);
        assert!(
            mempool.get_native_da(&hash).is_none(),
            "body absent before recovery"
        );
        worker.submit(vec![hash]);

        // Shard budget (~500ms) + a fast whole-body recovery — a 3s deadline is a wide
        // regression separator, not a tight race.
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(3);
        while mempool.get_native_da(&hash).is_none() {
            assert!(
                std::time::Instant::now() < deadline,
                "worker never recovered the body via the whole-body fallback (wedge!)"
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }

        assert!(
            whole.fetched.lock().unwrap().iter().any(|h| *h == hash.0),
            "the insufficient shard path must fall through to the whole-body pull for the hash"
        );

        // Exercise Drop-join on a live worker thread.
        drop(worker);
    }

    /// BS-4a: dropping the worker with an in-flight batch AND a queued backlog must
    /// join fast. Queued batches are DISCARDED via the shutdown flag (old defect:
    /// drop drained queue_depth x ~1s), and since Fix C the IN-FLIGHT batch inside
    /// recover_bodies_bounded also observes the flag (`cancel`) at the top of its
    /// wait loop, so it abandons its ~1s budget at the NEXT ~20ms slice boundary
    /// after the flag is set instead of running to completion. Uses a
    /// never-delivering fetcher so any processed batch would otherwise burn the full
    /// ~1s budget; the 3s bound is the regression separator — it cleanly separates
    /// fixed (≤~100ms: one slice) from regressed (≥~1s in-flight, up to ~9s without
    /// coalesce) while staying load-tolerant (elapsed bounds flake under
    /// parallel-suite load, mem 96dfce88).
    #[test]
    fn recovery_worker_drop_discards_backlog_and_joins_bounded() {
        let (_config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(torus_mempool::Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));

        // NeverFetcher delivers nothing, so the in-flight batch would burn the full
        // ~1s budget if it were not cancellable — the regression this test guards.
        let worker = DaRecoveryWorker::spawn(mempool.clone(), Arc::new(NeverFetcher), None, None);

        // 9 distinct single-hash batches: never-arriving hashes, so the worker's
        // store-check dedup can't drop them. First is taken in-flight; the rest are
        // coalesced into that same cycle (Fix A drains the queue via try_recv), so a
        // 9th queued would warn+drop — fine either way.
        for nonce in 100u64..109 {
            let hash = torus_types::compute_action_hash(&sign_claim_rewards(nonce));
            worker.submit(vec![hash]);
        }

        // Let the worker pick up a batch in-flight (now inside recover_bodies_bounded,
        // parked in its wait loop where the cancel check lives).
        std::thread::sleep(std::time::Duration::from_millis(50));

        let t = std::time::Instant::now();
        drop(worker);
        let elapsed = t.elapsed();
        // Visible under `--nocapture`: fixed ≈ one slice (≤~100ms), regressed ≥~1s.
        println!("drop-join elapsed: {elapsed:?}");
        assert!(
            elapsed < std::time::Duration::from_secs(3),
            "drop must not drain the backlog: took {elapsed:?}",
        );
    }

    /// Phase 2.3 (#5, RED first): when a hash-only push PRE-WARMED the bodies (they already
    /// sit in the fetcher inbound), the HOT local retry must ABSORB them into the DA store
    /// and reconstruct WITHOUT issuing a redundant network fetch. Asserts the body is
    /// recovered AND `fetch()` was never called. MUST fail before Task 4 (today only the
    /// hot-PULL phase absorbs, and it calls `fetch` first → fetch_count ≥ 1).
    #[test]
    fn prewarmed_bodies_absorbed_without_redundant_hot_fetch() {
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(torus_mempool::Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let mut app = TorusApp::new(state_db.clone(), &config, None, Some(mempool.clone()), None);

        let action = sign_claim_rewards(11);
        let hash = torus_types::compute_action_hash(&action);
        let body = bincode::serialize(&action).expect("serialize body");
        let fetcher = Arc::new(PrewarmFetcher {
            body,
            fetches: std::sync::atomic::AtomicUsize::new(0),
            drained: std::sync::atomic::AtomicBool::new(false),
        });
        app.set_native_da_fetcher(fetcher.clone());

        assert!(
            mempool.get_native_da(&hash).is_none(),
            "body absent before reconstruct"
        );
        let actions = app
            .reconstruct_native_actions_hot(&[hash])
            .expect("the pre-warmed body must be absorbed and reconstructed");
        assert_eq!(
            actions.len(),
            1,
            "the absorbed action is returned (in hash order)"
        );
        assert!(
            mempool.get_native_da(&hash).is_some(),
            "the pre-warmed body landed in the durable DA store",
        );
        assert_eq!(
            fetcher.fetches.load(std::sync::atomic::Ordering::Relaxed),
            0,
            "a pre-warmed body must be absorbed by the local retry -- no redundant hot fetch",
        );
    }

    /// BS-4a: when the body NEVER arrives, the hot path must FAIL THE VIEW (Err with
    /// the missing count) FAST — the contract is now fail-fast (one ~20 ms local slice
    /// + a non-blocking worker handoff), not merely under the 500 ms view timeout. The
    /// block is simply re-proposed next view. The 80 ms bound is 4x the 20 ms slice:
    /// under parallel-suite load elapsed bounds can flake (mem 96dfce88), so keep
    /// headroom above the nominal slice.
    #[test]
    fn hot_path_fails_view_fast_when_body_never_arrives() {
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(torus_mempool::Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let mut app = TorusApp::new(state_db.clone(), &config, None, Some(mempool.clone()), None);

        let action = sign_claim_rewards(9);
        let hash = torus_types::compute_action_hash(&action);
        app.set_native_da_fetcher(Arc::new(NeverFetcher));

        let start = std::time::Instant::now();
        let result = app.reconstruct_native_actions_hot(&[hash]);
        let elapsed = start.elapsed();

        assert_eq!(
            result.err(),
            Some(1),
            "a never-arriving body fails the view, reporting the missing count",
        );
        assert!(
            elapsed < std::time::Duration::from_millis(80),
            "hot path must fail fast (one local slice + non-blocking handoff): took {elapsed:?}",
        );
    }

    /// BS-4a: both recovery budgets stay within bounds. (a) The consensus-thread share
    /// of hot reconstruction is ONE local wake-on-arrival slice — well under the 500 ms
    /// view timeout (hotstuff: 4*EWNL + produce + validate < max_view_time), so
    /// validate_block fails a missed view instead of burning it. (b) The worker's
    /// off-thread pull budget stays under ~2 s, so an unrecoverable batch never
    /// outlives more than a couple of re-propose cycles (which resubmit the same
    /// hashes anyway). Companion of `pull_budget_is_at_least_one_second` (sync LOWER
    /// bound). Renamed from `hot_pull_budget_under_view_timeout` — there is no in-line
    /// hot pull anymore.
    #[test]
    fn recovery_budgets_within_bounds() {
        let local = RECONSTRUCT_RETRY_DELAY * RECONSTRUCT_RETRIES as u32;
        assert!(
            local < std::time::Duration::from_millis(50),
            "consensus-thread budget {local:?} (one slice) must be well under the 500 ms view timeout",
        );
        let worker = WORKER_PULL_DELAY * WORKER_PULL_RETRIES as u32;
        assert!(
            worker < std::time::Duration::from_secs(2),
            "worker pull budget {worker:?} must not outlive a couple of re-propose cycles",
        );
    }

    /// BS-4b (RED first): a body that never arrives must trigger EXACTLY ONE
    /// mid-budget re-fetch — covering a lost pull request/response — on top of the
    /// initial fetch, and NOT one re-fetch per wait tick. Drives `recover_bodies_bounded`
    /// directly with a small budget (10 × 10 ms = 100 ms, midpoint ~50 ms). Before the
    /// re-fetch lands this fails on `fetch_calls == 2` (today only the initial fetch fires).
    #[test]
    fn recover_bodies_refetches_once_mid_budget() {
        let (_config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(torus_mempool::Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));

        let action = sign_claim_rewards(77);
        let hash = torus_types::compute_action_hash(&action);
        let body = bincode::serialize(&action).expect("serialize body");
        // Never delivered: the body stays missing for the whole budget.
        let fetcher = Arc::new(CountingFetcher {
            body,
            deliver_on_drain: 0,
            fetch_calls: std::sync::atomic::AtomicUsize::new(0),
            drains: std::sync::atomic::AtomicUsize::new(0),
        });

        let recovered = recover_bodies_bounded(
            &mempool,
            fetcher.as_ref(),
            &[hash],
            10,
            std::time::Duration::from_millis(10),
            None,
            None,
        );
        assert!(
            !recovered,
            "a never-arriving body is not recovered in-budget"
        );
        assert_eq!(
            fetcher
                .fetch_calls
                .load(std::sync::atomic::Ordering::Relaxed),
            2,
            "initial fetch + exactly one mid-budget re-fetch (not one per tick)",
        );
    }

    /// BS-4b: a body that arrives well before the budget midpoint must NOT trigger a
    /// re-fetch — the initial fetch is the only one. `deliver_on_drain: 1` lands the
    /// body on the first wait-loop drain (~10 ms into the ~100 ms budget, midpoint ~50 ms).
    #[test]
    fn recover_bodies_no_refetch_when_body_arrives_early() {
        let (_config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(torus_mempool::Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));

        let action = sign_claim_rewards(88);
        let hash = torus_types::compute_action_hash(&action);
        let body = bincode::serialize(&action).expect("serialize body");
        // Delivered on the first drain after the initial fetch — well before the midpoint.
        let fetcher = Arc::new(CountingFetcher {
            body,
            deliver_on_drain: 1,
            fetch_calls: std::sync::atomic::AtomicUsize::new(0),
            drains: std::sync::atomic::AtomicUsize::new(0),
        });

        let recovered = recover_bodies_bounded(
            &mempool,
            fetcher.as_ref(),
            &[hash],
            10,
            std::time::Duration::from_millis(10),
            None,
            None,
        );
        assert!(recovered, "an early-arriving body is recovered");
        assert_eq!(
            fetcher
                .fetch_calls
                .load(std::sync::atomic::Ordering::Relaxed),
            1,
            "body arrived before the midpoint — only the initial fetch, no re-fetch",
        );
    }

    // ========================================================================
    // T1.2 body-determinism regression suite
    //
    // Instrumented devnet (t12-diag1) proved HotStuff consensus is SAFE — all
    // nodes vote + commit an identical block — yet a minority node executed a
    // DIFFERENT native-action body (native_count=40 of the committed 59) and
    // persisted a divergent eth header. Root cause: `on_committed_block`
    // preferred a stale `pending_proposals[height]` cache (a same-height
    // re-proposal overwrote the entry) over the committed consensus datum, for
    // BOTH the header and the body. These tests pin the two halves of the fix.
    // ========================================================================

    /// Build a committed HotStuff `Block` carrying a COMPACT datum for `block`.
    fn committed_compact_block(block: &TorusBlock) -> hotstuff_rs::types::block::Block {
        use hotstuff_rs::hotstuff::types::PhaseCertificate;
        use hotstuff_rs::types::data_types::BlockHeight;
        let datum = encode_proposal_datum(block, true);
        let hash = TorusApp::hash_datum(&datum);
        hotstuff_rs::types::block::Block::new(
            BlockHeight::new(block.header.height),
            PhaseCertificate::genesis_pc(),
            CryptoHash::new(hash),
            Data::new(vec![Datum::new(datum)]),
        )
    }

    /// T1.2 (a) RED-first: a STALE same-height `pending_proposals` entry (fewer
    /// actions than the committed block) must NEVER be executed in place of the
    /// committed datum. The body handed to execution must carry the COMMITTED
    /// action set (reconstructed from the durable DA store), never the cache's
    /// partial subset.
    ///
    /// RED on pre-fix code: the compact path did
    /// `if let Some(cached) = pending_proposals.remove(&height) { (cached.header, Ok(cached)) }`,
    /// so it executed the cached 40-action block and its 40-count header.
    /// GREEN after: header is taken verbatim from the committed compact and the
    /// bodies are reconstructed from DA (all-or-nothing), so 59 actions execute.
    #[test]
    fn committed_block_ignores_stale_smaller_pending_proposal() {
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(torus_mempool::Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));

        // The COMMITTED block: 59 native actions (nonces 1..=59).
        let committed_actions: Vec<SignedNativeAction> =
            (1..=59u64).map(sign_claim_rewards).collect();
        let committed_block = make_block(130, committed_actions.clone());
        // Every committed body lives in the durable DA store (proposer mirror).
        let _ = mempool.mirror_native_to_da(&committed_actions);

        let mut app = TorusApp::new(state_db.clone(), &config, None, Some(mempool), None);

        // Capture what on_committed_block hands to the execution pipeline.
        let (tx, rx) = std::sync::mpsc::sync_channel::<CommittedBlockMsg>(4);
        app.replace_exec_tx(tx);

        // A STALE same-height re-proposal cached only 40 of those actions — the
        // devnet "proposer executed 40 of its own 59" state.
        let stale_actions: Vec<SignedNativeAction> = (1..=40u64).map(sign_claim_rewards).collect();
        let stale_block = make_block(130, stale_actions);
        app.pending_proposals
            .insert(130, PendingProposal::new(stale_block));

        let committed = committed_compact_block(&committed_block);
        app.on_committed_block(&committed, committed.hash);

        let msg = rx
            .try_recv()
            .expect("committed block must be sent to execution");
        assert_eq!(
            msg.torus_block.native_actions.len(),
            59,
            "execution must run the COMMITTED body (59), never the stale cache's 40"
        );
        assert_eq!(
            msg.torus_block.header.native_action_count, 59,
            "the persisted header count must be the committed 59, not the cache's 40"
        );
        assert_eq!(
            msg.torus_block.header.canonical_header_bytes(),
            committed_block.header.canonical_header_bytes(),
            "header handed to execution must be byte-identical to the committed header"
        );
    }

    /// S444 AT-LEAST-ONCE FEED, app-side idempotency (RED-first). The hotstuff
    /// committed-block feed is replayed from a durable frontier after a restart
    /// (the min-height exec-feed gap fix), so `on_committed_block` may re-deliver
    /// heights the app has ALREADY sent to execution. A re-delivery below the
    /// exec frontier must be a cheap no-op: no manifest re-write (they are pruned
    /// at dispatch and would otherwise leak), no buffering, no frontier movement.
    ///
    /// RED at 2a80ff0: `persist_commit_manifest` ran unconditionally as the first
    /// durable action of the callback, so a replayed height re-created its
    /// (already pruned) CF_COMMIT_MANIFEST entry.
    #[test]
    fn redelivered_committed_height_below_exec_frontier_is_skipped() {
        let mut app = TorusApp::stub();
        app.exec_next_height = Some(10);

        let old_block = make_block(5, vec![sign_claim_rewards(5)]);
        let committed = committed_compact_block(&old_block);
        app.on_committed_block(&committed, committed.hash);

        assert!(
            load_commit_manifest(&app.state_db, 5).is_none(),
            "a benign re-delivery below the exec frontier must NOT re-write its commit \
             manifest (pruned at dispatch; re-writing leaks it forever)"
        );
        assert!(
            app.deferred_exec.is_empty(),
            "a re-delivered height below the frontier must never be buffered for execution"
        );
        assert_eq!(
            app.exec_next_height,
            Some(10),
            "the exec frontier must not move on a re-delivery"
        );
    }

    /// T1.2 (b) RED-first: feeding the execute path a body with FEWER native
    /// actions than the committed header's `native_action_count` must FAIL-STOP
    /// (latch `exec_failed`) and persist NOTHING — never silently execute a
    /// partial body and persist a header rebuilt from the wrong count.
    ///
    /// RED on pre-fix code: `execute_committed_block` had no body/header count
    /// guard, so it executed the 2 actions and `persist_block_header` wrote the
    /// (divergent) header verbatim — with `exec_failed` never latched.
    /// GREEN after: the guard latches fail-stop and returns before any persist.
    #[test]
    fn execute_partial_body_vs_header_count_fail_stops() {
        let (config, state_db) = make_test_config_and_db();
        let exec_ctx = make_exec_ctx(&config, &state_db);

        // Header claims 5 native actions; the body only carries 2 — the exact
        // partial-body shape the completeness fix forbids.
        let mut block = make_block(7, vec![sign_claim_rewards(1), sign_claim_rewards(2)]);
        block.header.native_action_count = 5;

        exec_ctx.execute_committed_block(&block, vec![]);

        assert!(
            exec_ctx.exec_failed.load(Ordering::SeqCst),
            "a body/header native_action_count mismatch must latch the fail-stop"
        );
        assert!(
            state_db
                .get_cf_raw(CF_BLOCK_HEADERS, &7u64.to_be_bytes())
                .unwrap()
                .is_none(),
            "a divergent header must NOT be persisted"
        );
        assert!(
            read_native_applied_height(&state_db).is_none(),
            "a fail-stopped block must not be marked applied"
        );
    }

    /// T1.2 (c) guard: for a normal, well-formed block the persisted eth header
    /// must be byte-identical to the committed header — the header-verbatim
    /// invariant. Passes before and after the fix; a regression that rebuilds
    /// the header from execution results would break it.
    #[test]
    fn persisted_header_equals_committed_header_byte_for_byte() {
        let (config, state_db) = make_test_config_and_db();
        let exec_ctx = make_exec_ctx(&config, &state_db);

        let block = make_block(3, vec![sign_claim_rewards(11), sign_claim_rewards(12)]);
        exec_ctx.execute_committed_block(&block, vec![]);

        let stored = state_db
            .get_cf_raw(CF_BLOCK_HEADERS, &3u64.to_be_bytes())
            .unwrap()
            .expect("normal block must persist a header");
        // Layout (persist_block_header): [0..32] = committed block hash,
        // [32..] = serde(header). Both derive from the committed header verbatim.
        let want_hash = alloy_primitives::keccak256(block.header.canonical_header_bytes());
        assert_eq!(
            &stored[..32],
            want_hash.as_slice(),
            "persisted block hash must equal keccak(committed canonical header)"
        );
        let persisted_header: TorusBlockHeader =
            serde_json::from_slice(&stored[32..]).expect("persisted header decodes");
        assert_eq!(
            persisted_header.canonical_header_bytes(),
            block.header.canonical_header_bytes(),
            "persisted header must be byte-identical to the committed header"
        );
    }

    // ========================================================================
    // Regime-B STRICT-ORDER EXECUTION (never execute H+1 before H).
    //
    // EVIDENCE: a full devnet run ended with permanently-missing executed
    // heights (v2: 987-989, v3: 911-913) while LATER heights executed —
    // consensus committed past a block whose native bodies were not
    // reconstructable at that instant, the deferred-body path dropped it, and
    // later blocks executed anyway. Native matching is order-dependent, so an
    // interior hole is PERMANENT divergence. These tests pin the invariant:
    // on_committed_block hands blocks to `exec_tx` strictly in ascending height
    // with NO gaps; a missing-body height holds every later height until it heals.
    // ========================================================================

    /// Wire a TorusApp with a live mempool DA store and a RECORDING exec channel,
    /// so a test can observe exactly what (and in what order) on_committed_block
    /// hands to the execution pipeline. Returns the app, the receiver, and the
    /// mempool (to mirror bodies into the DA store, i.e. make them reconstructable).
    fn app_with_recording_exec(
        config: &ChainConfig,
        state_db: &StateDb,
    ) -> (
        TorusApp,
        std::sync::mpsc::Receiver<CommittedBlockMsg>,
        Arc<Mempool>,
    ) {
        let mempool = Arc::new(torus_mempool::Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let mut app = TorusApp::new(state_db.clone(), config, None, Some(mempool.clone()), None);
        let (tx, rx) = std::sync::mpsc::sync_channel::<CommittedBlockMsg>(64);
        app.replace_exec_tx(tx);
        (app, rx, mempool)
    }

    /// r4 commit-persist: the live dispatch path (`on_committed_block` →
    /// `dispatch_to_exec`) persists header+body durably FIRST and hands the exec
    /// thread a message that reports both rows durable, so exec skips the redundant
    /// rewrite. The rows must really be on disk when the message is sent, and the
    /// commit manifest for that height must be gone (pruned in the same batch).
    /// s77 order latency: the commit stage is observed once per native action
    /// when its committed block is handed to execution.
    #[test]
    fn order_age_commit_observed_at_dispatch() {
        let (config, state_db) = make_test_config_and_db();
        let (mut app, rx, mempool) = app_with_recording_exec(&config, &state_db);
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        app.metrics = Some(metrics.clone());

        let a5 = vec![sign_claim_rewards(5), sign_claim_rewards(6)];
        let _ = mempool.mirror_native_to_da(&a5);
        let b5 = make_block(5, a5);
        app.exec_next_height = Some(5);
        let c5 = committed_compact_block(&b5);
        app.on_committed_block(&c5, c5.hash);
        rx.try_recv().expect("height 5 must reach execution");

        let text = metrics.encode();
        assert!(
            text.contains("torus_order_age_commit_seconds_count 2"),
            "one commit observation per native action:\n{text}"
        );
    }

    #[test]
    fn dispatch_reports_durable_rows_after_persisting_them() {
        let (config, state_db) = make_test_config_and_db();
        let (mut app, rx, mempool) = app_with_recording_exec(&config, &state_db);

        let a5 = vec![sign_claim_rewards(5)];
        let _ = mempool.mirror_native_to_da(&a5);
        let b5 = make_block(5, a5);
        app.exec_next_height = Some(5);

        let c5 = committed_compact_block(&b5);
        app.on_committed_block(&c5, c5.hash);

        let msg = rx.try_recv().expect("height 5 must reach execution");
        assert_eq!(msg.torus_block.header.height, 5);
        assert_eq!(
            msg.durable,
            DurableRows {
                header: true,
                body: true
            },
            "dispatch must report both durable rows so exec skips the rewrite"
        );
        let key = 5u64.to_be_bytes();
        assert!(
            state_db.get_cf_raw(CF_BLOCK_HEADERS, &key).unwrap().is_some(),
            "header row must already be durable when the message is sent"
        );
        let body = load_replay_body(&state_db, 5).expect("body row must already be durable");
        assert_eq!(body.native_actions.len(), 1);
        assert!(
            state_db.get_cf_raw(CF_COMMIT_MANIFEST, &key).unwrap().is_none(),
            "commit manifest pruned at dispatch (same batch as the durable body)"
        );
    }

    /// RED-first (out-of-order delivery): the execution pipeline must NEVER
    /// receive H+1 before H, even when H+1's bodies are fully available and H has
    /// not yet arrived. RED on pre-fix code: `on_committed_block` sent every
    /// reconstructable block immediately, so a committed H+1 executed while H was
    /// still deferred — the permanent interior-hole divergence. GREEN: H+1 is
    /// buffered until H arrives, then both drain in strict order.
    #[test]
    fn exec_pipeline_never_runs_higher_height_before_lower() {
        let (config, state_db) = make_test_config_and_db();
        let (mut app, rx, mempool) = app_with_recording_exec(&config, &state_db);

        // Both bodies are present in the DA store (nothing missing here — this is
        // pure ordering, not a hole).
        let a5 = vec![sign_claim_rewards(5)];
        let a6 = vec![sign_claim_rewards(6)];
        let _ = mempool.mirror_native_to_da(&a5);
        let _ = mempool.mirror_native_to_da(&a6);
        let b5 = make_block(5, a5);
        let b6 = make_block(6, a6);

        // The pipeline expects height 5 next.
        app.exec_next_height = Some(5);

        // H+1 (6) is committed with its body READY, but H (5) has not arrived.
        let c6 = committed_compact_block(&b6);
        app.on_committed_block(&c6, c6.hash);
        assert!(
            rx.try_recv().is_err(),
            "H+1 must NOT reach execution before H — strict height order (RED on pre-fix code)"
        );

        // H (5) arrives → 5 then 6 drain in ascending order.
        let c5 = committed_compact_block(&b5);
        app.on_committed_block(&c5, c5.hash);
        assert_eq!(
            rx.try_recv().unwrap().torus_block.header.height,
            5,
            "H executes first"
        );
        assert_eq!(
            rx.try_recv().unwrap().torus_block.header.height,
            6,
            "then H+1"
        );
        assert!(rx.try_recv().is_err(), "nothing else queued");
        assert!(!app.is_exec_failed(), "in-order delivery must not fail-stop");
    }

    /// RED-first (deferred hole heals): a committed block whose native bodies are
    /// initially missing is DEFERRED (not executed); a later committed block waits
    /// behind it; once the missing bodies land in the DA store, the next commit
    /// drives BOTH (and the follower) through execution in strict order.
    #[test]
    fn deferred_hole_executes_in_order_once_bodies_arrive() {
        let (config, state_db) = make_test_config_and_db();
        let (mut app, rx, mempool) = app_with_recording_exec(&config, &state_db);

        let a5 = vec![sign_claim_rewards(5)];
        let a6 = vec![sign_claim_rewards(6)];
        let a7 = vec![sign_claim_rewards(7)];
        // Initially only 6 and 7 are reconstructable; 5's body is MISSING.
        let _ = mempool.mirror_native_to_da(&a6);
        let _ = mempool.mirror_native_to_da(&a7);
        let b5 = make_block(5, a5.clone());
        let b6 = make_block(6, a6);
        let b7 = make_block(7, a7);

        app.exec_next_height = Some(5);

        // H=5 committed but body missing → deferred, nothing executes.
        let c5 = committed_compact_block(&b5);
        app.on_committed_block(&c5, c5.hash);
        assert!(
            rx.try_recv().is_err(),
            "a missing-body committed block must defer, not execute"
        );
        assert!(
            app.exec_hole_since.is_some(),
            "the hole clock must start when the head-of-line body is missing"
        );

        // H+1=6 committed WITH its body → must wait behind the hole at 5.
        let c6 = committed_compact_block(&b6);
        app.on_committed_block(&c6, c6.hash);
        assert!(
            rx.try_recv().is_err(),
            "H+1 must wait behind the deferred hole at H (no out-of-order execution)"
        );

        // Heal: 5's body arrives in the DA store; the next commit (7) drives the drain.
        let _ = mempool.mirror_native_to_da(&a5);
        let c7 = committed_compact_block(&b7);
        app.on_committed_block(&c7, c7.hash);

        assert_eq!(rx.try_recv().unwrap().torus_block.header.height, 5, "5 first");
        assert_eq!(rx.try_recv().unwrap().torus_block.header.height, 6, "then 6");
        assert_eq!(rx.try_recv().unwrap().torus_block.header.height, 7, "then 7");
        assert!(rx.try_recv().is_err(), "exactly three blocks, in order");
        assert!(
            !app.is_exec_failed(),
            "a healed hole must NOT latch fail-stop"
        );
        assert!(
            app.exec_hole_since.is_none(),
            "healing the hole must clear the hole clock"
        );
    }

    /// RED-first (heal-budget exhaustion): an execution hole that cannot heal
    /// within the budget must latch `exec_failed` — a node that cannot obtain a
    /// committed block's bodies is broken, and a silent divergence is worse than a
    /// halt. First detection stays WITHIN budget (retry, no latch); once the
    /// budget elapses, the next re-attempt latches the fail-stop.
    #[test]
    fn exec_hole_budget_exhaustion_latches_fail_stop() {
        let (config, state_db) = make_test_config_and_db();
        let (mut app, _rx, _mempool) = app_with_recording_exec(&config, &state_db);

        // 5's body is PERMANENTLY absent from the DA store (never mirrored).
        let b5 = make_block(5, vec![sign_claim_rewards(5)]);
        let b6 = make_block(6, vec![]); // empty follower, always reconstructable

        app.exec_next_height = Some(5);

        // First hit: hole detected, still within budget → retrying, NOT latched.
        let c5 = committed_compact_block(&b5);
        app.on_committed_block(&c5, c5.hash);
        assert!(
            !app.is_exec_failed(),
            "a fresh hole within budget must keep retrying, not fail-stop"
        );
        assert!(
            app.exec_hole_since.is_some(),
            "the hole clock must start on first detection"
        );

        // Simulate the heal budget elapsing (default 5 min).
        app.exec_hole_since =
            Some(std::time::Instant::now() - std::time::Duration::from_secs(6 * 60));

        // The next commit re-attempts the still-broken hole → budget exhausted →
        // fail-stop latched (halt, never diverge silently).
        let c6 = committed_compact_block(&b6);
        app.on_committed_block(&c6, c6.hash);
        assert!(
            app.is_exec_failed(),
            "a hole that cannot heal within the budget must latch exec_failed"
        );
    }

    // ======================================================================
    // bl2 exec pipeline (TORUS_EXEC_PIPELINE): hazard-table tests
    // (docs/perf/design-exec-pipeline-2026-08-20.md §5)
    // ======================================================================

    /// The adversarial block sequence every pipeline test runs (heights 1..=13,
    /// `epoch_length` 4 so heights 4/8/12 are epoch boundaries — serial under the
    /// pipeline). Encodes every read-your-writes hazard of the design:
    ///   1  fund A,B (TransferToPerp)                      native
    ///   2  empty                                          Marker job
    ///   3  A sell 100 x1, B buy 100 x1 -> fill            native (reads 1 across an empty)
    ///   4  ClaimRewards (epoch boundary -> barrier)       native, SERIAL
    ///   5  A sell 101 x1 resting                          native
    ///   6  B buy 101 x1 + DUPLICATE of 5's sell           native (nonce guard reads 5 via layer)
    ///   7  empty                                          Marker job
    ///   8  empty (epoch boundary)                         serial marker
    ///   9  A CreateSession(S)                             native
    ///  10  S-signed sell 102 x1 (verify reads 9's session via layer)   native
    ///  11  B buy 102 x1 -> fill                           native
    ///  12  empty (epoch boundary)                         serial marker
    ///  13  A sell 103 x1 (balance written in 11, read across an empty)  native
    fn pipeline_fixture_blocks() -> Vec<TorusBlock> {
        let k_a = k256::ecdsa::SigningKey::from_slice(&[41u8; 32]).unwrap();
        let k_b = k256::ecdsa::SigningKey::from_slice(&[42u8; 32]).unwrap();
        let s_key = ed25519_dalek::SigningKey::from_bytes(&[43u8; 32]);
        let deposit = U256::from(1_000 * FixedPoint::ONE.raw() as u128);
        let order = |is_buy: bool, price: i128| torus_types::PlaceOrderParams {
            market_id: 1,
            is_buy,
            price: FixedPoint::from_raw(price * FixedPoint::SCALE),
            quantity: FixedPoint::from_raw(FixedPoint::SCALE),
            order_type: torus_types::OrderType::Limit,
            time_in_force: torus_types::TimeInForce::GTC,
            reduce_only: false,
            client_order_id: None,
        };
        let sign = |a: NativeAction, n: u64, k: &k256::ecdsa::SigningKey| {
            torus_types::eip712::sign_native_action(a, NONCE_BASE + n, k)
        };
        let sell5 = sign(NativeAction::PlaceOrder(order(false, 101)), 9_004, &k_a);
        let session_expiry = (1000 + 9) * 1000 + 3_600_000;
        let mut blocks = vec![
            make_block(
                1,
                vec![
                    sign(NativeAction::TransferToPerp { amount: deposit }, 9_000, &k_a),
                    sign(NativeAction::TransferToPerp { amount: deposit }, 9_001, &k_b),
                ],
            ),
            make_block(2, vec![]),
            make_block(
                3,
                vec![
                    sign(NativeAction::PlaceOrder(order(false, 100)), 9_002, &k_a),
                    sign(NativeAction::PlaceOrder(order(true, 100)), 9_003, &k_b),
                ],
            ),
            make_block(4, vec![sign_claim_rewards(NONCE_BASE + 4)]),
            make_block(5, vec![sell5.clone()]),
            make_block(
                6,
                vec![
                    sign(NativeAction::PlaceOrder(order(true, 101)), 9_005, &k_b),
                    sell5,
                ],
            ),
            make_block(7, vec![]),
            make_block(8, vec![]),
            make_block(
                9,
                vec![sign(
                    NativeAction::CreateSession {
                        session_pubkey: s_key.verifying_key().to_bytes(),
                        expiry: session_expiry,
                        scope: torus_types::SessionScope::Trading,
                    },
                    9_006,
                    &k_a,
                )],
            ),
            make_block(
                10,
                vec![torus_types::eip712::sign_native_action_with_session(
                    NativeAction::PlaceOrder(order(false, 102)),
                    NONCE_BASE + 9_007,
                    &s_key,
                )],
            ),
            make_block(
                11,
                vec![sign(NativeAction::PlaceOrder(order(true, 102)), 9_008, &k_b)],
            ),
            make_block(12, vec![]),
            make_block(
                13,
                vec![sign(NativeAction::PlaceOrder(order(false, 103)), 9_009, &k_a)],
            ),
        ];
        link_blocks(&mut blocks);
        blocks
    }

    /// Link `parent_hash` to the ACTUAL predecessor (fixtures are non-empty).
    fn link_blocks(blocks: &mut [TorusBlock]) {
        for i in 1..blocks.len() {
            let parent = alloy_primitives::keccak256(blocks[i - 1].header.canonical_header_bytes());
            blocks[i].header.parent_hash = parent;
        }
    }

    /// The EVM balances the fixture's TransferToPerp actions draw from.
    fn fund_pipeline_fixture(state_db: &StateDb) {
        let deposit = U256::from(1_000 * FixedPoint::ONE.raw() as u128);
        for signed in &pipeline_fixture_blocks()[0].native_actions {
            fund_evm_balance(state_db, signed.recover_sender().unwrap(), deposit);
        }
    }

    fn pipeline_ctx(
        state_db: &StateDb,
        on: bool,
        gate: Option<Arc<crate::exec_pipeline::WorkerGate>>,
    ) -> ExecutionContext {
        let (mut config, _) = make_test_config_and_db();
        config.epoch_length = 4;
        let mut ctx = make_exec_ctx(&config, state_db);
        if on {
            ctx.attach_flush_worker(gate);
        }
        ctx
    }

    /// The LIVE dispatch path: header+body durable at commit, then exec with the
    /// durable rows (what makes a block eligible for the fast path).
    fn dispatch_and_execute(ctx: &ExecutionContext, state_db: &StateDb, block: &TorusBlock) {
        let durable = persist_committed_block_durably(state_db, block);
        assert!(durable.header && durable.body, "fixture rows must be dispatch-durable");
        ctx.execute_committed_block_with(block, vec![], durable);
    }

    /// One CF's `(key, value)` rows, tagged with the CF name.
    type CfDump = (&'static str, Vec<(Vec<u8>, Vec<u8>)>);

    fn dump_all_cfs(state_db: &StateDb) -> Vec<CfDump> {
        torus_state::cf::ALL_CF_NAMES
            .iter()
            .map(|cf| (*cf, StateBackend::iterate_cf(state_db, cf, None).unwrap()))
            .collect()
    }

    fn assert_dumps_equal(a: &[CfDump], b: &[CfDump], what: &str) {
        for ((cf, x), (_, y)) in a.iter().zip(b.iter()) {
            assert_eq!(x, y, "{what}: CF {cf} diverged");
        }
    }

    /// Run the fixture OFF (serial) or ON (pipeline), drain, return the full state
    /// dump + persisted native root + the ctx's fail-stop latch.
    fn run_pipeline_fixture(on: bool) -> (StateDb, Vec<CfDump>, torus_types::B256, Vec<u64>) {
        torus_state::native_trie::force_native_trie_maintenance_on_for_tests();
        let (_cfg, state_db) = make_test_config_and_db();
        fund_pipeline_fixture(&state_db);
        let gate = crate::exec_pipeline::WorkerGate::new();
        let ctx = pipeline_ctx(&state_db, on, Some(gate.clone()));
        for b in &pipeline_fixture_blocks() {
            dispatch_and_execute(&ctx, &state_db, b);
        }
        assert!(
            !ctx.exec_failed.load(std::sync::atomic::Ordering::SeqCst),
            "fixture must not fail-stop (on={on})"
        );
        drop(ctx); // drains + joins W
        let dump = dump_all_cfs(&state_db);
        let root = torus_state::native_trie::persisted_native_root(&state_db).unwrap();
        (state_db, dump, root, gate.received())
    }

    /// §5 `exec_pipeline_state_identical_over_sequence`: the same sequence ON vs
    /// s77 order latency: over the pipeline fixture, serial and pipelined, every
    /// native action is observed once at `exec` and once at `durable` (serial
    /// flush, flush worker, or barrier), and `fills_visible` exactly for the
    /// actions of the blocks whose trade rows were written.
    #[test]
    fn order_age_stages_observed_once_per_native_action() {
        // `writer = false`: no trade writer, rows take the synchronous fallback.
        for (on, writer) in [(false, true), (true, true), (false, false), (true, false)] {
            let (_cfg, state_db) = make_test_config_and_db();
            fund_pipeline_fixture(&state_db);
            let (mut config, _) = make_test_config_and_db();
            config.epoch_length = 4;
            let mut ctx = make_exec_ctx(&config, &state_db);
            let metrics = Arc::new(torus_telemetry::Metrics::new());
            ctx.metrics = Some(metrics.clone());
            ctx.trade_writer = writer.then(|| {
                torus_state::BackgroundCfWriter::spawn(state_db.clone(), "test-trade-writer", 8)
            });
            if on {
                ctx.attach_flush_worker(None);
            }
            let blocks = pipeline_fixture_blocks();
            for b in &blocks {
                dispatch_and_execute(&ctx, &state_db, b);
            }
            drop(ctx); // drains + joins W and the trade writer

            let native: usize = blocks.iter().map(|b| b.native_actions.len()).sum();
            let traded: std::collections::BTreeSet<u64> =
                StateBackend::iterate_cf(&state_db, torus_state::cf::CF_NATIVE_TRADES, None)
                    .unwrap()
                    .iter()
                    .map(|(k, _)| torus_state::trade_rows::parse_trade_key(k).unwrap().1)
                    .collect();
            let filled: usize = blocks
                .iter()
                .filter(|b| traded.contains(&b.header.height))
                .map(|b| b.native_actions.len())
                .sum();
            assert!(filled > 0, "fixture must produce fills (on={on} writer={writer})");

            let text = metrics.encode();
            let count = |stage: &str| {
                metric_value(&text, &format!("torus_order_age_{stage}_seconds_count")) as usize
            };
            assert_eq!(count("exec"), native, "exec (on={on} writer={writer}):\n{text}");
            assert_eq!(count("durable"), native, "durable (on={on} writer={writer}):\n{text}");
            assert_eq!(count("fills_visible"), filled, "fills_visible (on={on} writer={writer}):\n{text}");
        }
    }

    /// s77: the trade-writer backlog gauge must stay live on blocks WITHOUT
    /// trades (empties keep coming while the chain drains); the harness drain
    /// waits on it, so a value frozen at the last trade block would hang it.
    #[test]
    fn trade_writer_gauge_refreshes_on_blocks_without_trades() {
        let (_cfg, state_db) = make_test_config_and_db();
        fund_pipeline_fixture(&state_db);
        let (mut config, _) = make_test_config_and_db();
        config.epoch_length = 4;
        let mut ctx = make_exec_ctx(&config, &state_db);
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        ctx.metrics = Some(metrics.clone());
        ctx.trade_writer = Some(torus_state::BackgroundCfWriter::spawn(
            state_db.clone(),
            "test-trade-writer",
            8,
        ));
        let blocks = pipeline_fixture_blocks();
        for b in &blocks {
            dispatch_and_execute(&ctx, &state_db, b);
        }
        let writer = ctx.trade_writer.as_ref().unwrap();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while writer.queued_batches() > 0 {
            assert!(std::time::Instant::now() < deadline, "writer never drained");
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        let last = blocks.last().unwrap();
        let mut empty = make_block(last.header.height + 1, vec![]);
        empty.header.parent_hash = alloy_primitives::keccak256(last.header.canonical_header_bytes());
        dispatch_and_execute(&ctx, &state_db, &empty);

        let text = metrics.encode();
        assert_eq!(
            metric_value(&text, "torus_trade_writer_queued_batches"),
            0.0,
            "an empty block must refresh the drained writer's gauge:\n{text}"
        );
    }

    /// s77 trade-history switch: with trade history OFF no row reaches the two
    /// node-local trade CFs, and every OTHER CF plus the persisted native root
    /// is byte-identical to a run with it ON — the switch cannot touch
    /// consensus state.
    #[test]
    fn trade_history_off_writes_no_trade_rows_and_leaves_state_identical() {
        torus_state::native_trie::force_native_trie_maintenance_on_for_tests();
        let run = |history: bool| {
            let (_cfg, state_db) = make_test_config_and_db();
            fund_pipeline_fixture(&state_db);
            let (mut config, _) = make_test_config_and_db();
            config.epoch_length = 4;
            let mut ctx = make_exec_ctx(&config, &state_db);
            ctx.trade_history = history;
            for b in &pipeline_fixture_blocks() {
                dispatch_and_execute(&ctx, &state_db, b);
            }
            drop(ctx);
            let root = torus_state::native_trie::persisted_native_root(&state_db).unwrap();
            (dump_all_cfs(&state_db), root)
        };
        let (on, root_on) = run(true);
        let (off, root_off) = run(false);
        let trade_cfs = [
            torus_state::cf::CF_NATIVE_TRADES,
            torus_state::cf::CF_NATIVE_USER_TRADES,
        ];
        for ((cf, rows_on), (_, rows_off)) in on.iter().zip(off.iter()) {
            if trade_cfs.contains(cf) {
                assert!(!rows_on.is_empty(), "fixture must write {cf} when on");
                assert!(rows_off.is_empty(), "{cf} must stay empty when off");
            } else {
                assert_eq!(rows_on, rows_off, "CF {cf} must not depend on trade history");
            }
        }
        assert_eq!(root_on, root_off, "native root must not depend on trade history");
    }

    type SeenFills = Arc<std::sync::Mutex<Vec<Arc<torus_state::trade_rows::BlockFills>>>>;

    /// s80: a recording fill sink; `wants` is what `wants_fills` reports.
    struct TestSink {
        wants: bool,
        seen: SeenFills,
    }

    impl torus_state::trade_rows::FillSink for TestSink {
        fn wants_fills(&self) -> bool {
            self.wants
        }
        fn send_fills(&self, block: Arc<torus_state::trade_rows::BlockFills>) {
            self.seen.lock().unwrap().push(block);
        }
    }

    /// s80: run the pipeline fixture (exec pipeline `on`/off, trade history
    /// on/off, optionally with a recording fill sink whose `wants_fills` is
    /// `sink_wants`), drain, and return the full dump, the persisted native
    /// root and what the sink received.
    fn run_fill_fixture(
        on: bool,
        history: bool,
        sink_wants: Option<bool>,
    ) -> (Vec<CfDump>, torus_types::B256, Option<Vec<Arc<torus_state::trade_rows::BlockFills>>>) {
        torus_state::native_trie::force_native_trie_maintenance_on_for_tests();
        let (_cfg, state_db) = make_test_config_and_db();
        fund_pipeline_fixture(&state_db);
        let mut ctx = pipeline_ctx(&state_db, on, None);
        ctx.trade_history = history;
        let seen: SeenFills = Default::default();
        if let Some(wants) = sink_wants {
            let sink: Arc<dyn torus_state::trade_rows::FillSink> =
                Arc::new(TestSink { wants, seen: seen.clone() });
            assert!(ctx.fill_sink.set(sink).is_ok());
        }
        for b in &pipeline_fixture_blocks() {
            dispatch_and_execute(&ctx, &state_db, b);
        }
        assert!(!ctx.exec_failed.load(Ordering::SeqCst), "fixture must not fail-stop");
        drop(ctx); // drains + joins W
        let root = torus_state::native_trie::persisted_native_root(&state_db).unwrap();
        let seen = sink_wants.is_some().then(|| seen.lock().unwrap().clone());
        (dump_all_cfs(&state_db), root, seen)
    }

    fn cf_rows<'a>(dump: &'a [CfDump], cf: &str) -> &'a [(Vec<u8>, Vec<u8>)] {
        &dump.iter().find(|(name, _)| *name == cf).unwrap().1
    }

    /// (height, fill count, first fill's trade_index) per delivered block.
    fn fill_summary(seen: &[Arc<torus_state::trade_rows::BlockFills>]) -> Vec<(u64, usize, u32)> {
        seen.iter()
            .map(|b| (b.height, b.fills.len(), b.fills[0].trade_index))
            .collect()
    }

    /// s80: every executed block with fills reaches the sink exactly once, in
    /// height order, with serial and pipelined execution alike — and the
    /// delivered fills equal the trade-history rows for the same heights.
    #[test]
    fn fill_sink_receives_every_executed_block_in_order() {
        for on in [false, true] {
            let (dump, _root, seen) = run_fill_fixture(on, true, Some(true));
            let seen = seen.unwrap();
            assert_eq!(
                fill_summary(&seen),
                vec![(3, 1, 0), (6, 1, 0), (11, 1, 0)],
                "pipeline on={on}"
            );
            let mut from_rows = Vec::new();
            for (key, value) in cf_rows(&dump, torus_state::cf::CF_NATIVE_TRADES) {
                let (market, height, _chunk) = torus_state::trade_rows::parse_trade_key(key).unwrap();
                let (ts, trades) = torus_state::trade_rows::decode_trade_row(value).unwrap();
                for t in trades {
                    from_rows.push((height, ts, market, t));
                }
            }
            let from_sink: Vec<_> = seen
                .iter()
                .flat_map(|b| {
                    b.fills.iter().map(|f| {
                        let t = torus_state::trade_rows::MarketTrade {
                            trade_index: f.trade_index,
                            price_raw: f.price_raw,
                            qty_raw: f.qty_raw,
                            taker_side: f.taker_side,
                        };
                        (b.height, b.timestamp, f.market, t)
                    })
                })
                .collect();
            assert_eq!(from_sink, from_rows, "stream and history disagree (on={on})");
            for b in &seen {
                // A wanting sink: every fill carries its extras.
                assert_eq!(b.extras.len(), b.fills.len(), "extras index-aligned (on={on})");
                for e in &b.extras {
                    assert_ne!(e.maker_order_id, 0, "extras carry order ids");
                    assert_ne!(e.taker_order_id, 0, "extras carry order ids");
                }
            }
        }
    }

    /// s80 fix 1: with trade history ON and a sink nobody listens to
    /// (`wants_fills` false), blocks still reach the sink (for `newTrades`)
    /// but carry no extras, and every CF and the native root match a run
    /// without a sink.
    #[test]
    fn fill_sink_not_wanted_with_history_on_gets_fills_without_extras() {
        for on in [false, true] {
            let (plain, root_plain, _) = run_fill_fixture(on, true, None);
            let (idle, root_idle, seen) = run_fill_fixture(on, true, Some(false));
            let seen = seen.unwrap();
            assert_eq!(fill_summary(&seen), vec![(3, 1, 0), (6, 1, 0), (11, 1, 0)], "on={on}");
            assert!(seen.iter().all(|b| b.extras.is_empty()), "no subscriber, no extras (on={on})");
            let (_, _, wanted) = run_fill_fixture(on, true, Some(true));
            for (a, b) in seen.iter().zip(wanted.unwrap().iter()) {
                assert_eq!(a.fills, b.fills, "the fills do not depend on a subscriber (on={on})");
            }
            assert_dumps_equal(&plain, &idle, &format!("idle sink vs none, history on (on={on})"));
            assert_eq!(root_plain, root_idle, "native root (on={on})");
        }
    }

    /// s80: with trade history OFF a sink still gets the same blocks, and no
    /// trade row is written.
    #[test]
    fn fill_sink_works_with_trade_history_off() {
        for on in [false, true] {
            let (_, _, with_history) = run_fill_fixture(on, true, Some(true));
            let (dump, _root, seen) = run_fill_fixture(on, false, Some(true));
            let seen = seen.unwrap();
            assert_eq!(fill_summary(&seen), vec![(3, 1, 0), (6, 1, 0), (11, 1, 0)]);
            let with_history = with_history.unwrap();
            for (a, b) in seen.iter().zip(with_history.iter()) {
                assert_eq!(
                    (a.height, a.timestamp, &a.fills, &a.extras),
                    (b.height, b.timestamp, &b.fills, &b.extras)
                );
            }
            for cf in [torus_state::cf::CF_NATIVE_TRADES, torus_state::cf::CF_NATIVE_USER_TRADES] {
                assert!(cf_rows(&dump, cf).is_empty(), "{cf} must stay empty (on={on})");
            }
        }
    }

    /// s80: installing a sink changes nothing on disk — every CF and the
    /// persisted native root match a run without one (history on and off).
    #[test]
    fn no_fill_sink_leaves_state_identical() {
        for on in [false, true] {
            for history in [true, false] {
                let (plain, root_plain, _) = run_fill_fixture(on, history, None);
                let (sunk, root_sunk, _) = run_fill_fixture(on, history, Some(true));
                assert_dumps_equal(&plain, &sunk, &format!("sink vs none (on={on} history={history})"));
                assert_eq!(root_plain, root_sunk, "native root (on={on} history={history})");
            }
        }
    }

    /// s80 review: with trade history OFF and a sink installed that nobody
    /// listens to (`wants_fills` false, e.g. a validator with no stream
    /// subscriber), no fill is recorded — the sink gets nothing, no trade row
    /// is written, and every CF and the native root match a run without a sink.
    #[test]
    fn fill_sink_not_wanted_records_nothing_with_history_off() {
        for on in [false, true] {
            let (plain, root_plain, _) = run_fill_fixture(on, false, None);
            let (idle, root_idle, seen) = run_fill_fixture(on, false, Some(false));
            assert!(seen.unwrap().is_empty(), "an unwanted sink must receive nothing (on={on})");
            for cf in [torus_state::cf::CF_NATIVE_TRADES, torus_state::cf::CF_NATIVE_USER_TRADES] {
                assert!(cf_rows(&idle, cf).is_empty(), "{cf} must stay empty (on={on})");
            }
            assert_dumps_equal(&plain, &idle, &format!("idle sink vs none (on={on})"));
            assert_eq!(root_plain, root_idle, "native root (on={on})");
        }
    }

    /// OFF yields byte-identical state in EVERY CF and the same persisted native
    /// root — across empties, an epoch boundary (serial), a duplicated action
    /// (nonce guard through the layer), a session created in k and used by verify
    /// in k+1, and keys written in k and read in k+2.
    #[test]
    fn exec_pipeline_state_identical_over_sequence() {
        let (db_off, off, root_off, received_off) = run_pipeline_fixture(false);
        let (db_on, on, root_on, received_on) = run_pipeline_fixture(true);
        assert!(received_off.is_empty(), "serial binary: W never exists");
        // Every non-boundary height went through W (Flush for native, Marker for
        // empty); boundaries 4/8/12 were serial barriers (F2/F8).
        assert_eq!(received_on, vec![1, 2, 3, 5, 6, 7, 9, 10, 11, 13]);
        assert_dumps_equal(&off, &on, "pipeline ON vs OFF");
        assert_eq!(root_off, root_on, "persisted native root must be identical");
        assert_eq!(read_native_applied_height(&db_on), Some(13));
        assert_eq!(read_native_applied_height(&db_off), Some(13));
        // Sanity: the fixture actually produced fills and resting orders (the
        // comparison is not vacuous).
        let trades =
            StateBackend::iterate_cf(&db_on, torus_state::cf::CF_NATIVE_TRADES, None).unwrap();
        assert_eq!(trades.len(), 3, "fills at heights 3, 6 and 11");
        let nonces =
            StateBackend::iterate_cf(&db_on, torus_state::cf::CF_NATIVE_NONCES, None).unwrap();
        assert_eq!(nonces.len(), 11, "10 distinct fixture nonces + sign_claim_rewards(4); the duplicate in 6 consumed none");
    }

    /// §5 `exec_pipeline_parked_worker_reads_previous_height` (F1/F6 + depth
    /// bound + marker ordering): with W parked INSIDE job 1, the FIRST hand-off
    /// after it (the empty block 2's Marker job) blocks at the rendezvous — E
    /// cannot run two blocks ahead. Once released, block 3 (a fill that spends
    /// balances written only by block 1) executes correctly, and the marker ends
    /// at 3 with 2 never overwritten by batch(1).
    #[test]
    fn exec_pipeline_parked_worker_blocks_next_handoff_and_reads_previous_height() {
        let (_cfg, state_db) = make_test_config_and_db();
        fund_pipeline_fixture(&state_db);
        let blocks = pipeline_fixture_blocks();
        let gate = crate::exec_pipeline::WorkerGate::new();
        let ctx = pipeline_ctx(&state_db, true, Some(gate.clone()));

        gate.hold();
        dispatch_and_execute(&ctx, &state_db, &blocks[0]); // native 1 -> W received, parked
        assert!(gate.wait_received(1), "W must have taken job 1");
        assert_eq!(gate.received(), vec![1]);
        assert_eq!(ctx.exec_applied.load(std::sync::atomic::Ordering::SeqCst), 1);
        assert_eq!(read_native_applied_height(&state_db), None, "batch(1) not durable yet");

        // Block 2 must block at the hand-off (W still holds 1) — run it on a thread.
        let db2 = state_db.clone();
        let b2 = blocks[1].clone();
        let b3 = blocks[2].clone();
        let worker_thread = std::thread::spawn(move || {
            dispatch_and_execute(&ctx, &db2, &b2);
            dispatch_and_execute(&ctx, &db2, &b3);
            ctx
        });
        std::thread::sleep(std::time::Duration::from_millis(200));
        assert!(!worker_thread.is_finished(), "E must block on the FIRST hand-off after a parked job");
        assert_eq!(gate.received(), vec![1], "W must not have received job 2 while parked on 1");
        assert_eq!(read_native_applied_height(&state_db), None);

        gate.release();
        let ctx = worker_thread.join().unwrap();
        assert!(!ctx.exec_failed.load(std::sync::atomic::Ordering::SeqCst));
        drop(ctx);
        assert_eq!(gate.received(), vec![1, 2, 3]);
        assert_eq!(read_native_applied_height(&state_db), Some(3), "marker advanced in order: 1, 2, 3");
        let trades =
            StateBackend::iterate_cf(&state_db, torus_state::cf::CF_NATIVE_TRADES, None).unwrap();
        assert_eq!(trades.len(), 1, "block 3's fill spent balances written by block 1");
    }

    /// §5 `exec_pipeline_redelivery_is_skipped` (F3): while batch(1) is still on
    /// W, re-delivering block 1 must be SKIPPED by E's logical watermark — the
    /// durable marker still says "not applied". W receives exactly one job for 1,
    /// the deposits are debited once, no fail-stop (same hash = not a conflict).
    #[test]
    fn exec_pipeline_redelivery_is_skipped() {
        let (_cfg, state_db) = make_test_config_and_db();
        fund_pipeline_fixture(&state_db);
        let blocks = pipeline_fixture_blocks();
        let gate = crate::exec_pipeline::WorkerGate::new();
        let ctx = pipeline_ctx(&state_db, true, Some(gate.clone()));
        let a = blocks[0].native_actions[0].recover_sender().unwrap();
        let start = read_evm_balance(&state_db, a);

        gate.hold();
        dispatch_and_execute(&ctx, &state_db, &blocks[0]);
        assert_eq!(read_native_applied_height(&state_db), None);
        // Re-deliver 1 (same block, same hash) — synchronous skip, no hand-off.
        dispatch_and_execute(&ctx, &state_db, &blocks[0]);
        assert!(!ctx.exec_failed.load(std::sync::atomic::Ordering::SeqCst), "same hash is not a conflict");
        gate.release();
        drop(ctx);
        assert_eq!(gate.received(), vec![1], "exactly one job for height 1");
        assert_eq!(
            start - read_evm_balance(&state_db, a),
            U256::from(1_000 * FixedPoint::ONE.raw() as u128),
            "deposit debited exactly once"
        );
        assert_eq!(read_native_applied_height(&state_db), Some(1));
    }

    /// §5 `exec_pipeline_crash_before_write_replays_both` + `write_error_latches_failstop`
    /// (C1/C3): batch(2) fails on W AFTER E already executed block 3 on top of
    /// pending(2). E's hand-off of 3 sees the latch -> fail-stop, nothing of 2 or 3
    /// is written (marker stays 1, no trade rows). "Restart": a fresh serial
    /// context's `replay_committed` re-executes 2 and 3 from the dispatch-durable
    /// bodies and lands EXACTLY the serial state.
    #[test]
    fn exec_pipeline_crash_before_write_replays_both_and_matches_serial() {
        let blocks = pipeline_fixture_blocks();
        let first3 = &blocks[..3];

        // Reference: serial run of 1..=3.
        let (_c0, db_ref) = make_test_config_and_db();
        fund_pipeline_fixture(&db_ref);
        let ctx_ref = pipeline_ctx(&db_ref, false, None);
        for b in first3 {
            dispatch_and_execute(&ctx_ref, &db_ref, b);
        }
        drop(ctx_ref);
        let dump_ref = dump_all_cfs(&db_ref);

        // Pipelined run that "crashes" with batch(2) undurable.
        let (_c1, state_db) = make_test_config_and_db();
        fund_pipeline_fixture(&state_db);
        let gate = crate::exec_pipeline::WorkerGate::new();
        let ctx = pipeline_ctx(&state_db, true, Some(gate.clone()));
        dispatch_and_execute(&ctx, &state_db, &first3[0]);
        assert!(ctx.flush_worker.as_ref().unwrap().wait_idle());
        assert_eq!(read_native_applied_height(&state_db), Some(1));

        gate.hold();
        dispatch_and_execute(&ctx, &state_db, &first3[1]); // Marker(2) received, parked
        assert!(gate.wait_received(2));
        let db_t = state_db.clone();
        let b3 = first3[2].clone();
        let t = std::thread::spawn(move || {
            dispatch_and_execute(&ctx, &db_t, &b3); // engine(3) runs on pending(2); hand-off blocks
            ctx
        });
        std::thread::sleep(std::time::Duration::from_millis(200));
        assert!(!t.is_finished());
        // Crash: W's write of 2 fails -> latch; E's blocked hand-off of 3 errors.
        gate.fail_next();
        gate.release();
        let ctx = t.join().unwrap();
        assert!(
            ctx.exec_failed.load(std::sync::atomic::Ordering::SeqCst),
            "E must latch the fail-stop when W failed under it"
        );
        drop(ctx);
        assert_eq!(read_native_applied_height(&state_db), Some(1), "nothing of 2/3 durable");
        let trades =
            StateBackend::iterate_cf(&state_db, torus_state::cf::CF_NATIVE_TRADES, None).unwrap();
        assert!(trades.is_empty(), "block 3's fill must not have been written");

        // Restart: serial replay from the durable marker re-executes 2 and 3.
        let ctx2 = pipeline_ctx(&state_db, false, None);
        let (_last, parked) = TorusApp::replay_committed(&state_db, &ctx2);
        assert_eq!(parked, None);
        assert!(!ctx2.exec_failed.load(std::sync::atomic::Ordering::SeqCst));
        drop(ctx2);
        assert_eq!(read_native_applied_height(&state_db), Some(3));
        assert_dumps_equal(&dump_ref, &dump_all_cfs(&state_db), "replay after crash vs serial");
    }

    // ---- R01: a failed serial write of a block's state or marker fail-stops ----

    /// R01: nothing of `fail_at` or above is durable: the applied marker and
    /// the running state hash stay at `fail_at - 1` (no hash-unverified gap),
    /// and no nonce, action-status record or trade row of `fail_at..` exists.
    fn r01_assert_nothing_durable_from(db: &StateDb, fail_at: u64) {
        let below = fail_at.checked_sub(1).filter(|h| *h > 0);
        assert_eq!(
            read_native_applied_height(db),
            below,
            "applied marker below the failed height"
        );
        assert_eq!(
            torus_state::running_hash::read_running_hash(db).map(|(h, _)| h),
            below,
            "running state hash below the failed height"
        );
        assert_eq!(
            torus_state::running_hash::read_unverified_since(db),
            None,
            "no later height flushed over the gap (hash-unverified)"
        );
        let be = |v: &[u8]| u64::from_be_bytes(v.try_into().expect("8-byte height"));
        let nonces = StateBackend::iterate_cf(db, torus_state::cf::CF_NATIVE_NONCES, None).unwrap();
        assert!(
            nonces.iter().all(|(_, v)| be(v) < fail_at),
            "no nonce consumed at or above {fail_at}"
        );
        let status =
            StateBackend::iterate_cf(db, torus_state::cf::CF_BLOCK_ACTION_STATUS, None).unwrap();
        assert!(
            status.iter().all(|(k, _)| be(k) < fail_at),
            "no action-status record at or above {fail_at}"
        );
        let trades = StateBackend::iterate_cf(db, torus_state::cf::CF_NATIVE_TRADES, None).unwrap();
        assert!(
            trades
                .iter()
                .all(|(k, _)| torus_state::trade_rows::parse_trade_key(k).unwrap().1 < fail_at),
            "no trade row at or above {fail_at}"
        );
    }

    /// R01 live path: `blocks[..fail_at]` arrive through the dispatch path on
    /// a context (exec pipeline `on`/off) whose serial flush of `fail_at`
    /// fails. The fail-stop latches at `fail_at` (not before), nothing of
    /// `fail_at` is durable, and the next committed block is refused (not
    /// executed: its header would be written by execution). Returns the DB.
    fn r01_run_with_flush_fault(
        blocks: &[TorusBlock],
        fund: fn(&StateDb),
        fail_at: u64,
        on: bool,
    ) -> StateDb {
        let (_cfg, db) = make_test_config_and_db();
        fund(&db);
        let mut ctx = pipeline_ctx(&db, on, None);
        ctx.test_fail_flush_at = Some(fail_at);
        for b in &blocks[..fail_at as usize] {
            assert!(
                !ctx.exec_failed.load(Ordering::SeqCst),
                "latched before height {} (on={on})",
                b.header.height
            );
            dispatch_and_execute(&ctx, &db, b);
        }
        assert!(
            ctx.exec_failed.load(Ordering::SeqCst),
            "a failed flush at {fail_at} must latch the fail-stop (on={on})"
        );
        let next = &blocks[fail_at as usize];
        ctx.execute_committed_block(next, vec![]);
        drop(ctx); // drains + joins W
        assert!(
            load_replay_header(&db, next.header.height).is_none(),
            "block {} must not execute on top of the failed height (on={on})",
            next.header.height
        );
        r01_assert_nothing_durable_from(&db, fail_at);
        db
    }

    /// R01 restart: close and reopen the faulted DB, replay from the durable
    /// marker on a fresh serial context (as `TorusApp::new` does at boot; the
    /// replay must end at `replayed_to`), deliver the rest of `blocks`, and
    /// compare with an uninterrupted run of `blocks`: every CF (economic rows,
    /// consensus meta with the marker and the running hash), the applied
    /// height and the running state hash.
    fn r01_restart_and_compare(
        db: StateDb,
        blocks: &[TorusBlock],
        fund: fn(&StateDb),
        replayed_to: u64,
    ) {
        let dir = db.inner().path().to_path_buf();
        drop(db);
        let db = StateDb::open(&dir).expect("reopen the state db");
        torus_state::running_hash::configure_activation(&db, Some(1))
            .expect("configure running hash activation");
        let ctx = pipeline_ctx(&db, false, None);
        let (last, parked) = TorusApp::replay_committed(&db, &ctx);
        assert_eq!(parked, None);
        assert_eq!(
            last.height, replayed_to,
            "the replay re-executes the failed height"
        );
        for b in &blocks[replayed_to as usize..] {
            dispatch_and_execute(&ctx, &db, b);
        }
        assert!(
            !ctx.exec_failed.load(Ordering::SeqCst),
            "restart must not fail-stop"
        );
        drop(ctx);

        let (_c, db_ref) = make_test_config_and_db();
        fund(&db_ref);
        let ctx_ref = pipeline_ctx(&db_ref, false, None);
        for b in blocks {
            dispatch_and_execute(&ctx_ref, &db_ref, b);
        }
        assert!(!ctx_ref.exec_failed.load(Ordering::SeqCst));
        drop(ctx_ref);

        let top = blocks.last().unwrap().header.height;
        assert_eq!(read_native_applied_height(&db_ref), Some(top));
        assert_eq!(read_native_applied_height(&db), Some(top), "applied height");
        let hash = torus_state::running_hash::read_running_hash(&db);
        assert_eq!(hash.map(|(h, _)| h), Some(top));
        assert_eq!(
            hash,
            torus_state::running_hash::read_running_hash(&db_ref),
            "running state hash after the restart vs uninterrupted"
        );
        assert_dumps_equal(
            &dump_all_cfs(&db_ref),
            &dump_all_cfs(&db),
            "restart after a failed flush vs uninterrupted",
        );
    }

    /// R01: a native-only block (3: a fill) whose serial flush of state +
    /// applied marker fails fail-stops like an EVM block; RED on main: only
    /// EVM blocks latched, so 4 executed on a base without 3's fill.
    #[test]
    fn r01_native_only_flush_failure_fail_stops_and_restart_matches() {
        let blocks = pipeline_fixture_blocks();
        let db = r01_run_with_flush_fault(&blocks, fund_pipeline_fixture, 3, false);
        r01_restart_and_compare(db, &blocks[..6], fund_pipeline_fixture, 3);
    }

    /// R01: a marker-only flush (2: empty, no native phase) that fails
    /// fail-stops; RED on main: logged only, so 3 executed and its flush
    /// advanced the marker past 2.
    #[test]
    fn r01_marker_only_flush_failure_fail_stops_and_restart_matches() {
        let blocks = pipeline_fixture_blocks();
        let db = r01_run_with_flush_fault(&blocks, fund_pipeline_fixture, 2, false);
        r01_restart_and_compare(db, &blocks[..4], fund_pipeline_fixture, 2);
    }

    /// R01: epoch-boundary blocks always run serially, with the exec pipeline
    /// on (barrier) as well as off: a native boundary block (4) and an empty
    /// one (8, native phase for the validator-set plan) whose flush fails
    /// fail-stop; RED on main for both.
    #[test]
    fn r01_epoch_boundary_flush_failure_fail_stops_and_restart_matches() {
        let blocks = pipeline_fixture_blocks();
        for on in [false, true] {
            for (fail_at, top) in [(4u64, 6usize), (8, 10)] {
                let db = r01_run_with_flush_fault(&blocks, fund_pipeline_fixture, fail_at, on);
                r01_restart_and_compare(db, &blocks[..top], fund_pipeline_fixture, fail_at);
            }
        }
    }

    /// R01 replay path: a boot replay whose flush of a gap height fails stops
    /// there (`Failed`, fail-stop latched, nothing of it or later executed),
    /// and the next restart replays the whole gap to the uninterrupted state.
    /// Cases: a native boundary block (4) and an empty marker-only block (7).
    /// RED on main: the replay ran on past the failed height.
    #[test]
    fn r01_replay_flush_failure_fail_stops_and_restart_matches() {
        let blocks = pipeline_fixture_blocks();
        // (executed before the crash, failing height, committed top)
        for (executed, fail_at, top) in [(2usize, 4u64, 6usize), (5, 7, 9)] {
            let (_c, db) = make_test_config_and_db();
            fund_pipeline_fixture(&db);
            let ctx = pipeline_ctx(&db, false, None);
            for b in &blocks[..executed] {
                dispatch_and_execute(&ctx, &db, b);
            }
            drop(ctx);
            // Committed (header + body durable at dispatch), never executed.
            for b in &blocks[executed..top] {
                persist_committed_block_durably(&db, b);
            }
            let mut ctx = pipeline_ctx(&db, false, None);
            ctx.test_fail_flush_at = Some(fail_at);
            let (last, parked) = TorusApp::replay_committed(&db, &ctx);
            assert_eq!(parked, None);
            assert!(
                ctx.exec_failed.load(Ordering::SeqCst),
                "replay: a failed flush at {fail_at} must latch the fail-stop"
            );
            assert_eq!(
                last.height,
                fail_at - 1,
                "the replay stops at the failed height"
            );
            drop(ctx);
            r01_assert_nothing_durable_from(&db, fail_at);
            r01_restart_and_compare(db, &blocks[..top], fund_pipeline_fixture, top as u64);
        }
    }

    /// R01: the execution loop itself halts on the latch: a native-only flush
    /// failure at 3 ends the loop with its channel still open (blocks 4 and 5
    /// queued behind it are never executed). RED on main: the loop ran on.
    #[test]
    fn r01_execution_loop_halts_on_native_flush_failure() {
        let blocks = pipeline_fixture_blocks();
        let (_c, db) = make_test_config_and_db();
        fund_pipeline_fixture(&db);
        let mut ctx = pipeline_ctx(&db, false, None);
        ctx.test_fail_flush_at = Some(3);
        let latch = ctx.exec_failed.clone();
        let (tx, rx) = std::sync::mpsc::sync_channel(16);
        let handle = std::thread::spawn(move || execution_loop(rx, ctx));
        for b in &blocks[..5] {
            let durable = persist_committed_block_durably(&db, b);
            let msg = CommittedBlockMsg {
                torus_block: b.clone(),
                pending_slashes: vec![],
                durable,
            };
            if tx.send(msg).is_err() {
                break; // the loop already exited
            }
        }
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
        while !handle.is_finished() && std::time::Instant::now() < deadline {
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        let halted = handle.is_finished();
        drop(tx); // unblocks a loop that did not halt (RED) so the test ends
        handle.join().unwrap();
        assert!(
            halted,
            "the execution loop must exit on the fail-stop, channel still open"
        );
        assert!(latch.load(Ordering::SeqCst));
        r01_assert_nothing_durable_from(&db, 3);
    }

    /// R01b D: the exec channel closing while the node is NOT stopping (the
    /// consensus thread died and its `TorusApp` was dropped by the unwind)
    /// latches the fail-stop. RED on main: the loop logged "shutting down".
    #[test]
    fn r01b_exec_channel_close_without_shutdown_latches() {
        let (config, db) = make_test_config_and_db();
        let ctx = make_exec_ctx(&config, &db);
        let latch = ctx.exec_failed.clone();
        let (tx, rx) = std::sync::mpsc::sync_channel::<CommittedBlockMsg>(1);
        let handle = std::thread::spawn(move || execution_loop(rx, ctx));
        drop(tx);
        handle.join().unwrap();
        assert!(latch.load(Ordering::SeqCst), "an unexplained channel close must fail-stop");
    }

    /// R01b D: the same close after a deliberate stop does not latch.
    #[test]
    fn r01b_exec_channel_close_after_shutdown_does_not_latch() {
        let (config, db) = make_test_config_and_db();
        let ctx = make_exec_ctx(&config, &db);
        let latch = ctx.exec_failed.clone();
        ctx.exec_shutdown.store(true, Ordering::SeqCst);
        let (tx, rx) = std::sync::mpsc::sync_channel::<CommittedBlockMsg>(1);
        let handle = std::thread::spawn(move || execution_loop(rx, ctx));
        drop(tx);
        handle.join().unwrap();
        assert!(!latch.load(Ordering::SeqCst));
    }

    /// R01b D: a `TorusApp` dropped normally (node shutdown, test teardown)
    /// stops the execution thread without latching.
    #[test]
    fn r01b_torus_app_normal_drop_does_not_latch() {
        let app = TorusApp::stub();
        let latch = app.exec_failed_handle();
        drop(app); // joins the execution thread
        assert!(!latch.load(Ordering::SeqCst));
    }

    /// R01b D: a `TorusApp` dropped by a panic unwinding its thread (the
    /// `hotstuff-algo` case: a failed consensus write) latches the fail-stop
    /// once the execution thread sees its channel close.
    #[test]
    fn r01b_torus_app_dropped_by_unwind_latches() {
        let app = TorusApp::stub();
        let latch = app.exec_failed_handle();
        let t = std::thread::spawn(move || {
            let _app = app;
            panic!("simulated consensus write failure");
        });
        assert!(t.join().is_err());
        assert!(latch.load(Ordering::SeqCst), "consensus-thread death must fail-stop");
    }

    /// R01 regression guard: an EVM block whose flush fails still fail-stops
    /// as before (both arms: with fee revenue the EVM batch rides the native
    /// flush; at base fee 0 there is no native phase and it rides the marker
    /// flush), and the restart matches the uninterrupted run.
    #[test]
    fn r01_evm_block_flush_failure_still_fail_stops_and_restart_matches() {
        fn fund(db: &StateDb) {
            let key = k256::ecdsa::SigningKey::from_slice(&[66u8; 32]).unwrap();
            let funded = revm::state::AccountInfo {
                balance: U256::from(10u128.pow(18)),
                nonce: 0,
                code_hash: KECCAK_EMPTY_CODE,
                code: None,
                account_id: None,
            };
            db.put_account(&k256_address(&key), &funded).unwrap();
        }
        let key = k256::ecdsa::SigningKey::from_slice(&[66u8; 32]).unwrap();
        for base_fee in [None, Some(0u64)] {
            let mut b1 = make_block(1, vec![]);
            b1.evm_transactions = vec![signed_sstore_create(&key, 0)];
            b1.header.evm_tx_count = 1;
            if let Some(fee) = base_fee {
                b1.header.base_fee_per_gas = fee;
            }
            let mut blocks = vec![b1, make_block(2, vec![]), make_block(3, vec![])];
            link_blocks(&mut blocks);
            let db = r01_run_with_flush_fault(&blocks, fund, 1, false);
            r01_restart_and_compare(db, &blocks, fund, 1);
            // The tx really executed after the restart (the case is not vacuous).
            let (_c, db_ref) = make_test_config_and_db();
            fund(&db_ref);
            let ctx_ref = pipeline_ctx(&db_ref, false, None);
            for b in &blocks {
                dispatch_and_execute(&ctx_ref, &db_ref, b);
            }
            drop(ctx_ref);
            let sender = db_ref.get_account(&k256_address(&key)).unwrap().unwrap();
            assert_eq!(
                sender.nonce, 1,
                "the EVM tx executed (base_fee={base_fee:?})"
            );
        }
    }

    /// §5 `exec_pipeline_fold_header_runs_serial` (F9): a block whose header is
    /// NOT dispatch-durable (boot replay / failed dispatch batch) takes the
    /// barrier path under the flag — W receives nothing for it, its marker and
    /// folded header are durable synchronously — and the NEXT block's parent-link
    /// check can assert against the persisted header (no fail-stop), then rides W.
    #[test]
    fn exec_pipeline_fold_header_runs_serial() {
        let (_cfg, state_db) = make_test_config_and_db();
        fund_pipeline_fixture(&state_db);
        let blocks = pipeline_fixture_blocks();
        let gate = crate::exec_pipeline::WorkerGate::new();
        let ctx = pipeline_ctx(&state_db, true, Some(gate.clone()));

        ctx.execute_committed_block_with(&blocks[0], vec![], DurableRows::default());
        assert!(gate.received().is_empty(), "non-durable rows => serial, no W job");
        assert_eq!(read_native_applied_height(&state_db), Some(1), "serial marker durable synchronously");
        assert!(
            state_db.get_cf_raw(CF_BLOCK_HEADERS, &1u64.to_be_bytes()).unwrap().is_some(),
            "folded header landed with the serial batch"
        );

        dispatch_and_execute(&ctx, &state_db, &blocks[1]);
        assert!(!ctx.exec_failed.load(std::sync::atomic::Ordering::SeqCst), "parent-link check passed");
        drop(ctx);
        assert_eq!(gate.received(), vec![2]);
        assert_eq!(read_native_applied_height(&state_db), Some(2));
    }

    /// bl3 resident-books-untouched-advance under the pipeline (design §2.1
    /// step 10): an empty block's Marker job advances the rank8 holder ON E at
    /// the hand-off, and the NEXT native block's staleness guard reads the
    /// marker THROUGH its overlay's parent layer (the 1-key Marker pending set)
    /// — so while W still has Marker(2) in flight (DB marker = 1) the guard sees
    /// 2 and the holder is reused. The negative control pins that the layer is
    /// load-bearing: the same guard over the bare DB trips (reason=marker) and
    /// rebuilds. Kill-switch and serial-path ordering are pinned by
    /// `empty_blocks_advance_resident_holder_with_marker` and the torus-bridge
    /// `resident_books_tests`.
    #[test]
    fn exec_pipeline_empty_block_advances_resident_holder_through_parent_layer() {
        use torus_bridge::native_executor::{NativeExecContext, ResidentBooks};
        let (cfg, state_db) = make_test_config_and_db();
        fund_pipeline_fixture(&state_db);
        let blocks = pipeline_fixture_blocks();
        let gate = crate::exec_pipeline::WorkerGate::new();
        let ctx = pipeline_ctx(&state_db, true, Some(gate.clone()));

        // Native 1 through the pipeline, drained: marker(1) durable.
        dispatch_and_execute(&ctx, &state_db, &blocks[0]);
        assert!(ctx.flush_worker.as_ref().unwrap().wait_idle());
        assert_eq!(read_native_applied_height(&state_db), Some(1));

        // Seed the holder as height 1's resident post-state (classic mode).
        let mut holder = ResidentBooks::default();
        let mut seed = NativeExecContext::new_with_modes(
            state_db.clone(),
            1,
            1001,
            0,
            cfg.epoch_length,
            cfg.max_validators,
            Address::ZERO,
            cfg.treasury_address,
            cfg.dev_pool_address,
            false,
            Some(&mut holder),
        );
        seed.save_order_books();
        seed.stash_resident(&mut holder);
        assert_eq!(holder.height(), Some(1));
        *ctx.resident_books.lock().unwrap() = holder;

        // Empty 2 with W parked: the rendezvous completes (W RECEIVED Marker(2))
        // but the marker is NOT durable. The holder must already be at 2.
        gate.hold();
        dispatch_and_execute(&ctx, &state_db, &blocks[1]);
        assert!(gate.wait_received(2), "W must have taken Marker(2)");
        assert_eq!(read_native_applied_height(&state_db), Some(1), "Marker(2) in flight, not durable");
        assert_eq!(
            ctx.resident_books.lock().unwrap().height(),
            Some(2),
            "holder must advance on E at the hand-off, not at durability"
        );
        let parent = ctx.last_job.lock().unwrap().clone();
        assert_eq!(parent.as_ref().map(|p| p.height()), Some(2), "parent layer is Marker(2)");

        // Negative control: the guard over the BARE DB (marker=1) must trip.
        {
            let mut probe = std::mem::take(&mut *ctx.resident_books.lock().unwrap());
            let c = NativeExecContext::new_with_modes(
                state_db.clone(),
                3,
                1003,
                0,
                cfg.epoch_length,
                cfg.max_validators,
                Address::ZERO,
                cfg.treasury_address,
                cfg.dev_pool_address,
                false,
                Some(&mut probe),
            );
            assert!(c.resident_rebuilt(), "DB-only marker read (1) vs holder (2) must rebuild");
            // Re-seed at height 2 for the real check below (the probe drained it).
            let mut holder = ResidentBooks::default();
            let mut seed = NativeExecContext::new_with_modes(
                state_db.clone(),
                2,
                1002,
                0,
                cfg.epoch_length,
                cfg.max_validators,
                Address::ZERO,
                cfg.treasury_address,
                cfg.dev_pool_address,
                false,
                Some(&mut holder),
            );
            seed.save_order_books();
            seed.stash_resident(&mut holder);
            assert_eq!(holder.height(), Some(2));
            *ctx.resident_books.lock().unwrap() = holder;
        }

        // What E does for native 3: overlay layered on pending(2) = Marker(2).
        let overlay = NativeStateOverlay::with_parent(state_db.clone(), parent);
        let mut holder = std::mem::take(&mut *ctx.resident_books.lock().unwrap());
        let c = NativeExecContext::new_with_modes(
            overlay,
            3,
            1003,
            0,
            cfg.epoch_length,
            cfg.max_validators,
            Address::ZERO,
            cfg.treasury_address,
            cfg.dev_pool_address,
            false,
            Some(&mut holder),
        );
        assert!(
            c.resident_reused() && !c.resident_rebuilt(),
            "guard must read Marker(2) through the parent layer while W still holds it"
        );

        gate.release();
        assert!(ctx.flush_worker.as_ref().unwrap().wait_idle());
        assert_eq!(read_native_applied_height(&state_db), Some(2), "Marker(2) landed after release");
        assert!(!ctx.exec_failed.load(std::sync::atomic::Ordering::SeqCst));
    }

    // ======================================================================
    // s63 port of item 6a (origin 4298728): book-save pass 2 deferred to W
    // ======================================================================

    /// The deferred mode-2 book save (`save_order_books_deferred`) rides
    /// `Job::Flush` to the REAL flush worker, which applies it as a sidecar of
    /// the block's one atomic batch. Pins, against a serial reference over the
    /// same blocks:
    ///   (1) byte-identical final state in EVERY CF and the same persisted
    ///       native root (books entered the root computation on W);
    ///   (2) atomicity/thread attribution — while W holds job N parked, NONE
    ///       of block N's book bytes (nor its marker) is durable, and they
    ///       appear only after release: the write half provably ran on W;
    ///   (3) crash — an injected W write failure durably lands NOTHING of the
    ///       block (no book bytes, no marker) and latches the shared
    ///       fail-stop, so restart-replay re-executes from the marker.
    #[test]
    fn exec_pipeline_deferred_books_atomic_and_match_serial() {
        torus_state::native_trie::force_native_trie_maintenance_on_for_tests();
        use torus_bridge::native_executor::{
            BookMode, NativeExecContext, NativeExecutor, ResidentBooks,
        };
        use torus_state::cf::{CF_BOOK_ORDER_ROWS, CF_NATIVE_ORDER_BOOKS};
        use torus_state::native_trie::{
            build_native_trie_to_cf, persisted_native_root, NativeMemberCache,
        };

        let a = Address::from([61u8; 20]);
        let b = Address::from([62u8; 20]);
        let deposit = U256::from(1_000 * FixedPoint::ONE.raw() as u128);
        let order = |is_buy: bool, price: i128, qty: i128| torus_types::PlaceOrderParams {
            market_id: 1,
            is_buy,
            price: FixedPoint::from_raw(price * FixedPoint::SCALE),
            quantity: FixedPoint::from_raw(qty * FixedPoint::SCALE),
            order_type: torus_types::OrderType::Limit,
            time_in_force: torus_types::TimeInForce::GTC,
            reduce_only: false,
            client_order_id: None,
        };
        let amount = U256::from(500 * FixedPoint::ONE.raw() as u128);
        let blocks: Vec<Vec<(Address, NativeAction)>> = vec![
            vec![
                (a, NativeAction::TransferToPerp { amount }),
                (b, NativeAction::TransferToPerp { amount }),
                (a, NativeAction::PlaceOrder(order(false, 100, 1))),
                (a, NativeAction::PlaceOrder(order(false, 101, 2))),
                (b, NativeAction::PlaceOrder(order(true, 99, 1))),
                (
                    b,
                    NativeAction::PlaceOrder(torus_types::PlaceOrderParams {
                        order_type: torus_types::OrderType::StopMarket {
                            trigger: FixedPoint::from_raw(150 * FixedPoint::SCALE),
                        },
                        ..order(true, 100, 1)
                    }),
                ),
            ],
            // Fill and cancel-all in SEPARATE blocks: within one block the
            // engine's phase 1 (cancels) runs before the match phase.
            vec![(b, NativeAction::PlaceOrder(order(true, 100, 1)))], // fills A's sell
            vec![(a, NativeAction::CancelAllOrders { market_id: None })],
        ];

        // Execute one block on a leg: engine + save (serial or deferred) +
        // stash; the caller owns the flush (serial or via W).
        let exec_block = |db: &StateDb,
                          books: &mut ResidentBooks,
                          height: u64,
                          batch: &[(Address, NativeAction)],
                          deferred: bool| {
            let overlay = NativeStateOverlay::new(db.clone());
            let mut ctx = NativeExecContext::new_with_mode(
                overlay.clone(),
                height,
                1_000 + height,
                0,
                100,
                10,
                Address::ZERO,
                Address::ZERO,
                Address::ZERO,
                BookMode::LevelAuthority,
                Some(books),
            );
            assert!(ctx.fatal_error.is_none(), "load {height}: {:?}", ctx.fatal_error);
            NativeExecutor::execute_batch(&mut ctx, batch);
            assert!(ctx.fatal_error.is_none(), "exec {height}: {:?}", ctx.fatal_error);
            let _ = NativeExecutor::drain_core_writer(&mut ctx);
            let save = if deferred {
                Some(ctx.save_order_books_deferred().expect("mode 2 must defer"))
            } else {
                ctx.save_order_books();
                None
            };
            ctx.stash_resident(books);
            (overlay.freeze(height), save)
        };
        let dump_books = |db: &StateDb| -> Vec<(&'static str, Vec<u8>, Vec<u8>)> {
            let mut out = Vec::new();
            for cf in [CF_NATIVE_ORDER_BOOKS, CF_BOOK_ORDER_ROWS] {
                for (k, v) in StateBackend::iterate_cf(db, cf, None).unwrap() {
                    out.push((cf, k, v));
                }
            }
            out
        };
        let fund = |db: &StateDb| {
            fund_evm_balance(db, a, deposit);
            fund_evm_balance(db, b, deposit);
            build_native_trie_to_cf(db).unwrap();
        };
        let spawn_worker = |db: &StateDb,
                            gate: Arc<crate::exec_pipeline::WorkerGate>,
                            exec_failed: Arc<std::sync::atomic::AtomicBool>| {
            crate::exec_pipeline::FlushWorker::spawn(
                crate::exec_pipeline::WorkerEnv {
                    state_db: db.clone(),
                    trie_cache: Arc::new(std::sync::Mutex::new(Default::default())),
                    member_cache: Arc::new(std::sync::Mutex::new(
                        NativeMemberCache::with_budget(0),
                    )),
                    metrics: None,
                    exec_failed,
                    gate: Some(gate),
                },
                0,
            )
        };

        // ---- Serial reference (save + flush on "E"). ----
        let (_c0, db_ref) = make_test_config_and_db();
        fund(&db_ref);
        let mut books_ref = ResidentBooks::default();
        for (i, batch) in blocks.iter().enumerate() {
            let h = (i + 1) as u64;
            let (frozen, save) = exec_block(&db_ref, &mut books_ref, h, batch, false);
            assert!(save.is_none());
            frozen
                .flush_with_native_trie_stats(&db_ref, Some(h), None, None)
                .unwrap();
        }
        let dump_ref = dump_all_cfs(&db_ref);
        let root_ref = persisted_native_root(&db_ref).unwrap();
        let trades = StateBackend::iterate_cf(&db_ref, torus_state::cf::CF_NATIVE_TRADES, None)
            .unwrap();
        assert!(!trades.is_empty(), "fixture must produce a fill (not vacuous)");
        assert!(!dump_books(&db_ref).is_empty(), "fixture must persist book rows");

        // ---- Deferred through the real W (differential + hold ordering). ----
        let (_c1, db_w) = make_test_config_and_db();
        fund(&db_w);
        let gate = crate::exec_pipeline::WorkerGate::new();
        let exec_failed = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let worker = spawn_worker(&db_w, gate.clone(), exec_failed.clone());
        let mut books_w = ResidentBooks::default();

        for h in [1u64, 2] {
            let (frozen, save) =
                exec_block(&db_w, &mut books_w, h, &blocks[(h - 1) as usize], true);
            let save = save.unwrap();
            assert!(save.book_count() >= 1, "block {h} dirtied market 1");
            worker
                .submit(crate::exec_pipeline::Job::Flush {
                    height: h,
                    pending: frozen,
                    evm_addrs: vec![],
                    books: Some(save),
                    order_nonces: vec![],
                    action_status: None,
                })
                .unwrap();
            assert!(worker.wait_idle());
            assert_eq!(read_native_applied_height(&db_w), Some(h));
        }
        let books_after_2 = dump_books(&db_w);
        assert!(!books_after_2.is_empty(), "W applied the book sidecars");

        gate.hold();
        let (frozen3, save3) = exec_block(&db_w, &mut books_w, 3, &blocks[2], true);
        worker
            .submit(crate::exec_pipeline::Job::Flush {
                height: 3,
                pending: frozen3,
                evm_addrs: vec![],
                books: Some(save3.unwrap()),
                order_nonces: vec![],
                action_status: None,
            })
            .unwrap();
        assert!(gate.wait_received(3), "W must have taken job 3");
        // Parked: NOTHING of block 3 is durable — E wrote no book byte itself.
        assert_eq!(read_native_applied_height(&db_w), Some(2), "marker(3) in flight");
        assert_eq!(
            dump_books(&db_w),
            books_after_2,
            "no block-3 book byte may be durable while W holds the job"
        );
        gate.release();
        assert!(worker.wait_idle());
        drop(worker);
        assert!(!exec_failed.load(std::sync::atomic::Ordering::SeqCst));
        assert_eq!(read_native_applied_height(&db_w), Some(3));
        assert_dumps_equal(&dump_ref, &dump_all_cfs(&db_w), "deferred-through-W vs serial");
        assert_eq!(
            root_ref,
            persisted_native_root(&db_w).unwrap(),
            "native root must be identical with books applied on W"
        );

        // ---- Crash: injected W write failure = nothing durable + fail-stop. ----
        let (_c2, db_c) = make_test_config_and_db();
        fund(&db_c);
        let gate_c = crate::exec_pipeline::WorkerGate::new();
        let failed_c = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let worker_c = spawn_worker(&db_c, gate_c.clone(), failed_c.clone());
        let mut books_c = ResidentBooks::default();
        let (frozen, save) = exec_block(&db_c, &mut books_c, 1, &blocks[0], true);
        gate_c.fail_next();
        worker_c
            .submit(crate::exec_pipeline::Job::Flush {
                height: 1,
                pending: frozen,
                evm_addrs: vec![],
                books: save,
                order_nonces: vec![],
                action_status: None,
            })
            .unwrap();
        assert!(!worker_c.wait_idle(), "wait_idle must report the failure");
        assert!(worker_c.failed());
        assert!(
            failed_c.load(std::sync::atomic::Ordering::SeqCst),
            "shared fail-stop latched"
        );
        drop(worker_c);
        assert_eq!(read_native_applied_height(&db_c), None, "marker must not advance");
        assert!(
            dump_books(&db_c).is_empty(),
            "no book byte may be durable after an injected W write failure"
        );
    }

    /// Book-heavy sequence for the END-TO-END deferred-save tests (through
    /// `execute_committed_block_with`, epoch_length 4 → 4/8/12 are serial
    /// barriers). Covers resting sprays over several levels, a stop order,
    /// partial fills, a multi-level sweep, cancel-alls and empties:
    ///   1  fund A,B                                             native
    ///   2  A sells 100x3, 101x2, 102x1; B buys 99x1 + stop      native (deferred)
    ///   3  B buy 100x1 -> PARTIAL fill of A's 100x3            native (deferred, reads 2's books)
    ///   4  empty (epoch boundary)                               serial marker
    ///   5  B buy 101x3 -> sweeps 100x2 + partial 101           native (deferred)
    ///   6  empty                                                Marker job
    ///   7  A cancel-all mkt 1; B buy 97x2                       native (deferred)
    ///   8  A sell 97x1 -> fills B's 99 bid (epoch boundary)    native, SERIAL
    ///   9  A sell 96x1 -> partial of B's 97x2 level             native (deferred)
    ///  10  B cancel-all (stop + 97 remainder)                   native (deferred)
    ///  11  A sell 105x2 resting                                 native (deferred)
    ///  12  empty (epoch boundary)                               serial marker
    ///  13  B buy 105x1 -> partial fill, 105x1 stays resting     native (deferred)
    fn book_fixture_blocks() -> Vec<TorusBlock> {
        let k_a = k256::ecdsa::SigningKey::from_slice(&[51u8; 32]).unwrap();
        let k_b = k256::ecdsa::SigningKey::from_slice(&[52u8; 32]).unwrap();
        let deposit = U256::from(1_000 * FixedPoint::ONE.raw() as u128);
        let order = |is_buy: bool, price: i128, qty: i128| torus_types::PlaceOrderParams {
            market_id: 1,
            is_buy,
            price: FixedPoint::from_raw(price * FixedPoint::SCALE),
            quantity: FixedPoint::from_raw(qty * FixedPoint::SCALE),
            order_type: torus_types::OrderType::Limit,
            time_in_force: torus_types::TimeInForce::GTC,
            reduce_only: false,
            client_order_id: None,
        };
        let stop = torus_types::PlaceOrderParams {
            order_type: torus_types::OrderType::StopMarket {
                trigger: FixedPoint::from_raw(150 * FixedPoint::SCALE),
            },
            ..order(true, 100, 1)
        };
        let sign = |a: NativeAction, n: u64, k: &k256::ecdsa::SigningKey| {
            torus_types::eip712::sign_native_action(a, NONCE_BASE + n, k)
        };
        let place = |o: torus_types::PlaceOrderParams| NativeAction::PlaceOrder(o);
        let mut blocks = vec![
            make_block(
                1,
                vec![
                    sign(NativeAction::TransferToPerp { amount: deposit }, 1, &k_a),
                    sign(NativeAction::TransferToPerp { amount: deposit }, 1, &k_b),
                ],
            ),
            make_block(
                2,
                vec![
                    sign(place(order(false, 100, 3)), 2, &k_a),
                    sign(place(order(false, 101, 2)), 3, &k_a),
                    sign(place(order(false, 102, 1)), 4, &k_a),
                    sign(place(order(true, 99, 1)), 2, &k_b),
                    sign(place(stop), 3, &k_b),
                ],
            ),
            make_block(3, vec![sign(place(order(true, 100, 1)), 4, &k_b)]),
            make_block(4, vec![]),
            make_block(5, vec![sign(place(order(true, 101, 3)), 5, &k_b)]),
            make_block(6, vec![]),
            make_block(
                7,
                vec![
                    sign(NativeAction::CancelAllOrders { market_id: Some(1) }, 5, &k_a),
                    sign(place(order(true, 97, 2)), 6, &k_b),
                ],
            ),
            make_block(8, vec![sign(place(order(false, 97, 1)), 6, &k_a)]),
            make_block(9, vec![sign(place(order(false, 96, 1)), 7, &k_a)]),
            make_block(
                10,
                vec![sign(NativeAction::CancelAllOrders { market_id: None }, 7, &k_b)],
            ),
            make_block(11, vec![sign(place(order(false, 105, 2)), 8, &k_a)]),
            make_block(12, vec![]),
            make_block(13, vec![sign(place(order(true, 105, 1)), 8, &k_b)]),
        ];
        link_blocks(&mut blocks);
        blocks
    }

    fn fund_book_fixture(state_db: &StateDb) {
        let deposit = U256::from(1_000 * FixedPoint::ONE.raw() as u128);
        for signed in &book_fixture_blocks()[0].native_actions {
            fund_evm_balance(state_db, signed.recover_sender().unwrap(), deposit);
        }
    }

    /// `pipeline_ctx` with the book mode pinned (resident books forced on) —
    /// the test stand-in for `TORUS_BOOK_ROWS` + `TORUS_RESIDENT_BOOKS=1`,
    /// which are process-global `OnceLock`s in production.
    fn book_pipeline_ctx(
        state_db: &StateDb,
        on: bool,
        gate: Option<Arc<crate::exec_pipeline::WorkerGate>>,
        mode: torus_bridge::native_executor::BookMode,
    ) -> ExecutionContext {
        let mut ctx = pipeline_ctx(state_db, false, None);
        ctx.test_book_mode = Some(mode);
        if on {
            ctx.attach_flush_worker(gate);
        }
        ctx
    }

    fn dump_book_cfs(db: &StateDb) -> Vec<CfDump> {
        [torus_state::cf::CF_NATIVE_ORDER_BOOKS, torus_state::cf::CF_BOOK_ORDER_ROWS]
            .iter()
            .map(|cf| (*cf, StateBackend::iterate_cf(db, cf, None).unwrap()))
            .collect()
    }

    /// Book-CF rows visible THROUGH a frozen set only (layered over an empty
    /// DB) — i.e. the book bytes E itself wrote into block N's overlay.
    fn frozen_book_rows(frozen: &Arc<torus_state::FrozenPending>) -> usize {
        let (_c, empty) = make_test_config_and_db();
        let probe = NativeStateOverlay::with_parent(empty, Some(frozen.clone()));
        [torus_state::cf::CF_NATIVE_ORDER_BOOKS, torus_state::cf::CF_BOOK_ORDER_ROWS]
            .iter()
            .map(|cf| StateBackend::iterate_cf(&probe, cf, None).unwrap().len())
            .sum()
    }

    fn run_book_fixture(
        on: bool,
        mode: torus_bridge::native_executor::BookMode,
    ) -> (StateDb, Vec<CfDump>, torus_types::B256, Vec<u64>) {
        torus_state::native_trie::force_native_trie_maintenance_on_for_tests();
        let (_cfg, state_db) = make_test_config_and_db();
        fund_book_fixture(&state_db);
        let gate = crate::exec_pipeline::WorkerGate::new();
        let ctx = book_pipeline_ctx(&state_db, on, Some(gate.clone()), mode);
        for b in &book_fixture_blocks() {
            dispatch_and_execute(&ctx, &state_db, b);
            if on && !b.native_actions.is_empty() {
                let h = b.header.height;
                if !EpochManager::is_epoch_boundary(h, 4) {
                    // Deferral is ACTIVE: E handed W a frozen set with NO book
                    // bytes — they ride the job's sidecar instead.
                    let last = ctx.last_job.lock().unwrap().clone().expect("fast path");
                    assert_eq!(last.height(), h);
                    assert_eq!(frozen_book_rows(&last), 0, "h{h}: book writes must be deferred to W");
                }
            }
        }
        assert!(
            !ctx.exec_failed.load(std::sync::atomic::Ordering::SeqCst),
            "book fixture must not fail-stop (on={on}, {mode:?})"
        );
        drop(ctx);
        let dump = dump_all_cfs(&state_db);
        let root = torus_state::native_trie::persisted_native_root(&state_db).unwrap();
        (state_db, dump, root, gate.received())
    }

    /// END-TO-END (real `execute_committed_block_with` + real W): with the
    /// pipeline ON under level-authority modes 2 AND 3 + resident books, the
    /// deferred book save lands byte-identical state in EVERY CF and the same
    /// persisted native root as the serial (pipeline OFF) run, over a sequence
    /// with partial fills, a multi-level sweep, stops, cancel-alls, empties
    /// and serial barrier blocks interleaved. Also pins that deferral really
    /// engaged on every fast-path native block (no book bytes in E's frozen set).
    #[test]
    fn exec_pipeline_deferred_books_end_to_end_match_serial() {
        use torus_bridge::native_executor::BookMode;
        for mode in [BookMode::LevelAuthority, BookMode::LevelAuthorityChunked] {
            let (db_off, off, root_off, received_off) = run_book_fixture(false, mode);
            let (db_on, on, root_on, received_on) = run_book_fixture(true, mode);
            assert!(received_off.is_empty());
            assert_eq!(received_on, vec![1, 2, 3, 5, 6, 7, 9, 10, 11, 13], "{mode:?}");
            assert_dumps_equal(&off, &on, "deferred books ON vs OFF");
            assert_eq!(root_off, root_on, "{mode:?}: persisted native root must be identical");
            assert_eq!(read_native_applied_height(&db_on), Some(13));
            let trades =
                StateBackend::iterate_cf(&db_on, torus_state::cf::CF_NATIVE_TRADES, None).unwrap();
            assert!(trades.len() >= 5, "{mode:?}: fixture fills (not vacuous): {}", trades.len());
            let books = dump_book_cfs(&db_on);
            assert!(!books[0].1.is_empty() && !books[1].1.is_empty(), "{mode:?}: book rows persisted");
            assert_eq!(dump_book_cfs(&db_off), books);
        }
    }

    /// Crash-before-write under deferral: W's write of native 2 (with its book
    /// sidecar) fails AFTER E executed native 3 on top of pending(2). Nothing of
    /// 2/3 is durable (marker 1, no book bytes beyond block 1's), the fail-stop
    /// latches, and a serial restart-replay lands EXACTLY the serial state.
    #[test]
    fn exec_pipeline_deferred_books_crash_before_write_replays_and_matches_serial() {
        use torus_bridge::native_executor::BookMode;
        let mode = BookMode::LevelAuthorityChunked;
        let blocks = book_fixture_blocks();
        let first3 = &blocks[..3];

        let (_c0, db_ref) = make_test_config_and_db();
        fund_book_fixture(&db_ref);
        let ctx_ref = book_pipeline_ctx(&db_ref, false, None, mode);
        for b in first3 {
            dispatch_and_execute(&ctx_ref, &db_ref, b);
        }
        drop(ctx_ref);
        let dump_ref = dump_all_cfs(&db_ref);

        let (_c1, state_db) = make_test_config_and_db();
        fund_book_fixture(&state_db);
        let gate = crate::exec_pipeline::WorkerGate::new();
        let ctx = book_pipeline_ctx(&state_db, true, Some(gate.clone()), mode);
        dispatch_and_execute(&ctx, &state_db, &first3[0]);
        assert!(ctx.flush_worker.as_ref().unwrap().wait_idle());
        assert_eq!(read_native_applied_height(&state_db), Some(1));
        let books_after_1 = dump_book_cfs(&state_db);

        gate.hold();
        dispatch_and_execute(&ctx, &state_db, &first3[1]); // Flush(2)+books received, parked
        assert!(gate.wait_received(2));
        let db_t = state_db.clone();
        let b3 = first3[2].clone();
        let t = std::thread::spawn(move || {
            dispatch_and_execute(&ctx, &db_t, &b3); // engine(3) on pending(2); hand-off blocks
            ctx
        });
        std::thread::sleep(std::time::Duration::from_millis(200));
        assert!(!t.is_finished());
        gate.fail_next();
        gate.release();
        let ctx = t.join().unwrap();
        assert!(ctx.exec_failed.load(std::sync::atomic::Ordering::SeqCst));
        drop(ctx);
        assert_eq!(read_native_applied_height(&state_db), Some(1), "nothing of 2/3 durable");
        assert_eq!(dump_book_cfs(&state_db), books_after_1, "no book byte of 2/3 durable");

        let ctx2 = book_pipeline_ctx(&state_db, false, None, mode);
        let (_last, parked) = TorusApp::replay_committed(&state_db, &ctx2);
        assert_eq!(parked, None);
        assert!(!ctx2.exec_failed.load(std::sync::atomic::Ordering::SeqCst));
        drop(ctx2);
        assert_eq!(read_native_applied_height(&state_db), Some(3));
        assert_dumps_equal(&dump_ref, &dump_all_cfs(&state_db), "replay after crash vs serial");
    }

    /// Stale-parent guard: if the resident holder is NOT the predecessor's
    /// post-state while the parent job carried deferred book writes (holder
    /// drained), the next block would rebuild its books from the DB + a parent
    /// layer that lacks those bytes. E must instead BARRIER (wait for W) before
    /// loading — it blocks while W is parked, and the final state equals serial.
    #[test]
    fn exec_pipeline_deferred_books_rebuild_waits_for_worker() {
        use torus_bridge::native_executor::BookMode;
        let mode = BookMode::LevelAuthority;
        let blocks = book_fixture_blocks();
        let first3 = &blocks[..3];

        let (_c0, db_ref) = make_test_config_and_db();
        fund_book_fixture(&db_ref);
        let ctx_ref = book_pipeline_ctx(&db_ref, false, None, mode);
        for b in first3 {
            dispatch_and_execute(&ctx_ref, &db_ref, b);
        }
        drop(ctx_ref);
        let dump_ref = dump_all_cfs(&db_ref);

        let (_c1, state_db) = make_test_config_and_db();
        fund_book_fixture(&state_db);
        let gate = crate::exec_pipeline::WorkerGate::new();
        let ctx = book_pipeline_ctx(&state_db, true, Some(gate.clone()), mode);
        dispatch_and_execute(&ctx, &state_db, &first3[0]);
        assert!(ctx.flush_worker.as_ref().unwrap().wait_idle());

        gate.hold();
        dispatch_and_execute(&ctx, &state_db, &first3[1]); // deferred books of 2 parked on W
        assert!(gate.wait_received(2));
        ctx.resident_books.lock().unwrap().invalidate(); // force a rebuild for 3
        let db_t = state_db.clone();
        let b3 = first3[2].clone();
        let t = std::thread::spawn(move || {
            dispatch_and_execute(&ctx, &db_t, &b3);
            ctx
        });
        std::thread::sleep(std::time::Duration::from_millis(200));
        assert!(!t.is_finished(), "E must wait for W before rebuilding books");
        gate.release();
        let ctx = t.join().unwrap();
        assert!(!ctx.exec_failed.load(std::sync::atomic::Ordering::SeqCst));
        drop(ctx);
        assert_eq!(read_native_applied_height(&state_db), Some(3));
        assert_dumps_equal(&dump_ref, &dump_all_cfs(&state_db), "rebuild after deferred parent vs serial");
    }

    /// Kill switch: `TORUS_EXEC_PIPELINE=0` => no worker is attached, the
    /// context is the serial one (every existing test runs that path).
    #[test]
    fn exec_pipeline_kill_switch_has_no_worker() {
        let (_cfg, state_db) = make_test_config_and_db();
        let ctx = pipeline_ctx(&state_db, false, None);
        assert!(ctx.flush_worker.is_none());
        assert!(!crate::exec_pipeline::parse_exec_pipeline_toggle(Some("0".to_string())));
        assert!(crate::exec_pipeline::parse_exec_pipeline_toggle(None));
    }

    // ======================================================================
    // Running state hash (docs/plans/running-state-hash-impl.md)
    // ======================================================================

    type CapturedWrites = Vec<(u64, Vec<torus_state::running_hash::WriteEntry>)>;

    /// Run the book fixture (every block through the live dispatch path),
    /// "restarting" (fresh `ExecutionContext`: empty resident holder, caches,
    /// flush worker) after each height in `restart_after`, and return the
    /// per-block consensus write sets the flush saw.
    fn run_book_fixture_capturing(
        on: bool,
        mode: torus_bridge::native_executor::BookMode,
        restart_after: &[u64],
    ) -> CapturedWrites {
        run_book_fixture_capturing_with(on, mode, restart_after, false)
    }

    /// `drop_book_mode_marker`: at each restart delete the node-local
    /// `__book_mode__` row first — a DB from before that marker existed (or a
    /// node whose history differs only in node-local rows) re-writes it on the
    /// first save after the restart.
    fn run_book_fixture_capturing_with(
        on: bool,
        mode: torus_bridge::native_executor::BookMode,
        restart_after: &[u64],
        drop_book_mode_marker: bool,
    ) -> CapturedWrites {
        let (_cfg, state_db) = make_test_config_and_db();
        fund_book_fixture(&state_db);
        torus_state::running_hash::capture_begin(&state_db);
        let mut ctx = book_pipeline_ctx(&state_db, on, None, mode);
        for b in &book_fixture_blocks() {
            dispatch_and_execute(&ctx, &state_db, b);
            assert!(
                !ctx.exec_failed.load(std::sync::atomic::Ordering::SeqCst),
                "fixture must not fail-stop (on={on} {mode:?} restarts={restart_after:?})"
            );
            if restart_after.contains(&b.header.height) {
                drop(ctx); // drains + joins W
                if drop_book_mode_marker {
                    state_db
                        .delete_cf_raw(torus_state::cf::CF_NATIVE_MARKETS, b"__book_mode__")
                        .unwrap();
                }
                ctx = book_pipeline_ctx(&state_db, on, None, mode);
            }
        }
        drop(ctx);
        torus_state::running_hash::capture_take(&state_db)
    }

    fn assert_write_sets_equal(a: &CapturedWrites, b: &CapturedWrites, what: &str) {
        let heights = |w: &CapturedWrites| w.iter().map(|(h, _)| *h).collect::<Vec<_>>();
        assert_eq!(heights(a), heights(b), "{what}: flushed heights differ");
        for ((h, x), (_, y)) in a.iter().zip(b.iter()) {
            if x != y {
                let only_a: Vec<_> = x.iter().filter(|e| !y.contains(e)).collect();
                let only_b: Vec<_> = y.iter().filter(|e| !x.contains(e)).collect();
                panic!("{what}: write set of height {h} differs\n  only in first: {only_a:?}\n  only in second: {only_b:?}");
            }
        }
    }

    /// Task 1 GATE: the consensus write set of every block is a function of the
    /// committed blocks alone — identical straight through vs with restarts in
    /// the middle (resident books vs reloaded books), for every BookMode, and
    /// identical serial vs pipelined (deferred book save included).
    #[test]
    fn running_hash_write_set_determinism() {
        use torus_bridge::native_executor::BookMode;
        let restart_patterns: [&[u64]; 3] = [&[1], &[3, 6, 10], &[2, 4, 5, 7, 8, 9, 11, 12]];
        for mode in [
            BookMode::Classic,
            BookMode::OrderRows,
            BookMode::LevelAuthority,
            BookMode::LevelAuthorityChunked,
        ] {
            let serial = run_book_fixture_capturing(false, mode, &[]);
            assert_eq!(
                serial.iter().map(|(h, _)| *h).collect::<Vec<_>>(),
                (1..=13).collect::<Vec<u64>>(),
                "{mode:?}: every height (native and empty) must pass through the hashed flush"
            );
            let total: usize = serial.iter().map(|(_, w)| w.len()).sum();
            assert!(total > 40, "{mode:?}: fixture write set is not vacuous ({total})");
            for on in [false, true] {
                let straight = run_book_fixture_capturing(on, mode, &[]);
                assert_write_sets_equal(&serial, &straight, &format!("{mode:?} serial vs on={on}"));
                for restarts in restart_patterns {
                    let restarted = run_book_fixture_capturing(on, mode, restarts);
                    assert_write_sets_equal(
                        &straight,
                        &restarted,
                        &format!("{mode:?} on={on} straight vs restarts {restarts:?}"),
                    );
                }
            }
        }
    }

    /// Task 1: the node-local `__book_mode__` row is re-written after a restart
    /// on a DB that lacks it (pre-marker history). That write is excluded from
    /// the hashed set, so the consensus write sets still agree.
    #[test]
    fn running_hash_write_set_determinism_ignores_book_mode_marker_rewrite() {
        use torus_bridge::native_executor::BookMode;
        for mode in [BookMode::Classic, BookMode::LevelAuthorityChunked] {
            for on in [false, true] {
                let straight = run_book_fixture_capturing(on, mode, &[]);
                let rewritten = run_book_fixture_capturing_with(on, mode, &[3, 9], true);
                assert_write_sets_equal(
                    &straight,
                    &rewritten,
                    &format!("{mode:?} on={on} marker re-written after restart"),
                );
            }
        }
    }

    /// Fold the captured per-block write sets through the hash function.
    fn fold_captured(w: &CapturedWrites) -> (u64, [u8; 32]) {
        let mut h = [0u8; 32];
        for (height, writes) in w {
            h = torus_state::running_hash::next_running_hash(&h, *height, writes);
        }
        (w.last().map(|(height, _)| *height).unwrap_or(0), h)
    }

    /// Task 3: `META_RUNNING_STATE_HASH` after the book fixture is the chained
    /// function over every block's captured write set, and it is byte-identical
    /// serial vs pipelined, with and without restarts, in every BookMode.
    #[test]
    fn running_hash_identical_serial_pipelined_restart_every_book_mode() {
        use torus_bridge::native_executor::BookMode;
        for mode in [
            BookMode::Classic,
            BookMode::OrderRows,
            BookMode::LevelAuthority,
            BookMode::LevelAuthorityChunked,
        ] {
            let mut finals = Vec::new();
            for (on, restarts) in [
                (false, &[][..]),
                (true, &[][..]),
                (false, &[2, 4, 7, 10][..]),
                (true, &[1, 3, 6, 9, 12][..]),
            ] {
                let (_cfg, state_db) = make_test_config_and_db();
                fund_book_fixture(&state_db);
                torus_state::running_hash::capture_begin(&state_db);
                let mut ctx = book_pipeline_ctx(&state_db, on, None, mode);
                for b in &book_fixture_blocks() {
                    dispatch_and_execute(&ctx, &state_db, b);
                    if restarts.contains(&b.header.height) {
                        drop(ctx);
                        ctx = book_pipeline_ctx(&state_db, on, None, mode);
                    }
                }
                drop(ctx);
                let captured = torus_state::running_hash::capture_take(&state_db);
                let stored = torus_state::running_hash::read_running_hash(&state_db);
                assert_eq!(stored, Some(fold_captured(&captured)), "{mode:?} on={on} {restarts:?}");
                finals.push(stored.unwrap());
            }
            assert!(finals.windows(2).all(|w| w[0] == w[1]), "{mode:?}: {finals:?}");
        }
    }

    const KECCAK_EMPTY_CODE: B256 = B256::new([
        0xc5, 0xd2, 0x46, 0x01, 0x86, 0xf7, 0x23, 0x3c, 0x92, 0x7e, 0x7d, 0xb2, 0xdc, 0xc7, 0x03,
        0xc0, 0xe5, 0x00, 0xb6, 0x53, 0xca, 0x82, 0x27, 0x3b, 0x7b, 0xfa, 0xd8, 0x04, 0x5d, 0x85,
        0xa4, 0x70,
    ]);

    /// A signed EIP-1559 contract creation whose init code stores 1 at slot 0
    /// (`PUSH1 1 PUSH1 0 SSTORE`) — a bundle with an account, a storage slot
    /// and fee revenue.
    fn signed_sstore_create(key: &k256::ecdsa::SigningKey, nonce: u64) -> Vec<u8> {
        signed_eip1559(
            key,
            nonce,
            alloy_primitives::TxKind::Create,
            vec![0x60, 0x01, 0x60, 0x00, 0x55],
        )
    }

    /// A signed EIP-1559 tx (`to` call or create, `input` calldata / init code).
    fn signed_eip1559(
        key: &k256::ecdsa::SigningKey,
        nonce: u64,
        to: alloy_primitives::TxKind,
        input: Vec<u8>,
    ) -> Vec<u8> {
        signed_eip1559_with_value(key, nonce, to, input, U256::ZERO)
    }

    /// [`signed_eip1559`] carrying `value` wei.
    fn signed_eip1559_with_value(
        key: &k256::ecdsa::SigningKey,
        nonce: u64,
        to: alloy_primitives::TxKind,
        input: Vec<u8>,
        value: U256,
    ) -> Vec<u8> {
        signed_eip1559_gas(key, nonce, to, input, value, 300_000)
    }

    /// [`signed_eip1559_with_value`] declaring `gas_limit`.
    fn signed_eip1559_gas(
        key: &k256::ecdsa::SigningKey,
        nonce: u64,
        to: alloy_primitives::TxKind,
        input: Vec<u8>,
        value: U256,
        gas_limit: u64,
    ) -> Vec<u8> {
        use alloy_consensus::{SignableTransaction, TxEip1559, TxEnvelope};
        use alloy_rlp::Encodable;
        let tx = TxEip1559 {
            chain_id: TORUS_CHAIN_ID,
            nonce,
            max_fee_per_gas: 1_000_000_000,
            max_priority_fee_per_gas: 0,
            gas_limit,
            to,
            value,
            input: alloy_primitives::Bytes::from(input),
            access_list: Default::default(),
        };
        let sig_hash = tx.signature_hash();
        let (sig, recid) = key.sign_prehash_recoverable(sig_hash.as_slice()).unwrap();
        let signature = alloy_primitives::Signature::new(
            U256::from_be_slice(sig.r().to_bytes().as_slice()),
            U256::from_be_slice(sig.s().to_bytes().as_slice()),
            recid.is_y_odd(),
        );
        let mut buf = Vec::new();
        TxEnvelope::Eip1559(tx.into_signed(signature)).encode(&mut buf);
        buf
    }

    /// Out-of-batch fixture (Task 0 (a)-(c)), epoch_length 4:
    ///   1  EVM contract creation (bundle: accounts + storage)   serial
    ///   2  empty + a buffered equivocation slash                 serial marker
    ///   3  empty
    ///   4  empty, epoch boundary (nothing hashed: no snapshot)    serial marker
    fn out_of_batch_fixture() -> (Vec<TorusBlock>, k256::ecdsa::SigningKey, Address) {
        let key = k256::ecdsa::SigningKey::from_slice(&[61u8; 32]).unwrap();
        let mut blocks: Vec<TorusBlock> = (1..=4).map(|h| make_block(h, vec![])).collect();
        blocks[0].evm_transactions = vec![signed_sstore_create(&key, 0)];
        blocks[0].header.evm_tx_count = 1;
        link_blocks(&mut blocks);
        (blocks, key, Address::repeat_byte(0x77))
    }

    fn run_out_of_batch_fixture(restart_after: &[u64]) -> (StateDb, CapturedWrites) {
        let (blocks, key, validator) = out_of_batch_fixture();
        let (mut config, state_db) = make_test_config_and_db();
        config.epoch_length = 4;
        let sender = {
            let pubkey = key.verifying_key().to_encoded_point(false);
            Address::from_slice(&alloy_primitives::keccak256(&pubkey.as_bytes()[1..])[12..])
        };
        state_db
            .put_account(
                &sender,
                &revm::state::AccountInfo {
                    balance: U256::from(1_000_000_000_000_000_000u128),
                    nonce: 0,
                    code_hash: KECCAK_EMPTY_CODE,
                    code: None,
                    account_id: None,
                },
            )
            .unwrap();
        register_proposer(&state_db, validator);
        torus_state::running_hash::capture_begin(&state_db);
        let mut ctx = make_exec_ctx(&config, &state_db);
        for b in &blocks {
            let durable = persist_committed_block_durably(&state_db, b);
            let slashes = if b.header.height == 2 {
                vec![PendingSlash {
                    validator,
                    fraction_bps: 500,
                    reason: SlashReason::DoubleSign,
                    tombstone: true,
                }]
            } else {
                vec![]
            };
            ctx.execute_committed_block_with(b, slashes, durable);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst));
            if restart_after.contains(&b.header.height) {
                drop(ctx);
                ctx = make_exec_ctx(&config, &state_db);
            }
        }
        drop(ctx);
        let captured = torus_state::running_hash::capture_take(&state_db);
        (state_db, captured)
    }

    /// Task 3: every out-of-batch consensus write of Task 0 enters `D(n)` of the
    /// height whose execution made it durable — with the value the DB holds.
    #[test]
    fn running_hash_covers_out_of_batch_consensus_writes() {
        use torus_state::cf::{CF_SLASH_RECORDS, CF_STAKING_VALIDATORS, CF_STORAGE};
        use torus_state::running_hash::hashed_cf_id;
        let (state_db, captured) = run_out_of_batch_fixture(&[]);
        assert_eq!(captured.iter().map(|(h, _)| *h).collect::<Vec<_>>(), vec![1, 2, 3, 4]);
        let at = |h: u64| &captured.iter().find(|(x, _)| *x == h).unwrap().1;
        let in_db = |id: u8, cf: &str, w: &[torus_state::running_hash::WriteEntry]| {
            let rows: Vec<_> = w.iter().filter(|e| e.0 == id).collect();
            for (_, k, v) in &rows {
                assert_eq!(&state_db.get_cf_raw(cf, k).unwrap(), v, "{cf} entry must equal the DB");
            }
            rows.len()
        };
        // (c) EVM bundle: the contract's storage slot (only reachable via the bundle).
        let storage = hashed_cf_id(CF_STORAGE).unwrap();
        assert_eq!(in_db(storage, CF_STORAGE, at(1)), 1, "slot 0 of the created contract");
        // (a) slash at 2: the slash record and the slashed / tombstoned
        // validator row.
        let slashes = hashed_cf_id(CF_SLASH_RECORDS).unwrap();
        assert_eq!(in_db(slashes, CF_SLASH_RECORDS, at(2)), 1, "slash record");
        let validators = hashed_cf_id(CF_STAKING_VALIDATORS).unwrap();
        assert_eq!(in_db(validators, CF_STAKING_VALIDATORS, at(2)), 1, "validator row");
        // 3 is empty: nothing hashed.
        assert!(at(3).is_empty(), "{:?}", at(3));
        // (b) epoch boundary 4 (empty block): only what its execution wrote,
        // which includes the validator-set plan for 8 (bug (b)); every entry
        // equals the DB.
        let plan8 = [b"epoch_vset:plan:".as_slice(), &8u64.to_be_bytes()].concat();
        assert!(at(4).iter().any(|(_, k, _)| *k == plan8), "{:?}", at(4));
        for (id, k, v) in at(4) {
            let cf = torus_state::running_hash::HASHED_CFS.iter().find(|(i, _)| i == id).unwrap().1;
            assert_eq!(&state_db.get_cf_raw(cf, k).unwrap(), v, "{cf} entry must equal the DB");
        }
        // Restarts do not change the hash.
        let (db2, _) = run_out_of_batch_fixture(&[1, 2, 3]);
        assert_eq!(
            torus_state::running_hash::read_running_hash(&db2),
            torus_state::running_hash::read_running_hash(&state_db)
        );
        assert_eq!(
            torus_state::running_hash::read_running_hash(&state_db),
            Some(fold_captured(&captured))
        );
    }

    /// Review finding 1: the activation height is CHAIN-WIDE (chain config):
    /// nodes that ran a pre-upgrade binary (no running hash) up to different
    /// applied heights below it — serial or pipelined — and a node synced
    /// from genesis all hold the identical hash from the activation height
    /// on. A node whose DB is already above it is hash-unverified.
    #[test]
    fn running_hash_chain_wide_activation_nodes_upgraded_at_different_heights_agree() {
        use torus_bridge::native_executor::BookMode;
        use torus_state::running_hash::{
            configure_activation, read_activation_height, read_running_hash, read_unverified_since,
        };
        let mode = BookMode::LevelAuthorityChunked;
        let act = 6u64;
        let blocks = book_fixture_blocks();
        let node = |upgraded_at: usize, on: bool| {
            let (_c, db) = make_test_config_and_db();
            configure_activation(&db, None).unwrap(); // pre-upgrade binary
            fund_book_fixture(&db);
            let ctx = book_pipeline_ctx(&db, on, None, mode);
            for b in &blocks[..upgraded_at] {
                dispatch_and_execute(&ctx, &db, b);
            }
            drop(ctx);
            configure_activation(&db, Some(act)).unwrap(); // upgrade + restart
            torus_state::running_hash::capture_begin(&db);
            let ctx = book_pipeline_ctx(&db, on, None, mode);
            for b in &blocks[upgraded_at..] {
                dispatch_and_execute(&ctx, &db, b);
            }
            assert!(!ctx.exec_failed.load(Ordering::SeqCst));
            drop(ctx);
            let captured = torus_state::running_hash::capture_take(&db);
            (db, captured)
        };
        let (genesis_node, captured) = node(0, false);
        assert_eq!(captured.first().map(|(h, _)| *h), Some(act), "first hashed height = activation");
        assert_eq!(read_activation_height(&genesis_node), Some(act));
        let reference = read_running_hash(&genesis_node).unwrap();
        assert_eq!(reference, fold_captured(&captured), "h_act chains from zeros");
        assert_eq!(reference.0, 13);
        for (upgraded_at, on) in [(2, false), (3, true), (5, false), (5, true)] {
            let (db, _) = node(upgraded_at, on);
            assert_eq!(read_running_hash(&db), Some(reference), "upgraded at {upgraded_at} on={on}");
            assert_eq!(read_unverified_since(&db), None);
        }
        // DB above the activation height at upgrade: no valid h_{act..}.
        let (late, captured) = node(8, false);
        assert!(captured.is_empty(), "never hashed");
        assert_eq!(read_running_hash(&late), None);
        assert_eq!(read_unverified_since(&late), Some(9));
    }

    /// Task 4: kill after flushing N (committed blocks N+1.. durable, not yet
    /// executed), and kill between exec and flush (pipelined: batch(k) lost on
    /// W after E executed k+1) — the restart replay lands the uncrashed hash.
    #[test]
    fn running_hash_crash_replay_matches_uncrashed_run() {
        use torus_bridge::native_executor::BookMode;
        use torus_state::running_hash::read_running_hash;
        let mode = BookMode::LevelAuthorityChunked;
        let blocks = book_fixture_blocks();
        let reference = {
            let (_c, db) = make_test_config_and_db();
            fund_book_fixture(&db);
            let ctx = book_pipeline_ctx(&db, false, None, mode);
            for b in &blocks {
                dispatch_and_execute(&ctx, &db, b);
            }
            drop(ctx);
            read_running_hash(&db).unwrap()
        };
        assert_eq!(reference.0, 13);

        // (a) kill after flushing 5: 6..=13 committed (dispatch-durable) only.
        for on in [false, true] {
            let (_c, db) = make_test_config_and_db();
            fund_book_fixture(&db);
            let ctx = book_pipeline_ctx(&db, on, None, mode);
            for b in &blocks[..5] {
                dispatch_and_execute(&ctx, &db, b);
            }
            drop(ctx);
            for b in &blocks[5..] {
                let durable = persist_committed_block_durably(&db, b);
                assert!(durable.header && durable.body);
            }
            let ctx = book_pipeline_ctx(&db, false, None, mode);
            let (_last, parked) = TorusApp::replay_committed(&db, &ctx);
            assert_eq!(parked, None);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst));
            drop(ctx);
            assert_eq!(read_running_hash(&db), Some(reference), "(a) on={on}");
        }

        // (b) kill between exec and flush: W's write of 6 fails after E ran 7.
        let (_c, db) = make_test_config_and_db();
        fund_book_fixture(&db);
        let gate = crate::exec_pipeline::WorkerGate::new();
        let ctx = book_pipeline_ctx(&db, true, Some(gate.clone()), mode);
        for b in &blocks[..5] {
            dispatch_and_execute(&ctx, &db, b);
        }
        assert!(ctx.flush_worker.as_ref().unwrap().wait_idle());
        gate.hold();
        dispatch_and_execute(&ctx, &db, &blocks[5]);
        assert!(gate.wait_received(6));
        let (db_t, b7) = (db.clone(), blocks[6].clone());
        let t = std::thread::spawn(move || {
            dispatch_and_execute(&ctx, &db_t, &b7);
            ctx
        });
        std::thread::sleep(std::time::Duration::from_millis(200));
        gate.fail_next();
        gate.release();
        let ctx = t.join().unwrap();
        assert!(ctx.exec_failed.load(Ordering::SeqCst));
        drop(ctx);
        assert_eq!(read_running_hash(&db).map(|(h, _)| h), Some(5), "hash advances only with the batch");
        for b in &blocks[7..] {
            persist_committed_block_durably(&db, b);
        }
        let ctx = book_pipeline_ctx(&db, false, None, mode);
        let (_last, parked) = TorusApp::replay_committed(&db, &ctx);
        assert_eq!(parked, None);
        drop(ctx);
        assert_eq!(read_running_hash(&db), Some(reference), "(b) replay after a lost batch");
    }

    // ---- Running state hash: auto-attestation (Task 6) ----

    fn k256_address(key: &k256::ecdsa::SigningKey) -> Address {
        let pubkey = key.verifying_key().to_encoded_point(false);
        Address::from_slice(&alloy_primitives::keccak256(&pubkey.as_bytes()[1..])[12..])
    }

    /// Register `keys` as ACTIVE validators with equal stake.
    fn seed_active_validators(state_db: &StateDb, keys: &[&k256::ecdsa::SigningKey]) {
        let staking = StakingManager::new(state_db.clone());
        for (i, key) in keys.iter().enumerate() {
            let addr = k256_address(key);
            let v = torus_economics::types::ValidatorState {
                address: addr,
                pubkey: [i as u8 + 1; 32],
                commission_bps: 500,
                self_stake: U256::from(1_000u64),
                total_delegated: U256::ZERO,
                status: torus_economics::types::ValidatorStatus::Active,
                jailed_until: None,
                last_commission_change_block: None,
                oracle_signer: None,
            };
            staking.put_validator(&addr, &v).unwrap();
        }
    }

    /// Execute empty blocks `from..=to` through the live dispatch path.
    fn run_empty_blocks(ctx: &ExecutionContext, state_db: &StateDb, from: u64, to: u64) {
        for h in from..=to {
            dispatch_and_execute(ctx, state_db, &make_block(h, vec![]));
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "height {h}");
        }
    }

    /// The attestations sitting in `mempool`, as `(sender, height, hash)`.
    fn pooled_attestations(mempool: &Mempool) -> Vec<(Address, u64, B256)> {
        mempool
            .select_native_for_block(1_000)
            .into_iter()
            .filter_map(|a| match a.action {
                NativeAction::AttestStateHash { height, hash } => {
                    Some((a.recover_sender().unwrap(), height, hash))
                }
                _ => None,
            })
            .collect()
    }

    /// Task 6: a validator node with a configured account key submits exactly
    /// one attestation per checkpoint once the checkpoint is durable, through
    /// the normal mempool path; after a restart it re-submits only when its
    /// vote is not on-chain yet.
    #[test]
    fn state_hash_autosubmit_once_per_checkpoint_and_after_restart_only_if_missing() {
        use torus_state::running_hash::read_checkpoint;
        let key = k256::ecdsa::SigningKey::from_slice(&[71u8; 32]).unwrap();
        let me = k256_address(&key);
        let (config, state_db) = make_test_config_and_db();
        seed_active_validators(&state_db, &[&key]);
        let new_node = |mempool: &Arc<Mempool>| {
            let ctx = make_exec_ctx_with_mempool(&config, &state_db, Some(mempool.clone()), false);
            assert_eq!(ctx.state_hash.set_attest_key(key.clone()), me);
            ctx
        };
        let pool = |_: ()| {
            Arc::new(Mempool::new(state_db.clone(), torus_mempool::MempoolConfig::default()))
        };

        let m1 = pool(());
        let ctx = new_node(&m1);
        run_empty_blocks(&ctx, &state_db, 1, 99);
        assert!(pooled_attestations(&m1).is_empty(), "no checkpoint before 100");
        run_empty_blocks(&ctx, &state_db, 100, 100);
        let local = B256::from(read_checkpoint(&state_db, 100).expect("checkpoint 100 durable"));
        assert_eq!(pooled_attestations(&m1), vec![(me, 100, local)], "one attestation at 100");
        run_empty_blocks(&ctx, &state_db, 101, 150);
        assert_eq!(pooled_attestations(&m1).len(), 1, "never a second one for 100");
        drop(ctx);

        // Restart before inclusion: the vote is not on-chain -> re-submitted once.
        let m2 = pool(());
        let ctx = new_node(&m2);
        run_empty_blocks(&ctx, &state_db, 151, 152);
        let pooled = m2.select_native_for_block(1_000);
        assert_eq!(pooled.len(), 1, "re-submitted after restart");
        assert!(matches!(pooled[0].action, NativeAction::AttestStateHash { height: 100, .. }));

        // Include it (block 153); restart again: on-chain -> nothing submitted.
        let mut b153 = make_block(153, pooled);
        // The vote is signed at wall-clock time: the block carries that time
        // so the nonce is in the window exec checks against the block time.
        b153.header.timestamp = b153.native_actions[0].nonce / 1000;
        b153.header.parent_hash =
            alloy_primitives::keccak256(make_block(152, vec![]).header.canonical_header_bytes());
        dispatch_and_execute(&ctx, &state_db, &b153);
        let votes = StakingManager::new(state_db.clone()).state_hash_votes(100).unwrap();
        assert_eq!(votes, vec![(me, local.0)], "vote on-chain");
        drop(ctx);
        let m3 = pool(());
        let ctx = new_node(&m3);
        let mut b154 = make_block(154, vec![]);
        b154.header.parent_hash = alloy_primitives::keccak256(b153.header.canonical_header_bytes());
        dispatch_and_execute(&ctx, &state_db, &b154);
        assert!(pooled_attestations(&m3).is_empty(), "vote already on-chain: no re-submit");

        // A node without a key never submits; a key that is not an active
        // validator never submits.
        let m4 = pool(());
        let ctx = make_exec_ctx_with_mempool(&config, &state_db, Some(m4.clone()), false);
        let stranger = k256::ecdsa::SigningKey::from_slice(&[72u8; 32]).unwrap();
        ctx.state_hash.set_attest_key(stranger);
        let mut b155 = make_block(155, vec![]);
        b155.header.parent_hash = alloy_primitives::keccak256(b154.header.canonical_header_bytes());
        dispatch_and_execute(&ctx, &state_db, &b155);
        assert!(pooled_attestations(&m4).is_empty(), "non-validator key");
    }

    // ---- Running state hash: mismatch detection + gated fail-stop (Task 7) ----

    fn validator_keys() -> [k256::ecdsa::SigningKey; 3] {
        [81u8, 82, 83].map(|b| k256::ecdsa::SigningKey::from_slice(&[b; 32]).unwrap())
    }

    /// A node (serial or pipelined) at height 100 with 3 active validators;
    /// returns it with its metrics and its local checkpoint at 100.
    fn node_at_checkpoint(
        pipelined: bool,
        failstop: bool,
    ) -> (ExecutionContext, StateDb, Arc<torus_telemetry::Metrics>, B256) {
        let (config, state_db) = make_test_config_and_db();
        let keys = validator_keys();
        seed_active_validators(&state_db, &[&keys[0], &keys[1], &keys[2]]);
        let mut ctx = make_exec_ctx(&config, &state_db);
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        ctx.metrics = Some(metrics.clone());
        ctx.state_hash = Arc::new(crate::state_hash::StateHashMonitor::with_failstop(failstop));
        if pipelined {
            ctx.attach_flush_worker(None);
        }
        run_empty_blocks(&ctx, &state_db, 1, 100);
        let local = torus_state::running_hash::read_checkpoint(&state_db, 100).unwrap();
        (ctx, state_db, metrics, B256::from(local))
    }

    /// Block 101 carrying `votes` (validator index, hash) for checkpoint 100,
    /// then an empty 102 (lets a pipelined node make 101 durable).
    fn run_votes(ctx: &ExecutionContext, state_db: &StateDb, votes: &[(usize, B256)]) -> TorusBlock {
        let keys = validator_keys();
        let actions = votes
            .iter()
            .enumerate()
            .map(|(i, (v, hash))| {
                torus_types::eip712::sign_native_action(
                    NativeAction::AttestStateHash { height: 100, hash: *hash },
                    block_time_ms(101) + i as u64,
                    &keys[*v],
                )
            })
            .collect();
        let b101 = make_block(101, actions);
        dispatch_and_execute(ctx, state_db, &b101);
        let mut b102 = make_block(102, vec![]);
        b102.header.parent_hash = alloy_primitives::keccak256(b101.header.canonical_header_bytes());
        dispatch_and_execute(ctx, state_db, &b102);
        b101
    }

    fn mismatch_count(metrics: &torus_telemetry::Metrics, who: &str) -> u64 {
        let text = metrics.encode();
        let needle = format!("torus_state_hash_mismatch_total{{validator=\"{who}\"}} ");
        text.lines()
            .find_map(|l| l.strip_prefix(&needle))
            .map(|v| v.trim().parse().unwrap())
            .unwrap_or(0)
    }

    /// Task 7: a vote that differs from the local checkpoint raises the
    /// mismatch metric for that validator on every node (serial and pipelined),
    /// once; matching votes raise nothing; default (fail-stop unset) never
    /// latches; detection never writes state.
    #[test]
    fn state_hash_mismatch_differing_vote_reported_on_every_node_and_never_writes() {
        let addr_of = |i: usize| k256_address(&validator_keys()[i]).to_string();
        for pipelined in [false, true] {
            let (ctx, db, metrics, local) = node_at_checkpoint(pipelined, false);
            let other = B256::repeat_byte(0xee);
            let b101 = run_votes(&ctx, &db, &[(0, local), (1, other)]);
            assert_eq!(mismatch_count(&metrics, &addr_of(1)), 1, "pipelined={pipelined}");
            assert_eq!(mismatch_count(&metrics, &addr_of(0)), 0, "matching vote");
            assert_eq!(mismatch_count(&metrics, "quorum"), 0);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "fail-stop off by default");

            // Re-running detection (fresh monitor, fail-stop on) writes nothing.
            drop(ctx); // drains W
            let before = dump_all_cfs(&db);
            let monitor = crate::state_hash::StateHashMonitor::with_failstop(true);
            let latch = AtomicBool::new(false);
            for _ in 0..2 {
                monitor.after_block(&b101, &db, None, Some(&metrics), &latch);
            }
            assert_dumps_equal(&before, &dump_all_cfs(&db), "detection is read-only");
            assert!(!latch.load(Ordering::SeqCst), "no quorum -> nothing to fail-stop on");
        }
    }

    /// Task 7: a quorum hash that differs from the local checkpoint is reported
    /// (`validator="quorum"`); it latches `exec_failed` ONLY with fail-stop on.
    /// All votes in without a quorum -> the no-quorum metric.
    #[test]
    fn state_hash_mismatch_quorum_failstop_gated_and_no_quorum_metric() {
        let x = B256::repeat_byte(0xee);
        for failstop in [false, true] {
            let (ctx, db, metrics, _local) = node_at_checkpoint(false, failstop);
            run_votes(&ctx, &db, &[(0, x), (1, x), (2, x)]);
            assert_eq!(
                StakingManager::new(db.clone()).state_hash_quorum(100).unwrap(),
                Some(x.0),
                "quorum recorded on-chain"
            );
            assert_eq!(mismatch_count(&metrics, "quorum"), 1, "failstop={failstop}");
            assert_eq!(ctx.exec_failed.load(Ordering::SeqCst), failstop, "latched iff fail-stop on");
        }

        let (ctx, db, metrics, local) = node_at_checkpoint(false, true);
        run_votes(&ctx, &db, &[(0, local), (1, local), (2, x)]);
        assert_eq!(StakingManager::new(db.clone()).state_hash_quorum(100).unwrap(), None);
        assert_eq!(metric_value(&metrics.encode(), "torus_state_hash_no_quorum_total"), 1.0);
        assert!(!ctx.exec_failed.load(Ordering::SeqCst), "no quorum never latches");

        // Matching quorum: no mismatch, no latch.
        let (ctx, db, metrics, local) = node_at_checkpoint(false, true);
        run_votes(&ctx, &db, &[(0, local), (1, local), (2, local)]);
        assert_eq!(mismatch_count(&metrics, "quorum"), 0);
        assert!(!ctx.exec_failed.load(Ordering::SeqCst));
    }

    // ---- Review fixes (s83 independent review of the running state hash) ----

    /// Empty blocks `prev+1..=to` linked to the ACTUAL `prev` (after a block
    /// that carried actions); returns the last block.
    fn run_linked_empty(ctx: &ExecutionContext, db: &StateDb, prev: &TorusBlock, to: u64) -> TorusBlock {
        let mut prev = prev.clone();
        for h in prev.header.height + 1..=to {
            let mut b = make_block(h, vec![]);
            b.header.parent_hash = alloy_primitives::keccak256(prev.header.canonical_header_bytes());
            dispatch_and_execute(ctx, db, &b);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "height {h}");
            prev = b;
        }
        prev
    }

    fn mempool_for(db: &StateDb) -> Arc<Mempool> {
        Arc::new(Mempool::new(db.clone(), torus_mempool::MempoolConfig::default()))
    }

    /// Review finding 1: a hash-unverified node (DB above the activation
    /// height when it upgraded) never attests and reports itself unverified;
    /// one upgraded below the activation height attests every checkpoint.
    #[test]
    fn state_hash_unverified_node_never_attests() {
        use torus_state::running_hash::{configure_activation, read_unverified_since};
        let key = k256::ecdsa::SigningKey::from_slice(&[73u8; 32]).unwrap();
        for (upgraded_at, attests) in [(30u64, true), (60, false)] {
            let (config, db) = make_test_config_and_db();
            seed_active_validators(&db, &[&key]);
            configure_activation(&db, None).unwrap();
            let ctx = make_exec_ctx(&config, &db);
            run_empty_blocks(&ctx, &db, 1, upgraded_at);
            drop(ctx);
            configure_activation(&db, Some(50)).unwrap();
            let pool = mempool_for(&db);
            let mut ctx = make_exec_ctx_with_mempool(&config, &db, Some(pool.clone()), false);
            let metrics = Arc::new(torus_telemetry::Metrics::new());
            ctx.metrics = Some(metrics.clone());
            ctx.state_hash.set_attest_key(key.clone());
            run_empty_blocks(&ctx, &db, upgraded_at + 1, 250);
            let mut heights: Vec<u64> = pooled_attestations(&pool).iter().map(|(_, h, _)| *h).collect();
            heights.sort();
            let gauge = metric_value(&metrics.encode(), "torus_state_hash_unverified");
            if attests {
                assert_eq!(heights, vec![100, 200], "upgraded below the activation height: attests");
                assert_eq!(gauge, 0.0);
            } else {
                assert_eq!(read_unverified_since(&db), Some(61));
                assert!(heights.is_empty(), "hash-unverified: never attests ({heights:?})");
                assert_eq!(gauge, 1.0, "unverified gauge");
            }
        }
    }

    /// Review findings 1 / 5: a node whose local chain broke — a block whose
    /// hashed flush was lost while the applied marker moved past it (the
    /// serial path after a failed flush) — is hash-unverified: it never
    /// chains over the gap and never fail-stops, even on an on-chain quorum
    /// that differs from a checkpoint it still holds (the mismatch is still
    /// reported).
    #[test]
    fn state_hash_gap_marks_node_unverified_no_failstop() {
        use torus_state::running_hash::{read_running_hash, read_unverified_since};
        let (ctx, db, metrics, _local) = node_at_checkpoint(false, true);
        let b101 = make_block(101, vec![]);
        persist_committed_block_durably(&db, &b101);
        write_native_applied_height(&db, 101); // 101's hashed batch lost
        run_empty_blocks(&ctx, &db, 102, 105);
        assert_eq!(read_unverified_since(&db), Some(102));
        assert_eq!(read_running_hash(&db).map(|(h, _)| h), Some(100), "never chained over 101");
        let x = B256::repeat_byte(0xee);
        let keys = validator_keys();
        let votes = (0..3)
            .map(|v| {
                torus_types::eip712::sign_native_action(
                    NativeAction::AttestStateHash { height: 100, hash: x },
                    block_time_ms(106) + v as u64,
                    &keys[v],
                )
            })
            .collect();
        let b106 = make_block(106, votes);
        dispatch_and_execute(&ctx, &db, &b106);
        run_linked_empty(&ctx, &db, &b106, 107);
        assert_eq!(StakingManager::new(db.clone()).state_hash_quorum(100).unwrap(), Some(x.0));
        assert_eq!(mismatch_count(&metrics, "quorum"), 1, "mismatch still reported");
        assert!(!ctx.exec_failed.load(Ordering::SeqCst), "hash-unverified: no fail-stop");
        assert_eq!(torus_state::running_hash::read_divergence(&db), None);
        assert_eq!(metric_value(&metrics.encode(), "torus_state_hash_unverified"), 1.0);
    }

    /// Epoch / running-hash fixture validators: (account key, consensus key);
    /// the 5th has half the stake (it leaves a 4-seat set).
    fn epoch_fixture_validators() -> Vec<(k256::ecdsa::SigningKey, [u8; 32])> {
        (1..=5u8)
            .map(|i| {
                (
                    k256::ecdsa::SigningKey::from_slice(&[0x70 + i; 32]).unwrap(),
                    ed25519_dalek::SigningKey::from_bytes(&[0x30 + i; 32]).verifying_key().to_bytes(),
                )
            })
            .collect()
    }

    /// Seed the fixture validators like a genesis: Active rows + the recorded
    /// installed set.
    fn seed_epoch_fixture(db: &StateDb, vals: &[(k256::ecdsa::SigningKey, [u8; 32])]) {
        use torus_economics::types::{ValidatorState, ValidatorStatus};
        let staking = StakingManager::new(db.clone());
        for (i, (key, pubkey)) in vals.iter().enumerate() {
            let addr = k256_address(key);
            let tokens = if i == 4 { 500u64 } else { 1_000 };
            let row = ValidatorState {
                address: addr,
                pubkey: *pubkey,
                commission_bps: 500,
                self_stake: U256::from(tokens) * U256::from(10u64).pow(U256::from(18u64)),
                total_delegated: U256::ZERO,
                status: ValidatorStatus::Active,
                jailed_until: None,
                last_commission_change_block: None,
                oracle_signer: None,
            };
            staking.put_validator(&addr, &row).unwrap();
        }
        let set = EpochManager::compute_new_validator_set(&staking, u32::MAX, 0).unwrap();
        staking.record_genesis_epoch_set(&set).unwrap();
    }

    /// Blocks 1..=8 (epoch length 4): validator 0 rotates its consensus key at
    /// 2 (planned at 4, installed at 8), validator 1 changes its commission at
    /// 6. Returns the blocks and the rotated key.
    fn epoch_fixture_blocks(vals: &[(k256::ecdsa::SigningKey, [u8; 32])]) -> (Vec<TorusBlock>, [u8; 32]) {
        let rotated_key = ed25519_dalek::SigningKey::from_bytes(&[0x3f; 32]).verifying_key().to_bytes();
        let rotate = torus_types::eip712::sign_native_action(
            NativeAction::RotateValidatorKey { new_pubkey: torus_types::PublicKey(rotated_key) },
            NONCE_BASE + 1,
            &vals[0].0,
        );
        let commission = torus_types::eip712::sign_native_action(
            NativeAction::UpdateCommission { new_rate: 600 },
            NONCE_BASE + 1,
            &vals[1].0,
        );
        let mut blocks: Vec<TorusBlock> = (1..=8)
            .map(|h| {
                make_block(
                    h,
                    match h {
                        2 => vec![rotate.clone()],
                        6 => vec![commission.clone()],
                        _ => vec![],
                    },
                )
            })
            .collect();
        link_blocks(&mut blocks);
        (blocks, rotated_key)
    }

    /// Consensus bug (b) follow-up: `cf_staking_validators` is hashed. Three
    /// replicas whose execution lags the consensus thread by 1, 2 and 4 blocks
    /// at the boundaries 4 and 8 (key rotation installed at 8, validator 4
    /// Active -> Candidate at 8, a commission change at 6) hand hotstuff the
    /// same updates and record the identical per-height write sets and hash —
    /// and those write sets carry the validator rows exactly as the DB holds
    /// them. Replaces the consensus-thread-write test of review finding 2.
    ///
    /// RED before the re-inclusion: no validator-row entry in any write set.
    #[test]
    fn running_hash_epoch_rotation_identical_across_exec_lag_with_validator_rows() {
        use torus_economics::types::ValidatorStatus;
        use torus_state::cf::CF_STAKING_VALIDATORS;
        use torus_state::running_hash::{hashed_cf_id, read_running_hash};
        let vals = epoch_fixture_validators();
        let (blocks, rotated_key) = epoch_fixture_blocks(&vals);
        let node = |lag: u64| {
            let (mut config, db) = make_test_config_and_db();
            config.epoch_length = 4;
            config.max_validators = 4;
            seed_epoch_fixture(&db, &vals);
            let mut app = TorusApp::new(db.clone(), &config, None, None, None);
            torus_state::running_hash::capture_begin(&db);
            let ctx = make_exec_ctx(&config, &db);
            let mut next = 1u64;
            let mut seen = Vec::new();
            for boundary in [4u64, 8] {
                while next + lag <= boundary {
                    dispatch_and_execute(&ctx, &db, &blocks[next as usize - 1]);
                    next += 1;
                }
                let before = dump_all_cfs(&db);
                let updates = app.epoch_validator_set_updates(boundary).expect("plan ready");
                assert!(before == dump_all_cfs(&db), "consensus thread wrote the DB at {boundary}");
                seen.push(canonical_updates(updates));
            }
            while next <= 8 {
                dispatch_and_execute(&ctx, &db, &blocks[next as usize - 1]);
                next += 1;
            }
            assert!(!ctx.exec_failed.load(Ordering::SeqCst));
            drop(ctx);
            drop(app);
            let captured = torus_state::running_hash::capture_take(&db);
            (seen, captured, read_running_hash(&db), db)
        };
        let nodes: Vec<_> = [1u64, 2, 4].into_iter().map(node).collect();
        for (i, n) in nodes.iter().enumerate().skip(1) {
            assert_eq!(n.0, nodes[0].0, "node {i}: hotstuff updates per boundary");
            assert_eq!(n.1, nodes[0].1, "node {i}: per-height hashed write sets");
            assert_eq!(n.2, nodes[0].2, "node {i}: running hash");
        }
        let (seen, captured, hash, db) = &nodes[0];
        assert_eq!(*hash, Some(fold_captured(captured)));
        assert_eq!(seen[0], None, "first boundary: no plan");
        let (ins, del) = seen[1].clone().expect("plan for 8 changes the set");
        assert!(ins.iter().any(|(k, _)| *k == rotated_key), "{ins:?}");
        assert!(del.contains(&vals[0].1) && del.contains(&vals[4].1), "{del:?}");

        let staking = StakingManager::new(db.clone());
        let row = |i: usize| staking.get_validator(&k256_address(&vals[i].0)).unwrap().unwrap();
        assert_eq!(row(0).pubkey, rotated_key);
        assert_eq!(row(1).commission_bps, 600);
        assert_eq!(row(4).status, ValidatorStatus::Candidate);
        // The validator rows each height's execution wrote are hashed with the
        // bytes the DB holds.
        let id = hashed_cf_id(CF_STAKING_VALIDATORS).expect("validator rows are hashed");
        let rows_at = |h: u64| -> Vec<(Vec<u8>, Option<Vec<u8>>)> {
            captured
                .iter()
                .find(|(x, _)| *x == h)
                .unwrap()
                .1
                .iter()
                .filter(|e| e.0 == id)
                .map(|(_, k, v)| (k.clone(), v.clone()))
                .collect()
        };
        let db_row = |i: usize| {
            let key = k256_address(&vals[i].0).to_vec();
            let v = db.get_cf_raw(CF_STAKING_VALIDATORS, &key).unwrap();
            (key, v)
        };
        assert!(rows_at(6).contains(&db_row(1)), "commission change at 6: {:?}", rows_at(6));
        let at8 = rows_at(8);
        assert!(at8.contains(&db_row(0)), "rotated key at 8: {at8:?}");
        assert!(at8.contains(&db_row(4)), "status change at 8: {at8:?}");
    }

    /// Consensus bug (b) follow-up: a validator row corrupted on one node (1
    /// wei of self-stake, below any power / plan effect) diverges its running
    /// hash at the next execution write of that row (the commission change at
    /// 6). RED before the re-inclusion: identical hashes.
    #[test]
    fn running_hash_corrupted_validator_row_diverges() {
        use torus_state::running_hash::read_running_hash;
        let vals = epoch_fixture_validators();
        let (blocks, _) = epoch_fixture_blocks(&vals);
        let node = |corrupt: bool| {
            let (mut config, db) = make_test_config_and_db();
            config.epoch_length = 4;
            config.max_validators = 4;
            seed_epoch_fixture(&db, &vals);
            let ctx = make_exec_ctx(&config, &db);
            for b in &blocks[..7] {
                if corrupt && b.header.height == 6 {
                    let staking = StakingManager::new(db.clone());
                    let addr = k256_address(&vals[1].0);
                    let mut v = staking.get_validator(&addr).unwrap().unwrap();
                    v.self_stake += U256::from(1u64);
                    staking.put_validator(&addr, &v).unwrap();
                }
                dispatch_and_execute(&ctx, &db, b);
                assert!(!ctx.exec_failed.load(Ordering::SeqCst));
            }
            drop(ctx);
            read_running_hash(&db)
        };
        let (clean, corrupted) = (node(false), node(true));
        assert_eq!(clean.map(|(h, _)| h), Some(7));
        assert_ne!(clean, corrupted, "a corrupted validator row must change the hash");
    }

    /// Review finding 3: an attestation admitted to the mempool but dropped
    /// before inclusion is re-signed with a fresh nonce and resubmitted —
    /// only once the previous signature can no longer land (resubmit window;
    /// 0 here) — until the vote is ON-CHAIN. A late landing of the dropped
    /// one is rejected on-chain (first vote wins): never a second vote.
    #[test]
    fn state_hash_autosubmit_retries_until_on_chain_with_fresh_nonce() {
        let key = k256::ecdsa::SigningKey::from_slice(&[74u8; 32]).unwrap();
        let me = k256_address(&key);
        let node = |resubmit_after_ms: Option<u64>| {
            let (config, db) = make_test_config_and_db();
            seed_active_validators(&db, &[&key]);
            let m1 = mempool_for(&db);
            let mut ctx = make_exec_ctx_with_mempool(&config, &db, Some(m1.clone()), false);
            let mut monitor = crate::state_hash::StateHashMonitor::with_failstop(false);
            if let Some(ms) = resubmit_after_ms {
                monitor = monitor.with_resubmit_after_ms(ms);
            }
            ctx.state_hash = Arc::new(monitor);
            ctx.state_hash.set_attest_key(key.clone());
            run_empty_blocks(&ctx, &db, 1, 100);
            (ctx, db, m1)
        };

        // Default window: the dropped signature may still land — no resubmission yet.
        let (mut ctx, db, m1) = node(None);
        assert_eq!(pooled_attestations(&m1).len(), 1);
        let m2 = mempool_for(&db);
        ctx.mempool = Some(m2.clone()); // m1 dropped it
        run_empty_blocks(&ctx, &db, 101, 105);
        assert!(pooled_attestations(&m2).is_empty(), "previous nonce still live: no resubmission");
        drop(ctx);

        // Window elapsed: re-signed and resubmitted until on-chain.
        let (mut ctx, db, m1) = node(Some(0));
        let first = m1.select_native_for_block(1_000);
        assert_eq!(first.len(), 1);
        let m2 = mempool_for(&db);
        ctx.mempool = Some(m2.clone()); // m1 dropped it
        run_empty_blocks(&ctx, &db, 101, 101);
        let second = m2.select_native_for_block(1_000);
        assert_eq!(second.len(), 1, "resubmitted after the drop");
        assert!(matches!(second[0].action, NativeAction::AttestStateHash { height: 100, .. }));
        assert_ne!(second[0].nonce, first[0].nonce, "fresh nonce");
        // The resubmitted one lands, and the dropped one lands late: one vote.
        let local = torus_state::running_hash::read_checkpoint(&db, 100).unwrap();
        let mut b102 = make_block(102, vec![second[0].clone(), first[0].clone()]);
        // Votes are signed at wall-clock time: the block carries that time so
        // both nonces are in the window exec checks against the block time.
        b102.header.timestamp = second[0].nonce / 1000;
        ctx.mempool = Some(mempool_for(&db));
        dispatch_and_execute(&ctx, &db, &b102);
        assert_eq!(
            StakingManager::new(db.clone()).state_hash_votes(100).unwrap(),
            vec![(me, local)],
            "exactly one on-chain vote"
        );
        // On-chain: never submitted again.
        let m3 = mempool_for(&db);
        ctx.mempool = Some(m3.clone());
        run_linked_empty(&ctx, &db, &b102, 110);
        assert!(pooled_attestations(&m3).is_empty(), "vote on-chain: done");
    }

    /// Review finding 4: the fail-stop survives a restart. With fail-stop on,
    /// a quorum mismatch persists a node-local "diverged at checkpoint h"
    /// record with the latch; at boot the record re-latches `exec_failed`
    /// (so exit(70) + supervisor restart cannot resume voting). Fail-stop
    /// off: nothing recorded, nothing re-latched.
    #[test]
    fn state_hash_failstop_record_persists_and_relatches_at_boot() {
        use torus_state::running_hash::read_divergence;
        let x = B256::repeat_byte(0xee);
        let (ctx, db, _m, _local) = node_at_checkpoint(false, true);
        run_votes(&ctx, &db, &[(0, x), (1, x), (2, x)]);
        assert!(ctx.exec_failed.load(Ordering::SeqCst));
        drop(ctx);
        assert_eq!(read_divergence(&db), Some(100), "record persisted");
        let latch = AtomicBool::new(false);
        crate::state_hash::StateHashMonitor::with_failstop(true).relatch_at_boot(&db, &latch);
        assert!(latch.load(Ordering::SeqCst), "re-latched at boot");
        let latch = AtomicBool::new(false);
        crate::state_hash::StateHashMonitor::with_failstop(false).relatch_at_boot(&db, &latch);
        assert!(!latch.load(Ordering::SeqCst), "fail-stop off at boot: not re-latched");

        let (ctx, db, _m, _local) = node_at_checkpoint(false, false);
        run_votes(&ctx, &db, &[(0, x), (1, x), (2, x)]);
        drop(ctx);
        assert_eq!(read_divergence(&db), None, "fail-stop off: nothing recorded");
    }

    /// Review test gap: under the exec pipeline a block's votes sit in the
    /// parent layer (frozen, not durable: W is held) while the next block
    /// executes over it; that block's vote must complete the quorum by
    /// reading them through the parent layer.
    #[test]
    fn state_hash_pipelined_votes_in_parent_layer_complete_quorum_next_block() {
        let keys = validator_keys();
        let x = B256::repeat_byte(0x42);
        let vote = |v: usize| {
            torus_types::eip712::sign_native_action(
                NativeAction::AttestStateHash { height: 100, hash: x },
                block_time_ms(101) + v as u64,
                &keys[v],
            )
        };
        let (config, db) = make_test_config_and_db();
        seed_active_validators(&db, &[&keys[0], &keys[1], &keys[2]]);
        let gate = crate::exec_pipeline::WorkerGate::new();
        let mut ctx = make_exec_ctx(&config, &db);
        ctx.attach_flush_worker(Some(gate.clone()));
        run_empty_blocks(&ctx, &db, 1, 100);
        assert!(ctx.flush_worker.as_ref().unwrap().wait_idle());
        let b101 = make_block(101, vec![vote(0), vote(1)]);
        let mut b102 = make_block(102, vec![vote(2)]);
        b102.header.parent_hash = alloy_primitives::keccak256(b101.header.canonical_header_bytes());
        let durable_votes = || StakingManager::new(db.clone()).state_hash_votes(100).unwrap().len();
        gate.hold();
        dispatch_and_execute(&ctx, &db, &b101);
        assert!(gate.wait_received(101));
        let (db_t, b) = (db.clone(), b102.clone());
        let t = std::thread::spawn(move || {
            dispatch_and_execute(&ctx, &db_t, &b); // executes over 101's frozen layer
            ctx
        });
        std::thread::sleep(std::time::Duration::from_millis(200));
        assert_eq!(durable_votes(), 0, "101's votes are not durable while 102 executes");
        gate.release();
        let ctx = t.join().unwrap();
        assert!(!ctx.exec_failed.load(Ordering::SeqCst));
        drop(ctx);
        assert_eq!(durable_votes(), 3);
        assert_eq!(
            StakingManager::new(db.clone()).state_hash_quorum(100).unwrap(),
            Some(x.0),
            "102's vote completed the quorum over the parent layer's two"
        );
    }

    /// Review test gap: an EVM tx that calls a WRITER precompile (CoreWriter,
    /// 0x0810) through a contract, end to end on the committed-block path:
    /// the precompile's native side effect (a core-writer queue row, since bug
    /// (c) the EVM prefix of the block's flush batch, not in its overlay)
    /// enters `D(n)` of its height with the value the DB holds.
    #[test]
    fn running_hash_captures_evm_writer_precompile_side_effects_end_to_end() {
        use torus_state::cf::CF_CORE_WRITER_QUEUE;
        use torus_state::running_hash::{hashed_cf_id, read_running_hash};
        let key = k256::ecdsa::SigningKey::from_slice(&[62u8; 32]).unwrap();
        let (config, db) = make_test_config_and_db();
        let account = |code_hash: B256, balance: U256| revm::state::AccountInfo {
            balance,
            nonce: 0,
            code_hash,
            code: None,
            account_id: None,
        };
        db.put_account(&k256_address(&key), &account(KECCAK_EMPTY_CODE, U256::from(10u128.pow(18))))
            .unwrap();
        // Proxy: forward calldata to CoreWriter (0x0810), then STOP.
        #[rustfmt::skip]
        let code = vec![
            0x36, 0x5f, 0x5f, 0x37, // CALLDATACOPY(0, 0, CALLDATASIZE)
            0x5f, 0x5f, 0x36, 0x5f, 0x5f, // retSize retOffset argsSize argsOffset value
            0x61, 0x08, 0x10, 0x5a, 0xf1, 0x50, // PUSH2 0x0810 GAS CALL POP
            0x00, // STOP
        ];
        let proxy = Address::repeat_byte(0xC0);
        let code_hash = alloy_primitives::keccak256(&code);
        db.put_code(&code_hash, &code).unwrap();
        db.put_account(&proxy, &account(code_hash, U256::ZERO)).unwrap();
        let mut calldata = alloy_primitives::keccak256("cancelOrder(bytes32)".as_bytes())[..4].to_vec();
        calldata.extend_from_slice(&[0u8; 31]);
        calldata.push(42);
        let mut b1 = make_block(1, vec![]);
        b1.evm_transactions = vec![signed_eip1559(&key, 0, alloy_primitives::TxKind::Call(proxy), calldata)];
        b1.header.evm_tx_count = 1;

        torus_state::running_hash::capture_begin(&db);
        let ctx = make_exec_ctx(&config, &db);
        let durable = persist_committed_block_durably(&db, &b1);
        ctx.execute_committed_block_with(&b1, vec![], durable);
        assert!(!ctx.exec_failed.load(Ordering::SeqCst));
        drop(ctx);
        let captured = torus_state::running_hash::capture_take(&db);

        let queue_rows = StateBackend::iterate_cf(&db, CF_CORE_WRITER_QUEUE, None).unwrap();
        assert_eq!(queue_rows.len(), 1, "the tx succeeded and the precompile enqueued");
        let queue = hashed_cf_id(CF_CORE_WRITER_QUEUE).unwrap();
        let hashed: Vec<_> = captured[0].1.iter().filter(|e| e.0 == queue).collect();
        assert_eq!(captured[0].0, 1);
        assert_eq!(
            hashed,
            vec![&(queue, queue_rows[0].0.clone(), Some(queue_rows[0].1.clone()))],
            "the precompile's queue row is in D(1)"
        );
        assert_eq!(read_running_hash(&db), Some(fold_captured(&captured)));
    }

    /// Consensus bug (c), docs/plans/consensus-bug-c-evm-commit-atomicity.md:
    /// a node executes `block` once; another node stops right after the EVM
    /// section of its first attempt (a hard crash before the native flush) and
    /// re-executes the block after the restart (fresh exec context, durable
    /// applied-height marker below the block). Every column family must end
    /// identical. RED on main @ d623d3c: the EVM bundle was durable before the
    /// native flush, so the replay re-ran the txs on top of their own result.
    fn assert_crash_after_evm_section_replays_identically(
        block: &TorusBlock,
        key: &k256::ecdsa::SigningKey,
    ) {
        let node = |crash: bool| {
            let (config, db) = make_test_config_and_db();
            let funded = revm::state::AccountInfo {
                balance: U256::from(10u128.pow(18)),
                nonce: 0,
                code_hash: KECCAK_EMPTY_CODE,
                code: None,
                account_id: None,
            };
            db.put_account(&k256_address(key), &funded).unwrap();
            let durable = persist_committed_block_durably(&db, block);
            if crash {
                let mut ctx = make_exec_ctx(&config, &db);
                ctx.test_crash_after_evm_section = true;
                ctx.execute_committed_block_with(block, vec![], durable);
                drop(ctx);
                assert_eq!(read_native_applied_height(&db), None, "crashed before the flush");
            }
            let ctx = make_exec_ctx(&config, &db);
            ctx.execute_committed_block_with(block, vec![], durable);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst));
            drop(ctx);
            assert_eq!(read_native_applied_height(&db), Some(block.header.height));
            db
        };
        let (clean, crashed) = (node(false), node(true));
        for ((cf, a), (_, b)) in dump_all_cfs(&clean).iter().zip(dump_all_cfs(&crashed).iter()) {
            assert_eq!(a, b, "{cf} differs after the crash + replay");
        }
    }

    /// Bug (c): the replay must not lose the block's fee revenue (treasury /
    /// dev-pool credits) nor re-run a tx on its own committed nonce.
    #[test]
    fn evm_crash_between_evm_and_native_flush_replays_identically() {
        let key = k256::ecdsa::SigningKey::from_slice(&[63u8; 32]).unwrap();
        let mut b1 = make_block(1, vec![]);
        b1.evm_transactions = vec![signed_sstore_create(&key, 0)];
        b1.header.evm_tx_count = 1;
        assert_crash_after_evm_section_replays_identically(&b1, &key);
    }

    /// Bug (c): `[nonce 1, nonce 0]` — the first tx is skipped as nonce-too-high
    /// on the real execution; on a replay over the committed bundle it would be
    /// valid and run (a second contract, a second fee).
    #[test]
    fn evm_crash_after_evm_section_skipped_tx_not_revived() {
        let key = k256::ecdsa::SigningKey::from_slice(&[64u8; 32]).unwrap();
        let mut b1 = make_block(1, vec![]);
        b1.evm_transactions = vec![signed_sstore_create(&key, 1), signed_sstore_create(&key, 0)];
        b1.header.evm_tx_count = 2;
        assert_crash_after_evm_section_replays_identically(&b1, &key);
    }

    #[test]
    fn state_hash_mismatch_failstop_env_is_off_unless_exactly_1() {
        use crate::state_hash::parse_failstop;
        assert!(!parse_failstop(None));
        for off in ["0", "", "true", "yes", "2"] {
            assert!(!parse_failstop(Some(off.to_string())), "{off:?}");
        }
        assert!(parse_failstop(Some("1".to_string())));
        assert!(parse_failstop(Some(" 1 ".to_string())));
    }

    // ---- T0: epoch processing on EVERY boundary block ----

    /// What the T0 fixture observed. `rewarded`: validator inflation reached the
    /// validators at boundary 4. `validators`: (address, status, stake) after the
    /// run. `vs_updates_at`: whether consensus-side `epoch_validator_set_updates`
    /// emitted a validator-set change at boundaries 4 and 8 (a spurious diff
    /// switches hotstuff out of the 2-chain Generic commit, memory d8e0cf6b).
    #[derive(Debug, PartialEq)]
    struct EpochOutcome {
        rewarded: bool,
        validators: Vec<(Address, torus_economics::ValidatorStatus, U256)>,
        vs_updates_at: [bool; 2],
    }

    /// T0: epoch processing (permanent-stake rewards, validator inflation,
    /// native-side rotation) lives in the native phase, which is skipped for a
    /// block with no native action, fee or due CoreWriter row. HL runs epochs by
    /// round count: an EMPTY boundary block must still run it. Four Active
    /// validators (the BFT minimum), so the consensus-side rotation check is
    /// not vacuous.
    fn epoch_fixture(boundary_action: bool) -> EpochOutcome {
        torus_state::native_trie::force_native_trie_maintenance_on_for_tests();
        let (mut config, db) = make_test_config_and_db();
        config.epoch_length = 4;
        let staking = StakingManager::new(db.clone());
        let vals: Vec<Address> = (1..=4u8).map(|i| Address::new([0x50 + i; 20])).collect();
        for (i, v) in vals.iter().enumerate() {
            let pubkey = ed25519_dalek::SigningKey::from_bytes(&[0x50 + i as u8; 32])
                .verifying_key()
                .to_bytes();
            staking
                .put_validator(v, &torus_economics::ValidatorState {
                    address: *v,
                    pubkey,
                    commission_bps: 500,
                    self_stake: torus_economics::MIN_SELF_DELEGATION * U256::from(100 + i as u64),
                    total_delegated: U256::ZERO,
                    status: torus_economics::ValidatorStatus::Active,
                    jailed_until: None,
                    last_commission_change_block: None,
                    oracle_signer: None,
                })
                .unwrap();
        }
        // Consensus side: genesis set from staking, as on a real node
        // (`Genesis::initialize` records it; consensus bug (b): the first
        // execution-planned rotation diffs against it).
        let genesis_set = EpochManager::compute_new_validator_set(&staking, u32::MAX, 0).unwrap();
        staking.record_genesis_epoch_set(&genesis_set).unwrap();
        let mut app = TorusApp::new(db.clone(), &config, None, None, None);
        let ctx = make_exec_ctx(&config, &db);
        for h in 1..=3u64 {
            let root_before = torus_state::native_trie::persisted_native_root(&db).unwrap();
            ctx.execute_committed_block(&make_block(h, vec![]), vec![]);
            // Empty NON-boundary blocks keep skipping the native phase: marker
            // only, native root untouched, no epoch side effect.
            assert_eq!(read_native_applied_height(&db), Some(h));
            assert_eq!(
                torus_state::native_trie::persisted_native_root(&db).unwrap(),
                root_before,
                "empty non-boundary block {h} must not touch native state"
            );
            assert!(vals.iter().all(|v| staking.get_pending_rewards(v).unwrap().is_none()));
        }
        // Block 4 = epoch boundary; its proposal asks for the set change first.
        let at4 = app.epoch_validator_set_updates(4).expect("plan ready at 4").is_some();
        let actions = if boundary_action { vec![sign_claim_rewards(4)] } else { vec![] };
        ctx.execute_committed_block(&make_block(4, actions), vec![]);
        assert!(!ctx.exec_failed.load(Ordering::SeqCst));
        assert_eq!(read_native_applied_height(&db), Some(4));
        let rewarded = vals.iter().all(|v| {
            staking.get_pending_rewards(v).unwrap().is_some_and(|r| r.amount > U256::ZERO)
        });
        // Blocks 5-7 empty, linked to the persisted block 4 (non-empty in the
        // control); the rotation at boundary 8 then reads 4's post-state + 5-7.
        let stored4 = db.get_cf_raw(CF_BLOCK_HEADERS, &4u64.to_be_bytes()).unwrap().unwrap();
        let mut parent_hash = B256::from_slice(&stored4[..32]);
        for h in 5..=7u64 {
            let mut b = make_block(h, vec![]);
            b.header.parent_hash = parent_hash;
            parent_hash = alloy_primitives::keccak256(b.header.canonical_header_bytes());
            ctx.execute_committed_block(&b, vec![]);
            assert_eq!(read_native_applied_height(&db), Some(h));
        }
        assert!(!ctx.exec_failed.load(Ordering::SeqCst));
        let at8 = app.epoch_validator_set_updates(8).expect("plan ready at 8").is_some();
        drop(ctx);
        let validators = staking
            .all_validators()
            .unwrap()
            .into_iter()
            .map(|v| (v.address, v.status, v.total_stake()))
            .collect();
        EpochOutcome { rewarded, validators, vs_updates_at: [at4, at8] }
    }

    /// Control (GREEN today): a NON-empty boundary block credits inflation and
    /// changes nothing on the consensus side (unchanged set -> no updates).
    #[test]
    fn nonempty_epoch_boundary_block_runs_epoch_processing() {
        let out = epoch_fixture(true);
        assert!(out.rewarded, "control: inflation must be non-zero for this fixture");
        assert_eq!(out.vs_updates_at, [false, false], "no validator-set diff: {out:?}");
        assert!(out
            .validators
            .iter()
            .all(|(_, s, _)| *s == torus_economics::ValidatorStatus::Active));
    }

    /// T0: the EMPTY boundary block runs the same epoch processing and yields the
    /// SAME validator statuses / stakes / consensus-side updates as the control.
    #[test]
    fn empty_epoch_boundary_block_runs_epoch_processing() {
        let empty = epoch_fixture(false);
        assert!(empty.rewarded, "empty boundary block 4 must distribute validator inflation");
        assert_eq!(empty, epoch_fixture(true), "empty vs non-empty boundary must match");
    }

    // ---- T0b: block timestamp rule (rebase s87, owner option A) ----

    #[test]
    fn proposal_timestamp_drift_bound() {
        assert!(check_timestamp_drift(1_005, 1_000).is_ok(), "drift 5");
        assert!(check_timestamp_drift(1_006, 1_000).is_err(), "drift 6");
        assert!(check_timestamp_drift(0, 0).is_ok(), "first block after genesis (ts 0)");
        assert!(check_timestamp_drift(50, 1_000).is_ok(), "behind the clock");
        assert!(check_timestamp_drift(u64::MAX, u64::MAX).is_ok(), "no overflow");
    }

    /// The parent-timestamp source reads the header of either datum format.
    #[test]
    fn proposal_timestamp_datum_header_decodes_full_and_compact() {
        let mut b = make_block(7, vec![sign_claim_rewards(7)]);
        b.header.timestamp = 123_456;
        for compact in [false, true] {
            let h = datum_header(&encode_proposal_datum(&b, compact)).unwrap();
            assert_eq!(h.canonical_header_bytes(), b.header.canonical_header_bytes(), "compact={compact}");
        }
    }

    fn ts_app(now: u64) -> TorusApp {
        let (config, db) = make_test_config_and_db();
        let mut app = TorusApp::new(db, &config, None, None, None);
        app.test_now_secs = Some(now);
        app
    }

    fn child_of(parent: &TorusBlock, ts: u64) -> TorusBlock {
        let h = parent.header.height + 1;
        let mut b = make_block(h, vec![]);
        b.header.parent_hash = alloy_primitives::keccak256(parent.header.canonical_header_bytes());
        b.header.timestamp = ts;
        b
    }

    fn tip_2000() -> TorusBlock {
        let mut parent = make_block(4, vec![]);
        parent.header.timestamp = 2_000;
        parent
    }

    /// `check_proposal_data` (the pre-vote check) of `block` on the parent
    /// header `parent` (a non-genesis justify).
    fn pre_vote(app: &mut TorusApp, parent: &TorusBlock, block: &TorusBlock) -> BlockDataCheck {
        let hs_parent = hs_block(parent, PhaseCertificate::genesis_pc());
        let header = parent.header.clone();
        app.check_proposal_data(&hs_block(block, justify_for(&hs_parent)), move |_| {
            ParentHeader::Header(Box::new(header))
        })
    }

    /// A far-future proposal gets no vote: the pre-vote check refuses a
    /// timestamp more than MAX_BLOCK_TIMESTAMP_DRIFT_SECS ahead of the local
    /// clock; at the bound it votes.
    #[test]
    fn far_future_proposal_is_refused_before_the_vote() {
        let parent = tip_2000();
        let mut app = ts_app(2_010);
        assert_eq!(pre_vote(&mut app, &parent, &child_of(&parent, 2_015)), BlockDataCheck::Held);
        assert_eq!(pre_vote(&mut app, &parent, &child_of(&parent, 2_016)), BlockDataCheck::Invalid);
        assert_eq!(
            pre_vote(&mut app, &parent, &child_of(&parent, 9_999_999)),
            BlockDataCheck::Invalid
        );
    }

    /// No wedge: the same far-future block, once certified, is accepted
    /// wherever it is inserted — validate_block's link check (insertion /
    /// header + body / full proposal), the datum path (also block sync), and
    /// execution / crash replay never read the local clock.
    #[test]
    fn far_future_block_is_accepted_at_insertion_sync_execution_and_replay() {
        let parent = tip_2000();
        let far = child_of(&parent, 9_999_999);
        let mut app = ts_app(2_010);
        assert_eq!(pre_vote(&mut app, &parent, &far), BlockDataCheck::Invalid, "no vote");

        // Insertion: validate_block's parent-link check, then the datum path.
        let hs_parent = hs_block(&parent, PhaseCertificate::genesis_pc());
        let header = parent.header.clone();
        assert_eq!(
            check_parent_link(&far.header, &justify_for(&hs_parent), move |_| {
                ParentHeader::Header(Box::new(header))
            }),
            BlockDataCheck::Held
        );
        let datum = encode_proposal_datum(&far, false);
        assert!(matches!(
            app.validate_datum(&datum, &data_hash_of(&datum)),
            ValidateBlockResponse::Valid { .. }
        ));

        // Execution and crash replay.
        for replay in [false, true] {
            let (config, db) = make_test_config_and_db();
            let ctx = make_exec_ctx(&config, &db);
            let mut b1 = make_block(1, vec![]);
            b1.header.timestamp = 9_999_999;
            if replay {
                persist_committed_block_durably(&db, &b1);
                assert_eq!(TorusApp::replay_committed(&db, &ctx).1, None);
            } else {
                ctx.execute_committed_block(&b1, vec![]);
            }
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "replay={replay}");
            assert_eq!(read_native_applied_height(&db), Some(1), "replay={replay}");
        }
    }

    /// A regressing timestamp is refused before the vote and by
    /// `check_parent_link` (so also on insertion: a certified block never
    /// regresses, because a quorum ran the same pure header check).
    #[test]
    fn regressing_timestamp_is_refused_before_the_vote_and_by_the_parent_link() {
        let parent = tip_2000();
        let mut app = ts_app(2_010);
        assert_eq!(pre_vote(&mut app, &parent, &child_of(&parent, 2_000)), BlockDataCheck::Held);
        assert_eq!(pre_vote(&mut app, &parent, &child_of(&parent, 1_999)), BlockDataCheck::Invalid);
        let hs_parent = hs_block(&parent, PhaseCertificate::genesis_pc());
        for (ts, want) in [(2_000, BlockDataCheck::Held), (1_999, BlockDataCheck::Invalid)] {
            let header = parent.header.clone();
            assert_eq!(
                check_parent_link(&child_of(&parent, ts).header, &justify_for(&hs_parent), move |_| {
                    ParentHeader::Header(Box::new(header))
                }),
                want,
                "ts {ts}"
            );
        }
    }

    /// Genesis / first block: parent = genesis_parent_header (ts 0): only the
    /// drift bound can refuse it.
    #[test]
    fn proposal_timestamp_first_block_only_has_the_drift_bound() {
        let mut app = ts_app(1_700_000_000);
        let no_lookup = |_: &CryptoHash| -> ParentHeader { panic!("genesis justify") };
        let mut b1 = make_block(1, vec![]);
        b1.header.timestamp = 1_700_000_000;
        assert_eq!(
            app.check_proposal_data(&hs_block(&b1, PhaseCertificate::genesis_pc()), no_lookup),
            BlockDataCheck::Held
        );
        b1.header.timestamp = 1_700_000_006;
        assert_eq!(
            app.check_proposal_data(&hs_block(&b1, PhaseCertificate::genesis_pc()), no_lookup),
            BlockDataCheck::Invalid
        );
    }

    /// The proposer never emits a timestamp below its parent's, even when the
    /// parent's is ahead of the local clock (within drift), and the block it
    /// produces passes the pre-vote rule on a validator with the same clock.
    #[test]
    fn proposal_timestamp_from_proposer_after_future_ish_parent_is_valid() {
        let (config, db) = make_test_config_and_db();
        let mut app = TorusApp::new(db, &config, None, None, None);
        let now = unix_now_secs();
        let mut parent = app.last_header.clone();
        parent.timestamp = now + 3;
        let _ = app.build_proposal(parent.clone());
        let produced = &app.pending_proposals[&(parent.height + 1)].block;
        assert!(produced.header.timestamp >= parent.timestamp, "never below the parent");
        assert!(check_timestamp_drift(produced.header.timestamp, now).is_ok());
    }

    /// Committed history is accepted as-is: execution and crash replay never
    /// check the timestamp (a regressing one included).
    #[test]
    fn proposal_timestamp_execution_and_replay_accept_committed_history() {
        for replay in [false, true] {
            let (config, db) = make_test_config_and_db();
            let ctx = make_exec_ctx(&config, &db);
            let mut blocks = vec![
                make_block(1, vec![sign_claim_rewards(1)]),
                make_block(2, vec![sign_claim_rewards(2)]),
            ];
            blocks[0].header.timestamp = 5_000;
            blocks[1].header.timestamp = 4_000;
            link_blocks(&mut blocks);
            if replay {
                for b in &blocks {
                    persist_committed_block_durably(&db, b);
                }
                assert_eq!(TorusApp::replay_committed(&db, &ctx).1, None);
            } else {
                for b in &blocks {
                    ctx.execute_committed_block(b, vec![]);
                }
            }
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "replay={replay}");
            assert_eq!(read_native_applied_height(&db), Some(2), "replay={replay}");
        }
    }

    // ---- item 7 step 0: EVM header rules before the vote ----

    /// A signed EVM tx declaring `gas_limit` (a plain call, zero value).
    fn evm_tx_gas(nonce: u64, gas_limit: u64) -> Vec<u8> {
        let key = k256::ecdsa::SigningKey::from_slice(&[71u8; 32]).unwrap();
        let to = alloy_primitives::TxKind::Call(Address::repeat_byte(0x42));
        signed_eip1559_gas(&key, nonce, to, vec![], U256::ZERO, gas_limit)
    }

    /// `child_of(parent)` carrying `evm` (header `evm_tx_count` matching).
    fn evm_child_of(parent: &TorusBlock, evm: Vec<Vec<u8>>) -> TorusBlock {
        let mut b = child_of(parent, parent.header.timestamp);
        b.header.evm_tx_count = evm.len() as u32;
        b.evm_transactions = evm;
        b
    }

    /// [`pre_vote`] of `block` sent as a FULL or a COMPACT datum.
    fn pre_vote_as(
        app: &mut TorusApp,
        parent: &TorusBlock,
        block: &TorusBlock,
        compact: bool,
    ) -> BlockDataCheck {
        let hs_parent = hs_block(parent, PhaseCertificate::genesis_pc());
        let datum = encode_proposal_datum(block, compact);
        let hs = Block::new(
            hotstuff_rs::types::data_types::BlockHeight::new(block.header.height),
            justify_for(&hs_parent),
            CryptoHash::new(TorusApp::hash_datum(&datum)),
            Data::new(vec![Datum::new(datum)]),
        );
        let header = parent.header.clone();
        app.check_proposal_data(&hs, move |_| ParentHeader::Header(Box::new(header)))
    }

    /// `evm_gas_limit` and `base_fee_per_gas` must equal the parent's, before
    /// the vote and in `check_parent_link` (so also on insertion: a pure
    /// header check, the same verdict on every replica). Higher and lower are
    /// both refused; the first block is held to the genesis parent's values.
    /// RED before step 0: every variant was `Held`.
    #[test]
    fn evm_gas_limit_and_base_fee_must_equal_the_parents() {
        let parent = tip_2000();
        let mut app = ts_app(2_010);
        let honest = child_of(&parent, 2_000);
        assert_eq!(pre_vote(&mut app, &parent, &honest), BlockDataCheck::Held);
        let hs_parent = hs_block(&parent, PhaseCertificate::genesis_pc());
        type Change = fn(&mut TorusBlockHeader);
        let variants: [(&str, Change); 4] = [
            ("gas limit raised", |h| h.evm_gas_limit += 1),
            ("gas limit lowered", |h| h.evm_gas_limit -= 1),
            ("base fee raised", |h| h.base_fee_per_gas += 1),
            ("base fee lowered", |h| h.base_fee_per_gas -= 1),
        ];
        for (what, change) in variants {
            let mut b = honest.clone();
            change(&mut b.header);
            assert_eq!(
                pre_vote(&mut app, &parent, &b),
                BlockDataCheck::Invalid,
                "{what}"
            );
            let header = parent.header.clone();
            assert_eq!(
                check_parent_link(&b.header, &justify_for(&hs_parent), move |_| {
                    ParentHeader::Header(Box::new(header))
                }),
                BlockDataCheck::Invalid,
                "{what}: parent link"
            );
        }

        // First block: the parent is genesis_parent_header (30M, 1 gwei).
        let mut app = ts_app(1_700_000_000);
        let no_lookup = |_: &CryptoHash| -> ParentHeader { panic!("genesis justify") };
        let mut b1 = make_block(1, vec![]);
        b1.header.timestamp = 1_700_000_000;
        let genesis = torus_bridge::genesis_parent_header();
        assert_eq!(b1.header.evm_gas_limit, genesis.evm_gas_limit);
        assert_eq!(b1.header.base_fee_per_gas, genesis.base_fee_per_gas);
        assert_eq!(
            app.check_proposal_data(&hs_block(&b1, PhaseCertificate::genesis_pc()), no_lookup),
            BlockDataCheck::Held
        );
        b1.header.evm_gas_limit = 60_000_000;
        assert_eq!(
            app.check_proposal_data(&hs_block(&b1, PhaseCertificate::genesis_pc()), no_lookup),
            BlockDataCheck::Invalid
        );
    }

    /// Before the vote the EVM body must fit the header: `evm_tx_count`
    /// equals the body's tx count (crash replay trusts the header counts) and
    /// the txs' declared gas limits sum to at most `evm_gas_limit` (execution
    /// fails the whole EVM section over the limit). An undecodable tx counts
    /// no gas: execution skips it (s84 decision 1). Full and compact datums.
    /// RED before step 0: the count and gas variants were `Held`.
    #[test]
    fn evm_body_must_fit_the_header_before_the_vote() {
        let parent = tip_2000();
        let limit = parent.header.evm_gas_limit;
        let mut app = ts_app(2_010);
        for compact in [false, true] {
            let at_limit = evm_child_of(
                &parent,
                vec![evm_tx_gas(0, limit / 2), evm_tx_gas(1, limit / 2)],
            );
            assert_eq!(
                pre_vote_as(&mut app, &parent, &at_limit, compact),
                BlockDataCheck::Held,
                "declared gas == limit (compact={compact})"
            );
            let over = evm_child_of(
                &parent,
                vec![
                    evm_tx_gas(0, limit / 2),
                    evm_tx_gas(1, limit / 2),
                    evm_tx_gas(2, 21_000),
                ],
            );
            assert_eq!(
                pre_vote_as(&mut app, &parent, &over, compact),
                BlockDataCheck::Invalid,
                "declared gas > limit (compact={compact})"
            );
            let one_too_big = evm_child_of(&parent, vec![evm_tx_gas(0, limit + 1)]);
            assert_eq!(
                pre_vote_as(&mut app, &parent, &one_too_big, compact),
                BlockDataCheck::Invalid,
                "one tx over the limit (compact={compact})"
            );
            let with_garbage = evm_child_of(&parent, vec![evm_tx_gas(0, limit), vec![0xff; 8]]);
            assert_eq!(
                pre_vote_as(&mut app, &parent, &with_garbage, compact),
                BlockDataCheck::Held,
                "an undecodable tx is skipped at execution, counts no gas (compact={compact})"
            );
            for count in [0, 1, 3] {
                let mut miscounted = at_limit.clone();
                miscounted.header.evm_tx_count = count;
                assert_eq!(
                    pre_vote_as(&mut app, &parent, &miscounted, compact),
                    BlockDataCheck::Invalid,
                    "header evm_tx_count {count} != body 2 (compact={compact})"
                );
            }
        }
    }

    /// An honest proposal with EVM txs passes the pre-vote check, even with the
    /// proposer-local budget set far above the header limit: `drain_evm`
    /// caps the declared gas at min(header limit, budget).
    #[test]
    fn honest_proposal_with_evm_txs_passes_the_pre_vote_check() {
        let (config, db) = make_test_config_and_db();
        let key = k256::ecdsa::SigningKey::from_slice(&[71u8; 32]).unwrap();
        let sender = {
            let pubkey = key.verifying_key().to_encoded_point(false);
            Address::from_slice(&alloy_primitives::keccak256(&pubkey.as_bytes()[1..])[12..])
        };
        db.put_account(
            &sender,
            &revm::state::AccountInfo {
                balance: U256::from(1_000_000_000_000_000_000u128),
                nonce: 0,
                code_hash: KECCAK_EMPTY_CODE,
                code: None,
                account_id: None,
            },
        )
        .unwrap();
        let mempool = Arc::new(Mempool::new(
            db.clone(),
            torus_mempool::MempoolConfig {
                evm_block_gas_budget: u64::MAX,
                evm_sender_share_pct: 0,
                ..torus_mempool::MempoolConfig::default()
            },
        ));
        for nonce in 0..4 {
            mempool.add_evm_tx(evm_tx_gas(nonce, 10_000_000)).unwrap();
        }
        let mut app = TorusApp::new(db, &config, None, Some(mempool), None);
        let parent = TorusBlock {
            header: app.last_header.clone(),
            native_actions: vec![],
            evm_transactions: vec![],
            core_writer_actions: vec![],
        };
        let resp = app.build_proposal(parent.header.clone());
        let produced = app.pending_proposals[&(parent.header.height + 1)]
            .block
            .clone();
        assert_eq!(
            produced.evm_transactions.len(),
            3,
            "30M header limit fits three 10M txs"
        );
        assert_eq!(produced.header.evm_tx_count, 3);
        assert_eq!(produced.header.evm_gas_limit, parent.header.evm_gas_limit);
        assert_eq!(
            produced.header.base_fee_per_gas,
            parent.header.base_fee_per_gas
        );

        let hs_parent = hs_block(&parent, PhaseCertificate::genesis_pc());
        let hs = Block::new(
            hotstuff_rs::types::data_types::BlockHeight::new(produced.header.height),
            justify_for(&hs_parent),
            resp.data_hash,
            resp.data,
        );
        let header = parent.header.clone();
        assert_eq!(
            app.check_proposal_data(&hs, move |_| ParentHeader::Header(Box::new(header))),
            BlockDataCheck::Held
        );
    }

    // ---- item 2: oracle helpers ----

    const ORACLE_MARKET: u64 = 1;
    /// (signing-key seed, stake multiple of MIN_SELF_DELEGATION).
    const ORACLE_VALIDATORS: [(u8, u64); 3] = [(61, 1), (62, 1), (63, 3)];

    fn oracle_key(seed: u8) -> k256::ecdsa::SigningKey {
        k256::ecdsa::SigningKey::from_slice(&[seed; 32]).unwrap()
    }

    fn oracle_addr(seed: u8) -> Address {
        torus_types::eip712::sign_native_action(NativeAction::ClaimRewards, 0, &oracle_key(seed))
            .recover_sender()
            .unwrap()
    }

    fn oracle_put_validator(db: &StateDb, seed: u8, mult: u64, status: torus_economics::ValidatorStatus) {
        StakingManager::new(db.clone())
            .put_validator(
                &oracle_addr(seed),
                &torus_economics::ValidatorState {
                    address: oracle_addr(seed),
                    pubkey: [seed; 32],
                    commission_bps: 0,
                    self_stake: torus_economics::MIN_SELF_DELEGATION * U256::from(mult),
                    total_delegated: U256::ZERO,
                    status,
                    jailed_until: None,
                    last_commission_change_block: None,
                    oracle_signer: None,
                },
            )
            .unwrap();
    }

    /// 3 Active validators, market 1 listed, epoch length 1000 (no boundary).
    fn oracle_fixture_db() -> (ChainConfig, StateDb) {
        let (mut config, db) = make_test_config_and_db();
        config.epoch_length = 1_000;
        for (seed, mult) in ORACLE_VALIDATORS {
            oracle_put_validator(&db, seed, mult, torus_economics::ValidatorStatus::Active);
        }
        db.put_cf_raw(torus_state::cf::CF_NATIVE_MARKETS, &ORACLE_MARKET.to_be_bytes(), b"listed")
            .unwrap();
        (config, db)
    }

    fn px(v: i64) -> FixedPoint {
        FixedPoint::from_raw(v as i128 * FixedPoint::SCALE)
    }

    /// Heights 1..=rounds.len() (ts = 1000 + h: one second per block); round i =
    /// the (seed, price) submissions of block i+1; linked to actual parents.
    fn oracle_blocks(rounds: &[&[(u8, i64)]]) -> Vec<TorusBlock> {
        let mut blocks: Vec<TorusBlock> = rounds
            .iter()
            .enumerate()
            .map(|(i, subs)| {
                let h = i as u64 + 1;
                let actions = subs
                    .iter()
                    .map(|&(seed, price)| {
                        torus_types::eip712::sign_native_action(
                            NativeAction::SubmitOraclePrices(torus_types::OracleSubmission {
                                prices: vec![(ORACLE_MARKET, px(price))],
                                // review M1(b): sampled at the block's time (ms)
                                timestamp: (1_000 + h) * 1_000,
                            }),
                            NONCE_BASE + h * 1_000 + seed as u64,
                            &oracle_key(seed),
                        )
                    })
                    .collect();
                make_block(h, actions)
            })
            .collect();
        link_blocks(&mut blocks);
        blocks
    }

    fn oracle_sub_rows(db: &StateDb) -> Vec<(Vec<u8>, Vec<u8>)> {
        StateBackend::iterate_cf(db, torus_state::cf::CF_NATIVE_ORACLE, Some(b"sub")).unwrap()
    }

    /// T1: the oracle clock is the COMMITTED header timestamp. The submission
    /// row stores it (last 8 bytes of the value) — identical on the live
    /// dispatch path, execute_committed_block and crash replay.
    #[test]
    fn oracle_clock_is_the_committed_header_timestamp_on_every_path() {
        for path in ["serial", "dispatch", "replay"] {
            let (config, db) = oracle_fixture_db();
            let ctx = make_exec_ctx(&config, &db);
            // review M1(b): the sample must be within 5 s of the block time.
            let sub = torus_types::eip712::sign_native_action(
                NativeAction::SubmitOraclePrices(torus_types::OracleSubmission {
                    prices: vec![(ORACLE_MARKET, px(100))],
                    timestamp: 777_777_000,
                }),
                777_777_061, // at the block time below (exec nonce window)
                &oracle_key(61),
            );
            let mut blocks = vec![make_block(1, vec![sub])];
            blocks[0].header.timestamp = 777_777; // height 1: parent is the genesis header
            match path {
                "serial" => ctx.execute_committed_block(&blocks[0], vec![]),
                "dispatch" => dispatch_and_execute(&ctx, &db, &blocks[0]),
                _ => {
                    persist_committed_block_durably(&db, &blocks[0]);
                    let (_, parked) = TorusApp::replay_committed(&db, &ctx);
                    assert_eq!(parked, None, "{path}");
                }
            }
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "{path}");
            assert_eq!(read_native_applied_height(&db), Some(1), "{path}");
            let rows = oracle_sub_rows(&db);
            assert_eq!(rows.len(), 1, "{path}");
            let v = &rows[0].1;
            assert_eq!(u64::from_be_bytes(v[v.len() - 8..].try_into().unwrap()), 777_777, "{path}");
        }
    }

    /// The mark as AccountReader::mark sees it at block timestamp `now` (+ stamp block).
    fn mark_at(db: &StateDb, now: u64) -> Option<(FixedPoint, u64)> {
        let ctx = torus_bridge::native_executor::NativeExecContext::new(
            db.clone(), 0, now, 0, 1_000, 4, Address::ZERO, Address::ZERO, Address::ZERO,
        );
        let p = ctx.oracle.get_price(ORACLE_MARKET, now).ok()?;
        p.usable().map(|m| (m, p.block_number))
    }

    /// Signed submissions through committed blocks (ts = 1000 + h). Block 2 has
    /// NO native action and still aggregates (rows exist -> the step is due).
    #[test]
    fn oracle_e2e_three_validators_set_the_mark_from_the_next_block() {
        let (config, db) = oracle_fixture_db();
        oracle_put_validator(&db, 65, 1, torus_economics::ValidatorStatus::Candidate);
        let ctx = make_exec_ctx(&config, &db);
        let blocks = oracle_blocks(&[
            &[(61, 100), (62, 101), (63, 102), (64, 999), (65, 999)], // 64 unregistered, 65 Candidate
            &[],
            &[(61, 200), (62, 200), (63, 200)],
            &[],
        ]);
        ctx.execute_committed_block(&blocks[0], vec![]);
        assert_eq!(oracle_sub_rows(&db).len(), 3, "only Active validators' rows are stored");
        assert_eq!(mark_at(&db, 1_001), None, "block 1's submissions are not aggregated in block 1");
        ctx.execute_committed_block(&blocks[1], vec![]);
        assert_eq!(mark_at(&db, 1_002), Some((px(102), 2)), "stake-weighted (simple median 101)");
        ctx.execute_committed_block(&blocks[2], vec![]);
        assert_eq!(mark_at(&db, 1_003), Some((px(102), 3)), "block 3's prices count from block 4");
        ctx.execute_committed_block(&blocks[3], vec![]);
        assert_eq!(mark_at(&db, 1_004), Some((px(200), 4)));
        assert!(!ctx.exec_failed.load(Ordering::SeqCst));
        assert_eq!(read_native_applied_height(&db), Some(4));
    }

    /// 1: V1..V3 @100; 2..=11 empty (fresh through ts 1011, age 10); 12: V1, V2
    /// @150 -> 2 reporters: last price kept, stamp stays (11, 1011); rows gone at
    /// 23 (block 12's rows, ts 1012, age 11); usable through ts 1071, stale at 1072.
    #[test]
    fn oracle_e2e_two_reporters_keep_the_last_price_until_stale() {
        let (config, db) = oracle_fixture_db();
        let ctx = make_exec_ctx(&config, &db);
        let mut rounds: Vec<&[(u8, i64)]> = vec![&[(61, 100), (62, 100), (63, 100)]];
        rounds.extend(std::iter::repeat_n(&[][..], 10)); // 2..=11
        rounds.push(&[(61, 150), (62, 150)]); // 12
        rounds.extend(std::iter::repeat_n(&[][..], 12)); // 13..=24
        let blocks = oracle_blocks(&rounds);
        for b in &blocks[..11] {
            ctx.execute_committed_block(b, vec![]);
        }
        assert_eq!(mark_at(&db, 1_011), Some((px(100), 11)));
        for b in &blocks[11..13] {
            ctx.execute_committed_block(b, vec![]);
        }
        assert_eq!(mark_at(&db, 1_013), Some((px(100), 11)), "2 reporters: last price, stamp kept");
        for b in &blocks[13..] {
            ctx.execute_committed_block(b, vec![]);
        }
        assert!(oracle_sub_rows(&db).is_empty());
        assert_eq!(read_native_applied_height(&db), Some(24));
        assert_eq!(mark_at(&db, 1_071), Some((px(100), 11)), "age 60: usable");
        assert_eq!(mark_at(&db, 1_072), None, "age 61: stale -> no mark");
    }

    /// A block that runs the native phase ONLY for the oracle keeps the resident
    /// books (T0's single flag: no second, untouched-block advance).
    #[test]
    fn oracle_e2e_oracle_only_block_keeps_the_resident_books() {
        let (config, db) = oracle_fixture_db();
        let mut ctx = make_exec_ctx(&config, &db);
        ctx.test_book_mode = Some(torus_bridge::native_executor::BookMode::Classic);
        let blocks = oracle_blocks(&[&[(61, 100), (62, 100), (63, 100)], &[]]);
        ctx.execute_committed_block(&blocks[0], vec![]);
        assert_eq!(ctx.resident_books.lock().unwrap().height(), Some(1));
        ctx.execute_committed_block(&blocks[1], vec![]);
        assert_eq!(mark_at(&db, 1_002), Some((px(100), 2)));
        assert_eq!(ctx.resident_books.lock().unwrap().height(), Some(2), "holder not drained");
    }

    /// 1: V1..V3 @100; 2 empty; 3: V1..V3 @200; 4..=6 empty; 7: V1 @300, V2 @310;
    /// 8..=14 empty (ts = 1000 + h).
    fn oracle_determinism_blocks() -> Vec<TorusBlock> {
        let full = |p: i64| vec![(61u8, p), (62, p), (63, p)];
        let (r1, r3) = (full(100), full(200));
        // 300 / 310 keeps the fixture away from the 3 x MAD boundary.
        let r7: Vec<(u8, i64)> = vec![(61, 300), (62, 310)];
        let e: &[(u8, i64)] = &[];
        oracle_blocks(&[&r1[..], e, &r3[..], e, e, e, &r7[..], e, e, e, e, e, e, e])
    }

    enum OracleRun {
        Serial,
        /// Flush worker ON and PARKED inside job 1: block 2's due-check and
        /// aggregation see block 1's rows only through the parent layer.
        PipelinedParked,
        /// Blocks 1..=4 executed; 5..=14 committed durably, then boot replay.
        Replay,
    }

    /// Item 3 (T9): `fixture` builds the starting DB (oracle tests:
    /// `oracle_fixture_db`; liquidation: `liq_det_fixture`).
    fn run_fixture(
        mode: OracleRun,
        blocks: &[TorusBlock],
        fixture: fn() -> (ChainConfig, StateDb),
    ) -> (Vec<CfDump>, torus_types::B256, StateDb) {
        torus_state::native_trie::force_native_trie_maintenance_on_for_tests();
        let (config, db) = fixture();
        match mode {
            OracleRun::Serial => {
                let ctx = make_exec_ctx(&config, &db);
                for b in blocks {
                    dispatch_and_execute(&ctx, &db, b);
                }
                assert!(!ctx.exec_failed.load(Ordering::SeqCst));
            }
            OracleRun::PipelinedParked => {
                let gate = crate::exec_pipeline::WorkerGate::new();
                let mut ctx = make_exec_ctx(&config, &db);
                ctx.attach_flush_worker(Some(gate.clone()));
                gate.hold();
                dispatch_and_execute(&ctx, &db, &blocks[0]);
                assert!(gate.wait_received(1));
                let (db2, rest) = (db.clone(), blocks[1..].to_vec());
                let t = std::thread::spawn(move || {
                    for b in &rest {
                        dispatch_and_execute(&ctx, &db2, b);
                    }
                    ctx
                });
                std::thread::sleep(std::time::Duration::from_millis(200));
                gate.release();
                let ctx = t.join().unwrap();
                assert!(!ctx.exec_failed.load(Ordering::SeqCst));
                drop(ctx); // drains + joins W
            }
            OracleRun::Replay => {
                let ctx = make_exec_ctx(&config, &db);
                for b in &blocks[..4] {
                    dispatch_and_execute(&ctx, &db, b);
                }
                for b in &blocks[4..] {
                    persist_committed_block_durably(&db, b);
                }
                let (last, parked) = TorusApp::replay_committed(&db, &ctx);
                assert_eq!(parked, None);
                assert_eq!(last.height, blocks.len() as u64);
            }
        }
        assert_eq!(read_native_applied_height(&db), Some(blocks.len() as u64));
        let root = torus_state::native_trie::persisted_native_root(&db).unwrap();
        (dump_all_cfs(&db), root, db)
    }

    #[test]
    fn oracle_determinism_serial_pipelined_and_replay_are_identical() {
        let blocks = oracle_determinism_blocks();
        let (serial, root_s, db_s) = run_fixture(OracleRun::Serial, &blocks, oracle_fixture_db);
        let (piped, root_p, _) = run_fixture(OracleRun::PipelinedParked, &blocks, oracle_fixture_db);
        let (replay, root_r, _) = run_fixture(OracleRun::Replay, &blocks, oracle_fixture_db);
        // Non-vacuous: 8..=13: V1 300, V2 310 (ts 1007), V3 200 (ts 1003, 3x) in the
        // window through ts 1013 -> stake-weighted 200, re-stamped; 14: V3's row
        // (age 11) pruned -> 2 reporters, stamp stays 13; block 7's 2 rows remain.
        assert_eq!(mark_at(&db_s, 1_014), Some((px(200), 13)));
        assert_eq!(oracle_sub_rows(&db_s).len(), 2);
        assert_dumps_equal(&serial, &piped, "oracle: serial vs pipelined (parked)");
        assert_dumps_equal(&serial, &replay, "oracle: serial vs crash replay");
        assert_eq!(root_s, root_p);
        assert_eq!(root_s, root_r);
    }

    /// Correction s517 (T7): the final dump above cannot see a skipped block-2
    /// aggregation (block 3 re-aggregates the same rows and overwrites it).
    /// Here block 3's timestamp jumps to 1012: block 1's rows (ts 1001, age 11)
    /// are pruned unaggregated, so block 2's aggregate — due ONLY through the
    /// parked parent layer on the pipelined path — is the final mark.
    #[test]
    fn oracle_determinism_parent_layer_due_check_is_observable() {
        let mut blocks = oracle_blocks(&[&[(61, 100), (62, 100), (63, 100)], &[], &[]]);
        blocks[2].header.timestamp = 1_012; // last block: no child to relink
        let (serial, root_s, db_s) = run_fixture(OracleRun::Serial, &blocks, oracle_fixture_db);
        let (piped, root_p, _) = run_fixture(OracleRun::PipelinedParked, &blocks, oracle_fixture_db);
        assert_eq!(mark_at(&db_s, 1_012), Some((px(100), 2)), "block 2's aggregate survives");
        assert!(oracle_sub_rows(&db_s).is_empty(), "block 3 pruned block 1's rows");
        assert_dumps_equal(&serial, &piped, "oracle: serial vs pipelined (parent-layer due-check)");
        assert_eq!(root_s, root_p);
    }

    // ---- item 3: liquidation helpers ----

    /// oracle_fixture_db + T (seed 71) long `size` @ 1,000 against S (72); T funded
    /// `collateral`, S and maker M (73) funded 10^7. Seeded through PositionManager.
    fn liq_fixture_db(size: i64, collateral: i64) -> (ChainConfig, StateDb) {
        use torus_core::position::{MarginType, NativeBalance, PositionManager};
        let (config, db) = oracle_fixture_db();
        let pm = PositionManager::new(db.clone());
        for (seed, amt) in [(71u8, collateral), (72, 10_000_000), (73, 10_000_000)] {
            pm.put_native_balance(&oracle_addr(seed), &NativeBalance { available: px(amt), order_margin: FixedPoint::ZERO })
                .unwrap();
        }
        pm.apply_fill(&oracle_addr(71), ORACLE_MARKET, true, px(size), px(1_000), MarginType::Cross).unwrap();
        pm.apply_fill(&oracle_addr(72), ORACLE_MARKET, false, px(size), px(1_000), MarginType::Cross).unwrap();
        (config, db)
    }

    fn oracle_sub(seed: u8, h: u64, price: i64) -> SignedNativeAction {
        torus_types::eip712::sign_native_action(
            NativeAction::SubmitOraclePrices(torus_types::OracleSubmission {
                prices: vec![(ORACLE_MARKET, px(price))],
                timestamp: (1_000 + h) * 1_000, // review M1(b): sampled at the block's time (ms)
            }),
            NONCE_BASE + h * 1_000 + seed as u64,
            &oracle_key(seed),
        )
    }

    /// Item 6 Phase 2 step 0.2: only the oracle-only block is timed into
    /// `exec_oracle_only_block_seconds`; the cancel-all and by-id counts of
    /// the exec context reach the counters; the spawn gauges carry the
    /// process totals, named in `SpawnSite` order.
    #[test]
    fn phase2_step0_block_metrics() {
        use torus_state::spawn_count::{totals, SpawnSite};
        let (config, db) = oracle_fixture_db();
        let mut ctx = make_exec_ctx(&config, &db);
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        ctx.metrics = Some(metrics.clone());
        let user = |action, h: u64, k: u64| {
            torus_types::eip712::sign_native_action(
                action,
                NONCE_BASE + h * 1_000 + 100 + k,
                &oracle_key(71),
            )
        };
        let mut blocks = vec![
            make_block(1, vec![oracle_sub(61, 1, 100), oracle_sub(62, 1, 100)]),
            make_block(
                2,
                vec![
                    oracle_sub(61, 2, 100),
                    user(NativeAction::CancelAllOrders { market_id: None }, 2, 0),
                    user(NativeAction::CancelOrder { order_id: 999 }, 2, 1),
                ],
            ),
        ];
        link_blocks(&mut blocks);
        for b in &blocks {
            ctx.execute_committed_block(b, vec![]);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst));
        }
        let text = metrics.encode();
        for (name, want) in [
            ("torus_exec_block_seconds_count", 2.0),
            ("torus_exec_oracle_only_block_seconds_count", 1.0),
            ("torus_exec_cancel_all_total", 1.0),
            ("torus_exec_by_id_actions_total", 1.0),
        ] {
            assert_eq!(metric_value(&text, name), want, "{name}:\n{text}");
        }
        let now = totals();
        let sites = torus_telemetry::EXEC_SPAWN_SITES;
        for (site, i) in [
            ("match", SpawnSite::Match),
            ("settle", SpawnSite::Settle),
            ("save_books", SpawnSite::SaveBooks),
            ("margin_prepare", SpawnSite::MarginPrepare),
            ("open_orders", SpawnSite::OpenOrders),
            ("end_resident", SpawnSite::EndResident),
            ("flush_digest", SpawnSite::FlushDigest),
            ("root_buckets", SpawnSite::RootBuckets),
            ("load_books", SpawnSite::LoadBooks),
        ] {
            assert_eq!(sites[i as usize], site);
            let v = metric_value(&text, &format!("torus_exec_thread_spawns_{site}"));
            assert!(v <= now[i as usize] as f64, "{site}: {v}");
        }
    }

    fn signed_bid(seed: u8, nonce: u64, price: i64, qty: i64) -> SignedNativeAction {
        torus_types::eip712::sign_native_action(
            NativeAction::PlaceOrder(torus_types::PlaceOrderParams {
                market_id: ORACLE_MARKET,
                is_buy: true,
                price: px(price),
                quantity: px(qty),
                order_type: torus_types::OrderType::Limit,
                time_in_force: torus_types::TimeInForce::GTC,
                reduce_only: false,
                client_order_id: None,
            }),
            NONCE_BASE + nonce,
            &oracle_key(seed),
        )
    }

    /// Heights 1..=rounds.len() (ts = 1000 + h), linked.
    fn liq_blocks(rounds: Vec<Vec<SignedNativeAction>>) -> Vec<TorusBlock> {
        let mut blocks: Vec<TorusBlock> =
            rounds.into_iter().enumerate().map(|(i, a)| make_block(i as u64 + 1, a)).collect();
        link_blocks(&mut blocks);
        blocks
    }

    fn signed_pos_of(db: &StateDb, who: &Address) -> FixedPoint {
        match torus_core::position::PositionManager::new(db.clone()).get_position(who, ORACLE_MARKET).unwrap() {
            Some(p) if p.is_long => p.size,
            Some(p) => -p.size,
            None => FixedPoint::ZERO,
        }
    }

    /// Item 3 T8: the step runs at the END of the block (block 2's own bid fills
    /// the chunk) on the block-start mark; the cooldown / pending rows make an
    /// EMPTY block (no submission rows left) run the native phase.
    /// T long 200 @ 1,000, collateral 5,500, mark 990: stage 1, 20% chunks.
    /// HL parity (s88): in the 30 s cooldown after a chunk, stage 1 orders the
    /// ENTIRE position. Block 2: M bids 40 @ 985 and 50 @ 970; the chunk (40)
    /// takes the 985 bid -> 160, cooldown from ts 1002. Block 3 (empty, ts
    /// 1003): the full-position order (cap 965.25) takes the 970 bid -> 110
    /// (AV 2,300 < MM 2,722.5: still stage 1, still due). Blocks 4..=31: empty
    /// book, nothing fills. Block 32 (ts 1032, cooldown over): a chunk again,
    /// 20% of 110 = 22 -> 88.
    #[test]
    fn liquidation_e2e_chunks_at_block_end_and_cooldown_drives_empty_blocks() {
        let (config, db) = liq_fixture_db(200, 5_500);
        let ctx = make_exec_ctx(&config, &db);
        let t = oracle_addr(71);
        let mut rounds = vec![
            vec![oracle_sub(61, 1, 990), oracle_sub(62, 1, 990), oracle_sub(63, 1, 990)], // 1 (ts 1001)
            vec![signed_bid(73, 2_073, 985, 40), signed_bid(73, 2_074, 970, 50)],           // 2 (mark 990)
        ];
        rounds.extend(std::iter::repeat_n(Vec::new(), 29)); // 3..=31 (ts 1003..=1031)
        rounds.push(vec![signed_bid(73, 32_073, 985, 100)]); // 32 (ts 1032)
        let blocks = liq_blocks(rounds);
        ctx.execute_committed_block(&blocks[0], vec![]);
        assert_eq!(signed_pos_of(&db, &t), px(200), "block 1: no mark yet");
        ctx.execute_committed_block(&blocks[1], vec![]);
        assert_eq!(signed_pos_of(&db, &t), px(160), "block 2: chunk 1 filled by block 2's own 985 bid");
        ctx.execute_committed_block(&blocks[2], vec![]);
        assert_eq!(signed_pos_of(&db, &t), px(110), "block 3 (empty, cooldown): the entire position is ordered");
        for b in &blocks[3..31] {
            ctx.execute_committed_block(b, vec![]); // 4..=31 (ts <= 1031)
        }
        assert_eq!(signed_pos_of(&db, &t), px(110), "cooldown: empty book, nothing fills");
        assert!(oracle_sub_rows(&db).is_empty(), "rows pruned");
        ctx.execute_committed_block(&blocks[31], vec![]); // 32, ts 1032
        assert_eq!(signed_pos_of(&db, &t), px(88), "cooldown over: chunk 2 = 20% of 110");
        assert!(!ctx.exec_failed.load(Ordering::SeqCst));
        assert_eq!(read_native_applied_height(&db), Some(32));
    }

    /// T1 (71) long 10 @ 100, collateral 40; T2 (74) long 10 @ 100, collateral 50;
    /// S (72) short 20 @ 100; maker M (73). 1: V @100 + M bid 10 @ 95;
    /// 3: V @97 -> block 4: T1 backstop (AV 10 < 16.17), T2 stage 1 (AV 20) into
    /// M's bid; 5: V @80 -> block 6: vault AV 10 - 170 < 0 -> ADL vs S at 97.
    fn liq_det_fixture() -> (ChainConfig, StateDb) {
        use torus_core::position::{MarginType, NativeBalance, PositionManager};
        let (config, db) = oracle_fixture_db();
        let pm = PositionManager::new(db.clone());
        for (seed, amt) in [(71u8, 40), (74, 50), (72, 1_000_000), (73, 1_000_000)] {
            pm.put_native_balance(&oracle_addr(seed), &NativeBalance { available: px(amt), order_margin: FixedPoint::ZERO })
                .unwrap();
        }
        for long in [71u8, 74] {
            pm.apply_fill(&oracle_addr(long), ORACLE_MARKET, true, px(10), px(100), MarginType::Cross).unwrap();
            pm.apply_fill(&oracle_addr(72), ORACLE_MARKET, false, px(10), px(100), MarginType::Cross).unwrap();
        }
        (config, db)
    }

    fn liq_det_blocks() -> Vec<TorusBlock> {
        let subs = |h: u64, p: i64| vec![oracle_sub(61, h, p), oracle_sub(62, h, p), oracle_sub(63, h, p)];
        let mut r1 = subs(1, 100);
        r1.push(signed_bid(73, 1_073, 95, 10));
        let mut rounds = vec![r1, vec![], subs(3, 97), vec![], subs(5, 80)];
        rounds.extend(std::iter::repeat_n(Vec::new(), 9)); // 6..=14
        liq_blocks(rounds)
    }

    #[test]
    fn liquidation_determinism_serial_pipelined_and_replay_are_identical() {
        use torus_core::liquidation::LIQUIDATOR_VAULT;
        let blocks = liq_det_blocks();
        let (serial, root_s, db_s) = run_fixture(OracleRun::Serial, &blocks, liq_det_fixture);
        let (piped, root_p, _) = run_fixture(OracleRun::PipelinedParked, &blocks, liq_det_fixture);
        let (replay, root_r, _) = run_fixture(OracleRun::Replay, &blocks, liq_det_fixture);
        // Non-vacuous: all three mechanisms ran.
        assert_eq!(signed_pos_of(&db_s, &oracle_addr(71)), FixedPoint::ZERO, "T1 backstopped");
        assert_eq!(signed_pos_of(&db_s, &oracle_addr(74)), FixedPoint::ZERO, "T2 sold into the book");
        assert_eq!(signed_pos_of(&db_s, &oracle_addr(73)), px(10), "M bought T2's 10 @ 95");
        assert_eq!(signed_pos_of(&db_s, &LIQUIDATOR_VAULT), FixedPoint::ZERO, "vault ADL'd");
        assert_eq!(signed_pos_of(&db_s, &oracle_addr(72)), -px(10));
        assert_dumps_equal(&serial, &piped, "liquidation: serial vs pipelined (parked)");
        assert_dumps_equal(&serial, &replay, "liquidation: serial vs crash replay");
        assert_eq!(root_s, root_p);
        assert_eq!(root_s, root_r);
    }

    /// Item 6 C4 (plan Step 4, P3): the liquidation fixture (backstop, stage
    /// 1, vault ADL) with L1 (R + sums cache, the node path) and with the
    /// reference walk (`test_no_resident_rows`), serial and pipelined:
    /// identical liquidation / position / balance rows after every block,
    /// identical per-block consensus write sets (`h_n`), running hash and
    /// final dump.
    #[test]
    fn liquidation_l1_and_reference_walk_identical_every_block() {
        use torus_state::cf::{CF_NATIVE_BALANCES, CF_NATIVE_LIQUIDATION, CF_NATIVE_POSITIONS};
        let blocks = liq_det_blocks();
        let run = |pipelined: bool, no_r: bool| {
            let (config, db) = liq_det_fixture();
            torus_state::running_hash::capture_begin(&db);
            let mut ctx = make_exec_ctx(&config, &db);
            ctx.test_no_resident_rows = no_r;
            if pipelined {
                ctx.attach_flush_worker(None);
            }
            let mut per_block = Vec::new();
            for b in &blocks {
                dispatch_and_execute(&ctx, &db, b);
                assert!(!ctx.exec_failed.load(Ordering::SeqCst), "pipelined={pipelined} no_r={no_r}");
                if let Some(w) = ctx.flush_worker.as_ref() {
                    assert!(w.wait_idle());
                }
                let rows: Vec<CfDump> = [CF_NATIVE_LIQUIDATION, CF_NATIVE_POSITIONS, CF_NATIVE_BALANCES]
                    .iter()
                    .map(|cf| (*cf, StateBackend::iterate_cf(&db, cf, None).unwrap()))
                    .collect();
                per_block.push(rows);
            }
            assert_eq!(ctx.resident_books.lock().unwrap().rows_builds(), u64::from(!no_r));
            drop(ctx);
            let captured = torus_state::running_hash::capture_take(&db);
            let stored = torus_state::running_hash::read_running_hash(&db);
            (per_block, captured, stored, dump_all_cfs(&db))
        };
        for pipelined in [false, true] {
            let what = format!("pipelined={pipelined}");
            let (rows_ref, cap_ref, hash_ref, dump_ref) = run(pipelined, true);
            let (rows_l1, cap_l1, hash_l1, dump_l1) = run(pipelined, false);
            for (h, (a, b)) in rows_ref.iter().zip(rows_l1.iter()).enumerate() {
                assert_dumps_equal(a, b, &format!("{what}: rows after block {}", h + 1));
            }
            assert_write_sets_equal(&cap_ref, &cap_l1, &format!("{what}: walk vs L1"));
            assert!(hash_l1.is_some());
            assert_eq!(hash_ref, hash_l1, "{what}: running hash");
            assert_dumps_equal(&dump_ref, &dump_l1, &format!("{what}: final dump"));
        }
    }

    /// Option B (s87): GTC limits `(market, is_buy, price, qty)` as one
    /// PlaceOrderBatch of `seed`.
    fn signed_limits(seed: u8, nonce: u64, orders: &[(u64, bool, i64, i64)]) -> SignedNativeAction {
        let orders = orders
            .iter()
            .map(|&(market_id, is_buy, price, qty)| torus_types::PlaceOrderParams {
                market_id,
                is_buy,
                price: px(price),
                quantity: px(qty),
                order_type: torus_types::OrderType::Limit,
                time_in_force: torus_types::TimeInForce::GTC,
                reduce_only: false,
                client_order_id: None,
            })
            .collect();
        torus_types::eip712::sign_native_action(NativeAction::PlaceOrderBatch(orders), NONCE_BASE + nonce, &oracle_key(seed))
    }

    /// Option B: T (71) funded 101.0505 (101 + B-blind's δ top-up of its
    /// market-2 sell, s92, taken ahead of its market-1 pool), maker M (73)
    /// rich.
    fn option_b_fixture() -> (ChainConfig, StateDb) {
        use torus_core::position::{NativeBalance, PositionManager};
        let (config, db) = oracle_fixture_db();
        let pm = PositionManager::new(db.clone());
        for (seed, amt) in [(71u8, px(101) + FixedPoint::from_raw(px(505).raw() / 10_000)), (73, px(1_000_000))] {
            pm.put_native_balance(&oracle_addr(seed), &NativeBalance { available: amt, order_margin: FixedPoint::ZERO })
                .unwrap();
        }
        (config, db)
    }

    /// Option B (s87): block 1: M bids 10 @101 in markets 1 and 2; block 5
    /// (inside the replayed range): T sells 10 @100 in both in one batch —
    /// the market-2 sell (T's non-pool market) reserves at the start-of-batch
    /// best bid 101 and fills. Serial, pipelined (parked) and crash replay
    /// give identical state.
    #[test]
    fn option_b_serial_pipelined_and_replay_are_identical() {
        let mut rounds = vec![vec![signed_limits(73, 1_073, &[(1, true, 101, 10), (2, true, 101, 10)])]];
        rounds.extend(std::iter::repeat_n(Vec::new(), 3)); // 2..=4
        rounds.push(vec![signed_limits(71, 5_071, &[(1, false, 100, 10), (2, false, 100, 10)])]); // 5
        rounds.extend(std::iter::repeat_n(Vec::new(), 2)); // 6, 7
        let blocks = liq_blocks(rounds);
        let (serial, root_s, db_s) = run_fixture(OracleRun::Serial, &blocks, option_b_fixture);
        let (piped, root_p, _) = run_fixture(OracleRun::PipelinedParked, &blocks, option_b_fixture);
        let (replay, root_r, _) = run_fixture(OracleRun::Replay, &blocks, option_b_fixture);
        let pm = torus_core::position::PositionManager::new(db_s.clone());
        for m in [1u64, 2] {
            let p = pm.get_position(&oracle_addr(71), m).unwrap().unwrap_or_else(|| panic!("market {m}: T short"));
            assert_eq!((p.is_long, p.size), (false, px(10)), "market {m}: filled @101");
        }
        assert_dumps_equal(&serial, &piped, "option B: serial vs pipelined (parked)");
        assert_dumps_equal(&serial, &replay, "option B: serial vs crash replay");
        assert_eq!(root_s, root_p);
        assert_eq!(root_s, root_r);
    }

    /// Same-batch bid (B-blind, s92): T (71) 1,000, B (74) 1,000, M (73) rich.
    fn same_batch_bid_fixture() -> (ChainConfig, StateDb) {
        let (config, db) = option_b_fixture();
        let pm = torus_core::position::PositionManager::new(db.clone());
        for seed in [71u8, 74] {
            pm.put_native_balance(
                &oracle_addr(seed),
                &torus_core::position::NativeBalance { available: px(1_000), order_margin: FixedPoint::ZERO },
            )
            .unwrap();
        }
        (config, db)
    }

    /// Same-batch bid under B-blind (s92; was the s87 bound): block 1: M bids
    /// 10 @101 in markets 1 and 2 and asks 10 @110 in market 2; block 5: B
    /// bids 10 @105 in market 2, then T sells 10 @100 in both — the market-2
    /// sell (non-pool) is topped up to reserve(101.101, 10) only (B's bid is
    /// not read), fills 2 @105 and is cut. Serial, pipelined (parked) and
    /// crash replay give identical state.
    #[test]
    fn same_batch_bid_serial_pipelined_and_replay_are_identical() {
        let mut rounds = vec![vec![signed_limits(73, 1_073, &[(1, true, 101, 10), (2, true, 101, 10), (2, false, 110, 10)])]];
        rounds.extend(std::iter::repeat_n(Vec::new(), 3)); // 2..=4
        rounds.push(vec![
            signed_limits(74, 5_074, &[(2, true, 105, 10)]),
            signed_limits(71, 5_071, &[(1, false, 100, 10), (2, false, 100, 10)]),
        ]); // 5
        rounds.extend(std::iter::repeat_n(Vec::new(), 2)); // 6, 7
        let blocks = liq_blocks(rounds);
        let (serial, root_s, db_s) = run_fixture(OracleRun::Serial, &blocks, same_batch_bid_fixture);
        let (piped, root_p, _) = run_fixture(OracleRun::PipelinedParked, &blocks, same_batch_bid_fixture);
        let (replay, root_r, _) = run_fixture(OracleRun::Replay, &blocks, same_batch_bid_fixture);
        let pm = torus_core::position::PositionManager::new(db_s.clone());
        for (m, size) in [(1u64, 10), (2, 2)] {
            let p = pm.get_position(&oracle_addr(71), m).unwrap().unwrap_or_else(|| panic!("market {m}: T short"));
            assert_eq!((p.is_long, p.size), (false, px(size)), "market {m}: T filled");
        }
        let b = pm.get_position(&oracle_addr(74), 2).unwrap().expect("B long");
        assert_eq!((b.is_long, b.size), (true, px(2)), "B's same-batch bid filled 2 (beyond δ)");
        assert_dumps_equal(&serial, &piped, "same-batch bid: serial vs pipelined (parked)");
        assert_dumps_equal(&serial, &replay, "same-batch bid: serial vs crash replay");
        assert_eq!(root_s, root_p);
        assert_eq!(root_s, root_r);
    }

    fn signed_stop_limit_buy(seed: u8, nonce: u64, trigger: i64, limit: i64, qty: i64) -> SignedNativeAction {
        torus_types::eip712::sign_native_action(
            NativeAction::PlaceOrder(torus_types::PlaceOrderParams {
                market_id: ORACLE_MARKET,
                is_buy: true,
                price: px(limit),
                quantity: px(qty),
                order_type: torus_types::OrderType::StopLimit { trigger: px(trigger), limit: px(limit) },
                time_in_force: torus_types::TimeInForce::GTC,
                reduce_only: false,
                client_order_id: None,
            }),
            NONCE_BASE + nonce,
            &oracle_key(seed),
        )
    }

    /// Review M2 (s517): an account left under MM after its stage-1 action
    /// keeps the step DUE (pending row) — without new actions, oracle rows,
    /// cooldown or cursor. T long 10 @ 1,000, collateral 300, mark 990 (AV
    /// 200, MM 247.5: stage 1, 9,900 < 100k: no chunk). Block 13 (oracle rows
    /// pruned at 12): M bids 4 @ 966 and places a stop-limit buy 6 @ 966
    /// (trigger 960). The step sells 4 into the bid; that trade fires M's stop,
    /// which RESTS at 966 after T's IOC remainder is gone. T: AV 104 < MM
    /// 148.5 -> still stage 1. Block 14 is empty: only the pending row makes
    /// it run; T sells the last 6 into the stop's bid. Then nothing is due.
    #[test]
    fn liquidation_e2e_partial_stage1_keeps_the_step_due() {
        let (config, db) = liq_fixture_db(10, 300);
        let ctx = make_exec_ctx(&config, &db);
        let (t, m) = (oracle_addr(71), oracle_addr(73));
        let mut rounds = vec![vec![oracle_sub(61, 1, 990), oracle_sub(62, 1, 990), oracle_sub(63, 1, 990)]];
        rounds.extend(std::iter::repeat_n(Vec::new(), 11)); // 2..=12
        rounds.push(vec![signed_bid(73, 13_073, 966, 4), signed_stop_limit_buy(73, 13_074, 960, 966, 6)]); // 13
        rounds.extend(std::iter::repeat_n(Vec::new(), 2)); // 14, 15
        let blocks = liq_blocks(rounds);
        for b in &blocks[..13] {
            ctx.execute_committed_block(b, vec![]);
        }
        assert!(oracle_sub_rows(&db).is_empty(), "rows pruned: no oracle-due");
        assert_eq!(signed_pos_of(&db, &t), px(6), "block 13: partial (4 sold)");
        ctx.execute_committed_block(&blocks[13], vec![]); // 14: empty
        assert_eq!(signed_pos_of(&db, &t), FixedPoint::ZERO, "block 14 re-ran the step");
        assert_eq!(signed_pos_of(&db, &m), px(10));
        assert!(!NativeExecutor::liquidation_due(&db).unwrap(), "flat: nothing pending");
        ctx.execute_committed_block(&blocks[14], vec![]);
        assert!(!ctx.exec_failed.load(Ordering::SeqCst));
    }

    /// adl-budget P2: T (71) and 13 accounts (seeds 80..=92) long 10 @ 1,000,
    /// collateral 50 each, against S (72, short 140, rich).
    fn adl_e2e_fixture() -> (ChainConfig, StateDb) {
        use torus_core::position::{MarginType, NativeBalance, PositionManager};
        let (config, db) = oracle_fixture_db();
        let pm = PositionManager::new(db.clone());
        let fund = |seed: u8, amt: i64| {
            pm.put_native_balance(&oracle_addr(seed), &NativeBalance { available: px(amt), order_margin: FixedPoint::ZERO })
                .unwrap();
        };
        for seed in adl_e2e_longs() {
            fund(seed, 50);
            pm.apply_fill(&oracle_addr(seed), ORACLE_MARKET, true, px(10), px(1_000), MarginType::Cross).unwrap();
        }
        fund(72, 10_000_000);
        pm.apply_fill(&oracle_addr(72), ORACLE_MARKET, false, px(140), px(1_000), MarginType::Cross).unwrap();
        (config, db)
    }

    fn adl_e2e_longs() -> impl Iterator<Item = u8> {
        std::iter::once(71).chain(80..=92)
    }

    /// Block 1: the mark 970 (aggregated at block 2's start); 2..=16 empty.
    fn adl_e2e_blocks() -> Vec<TorusBlock> {
        let mut rounds = vec![vec![oracle_sub(61, 1, 970), oracle_sub(62, 1, 970), oracle_sub(63, 1, 970)]];
        rounds.extend(std::iter::repeat_n(Vec::new(), 15)); // 2..=16
        liq_blocks(rounds)
    }

    fn adl_rows(db: &StateDb) -> usize {
        let tag = torus_core::liquidation::ADL_OBLIGATION_TAG;
        StateBackend::iterate_cf(db, torus_state::cf::CF_NATIVE_LIQUIDATION, Some(&[tag])).unwrap().len()
    }

    /// adl-budget P2: obligation rows keep the step DUE. Mark 970: all 14
    /// longs are ADL'd at B = 2 (AV 50 - 300 < 0; price min(970, 995) =
    /// 970), flat, 14 rows, the long escrow long 140. `test_adl_work = 2`:
    /// B's own 14 transfers cost 14 x `ADL_TRANSFER_UNITS` >= 2 (s99), so
    /// block 2 drains nothing; then one row per block (a row costs >= 2: its
    /// visit + a ranking or a read), blocks 3..=16. Oracle rows are pruned
    /// at 12, so blocks 13..=16 carry no action, oracle row, cursor,
    /// cooldown or pending row: only the 0x07 rows run them. The last row
    /// drains in block 16, so block 2's aggregate (ts 1,002) still gives a
    /// usable mark at ts 1,016 (rows of a listed market without a mark
    /// wait). Two runs: equal native root and dumps.
    #[test]
    fn liquidation_e2e_adl_obligations_drain_over_empty_blocks() {
        use torus_core::liquidation::{ADL_ESCROW_LONG, COOLDOWN_TAG, CURSOR_KEY, PENDING_TAG};
        use torus_state::cf::CF_NATIVE_LIQUIDATION;
        torus_state::native_trie::force_native_trie_maintenance_on_for_tests();
        let blocks = adl_e2e_blocks();
        let run = || {
            let (config, db) = adl_e2e_fixture();
            let mut ctx = make_exec_ctx(&config, &db);
            ctx.test_adl_work = Some(2);
            let mut left = Vec::new();
            for (i, b) in blocks.iter().enumerate() {
                let h = i as u64 + 1;
                if h >= 13 {
                    assert!(oracle_sub_rows(&db).is_empty(), "block {h}: oracle rows pruned");
                    for tag in [COOLDOWN_TAG, CURSOR_KEY[0], PENDING_TAG] {
                        let rows = StateBackend::iterate_cf(&db, CF_NATIVE_LIQUIDATION, Some(&[tag])).unwrap();
                        assert!(rows.is_empty(), "block {h}: no 0x{tag:02x} row");
                    }
                }
                ctx.execute_committed_block(b, vec![]);
                assert!(!ctx.exec_failed.load(Ordering::SeqCst), "block {h}");
                left.push(adl_rows(&db));
            }
            drop(ctx);
            let root = torus_state::native_trie::persisted_native_root(&db).unwrap();
            (left, dump_all_cfs(&db), root, db)
        };
        let (left, dump_1, root_1, db) = run();
        let want: Vec<usize> = std::iter::once(0).chain((2..=16).map(|h| 16 - h)).collect();
        assert_eq!(left, want, "B = 2: 14 rows, none drained in B (its transfers spend W), one per block 3..=16");
        for seed in adl_e2e_longs() {
            assert_eq!(signed_pos_of(&db, &oracle_addr(seed)), FixedPoint::ZERO, "seed {seed}: flat at B");
        }
        assert_eq!(signed_pos_of(&db, &ADL_ESCROW_LONG), FixedPoint::ZERO, "the escrow drained");
        assert_eq!(signed_pos_of(&db, &oracle_addr(72)), FixedPoint::ZERO, "S closed 140 against the escrow");
        assert!(!NativeExecutor::liquidation_due(&db).unwrap());
        let (_, dump_2, root_2, _) = run();
        assert_dumps_equal(&dump_1, &dump_2, "adl drain: two runs");
        assert_eq!(root_1, root_2);
    }

    /// The drain keeps no in-memory state across blocks (the ranking cache is
    /// per block, the dust bound test-only): the blocks above, run 2 stops
    /// after block 8 (mid-drain: 8 rows left), drops the ExecutionContext AND
    /// the StateDb (RocksDB closed), opens the DB again from its directory
    /// (as a node restart does: running-hash activation configured again, a
    /// cold R slot, no resident state, a new Metrics instance) for 9..=15.
    /// Equal native root and dump after every block from 9 on, and the same
    /// drain work units (`liquidation_adl_work_total`) in every block 1..=16
    /// (18c review, s96 fix list d: the units are what a restart could
    /// change without moving W = 2's one-row-per-block progress).
    #[test]
    fn liquidation_e2e_adl_drain_survives_a_restart() {
        torus_state::native_trie::force_native_trie_maintenance_on_for_tests();
        let blocks = adl_e2e_blocks();
        let run = |restart_before: Option<usize>| {
            let (config, mut db) = adl_e2e_fixture();
            let dir = db.inner().path().to_path_buf();
            let open_ctx = |db: &StateDb| {
                let mut ctx = make_exec_ctx(&config, db);
                ctx.test_adl_work = Some(2);
                ctx.metrics = Some(Arc::new(torus_telemetry::Metrics::new()));
                ctx
            };
            let mut ctx = open_ctx(&db);
            let (mut after, mut units) = (Vec::new(), Vec::new());
            for (i, b) in blocks.iter().enumerate() {
                if Some(i) == restart_before {
                    assert_eq!(adl_rows(&db), 8, "mid-drain");
                    drop(ctx);
                    drop(db);
                    db = StateDb::open(&dir).expect("reopen the state db");
                    torus_state::running_hash::configure_activation(&db, config.state_hash_activation_height)
                        .expect("configure running hash activation");
                    assert_eq!(adl_rows(&db), 8, "mid-drain after the reopen");
                    ctx = open_ctx(&db);
                }
                let work = |ctx: &ExecutionContext| {
                    ctx.metrics.as_ref().expect("metrics attached").liquidation_adl_work_total.get()
                };
                let before = work(&ctx);
                ctx.execute_committed_block(b, vec![]);
                assert!(!ctx.exec_failed.load(Ordering::SeqCst), "block {}", i + 1);
                units.push(work(&ctx) - before);
                if i >= 8 {
                    after.push((dump_all_cfs(&db), torus_state::native_trie::persisted_native_root(&db).unwrap()));
                }
            }
            assert_eq!(adl_rows(&db), 0);
            (after, units)
        };
        let (straight, units_s) = run(None);
        let (restarted, units_r) = run(Some(8));
        assert!(units_s.iter().filter(|&&u| u > 0).count() >= 15, "B's units in block 2, a drain in blocks 3..=16: {units_s:?}");
        assert_eq!(units_s, units_r, "drain work units per block, straight vs restarted");
        for (i, ((d1, r1), (d2, r2))) in straight.iter().zip(restarted.iter()).enumerate() {
            assert_dumps_equal(d1, d2, &format!("block {}", i + 9));
            assert_eq!(r1, r2, "block {}: native root", i + 9);
        }
    }

    /// Liquidation telemetry is node-local: the M2 sequence above (stage 1
    /// in blocks 2..=14, T flat after 14) with metrics attached and
    /// without gives identical full dumps (block results included) and native
    /// roots; with metrics the step counters / gauge / histogram move.
    #[test]
    fn liquidation_telemetry_does_not_change_block_results_or_state() {
        torus_state::native_trie::force_native_trie_maintenance_on_for_tests();
        let mut rounds = vec![vec![oracle_sub(61, 1, 990), oracle_sub(62, 1, 990), oracle_sub(63, 1, 990)]];
        rounds.extend(std::iter::repeat_n(Vec::new(), 11)); // 2..=12
        rounds.push(vec![signed_bid(73, 13_073, 966, 4), signed_stop_limit_buy(73, 13_074, 960, 966, 6)]); // 13
        rounds.extend(std::iter::repeat_n(Vec::new(), 2)); // 14, 15
        let blocks = liq_blocks(rounds);
        let run = |metrics: Option<Arc<torus_telemetry::Metrics>>| {
            let (config, db) = liq_fixture_db(10, 300);
            let mut ctx = make_exec_ctx(&config, &db);
            ctx.metrics = metrics;
            for (i, b) in blocks.iter().enumerate() {
                ctx.execute_committed_block(b, vec![]);
                assert!(!ctx.exec_failed.load(Ordering::SeqCst), "block {}", i + 1);
            }
            drop(ctx);
            let root = torus_state::native_trie::persisted_native_root(&db).unwrap();
            (dump_all_cfs(&db), root, db)
        };
        let m = Arc::new(torus_telemetry::Metrics::new());
        let (with, root_w, db_w) = run(Some(m.clone()));
        let (without, root_n, _) = run(None);
        assert_eq!(signed_pos_of(&db_w, &oracle_addr(71)), FixedPoint::ZERO, "non-vacuous: T liquidated");
        assert_dumps_equal(&with, &without, "liquidation telemetry: metrics attached vs not");
        assert_eq!(root_w, root_n);
        // Block 1's submissions aggregate at block 2's start; T is acted on by
        // stage 1 in every block 2..=14 (no bid before block 13: it stays under
        // MM), once per block.
        assert_eq!(m.liquidations_stage1.get(), 13, "stage 1 in blocks 2..=14");
        assert_eq!(m.liquidation_acted.get(), 13);
        assert_eq!(m.liquidations_triggered.get(), 13);
        assert_eq!((m.liquidations_backstop.get(), m.liquidations_adl.get()), (0, 0));
        assert_eq!(m.liquidation_pending.get(), 0, "flat after block 14");
        let steps = m
            .encode()
            .lines()
            .find_map(|l| l.strip_prefix("torus_liquidation_step_seconds_count ").map(|v| v.trim().parse::<u64>().unwrap()));
        // One sample per native block: 1 (actions), 2..=12 (oracle rows /
        // pending row), 13 (actions), 14 (pending row); 15 runs no native
        // phase (flat, rows pruned, no actions).
        assert_eq!(steps, Some(14), "step samples");
    }

    /// s94 bad-debt route (`crates/torus-bridge/tests/
    /// offmark_bad_debt_tests.rs` has the executor-level cases), through
    /// committed blocks on the live dispatch path. A (seed 75) and B (76),
    /// one owner, each funded 100 = the IM of 10 at 200 (20x).
    /// Probe (77a3b21): B's IOC sell filled A's bid @200 in block 2, A was
    /// ADL'd at the block's end with -900 left in the vault, and B moved
    /// 1,100 to the EVM side for 200 deposited.
    /// Fixed: block 1 (no mark yet, never marked: no band): A's GTC bid 10
    /// @200 rests (reserves 100). Block 2 (mark 100): B's IOC sell @200 is
    /// rejected at placement by the price band (option 2: more than 50% from
    /// the mark; had it matched, option 1 would margin-cancel A's bid: loss
    /// 1,000 − tolerance 75 > A's free 0). B's TransferToSpot 100 takes back
    /// its own deposit. Block 3: B's 1,000 is refused. The vault stays at 0.
    #[test]
    fn offmark_fill_e2e_is_refused_and_the_counterparty_gets_back_only_its_deposit() {
        use torus_core::liquidation::LIQUIDATOR_VAULT;
        use torus_core::position::{NativeBalance, PositionManager};
        use torus_state::action_status::FailureReason;
        // Inside the nonce window (block h's time is (1_000 + h) s, window
        // +-60 s): the same base as `NONCE_BASE` on the nonce-window branch.
        const NB: u64 = 1_000_000;
        let (config, db) = oracle_fixture_db();
        let pm = PositionManager::new(db.clone());
        let (a, b) = (oracle_addr(75), oracle_addr(76));
        for t in [a, b] {
            pm.put_native_balance(&t, &NativeBalance { available: px(100), order_margin: FixedPoint::ZERO }).unwrap();
        }
        let ioc_sell = torus_types::eip712::sign_native_action(
            NativeAction::PlaceOrder(torus_types::PlaceOrderParams {
                market_id: ORACLE_MARKET,
                is_buy: false,
                price: px(200),
                quantity: px(10),
                order_type: torus_types::OrderType::Limit,
                time_in_force: torus_types::TimeInForce::IOC,
                reduce_only: false,
                client_order_id: None,
            }),
            NB + 2_076,
            &oracle_key(76),
        );
        let to_spot = |nonce: u64, amount: i64| {
            torus_types::eip712::sign_native_action(
                NativeAction::TransferToSpot { amount: U256::from(px(amount).raw() as u128) },
                NB + nonce,
                &oracle_key(76),
            )
        };
        let mut r1: Vec<SignedNativeAction> = (61..=63).map(|s| oracle_sub(s, 1, 100)).collect();
        r1.push(signed_bid(75, 1_075, 200, 10));
        let blocks = liq_blocks(vec![r1, vec![ioc_sell, to_spot(2_176, 100)], vec![to_spot(3_076, 1_000)]]);
        let ctx = make_exec_ctx(&config, &db);
        let native = |t: &Address| {
            let x = pm.get_native_balance(t).unwrap();
            (x.available, x.order_margin)
        };
        dispatch_and_execute(&ctx, &db, &blocks[0]);
        assert_eq!(native(&a), (FixedPoint::ZERO, px(100)), "block 1: A's bid @200 rests, IM at 200 reserved");
        dispatch_and_execute(&ctx, &db, &blocks[1]);
        assert_eq!(signed_pos_of(&db, &a), FixedPoint::ZERO, "block 2: no fill (B's sell refused by the band)");
        assert_eq!(signed_pos_of(&db, &b), FixedPoint::ZERO);
        assert_eq!(native(&a), (FixedPoint::ZERO, px(100)), "A's bid still rests");
        assert_eq!(native(&b), (FixedPoint::ZERO, FixedPoint::ZERO), "B: its own 100 withdrawn");
        assert_eq!(read_evm_balance(&db, b), U256::from(px(100).raw() as u128));
        assert_eq!(native(&LIQUIDATOR_VAULT).0, FixedPoint::ZERO);
        // Refused for the right reason: executed (not skipped), rejected
        // (review S3: HL `oracleRejected`) with `price_band`; the transfer
        // executed.
        let s2 = action_status(&db, 2).expect("block 2 status");
        assert!(s2.native_skipped.iter().all(|s| !s), "block 2: nothing skipped (nonces in window)");
        assert_eq!(s2.native_failed.len(), 1, "block 2: only B's sell failed");
        assert_eq!(s2.native_failed[0].reason, FailureReason::PriceBand, "block 2: refused by the band");
        assert_eq!(s2.native_failed[0].outcome, torus_state::action_status::Outcome::Rejected, "block 2: oracleRejected");
        dispatch_and_execute(&ctx, &db, &blocks[2]);
        let s3 = action_status(&db, 3).expect("block 3 status");
        assert!(s3.native_skipped.iter().all(|s| !s), "block 3: the transfer was executed, not skipped");
        assert_eq!(s3.native_failed.len(), 1, "block 3: B's 1,000 refused");
        assert_eq!(native(&b), (FixedPoint::ZERO, FixedPoint::ZERO));
        assert_eq!(read_evm_balance(&db, b), U256::from(px(100).raw() as u128), "block 3: nothing more");
        assert_eq!(native(&LIQUIDATOR_VAULT).0, FixedPoint::ZERO);
        assert!(!ctx.exec_failed.load(Ordering::SeqCst));
        assert_eq!(read_native_applied_height(&db), Some(3));
    }

    // ---- s517 oracle feeder S4: the hot oracle signer through whole blocks ----

    /// The hot signer key of validator `seed` (a separate address).
    fn signer_key(seed: u8) -> k256::ecdsa::SigningKey {
        oracle_key(seed.wrapping_add(100))
    }

    fn key_addr(key: &k256::ecdsa::SigningKey) -> Address {
        torus_types::eip712::sign_native_action(NativeAction::ClaimRewards, 0, key)
            .recover_sender()
            .unwrap()
    }

    /// `SetOracleSigner` from validator `seed`; `signer` = the new signer's key
    /// (its proof of possession, review M3) or `None` to clear.
    fn set_signer_action(h: u64, seed: u8, signer: Option<&k256::ecdsa::SigningKey>) -> SignedNativeAction {
        let nonce = NONCE_BASE + h * 1_000 + 500 + seed as u64;
        let action = match signer {
            None => NativeAction::SetOracleSigner { signer: Address::ZERO, proof: None },
            Some(k) => NativeAction::SetOracleSigner {
                signer: key_addr(k),
                proof: Some(torus_types::eip712::sign_oracle_signer_proof(&oracle_addr(seed), nonce, k)),
            },
        };
        torus_types::eip712::sign_native_action(action, nonce, &oracle_key(seed))
    }

    fn signer_submit(h: u64, key: &k256::ecdsa::SigningKey, tag: u8, price: i64) -> SignedNativeAction {
        signer_submit_at(h, key, tag, price, (1_000 + h) * 1_000)
    }

    fn signer_submit_at(h: u64, key: &k256::ecdsa::SigningKey, tag: u8, price: i64, sample_ms: u64) -> SignedNativeAction {
        torus_types::eip712::sign_native_action(
            NativeAction::SubmitOraclePrices(torus_types::OracleSubmission {
                prices: vec![(ORACLE_MARKET, px(price))],
                timestamp: sample_ms,
            }),
            NONCE_BASE + h * 1_000 + tag as u64,
            key,
        )
    }

    /// Heights 1..=n (ts = 1000 + h), linked to their actual parents.
    fn blocks_of(rounds: Vec<Vec<SignedNativeAction>>) -> Vec<TorusBlock> {
        let mut blocks: Vec<TorusBlock> = rounds
            .into_iter()
            .enumerate()
            .map(|(i, a)| make_block(i as u64 + 1, a))
            .collect();
        link_blocks(&mut blocks);
        blocks
    }

    fn signer_index_rows(db: &StateDb) -> Vec<(Vec<u8>, Vec<u8>)> {
        StateBackend::iterate_cf(db, torus_state::cf::CF_NATIVE_ORACLE, Some(b"sgn")).unwrap()
    }

    /// Block 1: every validator registers its signer (EIP-712, validator key).
    /// Block 2: the SIGNERS submit 100 / 101 / 102. Block 3: the stake-weighted
    /// mark (V3 = 3x) is 102 (simple median 101). Exercises batch signature
    /// recovery -> sender = signer -> resolution to the validator.
    #[test]
    fn oracle_signer_signed_submissions_aggregate_through_whole_blocks() {
        let (config, db) = oracle_fixture_db();
        let ctx = make_exec_ctx(&config, &db);
        let set: Vec<_> = ORACLE_VALIDATORS
            .iter()
            .map(|&(s, _)| set_signer_action(1, s, Some(&signer_key(s))))
            .collect();
        let subs: Vec<_> = [(61u8, 100i64), (62, 101), (63, 102)]
            .iter()
            .map(|&(s, p)| signer_submit(2, &signer_key(s), s, p))
            .collect();
        let blocks = blocks_of(vec![set, subs, vec![]]);
        for b in &blocks {
            ctx.execute_committed_block(b, vec![]);
        }
        assert!(!ctx.exec_failed.load(Ordering::SeqCst));
        assert_eq!(signer_index_rows(&db).len(), 3);
        let rows = oracle_sub_rows(&db);
        assert_eq!(rows.len(), 3, "one row per VALIDATOR");
        for (seed, _) in ORACLE_VALIDATORS {
            assert!(rows.iter().any(|(k, _)| &k[11..31] == oracle_addr(seed).as_slice()));
        }
        assert_eq!(mark_at(&db, 1_003), Some((px(102), 3)), "stake-weighted by the validators");
    }

    /// Block 2 carries V61's rotation AND a submission from its OLD signer: the
    /// oracle category runs before `Other`, so the row is written. Block 3: the
    /// old signer adds nothing; block 4: the new signer updates the row.
    #[test]
    fn oracle_signer_rotation_in_block_counts_old_signer_once_then_rejects_it() {
        let (config, db) = oracle_fixture_db();
        let ctx = make_exec_ctx(&config, &db);
        let (old, new) = (signer_key(61), oracle_key(222));
        let blocks = blocks_of(vec![
            vec![set_signer_action(1, 61, Some(&old))],
            vec![set_signer_action(2, 61, Some(&new)), signer_submit(2, &old, 1, 100)],
            vec![signer_submit(3, &old, 1, 500)],
            vec![signer_submit(4, &new, 2, 700)],
        ]);
        ctx.execute_committed_block(&blocks[0], vec![]);
        ctx.execute_committed_block(&blocks[1], vec![]);
        let after_rotation = oracle_sub_rows(&db);
        assert_eq!(after_rotation.len(), 1, "same-block: the old signer still counts once");
        assert_eq!(&after_rotation[0].0[11..31], oracle_addr(61).as_slice());
        assert_eq!(
            signer_index_rows(&db),
            vec![(
                torus_state::cf::oracle_signer_key(&key_addr(&new)).to_vec(),
                oracle_addr(61).to_vec()
            )]
        );
        ctx.execute_committed_block(&blocks[2], vec![]);
        assert_eq!(oracle_sub_rows(&db), after_rotation, "old signer rejected from the next block");
        ctx.execute_committed_block(&blocks[3], vec![]);
        let rows = oracle_sub_rows(&db);
        assert_eq!(rows.len(), 1);
        assert_ne!(rows, after_rotation, "the new signer's submission replaces the row");
        assert!(!ctx.exec_failed.load(Ordering::SeqCst));
    }

    /// Determinism: a chain with SetOracleSigner (set, rotate, clear) and signer
    /// submissions gives identical CF dumps + native roots serially, pipelined
    /// (parked) and through crash replay.
    #[test]
    fn oracle_signer_blocks_replay_identically() {
        let new61 = oracle_key(222);
        let set: Vec<_> = ORACLE_VALIDATORS
            .iter()
            .map(|&(s, _)| set_signer_action(1, s, Some(&signer_key(s))))
            .collect();
        let subs = |h: u64, p: i64| -> Vec<SignedNativeAction> {
            ORACLE_VALIDATORS.iter().map(|&(s, _)| signer_submit(h, &signer_key(s), s, p)).collect()
        };
        let mut b4 = subs(4, 300);
        b4.push(set_signer_action(4, 61, Some(&new61)));
        let blocks = blocks_of(vec![
            set,
            subs(2, 100),
            vec![],
            b4,
            vec![signer_submit(5, &signer_key(61), 61, 900), signer_submit(5, &new61, 1, 310)],
            vec![set_signer_action(6, 62, None)],
            subs(7, 400), // 62's cleared signer is rejected
            // review M1(b): two samples of V63 in one block; the newer (450)
            // must win whatever the in-block order.
            vec![
                signer_submit_at(8, &signer_key(63), 1, 450, 1_008_000),
                signer_submit_at(8, &signer_key(63), 2, 999, 1_007_500),
            ],
        ]);
        let (serial, root_s, db_s) = run_fixture(OracleRun::Serial, &blocks, oracle_fixture_db);
        let (piped, root_p, _) = run_fixture(OracleRun::PipelinedParked, &blocks, oracle_fixture_db);
        let (replay, root_r, _) = run_fixture(OracleRun::Replay, &blocks, oracle_fixture_db);
        // Non-vacuous: 61 -> new signer, 62 cleared, 63 unchanged.
        let idx = signer_index_rows(&db_s);
        assert_eq!(idx.len(), 2, "{idx:?}");
        assert!(idx.iter().any(|(k, v)| k[3..] == *key_addr(&new61).as_slice() && v[..] == *oracle_addr(61).as_slice()));
        assert!(idx.iter().any(|(k, v)| k[3..] == *key_addr(&signer_key(63)).as_slice() && v[..] == *oracle_addr(63).as_slice()));
        assert!(mark_at(&db_s, 1_008).is_some());
        let v63 = oracle_sub_rows(&db_s)
            .into_iter()
            .map(|(_, v)| <torus_core::oracle::OracleSubmission as borsh::BorshDeserialize>::try_from_slice(&v).unwrap())
            .find(|r| r.validator == oracle_addr(63))
            .unwrap();
        assert_eq!(v63.price, px(450), "newest sample of the block wins");
        assert_dumps_equal(&serial, &piped, "oracle signer: serial vs pipelined (parked)");
        assert_dumps_equal(&serial, &replay, "oracle signer: serial vs crash replay");
        assert_eq!(root_s, root_p);
        assert_eq!(root_s, root_r);
    }

    // ======================================================================
    // Item 6 Phase 1 (C1): resident rows R on the committed-block path
    // ======================================================================

    /// R between blocks (holder slot) as per-CF dumps; `None` = slot empty.
    fn resident_rows_dump(ctx: &ExecutionContext) -> Option<Vec<CfDump>> {
        let mut holder = ctx.resident_books.lock().unwrap();
        holder.rows().map(|r| {
            torus_state::resident_rows::RESIDENT_CFS
                .iter()
                .map(|cf| (*cf, r.rows(cf).unwrap().iter().map(|(k, v)| (k.clone(), v.clone())).collect()))
                .collect()
        })
    }

    /// R's two CFs scanned from the DB.
    fn resident_cfs_in_db(db: &StateDb) -> Vec<CfDump> {
        torus_state::resident_rows::RESIDENT_CFS
            .iter()
            .map(|cf| (*cf, StateBackend::iterate_cf(db, cf, None).unwrap()))
            .collect()
    }

    /// With R on: after block `h` (W drained when pipelined) the holder's R is
    /// at `h` and equals the DB scan of both CFs.
    fn assert_resident_rows_track_db(ctx: &ExecutionContext, db: &StateDb, h: u64, what: &str) {
        if let Some(w) = ctx.flush_worker.as_ref() {
            assert!(w.wait_idle(), "{what}: W failed");
        }
        assert_eq!(ctx.resident_books.lock().unwrap().rows_height(), Some(h), "{what}: R height after {h}");
        let rows = resident_rows_dump(ctx).expect("R stashed");
        assert_dumps_equal(&rows, &resident_cfs_in_db(db), &format!("{what}: R vs DB after {h}"));
        // Item 6 C7: the slot's decoded positions == a cold decode of R.
        assert_eq!(
            ctx.resident_books.lock().unwrap().trader_positions_match_rows(),
            Some(true),
            "{what}: decoded positions vs R after {h}"
        );
    }

    /// Run the book fixture in `mode`, serial or pipelined, with R
    /// (`no_r = false`, checked against the DB after every block) or without
    /// (`test_no_resident_rows`, today's path), restarting after the heights
    /// in `restart_after`. Returns the full dump, the per-block consensus
    /// write sets (`h_n` inputs), the stored running hash and R's builds.
    #[allow(clippy::type_complexity)]
    fn run_book_fixture_r(
        on: bool,
        mode: torus_bridge::native_executor::BookMode,
        no_r: bool,
        restart_after: &[u64],
    ) -> (Vec<CfDump>, CapturedWrites, Option<(u64, [u8; 32])>, u64) {
        let (_cfg, state_db) = make_test_config_and_db();
        fund_book_fixture(&state_db);
        torus_state::running_hash::capture_begin(&state_db);
        let new_ctx = || {
            let mut c = book_pipeline_ctx(&state_db, on, None, mode);
            c.test_no_resident_rows = no_r;
            c
        };
        let mut ctx = new_ctx();
        let mut builds = 0;
        for b in &book_fixture_blocks() {
            let h = b.header.height;
            dispatch_and_execute(&ctx, &state_db, b);
            let what = format!("{mode:?} on={on} no_r={no_r} restarts={restart_after:?}");
            assert!(!ctx.exec_failed.load(std::sync::atomic::Ordering::SeqCst), "{what}: fail-stop at {h}");
            if no_r {
                assert_eq!(ctx.resident_books.lock().unwrap().rows_height(), None, "{what}: no R");
            } else {
                assert_resident_rows_track_db(&ctx, &state_db, h, &what);
                assert_eq!(ctx.resident_books.lock().unwrap().rows_shared_fallbacks(), 0, "{what}");
            }
            if restart_after.contains(&h) {
                builds += ctx.resident_books.lock().unwrap().rows_builds();
                drop(ctx);
                ctx = new_ctx();
            }
        }
        builds += ctx.resident_books.lock().unwrap().rows_builds();
        drop(ctx);
        let captured = torus_state::running_hash::capture_take(&state_db);
        let stored = torus_state::running_hash::read_running_hash(&state_db);
        (dump_all_cfs(&state_db), captured, stored, builds)
    }

    /// Item 6 C1: R == the DB scan of both CFs after every block, serial and
    /// pipelined (sessions, claim rewards, empties advancing R, epoch
    /// boundaries), built once, never shared at the end of a block.
    #[test]
    fn resident_rows_equal_db_scan_after_every_block_serial_and_pipelined() {
        for on in [false, true] {
            let (_cfg, state_db) = make_test_config_and_db();
            fund_pipeline_fixture(&state_db);
            let ctx = pipeline_ctx(&state_db, on, None);
            for b in &pipeline_fixture_blocks() {
                dispatch_and_execute(&ctx, &state_db, b);
                assert!(!ctx.exec_failed.load(std::sync::atomic::Ordering::SeqCst));
                assert_resident_rows_track_db(&ctx, &state_db, b.header.height, &format!("on={on}"));
            }
            let mut holder = ctx.resident_books.lock().unwrap();
            assert_eq!(holder.rows_builds(), 1, "on={on}: built once at block 1");
            assert_eq!(holder.rows_shared_fallbacks(), 0, "on={on}: Arc::get_mut never fails");
            assert!(holder.rows().unwrap().len() > 2, "non-vacuous");
        }
    }

    /// Item 6 step 2: on the committed-block path, serial and pipelined, each
    /// native block hands `end_resident` to a worker (in flight when the
    /// block returns); the next block (native: `begin_resident`, untouched:
    /// `advance_untouched`) joins it, so R still equals the DB after every
    /// block; the end timer and the join's wait timer count once per worker.
    /// Prints the worker's time vs the exposed wait (18c sanity, tiny blocks).
    #[test]
    fn end_resident_runs_on_a_worker_joined_by_the_next_block() {
        for on in [false, true] {
            let (_cfg, state_db) = make_test_config_and_db();
            fund_pipeline_fixture(&state_db);
            let mut ctx = pipeline_ctx(&state_db, on, None);
            let metrics = Arc::new(torus_telemetry::Metrics::new());
            ctx.metrics = Some(metrics.clone());
            let mut spawned = 0.0;
            for b in &pipeline_fixture_blocks() {
                dispatch_and_execute(&ctx, &state_db, b);
                assert!(!ctx.exec_failed.load(std::sync::atomic::Ordering::SeqCst));
                let in_flight = ctx.resident_books.lock().unwrap().rows_in_flight();
                spawned += f64::from(u8::from(in_flight));
                // Odd heights: the next block joins the worker itself.
                if b.header.height.is_multiple_of(2) {
                    assert_resident_rows_track_db(&ctx, &state_db, b.header.height, &format!("worker on={on}"));
                }
            }
            ctx.resident_books.lock().unwrap().settle_rows();
            let text = metrics.encode();
            let v = |name: &str| metric_value(&text, name);
            assert!(spawned >= 4.0, "on={on}: native blocks ran on the worker ({spawned})");
            assert_eq!(v("torus_exec_end_resident_seconds_count"), spawned, "on={on}");
            assert_eq!(v("torus_exec_end_resident_wait_seconds_count"), spawned, "on={on}: one join per worker");
            println!(
                "STEP2 on={on} workers={spawned} end_resident_ms_sum={:.3} wait_ms_sum={:.3}",
                v("torus_exec_end_resident_seconds_sum") * 1e3,
                v("torus_exec_end_resident_wait_seconds_sum") * 1e3
            );
        }
    }

    /// Item 6 C1: the same block sequence with and without R lands identical
    /// CF dumps, identical per-block consensus write sets (`h_n`) and the same
    /// running hash, in all four BookModes, serial and pipelined; R also
    /// survives restarts (rebuilt cold) with the same result.
    #[test]
    fn resident_rows_on_off_identical_state_and_running_hash_every_book_mode() {
        use torus_bridge::native_executor::BookMode;
        for mode in [
            BookMode::Classic,
            BookMode::OrderRows,
            BookMode::LevelAuthority,
            BookMode::LevelAuthorityChunked,
        ] {
            for on in [false, true] {
                let what = format!("{mode:?} on={on}");
                let (dump_off, cap_off, hash_off, builds_off) = run_book_fixture_r(on, mode, true, &[]);
                let (dump_on, cap_on, hash_on, builds_on) = run_book_fixture_r(on, mode, false, &[]);
                assert_eq!((builds_off, builds_on), (0, 1), "{what}");
                assert_dumps_equal(&dump_off, &dump_on, &format!("{what}: without vs with R"));
                assert_write_sets_equal(&cap_off, &cap_on, &format!("{what}: without vs with R"));
                assert!(hash_on.is_some());
                assert_eq!(hash_off, hash_on, "{what}: running hash");
                let (dump_rs, cap_rs, hash_rs, builds_rs) = run_book_fixture_r(on, mode, false, &[3, 7]);
                assert_eq!(builds_rs, 3, "{what}: one build per (re)start");
                assert_dumps_equal(&dump_off, &dump_rs, &format!("{what}: with R + restarts"));
                assert_write_sets_equal(&cap_off, &cap_rs, &format!("{what}: with R + restarts"));
                assert_eq!(hash_off, hash_rs, "{what}: running hash with restarts");
            }
        }
    }

    /// Row 74: a storage / decode fault in the governance step (it runs after
    /// the liquidation check) fail-stops like the batches and the liquidation
    /// step: no flush (the DB is byte-identical to before the block), the
    /// applied height stays, and every later block refuses to execute.
    #[test]
    fn governance_storage_fault_fail_stops_and_flushes_nothing() {
        use std::sync::atomic::Ordering::SeqCst;
        use torus_bridge::native_executor::BookMode;
        use torus_state::cf::{CF_FEE_CONFIG, CF_GOVERNANCE_PROPOSALS};
        let blocks = book_fixture_blocks();
        let (_c, db) = make_test_config_and_db();
        fund_book_fixture(&db);
        let ctx = book_pipeline_ctx(&db, false, None, BookMode::Classic);
        dispatch_and_execute(&ctx, &db, &blocks[0]);
        dispatch_and_execute(&ctx, &db, &blocks[1]);
        assert!(!ctx.exec_failed.load(SeqCst));
        assert_eq!(read_native_applied_height(&db), Some(2));

        // Proposal counter > 0 and a proposal row that does not decode: the
        // governance step's scan returns a Borsh error (a local fault).
        db.put_cf_raw(CF_FEE_CONFIG, b"gov_next_id", &2u64.to_be_bytes())
            .unwrap();
        db.put_cf_raw(CF_GOVERNANCE_PROPOSALS, &1u64.to_be_bytes(), b"\xff")
            .unwrap();

        for b in &blocks[2..4] {
            let height = b.header.height;
            let durable = persist_committed_block_durably(&db, b);
            let before = dump_all_cfs(&db);
            ctx.execute_committed_block_with(b, vec![], durable);
            assert!(
                ctx.exec_failed.load(SeqCst),
                "block {height}: must fail-stop"
            );
            assert_eq!(
                read_native_applied_height(&db),
                Some(2),
                "block {height} not applied"
            );
            assert_dumps_equal(
                &before,
                &dump_all_cfs(&db),
                "nothing of the failed block flushed",
            );
        }
    }

    /// Row 74 item 4: the buffered-slash loop. A slash whose validator has a
    /// delegation row that does not decode (a local fault) fail-stops before
    /// `commit_tx`: nothing of the slashes nor of the block reaches the DB. A
    /// slash every node refuses alike (unknown validator) is only logged, as
    /// before.
    #[test]
    fn slash_storage_fault_fail_stops_unknown_validator_does_not() {
        use std::sync::atomic::Ordering::SeqCst;
        use torus_bridge::native_executor::BookMode;
        use torus_state::cf::CF_STAKING_DELEGATIONS;
        let slash = |validator: Address| PendingSlash {
            validator,
            fraction_bps: 500,
            reason: SlashReason::DoubleSign,
            tombstone: true,
        };
        let blocks = book_fixture_blocks();
        let (_c, db) = make_test_config_and_db();
        fund_book_fixture(&db);
        let val = Address::repeat_byte(0x66);
        register_proposer(&db, val);
        let ctx = book_pipeline_ctx(&db, false, None, BookMode::Classic);
        dispatch_and_execute(&ctx, &db, &blocks[0]);

        // Unknown validator: deterministic, logged, the block applies.
        let durable = persist_committed_block_durably(&db, &blocks[1]);
        ctx.execute_committed_block_with(
            &blocks[1],
            vec![slash(Address::repeat_byte(0x55))],
            durable,
        );
        assert!(
            !ctx.exec_failed.load(SeqCst),
            "an unknown validator must not halt"
        );
        assert_eq!(read_native_applied_height(&db), Some(2));

        // A delegation row of `val` that does not decode (only the slash
        // reads it): fail-stop, nothing written.
        let mut del_key = [0x11u8; 40];
        del_key[20..].copy_from_slice(val.as_slice());
        db.put_cf_raw(CF_STAKING_DELEGATIONS, &del_key, b"\xff")
            .unwrap();
        let durable = persist_committed_block_durably(&db, &blocks[2]);
        let before = dump_all_cfs(&db);
        ctx.execute_committed_block_with(
            &blocks[2],
            vec![slash(Address::repeat_byte(0x55)), slash(val)],
            durable,
        );
        assert!(
            ctx.exec_failed.load(SeqCst),
            "a slash storage fault must fail-stop"
        );
        assert_eq!(read_native_applied_height(&db), Some(2));
        assert_dumps_equal(
            &before,
            &dump_all_cfs(&db),
            "nothing of the failed block flushed",
        );
    }

    /// Item 6 C1, guard P7 on the committed-block path: a fatal block (wrong
    /// book mode -> load error -> fail-stop before the flush) leaves R taken,
    /// so its re-execution rebuilds; a height applied by another exec context
    /// (the holder skipped it) rebuilds too. R is never stale: it equals the
    /// DB after each step and the final state equals a run without R.
    #[test]
    fn resident_rows_guard_fatal_block_and_skipped_height_rebuild() {
        use std::sync::atomic::Ordering::SeqCst;
        use torus_bridge::native_executor::BookMode;
        let blocks = book_fixture_blocks();
        let first5 = &blocks[..5];

        let (_c0, db_ref) = make_test_config_and_db();
        fund_book_fixture(&db_ref);
        let mut ctx_ref = book_pipeline_ctx(&db_ref, false, None, BookMode::Classic);
        ctx_ref.test_no_resident_rows = true;
        for b in first5 {
            dispatch_and_execute(&ctx_ref, &db_ref, b);
        }
        drop(ctx_ref);
        let dump_ref = dump_all_cfs(&db_ref);

        let (_c1, db) = make_test_config_and_db();
        fund_book_fixture(&db);
        let mut ctx = book_pipeline_ctx(&db, false, None, BookMode::Classic);
        let builds = |ctx: &ExecutionContext| ctx.resident_books.lock().unwrap().rows_builds();
        dispatch_and_execute(&ctx, &db, &first5[0]);
        dispatch_and_execute(&ctx, &db, &first5[1]);
        assert_resident_rows_track_db(&ctx, &db, 2, "after 2");
        assert_eq!(builds(&ctx), 1);

        // Fatal block 3: the context loads in a mode the DB was not written in.
        ctx.test_book_mode = Some(BookMode::OrderRows);
        dispatch_and_execute(&ctx, &db, &first5[2]);
        assert!(ctx.exec_failed.load(SeqCst), "mode mismatch must fail-stop");
        assert_eq!(read_native_applied_height(&db), Some(2), "nothing of 3 durable");
        assert_eq!(ctx.resident_books.lock().unwrap().rows_height(), None, "R taken by the fatal block");
        assert_eq!(builds(&ctx), 1, "the fatal block reused R (successor of 2)");

        // Re-execute 3 (latch cleared, right mode): R rebuilds from the DB.
        ctx.test_book_mode = Some(BookMode::Classic);
        ctx.exec_failed.store(false, SeqCst);
        dispatch_and_execute(&ctx, &db, &first5[2]);
        assert!(!ctx.exec_failed.load(SeqCst));
        assert_eq!(builds(&ctx), 2, "re-executed 3 rebuilt R");
        assert_resident_rows_track_db(&ctx, &db, 3, "after re-executed 3");

        // Block 4 applied by another exec context: this holder skipped it.
        let ctx2 = book_pipeline_ctx(&db, false, None, BookMode::Classic);
        dispatch_and_execute(&ctx2, &db, &first5[3]);
        assert!(!ctx2.exec_failed.load(SeqCst));
        drop(ctx2);
        assert_eq!(ctx.resident_books.lock().unwrap().rows_height(), Some(3));
        dispatch_and_execute(&ctx, &db, &first5[4]);
        assert!(!ctx.exec_failed.load(SeqCst));
        assert_eq!(builds(&ctx), 3, "R at 3 vs block 5: rebuilt");
        assert_resident_rows_track_db(&ctx, &db, 5, "after 5");
        assert_eq!(ctx.resident_books.lock().unwrap().rows_shared_fallbacks(), 0);
        drop(ctx);
        assert_dumps_equal(&dump_ref, &dump_all_cfs(&db), "guard sequence with R vs without R");
    }

    /// Item 6 C1: an EVM lockbox deposit (0x0820) in block 1 is credited by
    /// block 2's CoreWriter drain (a write of `CF_NATIVE_BALANCES` through the
    /// block overlay, so R takes it); orders in 2 (placed before the drain)
    /// and 3 (on the credited balance) — identical state with and without R,
    /// serial and pipelined.
    #[test]
    fn resident_rows_lockbox_deposit_then_orders_identical_without_r() {
        let key = k256::ecdsa::SigningKey::from_slice(&[71u8; 32]).unwrap();
        let trader = k256_address(&key);
        let amount_wei: u128 = 1_000 * 10u128.pow(18); // 1000 native units
        let mut calldata = alloy_primitives::keccak256("depositToNative(uint128)".as_bytes())[..4].to_vec();
        calldata.extend_from_slice(&U256::from(amount_wei).to_be_bytes::<32>());
        let lockbox = torus_core::precompiles::precompile_address(torus_core::precompiles::ADDR_LOCKBOX);
        let order = |price: i128| {
            NativeAction::PlaceOrder(torus_types::PlaceOrderParams {
                market_id: 1,
                is_buy: true,
                price: FixedPoint::from_raw(price * FixedPoint::SCALE),
                quantity: FixedPoint::ONE,
                order_type: torus_types::OrderType::Limit,
                time_in_force: torus_types::TimeInForce::GTC,
                reduce_only: false,
                client_order_id: None,
            })
        };
        let mut blocks = vec![
            make_block(1, vec![]),
            make_block(2, vec![torus_types::eip712::sign_native_action(order(90), NONCE_BASE + 1, &key)]),
            make_block(3, vec![torus_types::eip712::sign_native_action(order(95), NONCE_BASE + 2, &key)]),
        ];
        blocks[0].evm_transactions = vec![signed_eip1559_with_value(
            &key,
            0,
            alloy_primitives::TxKind::Call(lockbox),
            calldata,
            U256::from(amount_wei),
        )];
        blocks[0].header.evm_tx_count = 1;
        link_blocks(&mut blocks);

        let mut dumps = Vec::new();
        for on in [false, true] {
            for no_r in [true, false] {
                let (_cfg, db) = make_test_config_and_db();
                db.put_account(
                    &trader,
                    &revm::state::AccountInfo {
                        balance: U256::from(10u128.pow(22)),
                        nonce: 0,
                        code_hash: KECCAK_EMPTY_CODE,
                        code: None,
                        account_id: None,
                    },
                )
                .unwrap();
                let mut ctx = pipeline_ctx(&db, on, None);
                ctx.test_no_resident_rows = no_r;
                let pm = torus_core::position::PositionManager::new(db.clone());
                let mut seen = Vec::new();
                for b in &blocks {
                    dispatch_and_execute(&ctx, &db, b);
                    assert!(!ctx.exec_failed.load(Ordering::SeqCst), "on={on} no_r={no_r}");
                    if let Some(w) = ctx.flush_worker.as_ref() {
                        assert!(w.wait_idle());
                    }
                    let bal = pm.get_native_balance(&trader).unwrap();
                    seen.push((bal.available + bal.order_margin, bal.order_margin));
                    if !no_r {
                        assert_resident_rows_track_db(&ctx, &db, b.header.height, "lockbox");
                    }
                }
                let credit = FixedPoint::from_raw(1_000 * FixedPoint::SCALE);
                assert_eq!(seen[0].0, FixedPoint::ZERO, "block 1: deposit queued, not credited");
                assert_eq!(seen[1].0, credit, "block 2: credited by the drain");
                assert_eq!(seen[1].1, FixedPoint::ZERO, "block 2's order ran before the drain: rejected");
                assert!(seen[2].1 > FixedPoint::ZERO, "block 3's order rests on the credited balance");
                drop(ctx);
                dumps.push(dump_all_cfs(&db));
            }
        }
        for d in &dumps[1..] {
            assert_dumps_equal(&dumps[0], d, "lockbox sequence: with/without R, serial/pipelined");
        }
    }

    /// R02 (audit option A, branch 1; APP:2409): a block whose CoreWriter
    /// queue read fails fail-stops — `exec_failed`, applied marker unchanged,
    /// nothing of the block flushed (every CF as before it ran; the queued
    /// deposit row still there) — and the restart's replay then matches an
    /// uninterrupted run. RED before R02: the drain's `Err` was dropped
    /// (`let _ =`), so the block flushed and was marked applied with the
    /// deposit never credited and its row stranded (no later height drains
    /// it). The no-fault run is the control (drain credits as before; also
    /// `resident_rows_lockbox_deposit_then_orders_identical_without_r`).
    #[test]
    fn r02_core_writer_queue_read_fault_fail_stops_block() {
        use torus_core::precompiles::{CoreWriterQueue, QueuedAction, QueuedActionKind};
        use torus_state::cf::CF_CORE_WRITER_QUEUE;
        let trader = Address::repeat_byte(0x5A);
        let credit = FixedPoint::from_raw(7 * FixedPoint::SCALE);
        let mut blocks = vec![make_block(1, vec![]), make_block(2, vec![])];
        link_blocks(&mut blocks);
        // A lockbox deposit queued by block 1's EVM, due in block 2.
        let setup = || {
            let (_cfg, db) = make_test_config_and_db();
            let qa = QueuedAction {
                trader,
                kind: QueuedActionKind::LockboxDeposit { amount: credit },
                block_queued: 1,
            };
            CoreWriterQueue::enqueue(&db, &qa).unwrap();
            db
        };
        let balance = |db: &StateDb| {
            torus_core::position::PositionManager::new(db.clone())
                .get_native_balance(&trader)
                .unwrap()
                .available
        };
        let queued = |db: &StateDb| {
            StateBackend::iterate_cf(db, CF_CORE_WRITER_QUEUE, None)
                .unwrap()
                .len()
        };
        let idle = |ctx: &ExecutionContext| {
            if let Some(w) = ctx.flush_worker.as_ref() {
                assert!(w.wait_idle());
            }
        };
        for on in [false, true] {
            // Control: no fault — block 2's drain credits the deposit.
            let db_ref = setup();
            let ctx = pipeline_ctx(&db_ref, on, None);
            for b in &blocks {
                dispatch_and_execute(&ctx, &db_ref, b);
            }
            idle(&ctx);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "on={on}");
            drop(ctx);
            assert_eq!(read_native_applied_height(&db_ref), Some(2), "on={on}");
            assert_eq!(balance(&db_ref), credit, "on={on}: drained and credited");
            assert_eq!(queued(&db_ref), 0, "on={on}");

            // Fault: block 2's queue read fails.
            let db = setup();
            let mut ctx = pipeline_ctx(&db, on, None);
            dispatch_and_execute(&ctx, &db, &blocks[0]);
            idle(&ctx);
            let durable = persist_committed_block_durably(&db, &blocks[1]);
            let before = dump_all_cfs(&db);
            ctx.test_core_writer_read_fault = true;
            ctx.execute_committed_block_with(&blocks[1], vec![], durable);
            idle(&ctx);
            assert!(
                ctx.exec_failed.load(Ordering::SeqCst),
                "on={on}: must fail-stop"
            );
            drop(ctx);
            assert_eq!(
                read_native_applied_height(&db),
                Some(1),
                "on={on}: block 2 not applied"
            );
            assert_dumps_equal(
                &before,
                &dump_all_cfs(&db),
                "R02: nothing of block 2 flushed",
            );
            assert_eq!(queued(&db), 1, "on={on}: the deposit row stays queued");
            assert_eq!(balance(&db), FixedPoint::ZERO, "on={on}");

            // Restart: the replay runs block 2 again (no fault) and matches.
            let ctx = pipeline_ctx(&db, false, None);
            let (_last, parked) = TorusApp::replay_committed(&db, &ctx);
            assert_eq!(parked, None);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst));
            drop(ctx);
            assert_eq!(read_native_applied_height(&db), Some(2), "on={on}");
            assert_dumps_equal(
                &dump_all_cfs(&db_ref),
                &dump_all_cfs(&db),
                "R02: replay vs no fault",
            );
        }
    }

    /// R02 branch 2: a fresh on-disk test DB (running hash on from height 1,
    /// as `make_test_config_and_db`) and its directory, so a restart test can
    /// close and reopen it.
    fn r02_reopenable_db() -> (std::path::PathBuf, StateDb) {
        torus_state::native_trie::force_native_trie_maintenance_on_for_tests();
        let dir = scratch_db_dir("torus-r02-replay");
        let db = StateDb::open(&dir).expect("open test db");
        torus_state::running_hash::configure_activation(&db, Some(1))
            .expect("configure running hash activation");
        (dir, db)
    }

    /// R02 branch 2 driver, serial and pipelined. Control: `blocks` on a
    /// fresh DB (`setup` seeds it), then `check` on the result. Fault: the
    /// same chain with `fault` injected into the LAST block. That block must
    /// fail-stop: `exec_failed`, the applied marker at the previous height,
    /// every CF exactly as before the block (nothing flushed, so nothing of
    /// the block executed). Restart: close and reopen the DB, replay with a
    /// fresh context and no fault; every CF, so also the applied marker and
    /// the running state hash (CF_CONSENSUS_META), equals the control.
    fn r02_assert_fault_fail_stops_then_replays(
        blocks: &[TorusBlock],
        setup: &dyn Fn(&StateDb),
        fault: ReplayFault,
        check: &dyn Fn(&StateDb),
    ) {
        let (last, prefix) = blocks.split_last().expect("at least one block");
        let top = last.header.height;
        for on in [false, true] {
            let (_c, db_ref) = make_test_config_and_db();
            setup(&db_ref);
            let ctx = pipeline_ctx(&db_ref, on, None);
            for b in blocks {
                dispatch_and_execute(&ctx, &db_ref, b);
            }
            assert!(ctx.pipeline_barrier(), "on={on}");
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "on={on}: control");
            drop(ctx);
            assert_eq!(read_native_applied_height(&db_ref), Some(top), "on={on}");
            check(&db_ref);

            let (dir, db) = r02_reopenable_db();
            setup(&db);
            let mut ctx = pipeline_ctx(&db, on, None);
            for b in prefix {
                dispatch_and_execute(&ctx, &db, b);
            }
            assert!(ctx.pipeline_barrier(), "on={on}");
            let durable = persist_committed_block_durably(&db, last);
            let before = dump_all_cfs(&db);
            ctx.test_replay_fault = Some(fault);
            ctx.execute_committed_block_with(last, vec![], durable);
            ctx.pipeline_barrier();
            assert!(
                ctx.exec_failed.load(Ordering::SeqCst),
                "on={on} {fault:?}: must fail-stop"
            );
            drop(ctx);
            assert_eq!(
                read_native_applied_height(&db),
                prefix.last().map(|b| b.header.height),
                "on={on} {fault:?}: the faulted block is not applied"
            );
            assert_dumps_equal(
                &before,
                &dump_all_cfs(&db),
                "R02: nothing of the block flushed",
            );

            // Restart: reopen, replay the faulted height without the fault.
            drop(db);
            let db = StateDb::open(&dir).expect("reopen");
            let ctx = pipeline_ctx(&db, false, None);
            let (_last, parked) = TorusApp::replay_committed(&db, &ctx);
            assert_eq!(parked, None);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "on={on}: replay");
            drop(ctx);
            assert_eq!(read_native_applied_height(&db), Some(top), "on={on}");
            assert_dumps_equal(
                &dump_all_cfs(&db_ref),
                &dump_all_cfs(&db),
                "R02: restart replay vs no fault",
            );
        }
    }

    /// The `ClaimRewards` action R02 branch 2 replays: `nonce` is in the
    /// window of every `make_block` height used here.
    fn r02_claim(nonce: u64) -> SignedNativeAction {
        let key = k256::ecdsa::SigningKey::from_slice(&[0x52; 32]).unwrap();
        torus_types::eip712::sign_native_action(NativeAction::ClaimRewards, nonce, &key)
    }

    fn r02_nonce_consumed(db: &StateDb, signed: &SignedNativeAction) -> bool {
        let key =
            torus_state::cf::native_nonce_key(&signed.recover_sender().unwrap(), signed.nonce);
        db.get_cf_raw(torus_state::cf::CF_NATIVE_NONCES, &key)
            .unwrap()
            .is_some()
    }

    /// R02 (audit option A, branch 2; the audit's P0 example): a replay-guard
    /// read of CF_NATIVE_NONCES that fails fail-stops the block. RED before:
    /// `.unwrap_or(None)` read the error as "not consumed", so block 2's
    /// replay of `a` (consumed in block 1) executed a second time. Control:
    /// without a fault the consumed nonce still rejects the replay and the
    /// fresh `b` executes.
    #[test]
    fn r02_nonce_read_fault_fail_stops_block() {
        let ms = block_time_ms(1);
        let (a, b) = (r02_claim(ms), r02_claim(ms + 1));
        let mut blocks = vec![
            make_block(1, vec![a.clone()]),
            make_block(2, vec![a, b.clone()]),
        ];
        link_blocks(&mut blocks);
        r02_assert_fault_fail_stops_then_replays(&blocks, &|_| {}, ReplayFault::NonceRead, &|db| {
            assert_eq!(
                action_status(db, 2).expect("block 2 record").native_skipped,
                vec![true, false],
                "the replayed `a` is skipped, the fresh `b` executes"
            );
            assert!(r02_nonce_consumed(db, &b));
        });
    }

    /// R02 branch 2: a failed CF_NATIVE_NONCES put fail-stops the block. The
    /// put goes into the block's overlay, which fails only on an unregistered
    /// CF or a frozen overlay (a code bug), but a lost nonce row would let the
    /// action replay later, so it is fatal, never ignored. RED before:
    /// `let _ =` dropped the error and the block flushed without the row.
    #[test]
    fn r02_nonce_put_fault_fail_stops_block() {
        let a = r02_claim(block_time_ms(1));
        let blocks = [make_block(1, vec![a.clone()])];
        r02_assert_fault_fail_stops_then_replays(&blocks, &|_| {}, ReplayFault::NoncePut, &|db| {
            assert_eq!(
                action_status(db, 1).expect("record").native_skipped,
                vec![false]
            );
            assert!(r02_nonce_consumed(db, &a));
        });
    }

    /// R02 (audit option A, branch 2): a session read that fails in the
    /// batch-verify callback fail-stops the block. RED before: `.ok().flatten()`
    /// turned the error into "no session" and the action was dropped (the
    /// block flushed with it skipped). Control: with the session present it
    /// executes; with no session row it is still dropped, no fail-stop.
    #[test]
    fn r02_session_read_fault_fail_stops_block() {
        let session_key = ed25519_dalek::SigningKey::from_bytes(&[0x53; 32]);
        let ms = block_time_ms(1);
        let block = make_block(
            1,
            vec![torus_types::eip712::sign_native_action_with_session(
                NativeAction::CancelOrder { order_id: 1 },
                ms,
                &session_key,
            )],
        );
        let put_session = |db: &StateDb| {
            db.put_session(
                &session_key.verifying_key().to_bytes(),
                &torus_types::SessionData {
                    owner: Address::new([0x53; 20]),
                    expiry: ms + 60_000,
                    scope: torus_types::SessionScope::Trading,
                    created_at: 0,
                },
            )
            .unwrap();
        };
        r02_assert_fault_fail_stops_then_replays(
            std::slice::from_ref(&block),
            &put_session,
            ReplayFault::SessionRead,
            &|db| {
                assert_eq!(
                    action_status(db, 1).expect("record").native_skipped,
                    vec![false]
                );
            },
        );
        // Control: a missing session is ordinary state — dropped, no fail-stop.
        for on in [false, true] {
            let (_c, db) = make_test_config_and_db();
            let ctx = pipeline_ctx(&db, on, None);
            dispatch_and_execute(&ctx, &db, &block);
            assert!(ctx.pipeline_barrier());
            assert!(
                !ctx.exec_failed.load(Ordering::SeqCst),
                "on={on}: no fail-stop"
            );
            drop(ctx);
            assert_eq!(read_native_applied_height(&db), Some(1));
            assert_eq!(
                action_status(&db, 1).expect("record").native_skipped,
                vec![true]
            );
        }
    }

    /// R02 branch 2: the "already applied?" check reads the durable marker; a
    /// failed read fail-stops instead of re-executing. RED before: the error
    /// read as "nothing applied" and the serial path executed block 1 again.
    /// Control: the re-delivery without a fault is skipped, no fail-stop.
    /// Restart (reopen) lands the control state.
    #[test]
    fn r02_applied_height_read_fault_on_redelivery_fail_stops() {
        let block = make_block(1, vec![r02_claim(block_time_ms(1))]);
        for on in [false, true] {
            let (_c, db_ref) = make_test_config_and_db();
            let ctx = pipeline_ctx(&db_ref, on, None);
            dispatch_and_execute(&ctx, &db_ref, &block);
            dispatch_and_execute(&ctx, &db_ref, &block);
            assert!(ctx.pipeline_barrier());
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "on={on}: control");
            drop(ctx);

            let (dir, db) = r02_reopenable_db();
            let mut ctx = pipeline_ctx(&db, on, None);
            dispatch_and_execute(&ctx, &db, &block);
            assert!(ctx.pipeline_barrier());
            let durable = persist_committed_block_durably(&db, &block);
            let before = dump_all_cfs(&db);
            ctx.test_replay_fault = Some(ReplayFault::AppliedRead);
            ctx.execute_committed_block_with(&block, vec![], durable);
            ctx.pipeline_barrier();
            assert!(
                ctx.exec_failed.load(Ordering::SeqCst),
                "on={on}: must fail-stop"
            );
            drop(ctx);
            assert_dumps_equal(&before, &dump_all_cfs(&db), "R02: no re-execution");

            drop(db);
            let db = StateDb::open(&dir).expect("reopen");
            let ctx = pipeline_ctx(&db, false, None);
            let (_last, parked) = TorusApp::replay_committed(&db, &ctx);
            assert_eq!(parked, None);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst));
            drop(ctx);
            assert_eq!(read_native_applied_height(&db), Some(1), "on={on}");
            assert_dumps_equal(
                &dump_all_cfs(&db_ref),
                &dump_all_cfs(&db),
                "R02: restart vs no fault",
            );
        }
    }

    /// R02 branch 2: boot replay reads the marker to find the gap; a failed
    /// read fail-stops instead of replaying from height 1. RED before: the
    /// error read as height 0 and every committed block executed again. The
    /// next boot (no fault) finds no gap and the state is untouched.
    #[test]
    fn r02_applied_height_read_fault_at_boot_replay_fail_stops() {
        let ms = block_time_ms(1);
        let mut blocks = vec![
            make_block(1, vec![r02_claim(ms)]),
            make_block(2, vec![r02_claim(ms + 1)]),
        ];
        link_blocks(&mut blocks);
        let (dir, db) = r02_reopenable_db();
        let ctx = pipeline_ctx(&db, false, None);
        for b in &blocks {
            dispatch_and_execute(&ctx, &db, b);
        }
        drop(ctx);
        let before = dump_all_cfs(&db);
        let mut ctx = pipeline_ctx(&db, false, None);
        ctx.test_replay_fault = Some(ReplayFault::AppliedRead);
        let (_last, parked) = TorusApp::replay_committed(&db, &ctx);
        assert_eq!(parked, None);
        assert!(ctx.exec_failed.load(Ordering::SeqCst), "must fail-stop");
        drop(ctx);
        assert_dumps_equal(&before, &dump_all_cfs(&db), "R02: nothing replayed");

        drop(db);
        let db = StateDb::open(&dir).expect("reopen");
        let ctx = pipeline_ctx(&db, false, None);
        let _ = TorusApp::replay_committed(&db, &ctx);
        assert!(!ctx.exec_failed.load(Ordering::SeqCst));
        drop(ctx);
        assert_eq!(read_native_applied_height(&db), Some(2));
        assert_dumps_equal(&before, &dump_all_cfs(&db), "R02: restart finds no gap");
    }

    /// R02 branch 2: the flush worker is seeded from the marker; a failed
    /// read fail-stops and attaches no worker. RED before: it attached with
    /// durable height 0.
    #[test]
    fn r02_applied_height_read_fault_at_worker_attach_fail_stops() {
        let (_c, db) = make_test_config_and_db();
        let (config, _) = make_test_config_and_db();
        let mut ctx = make_exec_ctx(&config, &db);
        ctx.test_replay_fault = Some(ReplayFault::AppliedRead);
        ctx.attach_flush_worker(None);
        assert!(ctx.exec_failed.load(Ordering::SeqCst), "must fail-stop");
        assert!(ctx.flush_worker.is_none(), "no worker on a guessed height");
    }

    /// R02 branch 2: `exec_next_height` is seeded from the marker on the
    /// first commit; a failed read fail-stops (nothing seeded, nothing sent,
    /// nothing written) instead of seeding at the incoming height. RED before:
    /// the error read as "nothing applied" and the block was dispatched with
    /// the frontier seeded there. Restart: a reopened node executes the block
    /// and lands exactly the state of a node that never faulted.
    #[test]
    fn r02_applied_height_read_fault_at_exec_seed_fail_stops() {
        let block = make_block(1, vec![r02_claim(block_time_ms(1))]);
        // Control: a node that never faulted.
        let (_d, db_ref) = r02_reopenable_db();
        let mut app = TorusApp::stub_on(db_ref.clone());
        app.enqueue_for_execution(1, ExecSource::Ready(block.clone()), vec![]);
        assert_eq!(app.exec_next_height, Some(2));
        drop(app); // joins the execution thread
        assert_eq!(read_native_applied_height(&db_ref), Some(1));

        for via_commit_guard in [false, true] {
            let (dir, db) = r02_reopenable_db();
            let mut app = TorusApp::stub_on(db.clone());
            let before = dump_all_cfs(&db);
            app.test_applied_read_fault = true;
            if via_commit_guard {
                // `on_committed_block`'s re-delivery guard seeds the same way.
                assert_eq!(app.exec_next_height_or_seed(1), None);
            } else {
                app.enqueue_for_execution(1, ExecSource::Ready(block.clone()), vec![]);
            }
            assert!(app.is_exec_failed(), "must fail-stop");
            assert_eq!(app.exec_next_height, None, "nothing seeded");
            drop(app); // joins the execution thread
            assert_dumps_equal(
                &before,
                &dump_all_cfs(&db),
                "R02: nothing dispatched or written",
            );
            drop(db);

            let db = StateDb::open(&dir).expect("reopen");
            let mut app = TorusApp::stub_on(db.clone());
            app.enqueue_for_execution(1, ExecSource::Ready(block.clone()), vec![]);
            drop(app);
            assert_eq!(read_native_applied_height(&db), Some(1));
            assert_dumps_equal(
                &dump_all_cfs(&db_ref),
                &dump_all_cfs(&db),
                "R02: restart vs no fault",
            );
        }
    }

    /// R02 branch 2: the epoch-plan check reads the marker; a failed read is
    /// EpochPlanNotReady (refuse the boundary block for now: liveness only),
    /// never "applied = 0". RED before: at the first boundary (needed = 0)
    /// the error passed as applied 0 and the plan was used.
    #[test]
    fn r02_applied_height_read_fault_epoch_plan_not_ready() {
        let mut app = TorusApp::stub();
        let boundary = app.epoch_length;
        assert!(app.epoch_validator_set_updates(boundary).is_ok(), "control");
        app.cached_vs_updates = None;
        app.test_applied_read_fault = true;
        assert!(app.epoch_validator_set_updates(boundary).is_err());
    }

    /// R02 branch 3: a local fault recorded by a reader without `&mut ctx`
    /// (`AccountReader::mark` / `price_band`: the oracle aggregate read
    /// failed; torus-bridge `r02_oracle_marks_tests` shows the real reads
    /// land there) fail-stops the block like `fatal_error`: the committer's
    /// checks use `take_fatal_error`. RED before: the checks read
    /// `fatal_error` only, so the block flushed on the reader's "no mark".
    #[test]
    fn r02_oracle_reader_fault_fail_stops_block() {
        let ms = block_time_ms(1);
        let (a, b) = (r02_claim(ms), r02_claim(ms + 1));
        let mut blocks = vec![make_block(1, vec![a.clone()]), make_block(2, vec![b.clone()])];
        link_blocks(&mut blocks);
        r02_assert_fault_fail_stops_then_replays(
            &blocks,
            &|_| {},
            ReplayFault::OracleReaderFault,
            &|db| {
                assert!(r02_nonce_consumed(db, &a));
                assert!(r02_nonce_consumed(db, &b));
            },
        );
    }

    /// R02 branch 3: an oracle aggregate row that does not decode on this
    /// node (a delisted market's: only the block mark table reads it) is a
    /// local fault: the block fail-stops (exec_failed, marker unchanged,
    /// nothing flushed). Once the row is repaired, the restart's replay
    /// matches a run that never had it. RED before: the row read as "no
    /// mark" and the block flushed.
    #[test]
    fn r02_undecodable_oracle_aggregate_fail_stops_block() {
        use torus_state::cf::CF_NATIVE_ORACLE;
        let garbage_key = [b"agg".as_slice(), &7u64.to_be_bytes()].concat();
        let ms = block_time_ms(1);
        let (a, b) = (r02_claim(ms), r02_claim(ms + 1));
        let mut blocks = vec![make_block(1, vec![a]), make_block(2, vec![b])];
        link_blocks(&mut blocks);
        for on in [false, true] {
            let (_c, db_ref) = make_test_config_and_db();
            let ctx = pipeline_ctx(&db_ref, on, None);
            for blk in &blocks {
                dispatch_and_execute(&ctx, &db_ref, blk);
            }
            assert!(ctx.pipeline_barrier(), "on={on}");
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "on={on}: control");
            drop(ctx);
            assert_eq!(read_native_applied_height(&db_ref), Some(2), "on={on}");

            let (dir, db) = r02_reopenable_db();
            let ctx = pipeline_ctx(&db, on, None);
            dispatch_and_execute(&ctx, &db, &blocks[0]);
            assert!(ctx.pipeline_barrier(), "on={on}");
            drop(ctx);
            // The row goes bad on disk; a fresh context (as after a
            // restart) reads it (the resident rows are built from the DB).
            db.put_cf_raw(CF_NATIVE_ORACLE, &garbage_key, b"garbage").unwrap();
            let ctx = pipeline_ctx(&db, on, None);
            let durable = persist_committed_block_durably(&db, &blocks[1]);
            let before = dump_all_cfs(&db);
            ctx.execute_committed_block_with(&blocks[1], vec![], durable);
            ctx.pipeline_barrier();
            assert!(ctx.exec_failed.load(Ordering::SeqCst), "on={on}: must fail-stop");
            drop(ctx);
            assert_eq!(read_native_applied_height(&db), Some(1), "on={on}: block 2 not applied");
            assert_dumps_equal(&before, &dump_all_cfs(&db), "R02: nothing of block 2 flushed");

            // Repair the row, restart, replay block 2.
            db.delete_cf_raw(CF_NATIVE_ORACLE, &garbage_key).unwrap();
            drop(db);
            let db = StateDb::open(&dir).expect("reopen");
            let ctx = pipeline_ctx(&db, false, None);
            let (_last, parked) = TorusApp::replay_committed(&db, &ctx);
            assert_eq!(parked, None);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "on={on}: replay");
            drop(ctx);
            assert_eq!(read_native_applied_height(&db), Some(2), "on={on}");
            assert_dumps_equal(&dump_all_cfs(&db_ref), &dump_all_cfs(&db), "R02: replay vs no fault");
        }
    }

    /// Item 6 C1, P6: crash between E's hand-off and W's write with R on —
    /// block 3 ran on R carried from block 1 (advanced over the empty 2) on
    /// top of pending(2); W's write of 2 fails, nothing of 2/3 is durable,
    /// R is not stashed. A restarted node (fresh holder: R rebuilt cold)
    /// replays 2 and 3 and lands exactly the state of a run without R.
    #[test]
    fn resident_rows_crash_between_handoff_and_write_restart_identical() {
        let blocks = pipeline_fixture_blocks();
        let first3 = &blocks[..3];

        let (_c0, db_ref) = make_test_config_and_db();
        fund_pipeline_fixture(&db_ref);
        let mut ctx_ref = pipeline_ctx(&db_ref, false, None);
        ctx_ref.test_no_resident_rows = true;
        for b in first3 {
            dispatch_and_execute(&ctx_ref, &db_ref, b);
        }
        drop(ctx_ref);
        let dump_ref = dump_all_cfs(&db_ref);

        let (_c1, state_db) = make_test_config_and_db();
        fund_pipeline_fixture(&state_db);
        let gate = crate::exec_pipeline::WorkerGate::new();
        let ctx = pipeline_ctx(&state_db, true, Some(gate.clone()));
        dispatch_and_execute(&ctx, &state_db, &first3[0]);
        assert!(ctx.flush_worker.as_ref().unwrap().wait_idle());
        assert_eq!(ctx.resident_books.lock().unwrap().rows_height(), Some(1));

        gate.hold();
        dispatch_and_execute(&ctx, &state_db, &first3[1]); // empty: Marker(2) parked, R advanced
        assert!(gate.wait_received(2));
        assert_eq!(ctx.resident_books.lock().unwrap().rows_height(), Some(2));
        let db_t = state_db.clone();
        let b3 = first3[2].clone();
        let t = std::thread::spawn(move || {
            dispatch_and_execute(&ctx, &db_t, &b3); // engine(3) on R + pending(2); hand-off blocks
            ctx
        });
        std::thread::sleep(std::time::Duration::from_millis(200));
        assert!(!t.is_finished());
        gate.fail_next();
        gate.release();
        let ctx = t.join().unwrap();
        assert!(ctx.exec_failed.load(Ordering::SeqCst));
        {
            let mut holder = ctx.resident_books.lock().unwrap();
            assert_eq!(holder.rows_builds(), 1, "block 3 reused R (no rebuild)");
            assert_eq!(holder.rows_height(), None, "failed hand-off: R not stashed");
        }
        drop(ctx);
        assert_eq!(read_native_applied_height(&state_db), Some(1), "nothing of 2/3 durable");

        let ctx2 = pipeline_ctx(&state_db, false, None);
        let (_last, parked) = TorusApp::replay_committed(&state_db, &ctx2);
        assert_eq!(parked, None);
        assert!(!ctx2.exec_failed.load(Ordering::SeqCst));
        assert_resident_rows_track_db(&ctx2, &state_db, 3, "after the replay");
        assert_eq!(ctx2.resident_books.lock().unwrap().rows_builds(), 1, "restart: R built cold once");
        drop(ctx2);
        assert_dumps_equal(&dump_ref, &dump_all_cfs(&state_db), "crash + restart with R vs serial without R");
    }

    // ======================================================================
    // Item 6 Phase 1 C5 (plan Step 5, P5): warm == cold
    // ======================================================================

    /// Blocks fed, epoch length (boundaries at 50 / 100 / 150 / 200) and the
    /// restart period of the cold replica (7 does not divide 50).
    const C5_BLOCKS: u64 = 210;
    const C5_EPOCH: u64 = 50;
    const C5_RESTART_EVERY: u64 = 7;
    const C5_MARKETS: [u64; 3] = [1, 2, 3];
    /// Traders (signing-key seeds): 81 / 82 also move funds EVM <-> perp,
    /// 84 is thin (margin cuts). Makers quote every market.
    const C5_TRADERS: [u8; 6] = [81, 82, 83, 84, 85, 86];
    const C5_MAKERS: [u8; 2] = [89, 90];
    /// Seeded before block 1: V1 long 10 @100 in market 1 (collateral 40),
    /// V2 short 10 @100 in market 2 (collateral 60): backstop after the
    /// shocks; V3 long 1,100 @100 in market 3 (collateral 6,200; notional
    /// over the chunk threshold, MM 5,500 at 100): stage 1 on the walk, 20%
    /// chunks into bids far thinner than its size (cooldown and pending
    /// rows); S their counterparty.
    const C5_V1: u8 = 91;
    const C5_V2: u8 = 93;
    const C5_V3: u8 = 94;
    const C5_S: u8 = 92;
    const C5_EVM_FUNDING: u128 = 10_000;

    /// splitmix64: the generator's only source of variety (fixed seed, no clock).
    struct C5Rng(u64);

    impl C5Rng {
        fn next(&mut self) -> u64 {
            self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
            let mut z = self.0;
            z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
            z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
            z ^ (z >> 31)
        }

        fn below(&mut self, n: u64) -> u64 {
            self.next() % n
        }
    }

    /// 3 Active oracle validators; market 1 a placeholder row (no margin
    /// config / shape: defaults), markets 2 and 3 governance-layout rows
    /// (lot 0.001, tick 0.01, initial margin 5% / 10%); traders, makers and
    /// the seeded thin positions funded; 81 / 82 hold EVM balance.
    fn c5_fixture() -> (ChainConfig, StateDb) {
        use torus_core::position::{MarginType, NativeBalance, PositionManager};
        let (mut config, db) = make_test_config_and_db();
        config.epoch_length = C5_EPOCH;
        for (seed, mult) in ORACLE_VALIDATORS {
            oracle_put_validator(&db, seed, mult, torus_economics::ValidatorStatus::Active);
        }
        db.put_cf_raw(torus_state::cf::CF_NATIVE_MARKETS, &1u64.to_be_bytes(), b"listed").unwrap();
        for (m, im) in [(2u64, 5i64), (3, 10)] {
            let row = (
                "BTC".to_string(),
                "USDC".to_string(),
                FixedPoint::SCALE / 1_000,
                FixedPoint::SCALE / 100,
                px(im).raw(),
            );
            db.put_cf_raw(torus_state::cf::CF_NATIVE_MARKETS, &m.to_be_bytes(), &borsh::to_vec(&row).unwrap())
                .unwrap();
        }
        let pm = PositionManager::new(db.clone());
        let fund = |seed: u8, amt: i64| {
            pm.put_native_balance(&oracle_addr(seed), &NativeBalance { available: px(amt), order_margin: FixedPoint::ZERO })
                .unwrap()
        };
        for (i, seed) in C5_TRADERS.into_iter().enumerate() {
            fund(seed, if seed == 84 { 150 } else { 3_000 + 1_000 * i as i64 });
        }
        for seed in C5_MAKERS.into_iter().chain([C5_S]) {
            fund(seed, 1_000_000);
        }
        fund(C5_V1, 40);
        fund(C5_V2, 60);
        fund(C5_V3, 6_200);
        let (v1, v2, s) = (oracle_addr(C5_V1), oracle_addr(C5_V2), oracle_addr(C5_S));
        pm.apply_fill(&v1, 1, true, px(10), px(100), MarginType::Cross).unwrap();
        pm.apply_fill(&s, 1, false, px(10), px(100), MarginType::Cross).unwrap();
        pm.apply_fill(&v2, 2, false, px(10), px(100), MarginType::Cross).unwrap();
        pm.apply_fill(&s, 2, true, px(10), px(100), MarginType::Cross).unwrap();
        pm.apply_fill(&oracle_addr(C5_V3), 3, true, px(1_100), px(100), MarginType::Cross).unwrap();
        pm.apply_fill(&s, 3, false, px(1_100), px(100), MarginType::Cross).unwrap();
        for seed in [81u8, 82] {
            fund_evm_balance(&db, oracle_addr(seed), U256::from(C5_EVM_FUNDING * FixedPoint::ONE.raw() as u128));
        }
        (config, db)
    }

    /// What the generator fed (non-vacuity of the input side).
    #[derive(Debug, Default)]
    struct C5Fed {
        empty: u64,
        mark_rounds: u64,
        non_pool_sell_batches: u64,
        cancels: u64,
        transfers: u64,
    }

    /// The P5 sequence: heights 1..=C5_BLOCKS (ts 1000 + h), linked. Oracle
    /// rounds (all 3 validators, all 3 markets) every 5th block plus at
    /// random, marks walking +-2 per round with two shocks (market 1 -15% at
    /// 60: V1 under water; market 2 +18% at 120: V2); a maker requoting
    /// every market each non-empty block (cancel-all every 6th); 1-3 trader
    /// actions: resting limits, crossing limits, two-market sell batches
    /// crossing the bid (the second is a non-pool sell: B-blind top-up),
    /// cancel-alls, EVM <-> perp transfers; ~1/5 of the other blocks empty.
    fn c5_blocks() -> (Vec<TorusBlock>, C5Fed) {
        let mut rng = C5Rng(0xC5_0005);
        let mut fed = C5Fed::default();
        let mut mark = [100i64; 3];
        let mut nonces: std::collections::HashMap<u8, u64> = Default::default();
        // The height being built: nonces sit at its block time (exec's window).
        let cur_h = std::cell::Cell::new(0u64);
        let mut sign = |seed: u8, action: NativeAction| {
            let n = nonces.entry(seed).or_insert(0);
            *n += 1;
            let nonce = NONCE_BASE + cur_h.get() * 1_000 + *n;
            torus_types::eip712::sign_native_action(action, nonce, &oracle_key(seed))
        };
        let order = |m: u64, is_buy: bool, price: i64, qty: i64| torus_types::PlaceOrderParams {
            market_id: m,
            is_buy,
            price: px(price),
            quantity: px(qty),
            order_type: torus_types::OrderType::Limit,
            time_in_force: torus_types::TimeInForce::GTC,
            reduce_only: false,
            client_order_id: None,
        };
        let units = |v: u128| U256::from(v * FixedPoint::ONE.raw() as u128);
        let mut blocks = Vec::new();
        for h in 1..=C5_BLOCKS {
            cur_h.set(h);
            let mut actions = Vec::new();
            let shock = h == 60 || h == 120;
            let mark_round = h == 1 || h % 5 == 1 || shock || rng.below(4) == 0;
            if mark_round {
                fed.mark_rounds += 1;
                match h {
                    1 => {}
                    60 => mark[0] = mark[0] * 85 / 100,
                    120 => mark[1] = mark[1] * 118 / 100,
                    _ => {
                        for p in &mut mark {
                            *p = (*p + rng.below(5) as i64 - 2).max(50);
                        }
                    }
                }
                for (seed, _) in ORACLE_VALIDATORS {
                    let prices = C5_MARKETS.iter().zip(mark).map(|(m, p)| (*m, px(p))).collect();
                    actions.push(torus_types::eip712::sign_native_action(
                        NativeAction::SubmitOraclePrices(torus_types::OracleSubmission {
                            prices,
                            timestamp: (1_000 + h) * 1_000,
                        }),
                        NONCE_BASE + h * 1_000 + seed as u64,
                        &oracle_key(seed),
                    ));
                }
            }
            if !mark_round && rng.below(5) == 0 {
                fed.empty += 1;
                blocks.push(make_block(h, actions));
                continue;
            }
            let maker = C5_MAKERS[(h % 2) as usize];
            if h % 6 == 0 {
                actions.push(sign(maker, NativeAction::CancelAllOrders { market_id: None }));
                fed.cancels += 1;
            }
            let mut quotes = Vec::new();
            for (i, m) in C5_MARKETS.into_iter().enumerate() {
                let q = 2 + rng.below(4) as i64;
                quotes.push(order(m, true, mark[i] - 1 - rng.below(2) as i64, q));
                quotes.push(order(m, false, mark[i] + 1 + rng.below(2) as i64, q));
            }
            actions.push(sign(maker, NativeAction::PlaceOrderBatch(quotes)));
            for _ in 0..1 + rng.below(3) {
                let t = C5_TRADERS[rng.below(C5_TRADERS.len() as u64) as usize];
                let mi = rng.below(3) as usize;
                let (m, p) = (C5_MARKETS[mi], mark[mi]);
                let qty = 1 + rng.below(4) as i64;
                let action = match rng.below(10) {
                    0..=3 => {
                        let is_buy = rng.below(2) == 0;
                        let off = 1 + rng.below(3) as i64;
                        NativeAction::PlaceOrder(order(m, is_buy, if is_buy { p - off } else { p + off }, qty))
                    }
                    4 | 5 => {
                        let is_buy = rng.below(2) == 0;
                        NativeAction::PlaceOrder(order(m, is_buy, if is_buy { p + 2 } else { p - 2 }, qty))
                    }
                    6 => {
                        let mj = (mi + 1 + rng.below(2) as usize) % 3;
                        fed.non_pool_sell_batches += 1;
                        NativeAction::PlaceOrderBatch(vec![
                            order(m, false, p - 2, qty),
                            order(C5_MARKETS[mj], false, mark[mj] - 2, qty),
                        ])
                    }
                    7 => {
                        fed.cancels += 1;
                        NativeAction::CancelAllOrders { market_id: (rng.below(2) == 0).then_some(m) }
                    }
                    8 if t == 81 || t == 82 => {
                        fed.transfers += 1;
                        if rng.below(2) == 0 {
                            NativeAction::TransferToPerp { amount: units(100) }
                        } else {
                            NativeAction::TransferToSpot { amount: units(50) }
                        }
                    }
                    _ => {
                        let mj = (mi + 1) % 3;
                        NativeAction::PlaceOrderBatch(vec![
                            order(m, true, p - 1 - rng.below(3) as i64, qty),
                            order(C5_MARKETS[mj], false, mark[mj] + 1 + rng.below(3) as i64, qty),
                        ])
                    }
                };
                actions.push(sign(t, action));
            }
            blocks.push(make_block(h, actions));
        }
        link_blocks(&mut blocks);
        (blocks, fed)
    }

    #[derive(Clone, Copy, Debug, PartialEq)]
    enum C5Replica {
        /// One context for every block.
        Warm,
        /// Context dropped and recreated after every `C5_RESTART_EVERY`th
        /// block: R, its decoded positions, the sums cache and the books
        /// rebuilt cold.
        Restarted,
        /// One context; the sums cache emptied before every block.
        SumsDropped,
    }

    struct C5Run {
        db: StateDb,
        dump: Vec<CfDump>,
        captured: CapturedWrites,
        hash: Option<(u64, [u8; 32])>,
        builds: u64,
        restarts: u64,
        sums_dropped: usize,
        r_rows: usize,
        /// Blocks after which an oracle mark price differed from the block before.
        mark_moves: u64,
        mark_moves_after_last_epoch: u64,
        /// Blocks after which `CF_NATIVE_LIQUIDATION` held cooldown / pending rows.
        liq_row_blocks: u64,
        metrics: Arc<torus_telemetry::Metrics>,
    }

    /// Feed `blocks` through the committed-block path on a fresh
    /// `c5_fixture` DB as `replica`. After every block: no fail-stop, R ==
    /// the DB scan of its CFs and decoded positions == a cold decode
    /// (`assert_resident_rows_track_db`; a restarted context has no R until
    /// its first native block), no shared fallback.
    fn c5_run(
        blocks: &[TorusBlock],
        replica: C5Replica,
        pipelined: bool,
        mode: Option<torus_bridge::native_executor::BookMode>,
    ) -> C5Run {
        use torus_state::cf::{CF_NATIVE_LIQUIDATION, CF_NATIVE_ORACLE};
        let (config, db) = c5_fixture();
        torus_state::running_hash::capture_begin(&db);
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        let what = format!("{replica:?} pipelined={pipelined} {mode:?}");
        let new_ctx = || {
            let mut c = make_exec_ctx(&config, &db);
            c.test_book_mode = mode;
            c.metrics = Some(metrics.clone());
            if pipelined {
                c.attach_flush_worker(None);
            }
            c
        };
        let mark_prices = |db: &StateDb| -> Vec<(Vec<u8>, Vec<u8>)> {
            StateBackend::iterate_cf(db, CF_NATIVE_ORACLE, Some(b"agg"))
                .unwrap()
                .into_iter()
                .map(|(k, v)| (k, v[..16].to_vec()))
                .collect()
        };
        let mut ctx = new_ctx();
        let (mut builds, mut restarts, mut sums_dropped) = (0, 0, 0);
        let (mut mark_moves, mut mark_moves_after_last_epoch, mut liq_row_blocks) = (0, 0, 0);
        let mut prev_marks = Vec::new();
        let last = blocks.last().expect("blocks").header.height;
        for b in blocks {
            let h = b.header.height;
            if replica == C5Replica::SumsDropped {
                sums_dropped += ctx.resident_books.lock().unwrap().drop_sums_cache();
            }
            dispatch_and_execute(&ctx, &db, b);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "{what}: fail-stop at {h}");
            if ctx.resident_books.lock().unwrap().rows_builds() == 0 {
                assert_eq!(replica, C5Replica::Restarted, "{what}: R never built by {h}");
                if let Some(w) = ctx.flush_worker.as_ref() {
                    assert!(w.wait_idle(), "{what}: W failed");
                }
                assert_eq!(ctx.resident_books.lock().unwrap().rows_height(), None, "{what}: {h}");
            } else {
                assert_resident_rows_track_db(&ctx, &db, h, &what);
            }
            assert_eq!(ctx.resident_books.lock().unwrap().rows_shared_fallbacks(), 0, "{what}: {h}");
            let marks = mark_prices(&db);
            if marks != prev_marks {
                mark_moves += 1;
                mark_moves_after_last_epoch += u64::from(h > (last / C5_EPOCH) * C5_EPOCH);
                prev_marks = marks;
            }
            // Cooldown / pending rows: tag + trader (the 9-byte previous-mark rows persist).
            liq_row_blocks += u64::from(
                StateBackend::iterate_cf(&db, CF_NATIVE_LIQUIDATION, None).unwrap().iter().any(|(k, _)| k.len() == 21),
            );
            if replica == C5Replica::Restarted && h % C5_RESTART_EVERY == 0 && h < last {
                builds += ctx.resident_books.lock().unwrap().rows_builds();
                restarts += 1;
                drop(ctx);
                ctx = new_ctx();
            }
        }
        let r_rows = ctx.resident_books.lock().unwrap().rows().map_or(0, |r| r.len());
        builds += ctx.resident_books.lock().unwrap().rows_builds();
        drop(ctx);
        let captured = torus_state::running_hash::capture_take(&db);
        let hash = torus_state::running_hash::read_running_hash(&db);
        let dump = dump_all_cfs(&db);
        C5Run {
            db,
            dump,
            captured,
            hash,
            builds,
            restarts,
            sums_dropped,
            r_rows,
            mark_moves,
            mark_moves_after_last_epoch,
            liq_row_blocks,
            metrics,
        }
    }

    /// Item 6 C5 (plan Step 5, P5): warm == cold in one configuration. The
    /// 210 blocks (4 epoch boundaries) through three replicas, each on its
    /// own DB: warm (one context), restarted every 7 blocks (R, decoded
    /// positions, sums cache, marks and books rebuilt cold) and sums-dropped
    /// (cache emptied before every block). R == DB after every block on
    /// each (`c5_run`); identical per-block consensus write sets (every
    /// `h_n`), running hash and full dump; the sequence is non-vacuous.
    /// Returns the warm run.
    fn c5_warm_equals_cold(pipelined: bool, mode: Option<torus_bridge::native_executor::BookMode>) -> C5Run {
        let started = std::time::Instant::now();
        let what = format!("pipelined={pipelined} {mode:?}");
        let (blocks, fed) = c5_blocks();
        assert_eq!(blocks.len() as u64, C5_BLOCKS);
        let warm = c5_run(&blocks, C5Replica::Warm, pipelined, mode);
        let restarted = c5_run(&blocks, C5Replica::Restarted, pipelined, mode);
        let dropped = c5_run(&blocks, C5Replica::SumsDropped, pipelined, mode);

        assert_eq!((warm.builds, dropped.builds), (1, 1), "{what}: R built once");
        assert_eq!(restarted.restarts, (C5_BLOCKS - 1) / C5_RESTART_EVERY, "{what}");
        assert_eq!(restarted.builds, restarted.restarts + 1, "{what}: one cold build per (re)start");
        assert_eq!(
            warm.captured.iter().map(|(h, _)| *h).collect::<Vec<_>>(),
            (1..=C5_BLOCKS).collect::<Vec<_>>(),
            "{what}: every height through the hashed flush"
        );
        assert!(warm.hash.is_some());
        assert_eq!(warm.hash, Some(fold_captured(&warm.captured)), "{what}");
        for (name, other) in [("restarted", &restarted), ("sums dropped", &dropped)] {
            assert_write_sets_equal(&warm.captured, &other.captured, &format!("{what}: warm vs {name}"));
            assert_eq!(warm.hash, other.hash, "{what}: running hash, warm vs {name}");
            assert_dumps_equal(&warm.dump, &other.dump, &format!("{what}: warm vs {name}"));
        }

        // Non-vacuous (the warm replica; the others equal it).
        let pm = torus_core::position::PositionManager::new(warm.db.clone());
        let fills = StateBackend::iterate_cf(&warm.db, torus_state::cf::CF_NATIVE_TRADES, None).unwrap().len();
        let liquidations = warm.metrics.liquidations_triggered.get();
        let top_ups = warm.metrics.sell_top_ups_full.get() + warm.metrics.sell_top_ups_partial.get();
        let v1 = signed_pos_of(&warm.db, &oracle_addr(C5_V1));
        let v2 = pm.get_position(&oracle_addr(C5_V2), 2).unwrap().map(|p| p.size);
        let v3 = pm.get_position(&oracle_addr(C5_V3), 3).unwrap().map(|p| p.size);
        let funded = U256::from(C5_EVM_FUNDING * FixedPoint::ONE.raw() as u128);
        let evm_moved = [81u8, 82].iter().filter(|&&s| read_evm_balance(&warm.db, oracle_addr(s)) != funded).count();
        println!(
            "C5 {what}: fed {fed:?}; fills {fills}, liquidations {liquidations}, top-ups {top_ups}, \
             mark moves {} ({} after the last epoch boundary), blocks with cooldown / pending rows {}, \
             R rows {}, V1 {v1:?}, V2 {v2:?}, V3 {v3:?}, EVM balances moved {evm_moved}, sums entries dropped {}, \
             restarts {} / builds {}; {:.1} s",
            warm.mark_moves,
            warm.mark_moves_after_last_epoch,
            warm.liq_row_blocks,
            warm.r_rows,
            dropped.sums_dropped,
            restarted.restarts,
            restarted.builds,
            started.elapsed().as_secs_f64(),
        );
        assert!(fed.empty >= 10 && fed.cancels >= 20 && fed.transfers >= 2 && fed.non_pool_sell_batches >= 10, "{fed:?}");
        assert!(fills >= 200, "{what}: fills {fills}");
        assert!(liquidations >= 2, "{what}: liquidations {liquidations}");
        assert!(top_ups >= 20, "{what}: B-blind top-ups {top_ups}");
        assert!(warm.mark_moves >= 50 && warm.mark_moves_after_last_epoch >= 1, "{what}: mark moves");
        assert!(warm.liq_row_blocks >= 1, "{what}: cooldown / pending rows");
        assert!(warm.r_rows >= 30, "{what}: R rows {}", warm.r_rows);
        assert_eq!(v1, FixedPoint::ZERO, "{what}: V1 liquidated");
        assert_eq!(v2, None, "{what}: V2 liquidated");
        assert_ne!(v3, Some(px(1_100)), "{what}: V3 liquidated");
        assert_eq!(evm_moved, 2, "{what}: deposits / withdrawals moved EVM balances");
        assert!(dropped.sums_dropped >= 500, "{what}: the cache held entries ({})", dropped.sums_dropped);
        warm
    }

    #[test]
    fn warm_equals_cold_every_block_serial() {
        c5_warm_equals_cold(false, None);
    }

    /// Also serial == pipelined (one more warm run).
    #[test]
    fn warm_equals_cold_every_block_pipelined() {
        let piped = c5_warm_equals_cold(true, None);
        let serial = c5_run(&c5_blocks().0, C5Replica::Warm, false, None);
        assert_write_sets_equal(&serial.captured, &piped.captured, "serial vs pipelined");
        assert_eq!(serial.hash, piped.hash, "serial vs pipelined");
        assert_dumps_equal(&serial.dump, &piped.dump, "serial vs pipelined");
    }

    #[test]
    fn warm_equals_cold_every_block_pipelined_level_authority_chunked() {
        c5_warm_equals_cold(true, Some(torus_bridge::native_executor::BookMode::LevelAuthorityChunked));
    }

    // ======================================================================
    // Item 6 Phase 2 (plan 9.8): app-level differential of torus-bridge's
    // reference paths (full-scan cancel-all, per-row position flush) against
    // the production paths, through the test-only `test-reference-paths`
    // feature. P2-1 (cancel-all index) and P2-2 (batch flush) keep it green.
    // ======================================================================

    const P2_BLOCKS: u64 = 130;
    /// Seeded long 30 @100 in market 1 (collateral 300): rests bids far
    /// below the mark and a buy stop far above it in markets 2 / 3, never
    /// cancels, and is liquidated later (the walk or the market-1 shock at
    /// 60), so the liquidation step's cancel takes its orders and stops.
    const P2_V4: u8 = 95;

    /// `c5_fixture` plus V4 (above).
    fn p2_fixture() -> (ChainConfig, StateDb) {
        use torus_core::position::{MarginType, NativeBalance, PositionManager};
        let (config, db) = c5_fixture();
        let pm = PositionManager::new(db.clone());
        pm.put_native_balance(
            &oracle_addr(P2_V4),
            &NativeBalance {
                available: px(300),
                order_margin: FixedPoint::ZERO,
            },
        )
        .unwrap();
        pm.apply_fill(
            &oracle_addr(P2_V4),
            1,
            true,
            px(30),
            px(100),
            MarginType::Cross,
        )
        .unwrap();
        pm.apply_fill(
            &oracle_addr(C5_S),
            1,
            false,
            px(30),
            px(100),
            MarginType::Cross,
        )
        .unwrap();
        (config, db)
    }

    /// What the generator fed (non-vacuity of the input side).
    #[derive(Debug, Default)]
    struct P2Fed {
        cancel_all_none: u64,
        cancel_all_some: u64,
        /// A sender's second cancel-all in the same block (same run).
        repeated: u64,
        stops: u64,
        crossing: u64,
        v4_actions: u64,
        cancel_only_blocks: u64,
        /// Reduce-only places (single or in a batch), `p2_blocks(true)` only.
        reduce_only: u64,
    }

    /// The P2 sequence: heights 1..=P2_BLOCKS (ts 1000 + h), linked. C5's
    /// mark walk (oracle rounds every 5th block plus at random, shocks at 60
    /// and 120); every non-empty block a maker requotes every market (its
    /// cancel-all, `None` or `Some(m)`, every 4th block); 2-5 trader actions:
    /// resting and crossing limits (partial fills), stop-markets and
    /// stop-limits near the last trade (some trigger into resting orders),
    /// cancel-alls `None` / `Some(m)` (a block's cancel-alls form one run;
    /// some senders send two), two-market batches; V4 rests early and is
    /// liquidated later; ~1/6 of the other blocks empty, ~1/5 of the rest
    /// cancel-alls only. `ro` (review gap 2): a third of the trader places
    /// (resting, crossing, stops, batch legs) are reduce-only; the crossing
    /// places reduce, close and flip the positions they depend on, the
    /// liquidations close some. The extra draws happen only with `ro`, so
    /// `ro: false` is the original sequence.
    fn p2_blocks(ro: bool) -> (Vec<TorusBlock>, P2Fed) {
        let mut rng = C5Rng(0x9e21_0008);
        let mut fed = P2Fed::default();
        let mut mark = [100i64; 3];
        let mut nonces: std::collections::HashMap<u8, u64> = Default::default();
        let cur_h = std::cell::Cell::new(0u64);
        let mut sign = |seed: u8, action: NativeAction| {
            let n = nonces.entry(seed).or_insert(0);
            *n += 1;
            let nonce = NONCE_BASE + cur_h.get() * 1_000 + *n;
            torus_types::eip712::sign_native_action(action, nonce, &oracle_key(seed))
        };
        let order =
            |m: u64, is_buy: bool, price: i64, qty: i64, order_type: torus_types::OrderType| {
                torus_types::PlaceOrderParams {
                    market_id: m,
                    is_buy,
                    price: px(price),
                    quantity: px(qty),
                    order_type,
                    time_in_force: torus_types::TimeInForce::GTC,
                    reduce_only: false,
                    client_order_id: None,
                }
            };
        let limit = |m: u64, is_buy: bool, price: i64, qty: i64| {
            order(m, is_buy, price, qty, torus_types::OrderType::Limit)
        };
        let mut blocks = Vec::new();
        for h in 1..=P2_BLOCKS {
            cur_h.set(h);
            let mut actions = Vec::new();
            let shock = h == 60 || h == 120;
            let mark_round = h == 1 || h % 5 == 1 || shock || rng.below(4) == 0;
            if mark_round {
                match h {
                    1 => {}
                    60 => mark[0] = mark[0] * 85 / 100,
                    120 => mark[1] = mark[1] * 118 / 100,
                    _ => {
                        for p in &mut mark {
                            *p = (*p + rng.below(5) as i64 - 2).max(50);
                        }
                    }
                }
                for (seed, _) in ORACLE_VALIDATORS {
                    let prices = C5_MARKETS
                        .iter()
                        .zip(mark)
                        .map(|(m, p)| (*m, px(p)))
                        .collect();
                    actions.push(torus_types::eip712::sign_native_action(
                        NativeAction::SubmitOraclePrices(torus_types::OracleSubmission {
                            prices,
                            timestamp: (1_000 + h) * 1_000,
                        }),
                        NONCE_BASE + h * 1_000 + seed as u64,
                        &oracle_key(seed),
                    ));
                }
            }
            if !mark_round && rng.below(6) == 0 {
                blocks.push(make_block(h, actions));
                continue;
            }
            if rng.below(5) == 0 {
                // Cancel-only block: the books these cancel-alls touch are
                // dirty only through them (a missed cancel or dirty mark
                // shows in the CF dump).
                fed.cancel_only_blocks += 1;
                for _ in 0..1 + rng.below(3) {
                    let t = C5_TRADERS[rng.below(C5_TRADERS.len() as u64) as usize];
                    let target = (rng.below(3) == 0).then(|| C5_MARKETS[rng.below(3) as usize]);
                    if target.is_some() {
                        fed.cancel_all_some += 1;
                    } else {
                        fed.cancel_all_none += 1;
                    }
                    actions.push(sign(t, NativeAction::CancelAllOrders { market_id: target }));
                }
                blocks.push(make_block(h, actions));
                continue;
            }
            let maker = C5_MAKERS[(h % 2) as usize];
            match h % 4 {
                0 => {
                    actions.push(sign(
                        maker,
                        NativeAction::CancelAllOrders { market_id: None },
                    ));
                    fed.cancel_all_none += 1;
                }
                2 => {
                    let m = C5_MARKETS[(h / 4 % 3) as usize];
                    actions.push(sign(
                        maker,
                        NativeAction::CancelAllOrders { market_id: Some(m) },
                    ));
                    fed.cancel_all_some += 1;
                }
                _ => {}
            }
            let mut quotes = Vec::new();
            for (i, m) in C5_MARKETS.into_iter().enumerate() {
                let q = 2 + rng.below(4) as i64;
                quotes.push(limit(m, true, mark[i] - 1 - rng.below(2) as i64, q));
                quotes.push(limit(m, false, mark[i] + 1 + rng.below(2) as i64, q));
            }
            actions.push(sign(maker, NativeAction::PlaceOrderBatch(quotes)));
            if (2..=40).contains(&h) && h % 4 == 3 {
                // V4: a bid far below the mark and a buy stop far above it.
                fed.v4_actions += 2;
                actions.push(sign(
                    P2_V4,
                    NativeAction::PlaceOrder(limit(2, true, mark[1] - 30, 1)),
                ));
                let trigger = mark[2] + 40;
                actions.push(sign(
                    P2_V4,
                    NativeAction::PlaceOrder(order(
                        3,
                        true,
                        trigger + 10,
                        1,
                        torus_types::OrderType::StopMarket {
                            trigger: px(trigger),
                        },
                    )),
                ));
            }
            for _ in 0..2 + rng.below(4) {
                let t = C5_TRADERS[rng.below(C5_TRADERS.len() as u64) as usize];
                let mi = rng.below(3) as usize;
                let (m, p) = (C5_MARKETS[mi], mark[mi]);
                let qty = 1 + rng.below(4) as i64;
                let is_buy = rng.below(2) == 0;
                let mut action = match rng.below(13) {
                    0..=2 => {
                        let off = 1 + rng.below(3) as i64;
                        NativeAction::PlaceOrder(limit(
                            m,
                            is_buy,
                            if is_buy { p - off } else { p + off },
                            qty,
                        ))
                    }
                    3..=5 => {
                        // Crossing, larger than one quote: partial fills, the rest rests.
                        fed.crossing += 1;
                        NativeAction::PlaceOrder(limit(
                            m,
                            is_buy,
                            if is_buy { p + 2 } else { p - 2 },
                            qty + 4,
                        ))
                    }
                    6 => {
                        // Stop-limit near the touch: crossing trades fire it, its limit
                        // then rests or fills.
                        fed.stops += 1;
                        let (trigger, lim) = if is_buy {
                            (p + 2, p + 1)
                        } else {
                            (p - 2, p - 1)
                        };
                        NativeAction::PlaceOrder(order(
                            m,
                            is_buy,
                            lim,
                            qty,
                            torus_types::OrderType::StopLimit {
                                trigger: px(trigger),
                                limit: px(lim),
                            },
                        ))
                    }
                    7 => {
                        fed.stops += 1;
                        let trigger = if is_buy { p + 3 } else { p - 3 };
                        let cap = if is_buy { trigger + 10 } else { trigger - 10 };
                        NativeAction::PlaceOrder(order(
                            m,
                            is_buy,
                            cap,
                            qty,
                            torus_types::OrderType::StopMarket {
                                trigger: px(trigger),
                            },
                        ))
                    }
                    8 | 9 => {
                        fed.cancel_all_none += 1;
                        if rng.below(3) == 0 {
                            // The same sender again in the same run.
                            fed.repeated += 1;
                            let again = if rng.below(2) == 0 { None } else { Some(m) };
                            actions
                                .push(sign(t, NativeAction::CancelAllOrders { market_id: again }));
                        }
                        NativeAction::CancelAllOrders { market_id: None }
                    }
                    10 => {
                        fed.cancel_all_some += 1;
                        NativeAction::CancelAllOrders { market_id: Some(m) }
                    }
                    _ => {
                        let mj = (mi + 1) % 3;
                        NativeAction::PlaceOrderBatch(vec![
                            limit(m, true, p - 1 - rng.below(3) as i64, qty),
                            limit(
                                C5_MARKETS[mj],
                                false,
                                mark[mj] + 1 + rng.below(3) as i64,
                                qty,
                            ),
                        ])
                    }
                };
                if ro {
                    let legs = match &mut action {
                        NativeAction::PlaceOrder(p) => std::slice::from_mut(p),
                        NativeAction::PlaceOrderBatch(ps) => ps.as_mut_slice(),
                        _ => &mut [],
                    };
                    for p in legs {
                        if rng.below(3) == 0 {
                            p.reduce_only = true;
                            fed.reduce_only += 1;
                        }
                    }
                }
                actions.push(sign(t, action));
            }
            blocks.push(make_block(h, actions));
        }
        link_blocks(&mut blocks);
        (blocks, fed)
    }

    struct P2Run {
        db: StateDb,
        dump: Vec<CfDump>,
        captured: CapturedWrites,
        hash: Option<(u64, [u8; 32])>,
        metrics: Arc<torus_telemetry::Metrics>,
        /// Classic layout only (else 0): V4's resting orders + pending stops
        /// in markets 2 / 3, the most seen after any block and after the last.
        v4_max: usize,
        v4_last: usize,
        /// P2-1: blocks after which the resident holder carried a built
        /// cancel-all index (checked to cover the books), and restarts.
        index_checked: u64,
        restarts: u64,
        /// Review gap 1: crashes replayed / stale holders put back (`P2Fault`).
        faults: u64,
        /// Review gap 2, classic layout only (else 0): the most resting
        /// reduce-only orders after any block, and how often a position
        /// under resting reduce-only orders was reduced, closed or flipped
        /// by the next block.
        ro_resting_max: usize,
        ro_moved: u64,
    }

    /// P2-1 review (GPT-6.1-sol, gap 1): what `p2_run` does to the node
    /// besides feeding the blocks.
    #[derive(Clone, Debug)]
    enum P2Fault {
        None,
        /// Drop and recreate the context after every n-th block (books, R
        /// and the cancel-all index rebuilt from the DB).
        RestartEvery(u64),
        /// Pipelined only. For each k: W's write of k + 1 fails after E ran
        /// k + 2 on top of it (fail-stop; nothing of k + 1 / k + 2 durable,
        /// E's holder already carries their books and a warm cancel-all
        /// index). A new context that KEEPS that holder replays k + 1 and
        /// k + 2 from the DB (`replay_committed`): the staleness guard must
        /// drop the books and the index (holder ahead of the DB) and rebuild.
        CrashAfter(Vec<u64>),
        /// For each (a, b): after block a the holder (warm index) is taken
        /// out, blocks a + 1 ..= b run without it (the first rebuilds from
        /// the DB), then it is put back: block b + 1 meets a holder stamped a
        /// over the DB at b (holder behind the DB), the staleness guard trips
        /// (height and marker) and rebuilds.
        StaleHolder(Vec<(u64, u64)>),
    }

    /// V4's resting orders + pending stops in the classic book blobs of
    /// markets 2 / 3 (0 in other layouts).
    fn p2_v4_resting(db: &StateDb) -> usize {
        use borsh::BorshDeserialize;
        let v4 = oracle_addr(P2_V4);
        [2u64, 3]
            .iter()
            .filter_map(|m| {
                db.get_cf_raw(torus_state::cf::CF_NATIVE_ORDER_BOOKS, &m.to_be_bytes())
                    .unwrap()
            })
            .filter_map(|bytes| torus_core::order_book::OrderBook::try_from_slice(&bytes).ok())
            .map(|mut book| book.open_order_count(&v4) + book.take_pending_stops(&v4).len())
            .sum()
    }

    /// Review gap 2: (trader, market) -> (signed position, resting
    /// reduce-only orders) from the classic book blobs (empty in other
    /// layouts).
    fn p2_ro_resting(
        db: &StateDb,
    ) -> std::collections::BTreeMap<(Address, u64), (FixedPoint, usize)> {
        use borsh::BorshDeserialize;
        let pm = torus_core::position::PositionManager::new(db.clone());
        let mut out = std::collections::BTreeMap::new();
        for m in C5_MARKETS {
            let Some(bytes) = db
                .get_cf_raw(torus_state::cf::CF_NATIVE_ORDER_BOOKS, &m.to_be_bytes())
                .unwrap()
            else {
                continue;
            };
            let book = torus_core::order_book::OrderBook::try_from_slice(&bytes).unwrap();
            for t in book.reduce_only_traders() {
                let n = book
                    .orders_for_trader(&t)
                    .iter()
                    .filter(|o| o.reduce_only)
                    .count();
                if n > 0 {
                    out.insert((t, m), (p2_signed_position(&pm, &t, m), n));
                }
            }
        }
        out
    }

    fn p2_signed_position(
        pm: &torus_core::position::PositionManager<StateDb>,
        trader: &Address,
        market: u64,
    ) -> FixedPoint {
        match pm.get_position(trader, market).unwrap() {
            Some(p) if p.is_long => p.size,
            Some(p) => -p.size,
            None => FixedPoint::ZERO,
        }
    }

    /// P2-1: the carried cancel-all index (once built) covers the books;
    /// returns whether `ctx`'s holder carried a built index. s104: with
    /// resident books, the index size gauges show the holder's index (0 / 0
    /// while not built).
    fn p2_index_covers_books(ctx: &ExecutionContext, what: &str) -> bool {
        let index = ctx.resident_books.lock().unwrap().trader_index();
        if let (Some((carried, _)), Some(m)) = (&index, ctx.metrics.as_ref()) {
            let (entries, traders) = carried.as_ref().map_or((0, 0), |c| {
                (
                    c.values().map(Vec::len).sum::<usize>() as i64,
                    c.len() as i64,
                )
            });
            assert_eq!(
                (
                    m.exec_cancel_all_index_entries.get(),
                    m.exec_cancel_all_index_traders.get()
                ),
                (entries, traders),
                "{what}: index size gauges"
            );
        }
        let Some((Some(carried), rebuilt)) = index else {
            return false;
        };
        for (trader, markets) in &rebuilt {
            let listed = carried.get(trader).map_or(&[][..], Vec::as_slice);
            for m in markets {
                assert!(
                    listed.binary_search(m).is_ok(),
                    "{what}: {trader} has orders or stops in market {m}, the index lists {listed:?}"
                );
            }
        }
        true
    }

    /// Feed `blocks` through the committed-block path on a fresh
    /// `p2_fixture` DB. `reference`: every block on the bridge's reference
    /// paths (`test_reference_paths`). `fault`: see [`P2Fault`]. After every
    /// block with resident books, the carried cancel-all index (once built)
    /// covers the books (P2-1).
    fn p2_run(
        blocks: &[TorusBlock],
        pipelined: bool,
        mode: Option<torus_bridge::native_executor::BookMode>,
        reference: bool,
        fault: &P2Fault,
    ) -> P2Run {
        let (config, db) = p2_fixture();
        torus_state::running_hash::capture_begin(&db);
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        let what = format!("pipelined={pipelined} {mode:?} reference={reference} {fault:?}");
        let gate = crate::exec_pipeline::WorkerGate::new();
        let new_ctx = |attach: bool| {
            let mut ctx = make_exec_ctx(&config, &db);
            ctx.test_book_mode = mode;
            ctx.test_reference_paths = reference;
            ctx.metrics = Some(metrics.clone());
            if pipelined && attach {
                ctx.attach_flush_worker(Some(gate.clone()));
            }
            ctx
        };
        let mut ctx = new_ctx(true);
        let (mut v4_max, mut v4_last, mut index_checked, mut restarts, mut faults) =
            (0, 0, 0, 0, 0);
        let (mut ro_resting_max, mut ro_moved) = (0, 0);
        let mut ro_last = std::collections::BTreeMap::new();
        let mut withheld: Option<torus_bridge::native_executor::ResidentBooks> = None;
        let mut skip_to = 0;
        for b in blocks {
            let h = b.header.height;
            if h <= skip_to {
                continue;
            }
            let crash = match fault {
                P2Fault::CrashAfter(ks) => ks.contains(&(h - 1)),
                _ => false,
            };
            if crash {
                // Blocks k + 1 = h and k + 2 = h + 1: W parks on k + 1, E runs
                // k + 2 on top of it, then W's write fails.
                assert!(pipelined, "{what}: a crash needs the flush worker");
                let k = h - 1;
                let next = blocks[h as usize].clone();
                assert_eq!(next.header.height, k + 2);
                gate.hold();
                dispatch_and_execute(&ctx, &db, b);
                assert!(gate.wait_received(k + 1), "{what}: W took {}", k + 1);
                let db_t = db.clone();
                let t = std::thread::spawn(move || {
                    dispatch_and_execute(&ctx, &db_t, &next);
                    ctx
                });
                std::thread::sleep(std::time::Duration::from_millis(200));
                gate.fail_next();
                gate.release();
                let failed = t.join().unwrap();
                assert!(
                    failed.exec_failed.load(Ordering::SeqCst),
                    "{what}: crash after {k} latched"
                );
                let holder = std::mem::take(&mut *failed.resident_books.lock().unwrap());
                drop(failed);
                assert!(
                    holder.height().is_some_and(|hh| hh > k),
                    "{what}: the holder is past the DB ({:?} > {k})",
                    holder.height()
                );
                assert!(
                    matches!(holder.trader_index(), Some((Some(_), _))),
                    "{what}: crash after {k}: the holder carries a warm index"
                );
                assert_eq!(read_native_applied_height(&db), Some(k), "{what}");
                let mut replay = new_ctx(false);
                *replay.resident_books.lock().unwrap() = holder;
                let (_last, parked) = TorusApp::replay_committed(&db, &replay);
                assert_eq!(parked, None, "{what}");
                assert!(
                    !replay.exec_failed.load(Ordering::SeqCst),
                    "{what}: replay after {k}"
                );
                assert_eq!(read_native_applied_height(&db), Some(k + 2), "{what}");
                if pipelined {
                    replay.attach_flush_worker(Some(gate.clone()));
                }
                ctx = replay;
                faults += 1;
                skip_to = k + 2;
            } else {
                dispatch_and_execute(&ctx, &db, b);
                assert!(
                    !ctx.exec_failed.load(Ordering::SeqCst),
                    "{what}: fail-stop at {h}"
                );
                if let Some(w) = ctx.flush_worker.as_ref() {
                    assert!(w.wait_idle(), "{what}: W failed");
                }
            }
            let h = h.max(skip_to);
            v4_last = p2_v4_resting(&db);
            v4_max = v4_max.max(v4_last);
            let ro_now = p2_ro_resting(&db);
            let pm = torus_core::position::PositionManager::new(db.clone());
            for (&(t, m), &(pos, _)) in &ro_last {
                let new = p2_signed_position(&pm, &t, m);
                let flipped = new != FixedPoint::ZERO
                    && pos != FixedPoint::ZERO
                    && (new > FixedPoint::ZERO) != (pos > FixedPoint::ZERO);
                let abs = |p: FixedPoint| if p < FixedPoint::ZERO { -p } else { p };
                if flipped || abs(new) < abs(pos) {
                    ro_moved += 1;
                }
            }
            ro_resting_max = ro_resting_max.max(ro_now.values().map(|v| v.1).sum());
            ro_last = ro_now;
            if p2_index_covers_books(&ctx, &format!("{what}: after {h}")) {
                index_checked += 1;
            }
            if let P2Fault::StaleHolder(windows) = fault {
                if windows.iter().any(|w| w.0 == h) {
                    let holder = std::mem::take(&mut *ctx.resident_books.lock().unwrap());
                    assert!(
                        matches!(holder.trader_index(), Some((Some(_), _))),
                        "{what}: after {h}: the withheld holder carries a warm index"
                    );
                    assert_eq!(holder.height(), Some(h), "{what}");
                    withheld = Some(holder);
                }
                if windows.iter().any(|w| w.1 == h) {
                    let stale = withheld.take().expect("withheld earlier");
                    *ctx.resident_books.lock().unwrap() = stale;
                    faults += 1;
                }
            }
            if matches!(fault, P2Fault::RestartEvery(n) if h % n == 0) && h < P2_BLOCKS {
                restarts += 1;
                drop(ctx);
                ctx = new_ctx(true);
            }
        }
        drop(ctx);
        let captured = torus_state::running_hash::capture_take(&db);
        let hash = torus_state::running_hash::read_running_hash(&db);
        let dump = dump_all_cfs(&db);
        P2Run {
            db,
            dump,
            captured,
            hash,
            metrics,
            v4_max,
            v4_last,
            index_checked,
            restarts,
            faults,
            ro_resting_max,
            ro_moved,
        }
    }

    /// Plan 9.8: the reference paths and the production paths give
    /// identical per-block consensus write sets (every `h_n`), running hash
    /// and full CF dump (state, books, trades, action status), serial and
    /// pipelined, in `mode` (`None`: the env default, classic without the
    /// resident holder). The switch reaches the context (the reference
    /// cancel-all keeps no counters) and the sequence is non-vacuous. P2-1:
    /// production uses the cancel-all index, whose carried copy covers the
    /// books after every block (resident modes, `p2_run`); a replica
    /// restarted every 7 blocks (index rebuilt from the loaded books) gives
    /// the same write sets, hash and dump. `ro` (review gap 2): on
    /// `p2_blocks(true)` (reduce-only places).
    fn p2_reference_differential(mode: Option<torus_bridge::native_executor::BookMode>, ro: bool) {
        let (blocks, fed) = p2_blocks(ro);
        assert_eq!(blocks.len() as u64, P2_BLOCKS);
        assert!(
            fed.cancel_all_none >= 40
                && fed.cancel_all_some >= 20
                && fed.repeated >= 5
                && fed.stops >= 20
                && fed.cancel_only_blocks >= 10
                && (!ro || fed.reduce_only >= 40),
            "{fed:?}"
        );
        for pipelined in [false, true] {
            let what = format!("pipelined={pipelined} {mode:?} ro={ro}");
            let reference = p2_run(&blocks, pipelined, mode, true, &P2Fault::None);
            let current = p2_run(&blocks, pipelined, mode, false, &P2Fault::None);
            assert_write_sets_equal(
                &reference.captured,
                &current.captured,
                &format!("{what}: reference vs current"),
            );
            assert_eq!(
                reference
                    .captured
                    .iter()
                    .map(|(h, _)| *h)
                    .collect::<Vec<_>>(),
                (1..=P2_BLOCKS).collect::<Vec<_>>(),
                "{what}: every height through the hashed flush"
            );
            assert!(current.hash.is_some());
            assert_eq!(reference.hash, current.hash, "{what}: running hash");
            assert_dumps_equal(
                &reference.dump,
                &current.dump,
                &format!("{what}: reference vs current"),
            );
            // P2-1 restart: the cancel-all index rebuilt from the loaded books
            // every 7 blocks gives the same blocks as the carried one.
            let restarted = p2_run(&blocks, pipelined, mode, false, &P2Fault::RestartEvery(7));
            assert_eq!(restarted.restarts, (P2_BLOCKS - 1) / 7, "{what}");
            assert_write_sets_equal(
                &reference.captured,
                &restarted.captured,
                &format!("{what}: reference vs restarted"),
            );
            assert_eq!(
                reference.hash, restarted.hash,
                "{what}: running hash, restarted"
            );
            assert_dumps_equal(
                &reference.dump,
                &restarted.dump,
                &format!("{what}: reference vs restarted"),
            );
            if mode.is_some() {
                // Resident books: the carried index was built and checked.
                assert!(
                    current.index_checked >= P2_BLOCKS - 10,
                    "{what}: {}",
                    current.index_checked
                );
                assert!(
                    restarted.index_checked >= P2_BLOCKS / 2,
                    "{what}: {}",
                    restarted.index_checked
                );
            }
            // The switch took: only the production cancel-all counts.
            assert_eq!(reference.metrics.exec_cancel_all.get(), 0, "{what}");
            assert!(
                current.metrics.exec_cancel_all.get() >= 60,
                "{what}: {}",
                current.metrics.exec_cancel_all.get()
            );

            // Non-vacuous (the runs are equal, so one side is enough).
            let fills =
                StateBackend::iterate_cf(&current.db, torus_state::cf::CF_NATIVE_TRADES, None)
                    .unwrap()
                    .len();
            let liquidations = current.metrics.liquidations_triggered.get();
            println!(
                "P2 {what}: fed {fed:?}; fills {fills}, liquidations {liquidations}, cancel-alls {} (books hit {}), \
                 V4 resting max {} last {}",
                current.metrics.exec_cancel_all.get(),
                current.metrics.exec_cancel_all_books_hit.get(),
                current.v4_max,
                current.v4_last,
            );
            assert!(fills >= 80, "{what}: fills {fills}");
            assert!(liquidations >= 3, "{what}: liquidations {liquidations}");
            assert!(
                current.metrics.exec_cancel_all_books_hit.get() >= 40,
                "{what}"
            );
            if ro && mode.is_none_or(|m| m == torus_bridge::native_executor::BookMode::Classic) {
                // Reduce-only orders rested, and positions under them moved.
                println!(
                    "P2 {what}: reduce-only resting max {}, positions moved under them {}",
                    current.ro_resting_max, current.ro_moved
                );
                assert!(
                    current.ro_resting_max >= 3,
                    "{what}: {}",
                    current.ro_resting_max
                );
                assert!(current.ro_moved >= 3, "{what}: {}", current.ro_moved);
            }
            if mode.is_none_or(|m| m == torus_bridge::native_executor::BookMode::Classic) {
                // V4 never cancels: the liquidation step's cancel took what it rested.
                assert!(current.v4_max >= 4, "{what}: V4 rested {}", current.v4_max);
                assert_eq!(
                    current.v4_last, 0,
                    "{what}: V4's orders and stops left after its liquidation"
                );
                assert_eq!(
                    torus_core::position::PositionManager::new(current.db.clone())
                        .get_position(&oracle_addr(P2_V4), 1)
                        .unwrap()
                        .map(|p| p.size),
                    None,
                    "{what}: V4 liquidated"
                );
            }
        }
    }

    #[test]
    fn reference_paths_match_production_classic_reload() {
        p2_reference_differential(None, false);
    }

